"use client";

import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

/**
 * Soft ambient page wash + slow drifting orbs (Framer Sites–style).
 * Fixed behind content; respects prefers-reduced-motion.
 *
 * Orbs mount only after hydration — useReducedMotion differs on server
 * (null) vs client (boolean) and would otherwise mismatch SSR HTML.
 */
export function PageAtmosphere() {
  const [hydrated, setHydrated] = useState(false);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    setHydrated(true);
  }, []);

  const showOrbs = hydrated && !reduceMotion;

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 -z-10 overflow-hidden"
    >
      <div
        className="absolute inset-0 bg-background"
        style={{
          backgroundImage: "var(--brand-page-atmosphere)",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
        }}
      />

      {showOrbs ? (
        <>
          <motion.div
            className="absolute -left-[18%] -top-[22%] h-[58vmin] w-[58vmin] rounded-full bg-brand-cyan/30 blur-3xl"
            animate={{
              x: [0, 48, -20, 0],
              y: [0, 28, 52, 0],
              scale: [1, 1.12, 0.96, 1],
            }}
            transition={{
              duration: 22,
              repeat: Infinity,
              ease: "easeInOut",
            }}
          />
          <motion.div
            className="absolute -right-[16%] -top-[12%] h-[52vmin] w-[52vmin] rounded-full bg-accent/28 blur-3xl"
            animate={{
              x: [0, -42, 18, 0],
              y: [0, 40, 12, 0],
              scale: [1, 0.94, 1.1, 1],
            }}
            transition={{
              duration: 26,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 1.2,
            }}
          />
          <motion.div
            className="absolute bottom-[-28%] left-[22%] h-[62vmin] w-[62vmin] rounded-full bg-primary/14 blur-3xl"
            animate={{
              x: [0, 36, -28, 0],
              y: [0, -34, -12, 0],
              scale: [1, 1.08, 0.92, 1],
            }}
            transition={{
              duration: 28,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 0.6,
            }}
          />
          <motion.div
            className="absolute right-[18%] top-[38%] h-[36vmin] w-[36vmin] rounded-full bg-brand-mint/22 blur-3xl"
            animate={{
              x: [0, -24, 30, 0],
              y: [0, 22, -18, 0],
              opacity: [0.55, 0.85, 0.6, 0.55],
            }}
            transition={{
              duration: 20,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 2,
            }}
          />
        </>
      ) : null}
    </div>
  );
}

