import { chromium } from 'playwright';

const sites = [
  { name: 'canopy', url: 'https://canopymanagement.com/' },
  { name: 'olifant', url: 'https://olifantdigital.com/' },
  { name: 'mag', url: 'https://myamazonguy.com/' },
  { name: 'amzdudes', url: 'https://amzdudes.com/' },
];

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

for (const site of sites) {
  try {
    await page.goto(site.url, { waitUntil: 'domcontentloaded', timeout: 45000 });
    await page.waitForTimeout(2500);
    const data = await page.evaluate(() => {
      const html = document.documentElement;
      const body = document.body;
      const hs = getComputedStyle(html);
      const bs = getComputedStyle(body);

      const candidates = [];
      const nodes = document.querySelectorAll('body *');
      for (const el of nodes) {
        const s = getComputedStyle(el);
        const bg = s.backgroundImage;
        if (!bg || bg === 'none') continue;
        if (!/gradient|radial|blur/i.test(bg) && !/blur/.test(s.filter)) continue;
        const rect = el.getBoundingClientRect();
        if (rect.width < 80 || rect.height < 80) continue;
        const opacity = parseFloat(s.opacity);
        const bgColor = s.backgroundColor;
        candidates.push({
          tag: el.tagName.toLowerCase(),
          className: (el.className || '').toString().slice(0, 120),
          bgImage: bg.slice(0, 280),
          bgColor,
          opacity,
          filter: s.filter,
          position: s.position,
          zIndex: s.zIndex,
          w: Math.round(rect.width),
          h: Math.round(rect.height),
          top: Math.round(rect.top),
          left: Math.round(rect.left),
        });
        if (candidates.length >= 18) break;
      }

      // also sample absolute/fixed large blurred orbs
      const orbs = [];
      for (const el of nodes) {
        const s = getComputedStyle(el);
        const filter = s.filter || '';
        const blurMatch = filter.match(/blur\((\d+(?:\.\d+)?)px\)/);
        if (!blurMatch) continue;
        const blur = parseFloat(blurMatch[1]);
        if (blur < 20) continue;
        const rect = el.getBoundingClientRect();
        if (rect.width < 100 || rect.height < 100) continue;
        orbs.push({
          className: (el.className || '').toString().slice(0, 100),
          bgColor: s.backgroundColor,
          opacity: parseFloat(s.opacity),
          blur,
          position: s.position,
          w: Math.round(rect.width),
          h: Math.round(rect.height),
          top: Math.round(rect.top),
          left: Math.round(rect.left),
        });
        if (orbs.length >= 12) break;
      }

      return {
        htmlBg: hs.backgroundColor,
        htmlBgImage: hs.backgroundImage.slice(0, 200),
        bodyBg: bs.backgroundColor,
        bodyBgImage: bs.backgroundImage.slice(0, 200),
        candidates,
        orbs,
      };
    });
    console.log('\n==== ' + site.name + ' ====');
    console.log(JSON.stringify(data, null, 2));
    await page.screenshot({ path: `docs/qa/competitors/bg-${site.name}.png`, fullPage: false });
  } catch (e) {
    console.log('\n==== ' + site.name + ' ERROR ====');
    console.log(String(e));
  }
}

await browser.close();
