"use client";

import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

/**
 * Soft ambient page wash + slow drifting orbs (competitor / Framer-light).
 * Opacity matched to Canopy radial blobs (fill-opacity ~0.15–0.20).
 * Orbs mount after hydration to avoid useReducedMotion SSR mismatch.
 */
export function PageAtmosphere() {
  const [hydrated, setHydrated] = useState(false);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    setHydrated(true);
  }, []);

  const showOrbs = hydrated && !reduceMotion;

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 -z-10 overflow-hidden"
    >
      <div
        className="absolute inset-0 bg-background"
        style={{
          backgroundImage: "var(--brand-page-atmosphere)",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
        }}
      />

      {showOrbs ? (
        <>
          <motion.div
            className="absolute -left-[12%] -top-[18%] h-[52vmin] w-[52vmin] rounded-full bg-brand-cyan/[0.12] blur-[90px]"
            animate={{
              x: [0, 36, -14, 0],
              y: [0, 20, 36, 0],
              scale: [1, 1.08, 0.98, 1],
            }}
            transition={{
              duration: 24,
              repeat: Infinity,
              ease: "easeInOut",
            }}
          />
          <motion.div
            className="absolute -right-[10%] -top-[8%] h-[48vmin] w-[48vmin] rounded-full bg-accent/[0.1] blur-[90px]"
            animate={{
              x: [0, -30, 12, 0],
              y: [0, 28, 8, 0],
              scale: [1, 0.96, 1.06, 1],
            }}
            transition={{
              duration: 28,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 1.2,
            }}
          />
          <motion.div
            className="absolute bottom-[-22%] left-[28%] h-[56vmin] w-[56vmin] rounded-full bg-primary/[0.07] blur-[100px]"
            animate={{
              x: [0, 24, -18, 0],
              y: [0, -22, -8, 0],
              scale: [1, 1.05, 0.95, 1],
            }}
            transition={{
              duration: 30,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 0.6,
            }}
          />
        </>
      ) : null}
    </div>
  );
}

