() => {
  const form = document.querySelector('form');
  if (!form) return { error: 'no form' };
  const rect = form.getBoundingClientRect();
  const labels = [...form.querySelectorAll('label, input, select, textarea, button')].map((el) => ({
    tag: el.tagName.toLowerCase(),
    type: el.getAttribute('type'),
    name: el.getAttribute('name'),
    placeholder: el.getAttribute('placeholder'),
    text: (el.textContent || '').trim().slice(0, 80),
    className: String(el.className || '').slice(0, 80)
  })).filter((x) => x.tag === 'label' || x.tag === 'input' || x.tag === 'select' || x.tag === 'textarea' || x.tag === 'button').slice(0, 40);
  const card = form.closest('div, section, aside');
  const cs = card ? getComputedStyle(card) : null;
  return {
    formRect: { w: Math.round(rect.width), h: Math.round(rect.height), top: Math.round(rect.top) },
    formBg: getComputedStyle(form).backgroundColor,
    labels,
    heading: document.querySelector('h1')?.textContent?.trim().slice(0,120)
  };
}

