"use client";

import { useActionState } from "react";
import Link from "next/link";
import type { FormActionState } from "@/domain/forms/form-action-state";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";

interface FormFieldOption {
  value: string;
  label: string;
}

interface FormFieldConfig {
  name: string;
  label: string;
  type: "text" | "email" | "tel" | "url" | "textarea" | "select";
  required: boolean;
  placeholder?: string;
  options?: FormFieldOption[];
}

interface ConfigurableFormProps {
  formId: string;
  fields: FormFieldConfig[];
  submitLabel: string;
  consentLabel: string;
  action: (
    state: FormActionState,
    formData: FormData,
  ) => FormActionState | Promise<FormActionState>;
  initialState: FormActionState;
  /** Compact spacing + optional 2-column grid (AMZ Dudes–style hero). */
  density?: "default" | "compact";
  columns?: 1 | 2;
  submitVariant?: "primary" | "accent";
  submitFullWidth?: boolean;
  className?: string;
}

const selectClassName =
  "flex h-11 w-full rounded-sm border border-border bg-background px-3 py-2 text-sm text-text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent disabled:cursor-not-allowed disabled:opacity-50";

export function ConfigurableForm({
  formId,
  fields,
  submitLabel,
  consentLabel,
  action,
  initialState,
  density = "default",
  columns = 1,
  submitVariant = "primary",
  submitFullWidth = false,
  className,
}: ConfigurableFormProps) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const compact = density === "compact";

  return (
    <form
      action={formAction}
      noValidate
      className={cn(compact ? "space-y-4" : "space-y-6", className)}
      aria-describedby={`${formId}-status`}
    >
      <div className="hidden" aria-hidden="true">
        <label htmlFor={`${formId}-website`}>Website</label>
        <input
          id={`${formId}-website`}
          name="website"
          type="text"
          tabIndex={-1}
          autoComplete="off"
        />
      </div>

      <div
        className={cn(
          columns === 2
            ? "grid gap-x-3 gap-y-4 sm:grid-cols-2"
            : compact
              ? "space-y-4"
              : "space-y-6",
        )}
      >
        {fields.map((field) => {
          const fieldId = `${formId}-${field.name}`;
          const error = state.fieldErrors?.[field.name]?.[0];
          const errorId = error ? `${fieldId}-error` : undefined;
          const spansFull =
            columns === 2 &&
            (field.type === "textarea" || field.name === "message");

          return (
            <div
              key={field.name}
              className={cn("space-y-1.5", spansFull && "sm:col-span-2")}
            >
              <Label htmlFor={fieldId} className={compact ? "text-sm" : undefined}>
                {field.label}
                {field.required ? (
                  <span className="text-error" aria-hidden="true">
                    {" "}
                    *
                  </span>
                ) : null}
              </Label>

              {field.type === "textarea" ? (
                <Textarea
                  id={fieldId}
                  name={field.name}
                  required={field.required}
                  placeholder={field.placeholder}
                  aria-invalid={Boolean(error)}
                  aria-describedby={errorId}
                  rows={compact ? 3 : 5}
                />
              ) : field.type === "select" ? (
                <select
                  id={fieldId}
                  name={field.name}
                  required={field.required}
                  aria-invalid={Boolean(error)}
                  aria-describedby={errorId}
                  className={cn(selectClassName, error && "border-error")}
                  defaultValue=""
                >
                  {field.options?.map((option) => (
                    <option
                      key={`${field.name}-${option.value}`}
                      value={option.value}
                    >
                      {option.label}
                    </option>
                  ))}
                </select>
              ) : (
                <Input
                  id={fieldId}
                  name={field.name}
                  type={field.type}
                  required={field.required}
                  placeholder={field.placeholder}
                  aria-invalid={Boolean(error)}
                  aria-describedby={errorId}
                  className={error ? "border-error" : undefined}
                />
              )}

              {error ? (
                <p id={errorId} className="text-small text-error" role="alert">
                  {error}
                </p>
              ) : null}
            </div>
          );
        })}
      </div>

      <div className={cn("space-y-2", columns === 2 && "sm:col-span-2")}>
        <div className="flex items-start gap-3">
          <input
            id={`${formId}-consent`}
            name="consent"
            type="checkbox"
            value="true"
            required
            className="mt-1 h-4 w-4 rounded border-border accent-primary focus-visible:ring-2 focus-visible:ring-primary"
            aria-invalid={Boolean(state.fieldErrors?.consent)}
            aria-describedby={
              state.fieldErrors?.consent
                ? `${formId}-consent-error`
                : `${formId}-consent-label`
            }
          />
          <Label
            id={`${formId}-consent-label`}
            htmlFor={`${formId}-consent`}
            className="font-normal text-small"
          >
            {consentLabel}{" "}
            <Link
              href="/privacy-policy-2/"
              className="text-link hover:text-link-hover hover:underline"
            >
              Privacy policy
            </Link>
          </Label>
        </div>
        {state.fieldErrors?.consent ? (
          <p
            id={`${formId}-consent-error`}
            className="text-small text-error"
            role="alert"
          >
            {state.fieldErrors.consent[0]}
          </p>
        ) : null}
      </div>

      <div id={`${formId}-status`} aria-live="polite">
        {state.message ? (
          <p
            className={cn(
              "rounded-sm border px-4 py-3 text-small",
              state.success
                ? "border-success/30 bg-success/10 text-text-primary"
                : "border-error/30 bg-error/10 text-text-primary",
            )}
            role={state.success ? "status" : "alert"}
          >
            {state.message}
          </p>
        ) : null}
      </div>

      <PrimaryButton
        type="submit"
        disabled={pending}
        variant={submitVariant}
        className={cn(submitFullWidth && "w-full justify-center")}
      >
        {pending ? "Submitting..." : submitLabel}
      </PrimaryButton>
    </form>
  );
}

import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { submitAuditForm } from "@/app/(marketing)/free-audit-2/actions";
import { ConfigurableForm } from "@/components/forms/configurable-form";
import { PrimaryButton } from "@/components/ui/primary-button";
import { initialFormActionState } from "@/domain/forms/form-action-state";
import {
  readNavLink,
  readRecordArray,
  readString,
} from "./section-data";
import { SectionShell } from "./section-shell";

interface HeroSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface HeroFormField {
  name: string;
  label: string;
  type: "text" | "email" | "tel" | "url" | "textarea" | "select";
  required: boolean;
  placeholder?: string;
  options?: { value: string; label: string }[];
}

function readHeroFormFields(value: unknown): HeroFormField[] {
  if (!Array.isArray(value)) return [];

  return value.flatMap((item) => {
    if (!item || typeof item !== "object") return [];
    const record = item as Record<string, unknown>;
    const name = readString(record.name);
    const label = readString(record.label);
    const type = readString(record.type, "text");
    if (!name || !label) return [];
    if (
      type !== "text" &&
      type !== "email" &&
      type !== "tel" &&
      type !== "url" &&
      type !== "textarea" &&
      type !== "select"
    ) {
      return [];
    }

    const options = Array.isArray(record.options)
      ? record.options.flatMap((option) => {
          if (!option || typeof option !== "object") return [];
          const opt = option as Record<string, unknown>;
          const value = readString(opt.value);
          const optionLabel = readString(opt.label);
          if (value === undefined || !optionLabel) return [];
          return [{ value, label: optionLabel }];
        })
      : undefined;

    return [
      {
        name,
        label,
        type,
        required: Boolean(record.required),
        placeholder: readString(record.placeholder) || undefined,
        options,
      },
    ];
  });
}

export function HeroSection({ id, data }: HeroSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const headline = readString(data.headline);
  const subheadline = readString(data.subheadline);
  const supportLine = readString(data.supportLine);
  const trustLine = readString(data.trustLine);
  const primaryCta = readNavLink(data.primaryCta);
  const secondaryCta = readNavLink(data.secondaryCta);
  const partnerBadge =
    data.partnerBadge && typeof data.partnerBadge === "object"
      ? (data.partnerBadge as Record<string, unknown>)
      : null;
  const partnerBadgeLabel = readString(partnerBadge?.label);
  const partnerBadgeImage = readString(partnerBadge?.image);
  const partnerBadgeHref = readString(partnerBadge?.href);

  const visual = data.visual as Record<string, unknown> | undefined;
  const visualType = readString(visual?.type, "leadForm");
  const formHeading = readString(visual?.formHeading, "Get your free audit");
  const formSubheading = readString(visual?.formSubheading);
  const submitLabel = readString(visual?.submitLabel, "Get your free audit");
  const consentLabel = readString(
    visual?.consentLabel,
    "I agree to the privacy policy and consent to being contacted about my audit request.",
  );
  const formFields = readHeroFormFields(visual?.fields);
  const showLeadForm = visualType === "leadForm" && formFields.length > 0;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={`${id}-heading`}
      className="relative overflow-hidden py-14 sm:py-16 lg:py-20"
    >
      <div className="relative grid items-start gap-10 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,0.95fr)] lg:gap-12 lg:items-center">
        <div className="max-w-xl">
          {eyebrow ? (
            <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">
              {eyebrow}
            </p>
          ) : null}

          <h1
            id={`${id}-heading`}
            className="mt-3 text-hero text-text-primary text-balance"
          >
            {headline}
          </h1>

          {subheadline ? (
            <p className="mt-5 text-body text-text-secondary text-pretty">
              {subheadline}
            </p>
          ) : null}

          {primaryCta || secondaryCta ? (
            <div className="mt-8 flex flex-wrap items-center gap-x-6 gap-y-3">
              {primaryCta ? (
                <PrimaryButton asChild variant="accent">
                  <Link href={primaryCta.href}>
                    {primaryCta.label}
                    <ArrowRight className="h-4 w-4" aria-hidden="true" />
                  </Link>
                </PrimaryButton>
              ) : null}
              {secondaryCta ? (
                <Link
                  href={secondaryCta.href}
                  className="inline-flex min-h-11 items-center text-sm font-medium text-text-primary underline-offset-4 transition-colors hover:text-link-hover hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                >
                  {secondaryCta.label}
                </Link>
              ) : null}
            </div>
          ) : null}

          {supportLine ? (
            <p className="mt-5 text-small text-text-secondary">{supportLine}</p>
          ) : null}

          {partnerBadgeImage || trustLine ? (
            <div className="mt-6 flex flex-wrap items-center gap-3">
              {partnerBadgeImage ? (
                partnerBadgeHref ? (
                  <a
                    href={partnerBadgeHref}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                  >
                    <Image
                      src={partnerBadgeImage}
                      alt={partnerBadgeLabel || "Partner badge"}
                      width={140}
                      height={40}
                      className="h-8 w-auto"
                    />
                  </a>
                ) : (
                  <Image
                    src={partnerBadgeImage}
                    alt={partnerBadgeLabel || "Partner badge"}
                    width={140}
                    height={40}
                    className="h-8 w-auto"
                  />
                )
              ) : null}
              {partnerBadgeImage && trustLine ? (
                <span
                  className="hidden h-4 w-px bg-border sm:inline-block"
                  aria-hidden="true"
                />
              ) : null}
              {trustLine ? (
                <p className="text-small text-text-secondary">{trustLine}</p>
              ) : null}
            </div>
          ) : null}
        </div>

        {showLeadForm ? (
          <div
            id="hero-lead-form"
            className="w-full rounded-lg border border-border bg-background p-5 shadow-md sm:p-6 lg:p-7"
          >
            <h2 className="text-h3 text-text-primary">{formHeading}</h2>
            {formSubheading ? (
              <p className="mt-2 text-small text-text-secondary">
                {formSubheading}
              </p>
            ) : null}
            <div className="mt-5">
              <ConfigurableForm
                formId="hero-audit-form"
                fields={formFields}
                submitLabel={submitLabel}
                consentLabel={consentLabel}
                action={submitAuditForm}
                initialState={initialFormActionState}
                density="compact"
                columns={2}
                submitVariant="accent"
                submitFullWidth
              />
            </div>
          </div>
        ) : null}
      </div>
    </SectionShell>
  );
}

