  // find dark/orange top strip
  const candidates = [...document.querySelectorAll('body > * , body > div > *')].slice(0, 30);
  const bars = [];
  for (const el of document.querySelectorAll('div, section, aside')) {
    const s = getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    if (rect.top > 5 || rect.height < 20 || rect.height > 80 || rect.width < 400) continue;
    const bg = s.backgroundColor;
    if (bg === 'rgba(0, 0, 0, 0)' || bg === 'transparent') continue;
    bars.push({
      className: String(el.className).slice(0, 120),
      bg,
      color: s.color,
      height: Math.round(rect.height),
      text: (el.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 160)
    });
    if (bars.length >= 6) break;
  }
  return bars;
}

() => {
  const all = [...document.body.querySelectorAll('*')];
  const hits = [];
  for (const el of all) {
    const t = (el.textContent || '').trim();
    if (!t) continue;
    if (/ask ai|free consultation|get free|promo|ribbon|announcement/i.test(t) && t.length < 120) {
      const s = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      if (r.height > 100 || r.width < 200) continue;
      hits.push({
        tag: el.tagName,
        className: String(el.className).slice(0,100),
        text: t.slice(0,100),
        bg: s.backgroundColor,
        color: s.color,
        top: Math.round(r.top),
        h: Math.round(r.height)
      });
      if (hits.length >= 15) break;
    }
  }
  // first visible strip at top
  const topEls = all.filter(el => {
    const r = el.getBoundingClientRect();
    return r.top >= 0 && r.top < 8 && r.height >= 28 && r.height <= 56 && r.width > 600;
  }).slice(0,8).map(el => {
    const s = getComputedStyle(el);
    return { className: String(el.className).slice(0,100), bg: s.backgroundColor, color: s.color, text: (el.textContent||'').replace(/\s+/g,' ').trim().slice(0,140), h: Math.round(el.getBoundingClientRect().height) };
  });
  return { hits, topEls };
}

