    state: FormActionState,
    formData: FormData,
  ) => FormActionState | Promise<FormActionState>;
  initialState: FormActionState;
  density?: "default" | "compact";
  columns?: 1 | 2;
  submitVariant?: "primary" | "accent";
  submitFullWidth?: boolean;
  className?: string;
}

const fieldControlClass =
  "border-border bg-background text-text-primary placeholder:text-text-secondary focus-visible:ring-primary";

export function ConfigurableForm({
  formId,
  fields,
  submitLabel,
  consentLabel,
  action,
  initialState,
  density = "default",
  columns = 1,
  submitVariant = "primary",
  submitFullWidth = false,
  className,
}: ConfigurableFormProps) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const compact = density === "compact";

  return (
    <form
      action={formAction}
      noValidate
      className={cn(compact ? "space-y-3.5" : "space-y-6", className)}
      aria-describedby={`${formId}-status`}
    >
      <div className="hidden" aria-hidden="true">
        <label htmlFor={`${formId}-website`}>Website</label>
        <input
          id={`${formId}-website`}
          name="website"
          type="text"
          tabIndex={-1}
          autoComplete="off"
        />
      </div>

      <div
        className={cn(
          columns === 2
            ? "grid grid-cols-1 gap-x-3 gap-y-3.5 sm:grid-cols-2"
            : compact
              ? "space-y-3.5"
              : "space-y-6",
        )}
      >
        {fields.map((field) => {
          const fieldId = `${formId}-${field.name}`;
          const error = state.fieldErrors?.[field.name]?.[0];
          const errorId = error ? `${fieldId}-error` : undefined;
          const spansFull =
            columns === 2 &&
            (field.type === "textarea" || field.name === "message");

          return (
            <div
              key={field.name}
              className={cn("space-y-1.5", spansFull && "sm:col-span-2")}
            >
              <Label htmlFor={fieldId} className="text-sm text-text-primary">
                {field.label}
                {field.required ? (
                  <span className="text-error" aria-hidden="true">
                    {" "}
                    *
                  </span>
                ) : null}
              </Label>

              {field.type === "textarea" ? (
                <Textarea
                  id={fieldId}
                  name={field.name}
                  required={field.required}
                  placeholder={field.placeholder}
                  aria-invalid={Boolean(error)}
                  aria-describedby={errorId}
                  rows={compact ? 3 : 5}
                  className={cn(
                    fieldControlClass,
                    compact && "min-h-[88px]",
                    error && "border-error",
                  )}
                />
              ) : field.type === "select" ? (
                <Select
                  id={fieldId}
                  name={field.name}
                  required={field.required}
                  aria-invalid={Boolean(error)}
                  aria-describedby={errorId}
                  className={cn(error && "border-error")}
                  defaultValue=""
                >
                  {field.options?.map((option) => (
                    <option
                      key={`${field.name}-${option.value}`}
                      value={option.value}
                    >
                      {option.label}
                    </option>
                  ))}
                </Select>
              ) : (
                <Input
                  id={fieldId}
                  name={field.name}
                  type={field.type}
                  required={field.required}
                  placeholder={field.placeholder}
                  aria-invalid={Boolean(error)}
                  aria-describedby={errorId}
                  className={cn(
                    fieldControlClass,
                    error && "border-error",
                  )}
                />
              )}

              {error ? (
                <p id={errorId} className="text-small text-error" role="alert">
                  {error}
                </p>
              ) : null}
            </div>
          );
        })}
      </div>

      <div className="space-y-2">
        <div className="flex items-start gap-3">
          <input
            id={`${formId}-consent`}
            name="consent"
            type="checkbox"
            value="true"
            required
            className="mt-1 h-4 w-4 shrink-0 rounded border-border accent-primary focus-visible:ring-2 focus-visible:ring-primary"
            aria-invalid={Boolean(state.fieldErrors?.consent)}
            aria-describedby={
              state.fieldErrors?.consent
                ? `${formId}-consent-error`
                : `${formId}-consent-label`
            }
          />
          <Label
            id={`${formId}-consent-label`}
            htmlFor={`${formId}-consent`}
            className="font-normal text-small leading-snug text-text-secondary"
          >
            {consentLabel}{" "}
            <Link
              href="/privacy-policy-2/"
              className="text-primary underline-offset-2 hover:text-accent hover:underline"
            >
              Privacy policy
            </Link>
          </Label>
        </div>
        {state.fieldErrors?.consent ? (
          <p
            id={`${formId}-consent-error`}
            className="text-small text-error"
            role="alert"
          >
            {state.fieldErrors.consent[0]}
          </p>
        ) : null}
      </div>

      <div id={`${formId}-status`} aria-live="polite">
        {state.message ? (
          <p
            className={cn(
              "rounded-sm border px-4 py-3 text-small",
              state.success
                ? "border-success/30 bg-success/10 text-text-primary"
                : "border-error/30 bg-error/10 text-text-primary",
            )}
            role={state.success ? "status" : "alert"}
          >
            {state.message}
          </p>
        ) : null}
      </div>

      <PrimaryButton
        type="submit"
        disabled={pending}
        variant={submitVariant}
        className={cn(submitFullWidth && "w-full justify-center")}
      >
        {pending ? "Submitting..." : submitLabel}
      </PrimaryButton>
    </form>
  );
}

import Link from "next/link";
import { ArrowRight } from "lucide-react";
import type { SiteConfig } from "@/domain/content/schemas";
import { cn } from "@/lib/utils";

interface AnnouncementBarProps {
  site: SiteConfig;
}

/**
 * Promo ribbon inspired by mid-market agency top bars (structure only).
 * Theming: brand navy + cyan wash. Copy and actions are eCom Gliders–specific
 * (no third-party AI branding or competitor wording).
 */
export function AnnouncementBar({ site }: AnnouncementBarProps) {
  const { announcementBar } = site;

  if (!announcementBar.enabled) {
    return null;
  }

  const message = announcementBar.message;
  const kicker = announcementBar.kicker ?? "Live";
  const actions = announcementBar.actions ?? [];
  const legacyItems = announcementBar.items ?? [];
  const hasPromoLayout = Boolean(message) || actions.length > 0;

  if (!hasPromoLayout && legacyItems.length === 0) {
    return null;
  }

  return (
    <div
      className="border-b border-primary-dark text-text-on-dark"
      style={{
        backgroundImage:
          "linear-gradient(90deg, color-mix(in srgb, var(--color-brandCyan) 22%, transparent) 0%, transparent 32%), linear-gradient(180deg, var(--color-primary) 0%, var(--color-primaryDark) 100%)",
      }}
      role="region"
      aria-label="Site announcements"
    >
      <div
        className={cn(
          "container-page flex flex-col gap-2 py-2.5 sm:flex-row sm:items-center sm:justify-between sm:gap-4 sm:py-0 sm:min-h-[46px]",
        )}
      >
        <div className="flex min-w-0 items-start gap-2.5 sm:items-center">
          <span className="relative mt-1.5 flex h-2 w-2 shrink-0 sm:mt-0" aria-hidden="true">
            <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-accent opacity-60" />
            <span className="relative inline-flex h-2 w-2 rounded-full bg-accent" />
          </span>
          {kicker ? (
            <span className="shrink-0 text-xs font-semibold uppercase tracking-wide text-accent">
              {kicker}
            </span>
          ) : null}
          {message ? (
            <p className="min-w-0 text-small leading-snug text-text-on-dark/95">
              {message}
            </p>
          ) : (
            <div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-small">
              {legacyItems.map((item, index) => (
                <span key={item} className="inline-flex items-center gap-3">
                  {index > 0 ? (
                    <span
                      className="hidden h-3 w-px shrink-0 bg-text-on-dark/35 sm:inline-block"
                      aria-hidden="true"
                    />
                  ) : null}
                  <span>{item}</span>
                </span>
              ))}
              {announcementBar.link ? (
                <Link
                  href={announcementBar.link.href}
                  className="inline-flex items-center gap-1 font-medium underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
                >
                  {announcementBar.link.label}
                  <ArrowRight className="h-3.5 w-3.5" aria-hidden="true" />
                </Link>
              ) : null}
            </div>
          )}
        </div>

        {actions.length > 0 ? (
          <div className="flex flex-wrap items-center gap-2 sm:shrink-0 sm:justify-end">
            {actions.map((action) => {
              const style = action.style ?? "outline";
              return (
                <Link
                  key={`${action.href}-${action.label}`}
                  href={action.href}
                  className={cn(
                    "inline-flex h-8 items-center justify-center gap-1 rounded-sm px-3 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary",
                    style === "accent"
                      ? "bg-accent text-text-on-dark hover:bg-accent-alt"
                      : "border border-text-on-dark/35 text-text-on-dark hover:border-text-on-dark hover:bg-text-on-dark/10",
                  )}
                >
                  {action.label}
                  {style === "accent" ? (
                    <ArrowRight className="h-3.5 w-3.5" aria-hidden="true" />
                  ) : null}
                </Link>
              );
            })}
          </div>
        ) : null}
      </div>
    </div>
  );
}

