() => {
  const vw = window.innerWidth;
  const candidates = [];
  const seen = new Set();
  for (const el of document.querySelectorAll('header *, .container, .wrap, .inner, main *, nav, [class*=container], [class*=Container], [class*=wrap], [class*=row]')) {
    const s = getComputedStyle(el);
    const mw = s.maxWidth;
    if (!mw || mw === 'none' || mw === '0px') continue;
    const px = parseFloat(mw);
    if (!Number.isFinite(px) || px < 600 || px > 2000) continue;
    const key = mw + '|' + Math.round(el.getBoundingClientRect().width);
    if (seen.has(key)) continue;
    seen.add(key);
    const r = el.getBoundingClientRect();
    if (r.width < 500) continue;
    candidates.push({
      maxWidth: mw,
      renderedW: Math.round(r.width),
      tag: el.tagName.toLowerCase(),
      className: String(el.className || '').slice(0, 80),
      top: Math.round(r.top)
    });
  }
  candidates.sort((a,b) => parseFloat(b.maxWidth) - parseFloat(a.maxWidth));
  // most common content widths among header/main
  const freq = {};
  for (const c of candidates) {
    const k = c.maxWidth;
    freq[k] = (freq[k] || 0) + 1;
  }
  return { viewport: vw, topCandidates: candidates.slice(0, 12), freq };
}

