    const s = getComputedStyle(el);
    const mw = s.maxWidth;
    if (!mw || mw === 'none') continue;
    const px = parseFloat(mw);
    if (!Number.isFinite(px) || px < 700 || px > 1800) continue;
    const r = el.getBoundingClientRect();
    if (r.width < 600 || r.top > 1200) continue;
    const key = Math.round(px);
    if (seen.has(key)) continue;
    seen.add(key);
    candidates.push({ maxWidth: mw, renderedW: Math.round(r.width), className: String(el.className||'').slice(0,70), top: Math.round(r.top) });
  }
  candidates.sort((a,b) => parseFloat(b.maxWidth) - parseFloat(a.maxWidth));
  return { site: 'sequence', viewport: window.innerWidth, candidates: candidates.slice(0,8) };
}

