import Link from "next/link";
import { Sparkles } from "lucide-react";
import type { SiteConfig } from "@/domain/content/schemas";
import { cn } from "@/lib/utils";

interface AnnouncementBarProps {
  site: SiteConfig;
}

function buildAiPrompt(agencyName: string, siteHost: string): string {
  return (
    `I run an Amazon brand and want to lower ACOS while scaling revenue. ` +
    `Ask me smart discovery questions, then recommend whether a full-service Amazon agency ` +
    `like ${agencyName} (${siteHost}) is a fit, and outline a 30-day growth plan.`
  );
}

/**
 * Promo / Ask-AI ribbon. Structure inspired by mid-market agency top bars;
 * copy, colors, and prompts are eCom Gliders–specific (not competitor branding).
 */
export function AnnouncementBar({ site }: AnnouncementBarProps) {
  const { announcementBar } = site;

  if (!announcementBar.enabled) {
    return null;
  }

  const message = announcementBar.message;
  const kicker = announcementBar.kicker ?? "Live";
  const actions = announcementBar.actions ?? [];
  const legacyItems = announcementBar.items ?? [];
  const hasPromoLayout = Boolean(message) || actions.length > 0;

  if (!hasPromoLayout && legacyItems.length === 0) {
    return null;
  }

  return (
    <div
      className="relative border-b border-primary-dark text-text-on-dark"
      style={{
        backgroundImage: [
          "radial-gradient(circle at 1px 1px, color-mix(in srgb, #FFFFFF 12%, transparent) 1px, transparent 0)",
          "linear-gradient(90deg, color-mix(in srgb, var(--color-brandCyan) 18%, transparent) 0%, transparent 30%)",
          "linear-gradient(180deg, var(--color-primary) 0%, var(--color-primaryDark) 100%)",
        ].join(", "),
        backgroundSize: "18px 18px, auto, auto",
      }}
      role="region"
      aria-label="Site announcements"
    >
      <div className="container-page flex flex-col gap-2.5 py-2.5 sm:min-h-[46px] sm:flex-row sm:items-center sm:justify-between sm:gap-4 sm:py-0">
        <div className="flex min-w-0 items-start gap-2.5 sm:items-center">
          <span
            className="relative mt-1.5 flex h-2 w-2 shrink-0 sm:mt-0"
            aria-hidden="true"
          >
            <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-accent opacity-60" />
            <span className="relative inline-flex h-2 w-2 rounded-full bg-accent" />
          </span>
          {kicker ? (
            <span className="shrink-0 rounded-sm border border-accent/70 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-text-on-dark">
              {kicker}
            </span>
          ) : null}
          {message ? (
            <p className="min-w-0 text-small leading-snug text-text-on-dark/90">
              {message}
            </p>
          ) : (
            <div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-small">
              {legacyItems.map((item, index) => (
                <span key={item} className="inline-flex items-center gap-3">
                  {index > 0 ? (
                    <span
                      className="hidden h-3 w-px shrink-0 bg-text-on-dark/35 sm:inline-block"
                      aria-hidden="true"
                    />
                  ) : null}
                  <span>{item}</span>
                </span>
              ))}
            </div>
          )}
        </div>

        {actions.length > 0 ? (
          <div className="flex flex-wrap items-center gap-2 sm:shrink-0 sm:justify-end">
            <span className="hidden items-center gap-1 text-[10px] font-semibold uppercase tracking-wide text-accent sm:inline-flex">
              <Sparkles className="h-3.5 w-3.5" aria-hidden="true" />
              Ask AI
            </span>
            {actions.map((action) => {
              const style = action.style ?? "outline";
              return (
                <a
                  key={`${action.href}-${action.label}`}
                  href={action.href}
                  target={action.external ? "_blank" : undefined}
                  rel={action.external ? "noopener noreferrer" : undefined}
                  className={cn(
                    "inline-flex h-8 items-center justify-center gap-1.5 rounded-sm px-3 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary",
                    style === "chatgpt" &&
                      "bg-[color-mix(in_srgb,var(--color-brandCyan)_35%,var(--color-primaryDark))] text-text-on-dark hover:bg-[color-mix(in_srgb,var(--color-brandCyan)_50%,var(--color-primaryDark))]",
                    style === "claude" &&
                      "bg-accent text-text-on-dark hover:bg-accent-alt",
                    style === "accent" &&
                      "bg-accent text-text-on-dark hover:bg-accent-alt",
                    style === "outline" &&
                      "border border-text-on-dark/35 text-text-on-dark hover:border-text-on-dark hover:bg-text-on-dark/10",
                  )}
                >
                  {action.label}
                </a>
              );
            })}
          </div>
        ) : null}
      </div>
    </div>
  );
}

/** Helper for config authors — not used at runtime. */
export const announcementAiPromptPreview = buildAiPrompt;

