() => {
  const content = document.querySelector('[data-radix-select-viewport], [role="listbox"]');
  const items = [...document.querySelectorAll('[role="option"]')].slice(0, 4).map(el => {
    const s = getComputedStyle(el);
    return {
      text: el.textContent?.trim().slice(0,40),
      bg: s.backgroundColor,
      color: s.color,
      highlighted: el.getAttribute('data-highlighted'),
      state: el.getAttribute('data-state')
    };
  });
  const contentStyle = content ? getComputedStyle(content.closest('[data-radix-popper-content-wrapper], [role="listbox"]')?.parentElement || content) : null;
  return {
    itemCount: document.querySelectorAll('[role="option"]').length,
    items,
    listBg: content ? getComputedStyle(content).backgroundColor : null
  };
