import Image from "next/image";
import type { SiteConfig } from "@/domain/content/schemas";
import { cn } from "@/lib/utils";

interface AnnouncementBarProps {
  site: SiteConfig;
}

/**
 * Ask-AI utility strip — eCom Gliders layout (not AMZ Dudes pill row).
 * Logo chips on light surfaces; navy bar; four assistants with brand marks.
 */
export function AnnouncementBar({ site }: AnnouncementBarProps) {
  const { announcementBar } = site;

  if (!announcementBar.enabled) {
    return null;
  }

  const message = announcementBar.message;
  const kicker = announcementBar.kicker;
  const actions = announcementBar.actions ?? [];
  const legacyItems = announcementBar.items ?? [];
  const hasPromoLayout = Boolean(message) || actions.length > 0;

  if (!hasPromoLayout && legacyItems.length === 0) {
    return null;
  }

  return (
    <div
      className="border-b border-border bg-primary text-text-on-dark"
      role="region"
      aria-label="Ask an AI assistant about eCom Gliders"
    >
      <div className="container-page flex flex-col gap-3 py-3 lg:flex-row lg:items-center lg:justify-between lg:gap-6 lg:py-2.5">
        <div className="min-w-0 space-y-1">
          {kicker ? (
            <p className="text-[10px] font-semibold uppercase tracking-[0.14em] text-brand-cyan">
              {kicker}
            </p>
          ) : null}
          {message ? (
            <p className="text-small leading-snug text-text-on-dark/95 sm:text-sm">
              {message}
            </p>
          ) : (
            <div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-small">
              {legacyItems.map((item, index) => (
                <span key={item} className="inline-flex items-center gap-3">
                  {index > 0 ? (
                    <span
                      className="hidden h-3 w-px shrink-0 bg-text-on-dark/35 sm:inline-block"
                      aria-hidden="true"
                    />
                  ) : null}
                  <span>{item}</span>
                </span>
              ))}
            </div>
          )}
        </div>

        {actions.length > 0 ? (
          <ul className="flex flex-wrap items-center gap-2 sm:gap-2.5 lg:shrink-0 lg:justify-end">
            {actions.map((action) => (
              <li key={`${action.href}-${action.label}`}>
                <a
                  href={action.href}
                  target={action.external ? "_blank" : undefined}
                  rel={action.external ? "noopener noreferrer" : undefined}
                  className={cn(
                    "group inline-flex h-9 items-center gap-2 rounded-md border border-border/20 bg-background px-2.5 text-xs font-medium text-text-primary shadow-sm",
                    "transition-colors hover:border-accent/40 hover:bg-surface focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary",
                  )}
                >
                  {action.icon ? (
                    <Image
                      src={action.icon}
                      alt=""
                      width={16}
                      height={16}
                      className="h-4 w-4 shrink-0"
                      unoptimized
                    />
                  ) : null}
                  <span>{action.label}</span>
                  <span className="sr-only"> (opens in a new tab)</span>
                </a>
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    </div>
  );
}

