() => {
  const els = [];
  for (const el of document.querySelectorAll('body *')) {
    const s = getComputedStyle(el);
    const mw = s.maxWidth;
    const px = parseFloat(mw);
    if (!Number.isFinite(px) || px < 1100 || px > 1400) continue;
    const r = el.getBoundingClientRect();
    if (r.width < 900 || r.top > 200) continue;
    els.push({
      maxWidth: mw,
      width: Math.round(r.width),
      left: Math.round(r.left),
      right: Math.round(window.innerWidth - r.right),
      paddingLeft: s.paddingLeft,
      paddingRight: s.paddingRight,
      className: String(el.className||'').slice(0,80),
      top: Math.round(r.top)
    });
  }
  // also header row
  const header = document.querySelector('.header-wrapper, header, .header, #header');
  let headerInfo = null;
  if (header) {
    const inner = header.querySelector('.flex-row, .container, .row, .header-inner') || header;
    const s = getComputedStyle(inner);
    const r = inner.getBoundingClientRect();
    headerInfo = { maxWidth: s.maxWidth, width: Math.round(r.width), left: Math.round(r.left), right: Math.round(window.innerWidth - r.right), pl: s.paddingLeft, pr: s.paddingRight, className: String(inner.className||'').slice(0,80) };
  }
  return { viewport: window.innerWidth, els: els.slice(0,8), headerInfo };
}

