async () => {
  const imgs = [...document.querySelectorAll('[aria-label*="Ask an AI"] img')];
  const results = [];
  for (const img of imgs) {
    const src = img.getAttribute('src');
    const res = await fetch(src);
    const text = await res.text();
    results.push({
      src,
      status: res.status,
      hasFill: /fill="#/.test(text),
      title: (text.match(/<title>([^<]+)<\/title>/) || [])[1] || null,
      bytes: text.length
    });
  }
  return results;
}

