import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  trailingSlash: true,
  images: {
    // Serve modern formats when the browser supports them (CWV / LCP).
    formats: ["image/avif", "image/webp"],
    // Match global shell (1320px) plus common device widths.
    deviceSizes: [640, 750, 828, 1080, 1200, 1320, 1920],
    // Icon / badge / logo slots used in header, trust, AI chips.
    imageSizes: [16, 32, 48, 64, 96, 128, 160, 256, 384],
    minimumCacheTTL: 60 * 60 * 24 * 30,
    remotePatterns: [
      {
        protocol: "https",
        hostname: "ecomgliders.com",
      },
      {
        protocol: "https",
        hostname: "www.ecomgliders.com",
      },
    ],
  },
};

export default nextConfig;

import Image from "next/image";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";

interface BrandLogoProps {
  className?: string;
  width: number;
  height: number;
  alt?: string;
  /** Header / LCP: true. Footer and secondary: false (lazy). */
  priority?: boolean;
}

export function BrandLogo({
  className,
  width,
  height,
  alt = `${designSystem.brand.name} logo`,
  priority = false,
}: BrandLogoProps) {
  return (
    <Image
      src={designSystem.brand.logo.light}
      alt={alt}
      width={width}
      height={height}
      className={cn(className)}
      priority={priority}
      sizes={`${width}px`}
      quality={85}
    />
  );
}

"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { Badge } from "@/components/ui/badge";

interface TrustLogoProps {
  label: string;
  image: string;
  alt: string;
  href?: string;
}

export function TrustLogo({ label, image, alt, href }: TrustLogoProps) {
  const [imageFailed, setImageFailed] = useState(false);

  const content = (
    <div className="flex h-16 min-w-[120px] items-center justify-center rounded-md border border-border bg-background px-4">
      {!imageFailed && image ? (
        <Image
          src={image}
          alt={alt || label}
          width={140}
          height={48}
          className="max-h-12 w-auto max-w-[140px] object-contain"
          sizes="140px"
          quality={70}
          loading="lazy"
          onError={() => setImageFailed(true)}
        />
      ) : (
        <Badge variant="outline" className="whitespace-nowrap">
          {label}
        </Badge>
      )}
    </div>
  );

  if (href) {
    return (
      <Link
        href={href}
        className="transition-opacity hover:opacity-80"
        target="_blank"
        rel="noopener noreferrer"
      >
        {content}
      </Link>
    );
  }

  return content;
}

