"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

export type TrustLogoVariant = "cert" | "client" | "badge";

interface TrustLogoProps {
  label: string;
  image: string;
  alt: string;
  href?: string;
  variant?: TrustLogoVariant;
  className?: string;
}

export function TrustLogo({
  label,
  image,
  alt,
  href,
  variant = "cert",
  className,
}: TrustLogoProps) {
  const [imageFailed, setImageFailed] = useState(false);

  const shellClass =
    variant === "client"
      ? "flex h-10 items-center justify-center px-3 opacity-70 grayscale transition-[opacity,filter] hover:opacity-100 hover:grayscale-0"
      : variant === "badge"
        ? "flex h-10 items-center justify-center px-2"
        : "flex h-14 min-w-[112px] items-center justify-center rounded-md border border-border bg-background px-4";

  const imageClass =
    variant === "client"
      ? "max-h-8 w-auto max-w-[120px] object-contain"
      : variant === "badge"
        ? "max-h-8 w-auto max-w-[130px] object-contain"
        : "max-h-10 w-auto max-w-[140px] object-contain";

  const content = (
    <div className={cn(shellClass, className)}>
      {!imageFailed && image ? (
        <Image
          src={image}
          alt={alt || label}
          width={variant === "client" ? 120 : 140}
          height={variant === "client" ? 32 : 48}
          className={imageClass}
          sizes={variant === "client" ? "120px" : "140px"}
          quality={70}
          loading="lazy"
          onError={() => setImageFailed(true)}
        />
      ) : (
        <Badge variant="outline" className="whitespace-nowrap text-xs">
          {label}
        </Badge>
      )}
    </div>
  );

  if (href) {
    return (
      <Link
        href={href}
        className="transition-opacity hover:opacity-80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        target="_blank"
        rel="noopener noreferrer"
      >
        {content}
      </Link>
    );
  }

  return content;
}

