interface TrustClientItem {
  label: string;
  image: string;
  alt: string;
}

interface TrustClientMarqueeProps {
  items: TrustClientItem[];
}

/**
 * CSS marquee for client logos. Pauses on hover/focus-within.
 * prefers-reduced-motion: static wrap (no animation).
 */
export function TrustClientMarquee({ items }: TrustClientMarqueeProps) {
  if (items.length === 0) return null;

  const track = [...items, ...items];

  return (
    <div className="w-full">
      <ul className="flex flex-wrap items-center justify-center gap-x-6 gap-y-3 md:hidden">
        {items.map((item) => (
          <li key={`static-${item.image}`}>
            <TrustLogo
              label={item.label}
              image={item.image}
              alt={item.alt}
              variant="client"
            />
          </li>
        ))}
      </ul>

      <div className="group relative hidden overflow-hidden md:block">
        <div
          className="flex w-max items-center gap-10 motion-safe:animate-trust-marquee motion-safe:group-hover:[animation-play-state:paused] motion-safe:group-focus-within:[animation-play-state:paused] motion-reduce:animate-none motion-reduce:flex-wrap motion-reduce:justify-center motion-reduce:w-full"
          tabIndex={0}
        >
          {track.map((item, index) => (
            <div
              key={`${item.image}-${index}`}
              className="shrink-0"
              aria-hidden={index >= items.length ? true : undefined}
            >
              <TrustLogo
                label={item.label}
                image={item.image}
                alt={index >= items.length ? "" : item.alt}
                variant="client"
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";
import { TrustClientMarquee } from "./trust-client-marquee";
import { TrustLogo } from "./trust-logo";

interface TrustBarSectionProps {
  id: string;
  data: Record<string, unknown>;
}

function readLogoItems(value: unknown) {
  return readRecordArray(value)
    .map((item) => {
      const label = readString(item.label);
      const image = readString(item.image);
      const alt = readString(item.alt, label);
      const href = readString(item.href) || undefined;
      if (!label && !image) return null;
      return { label, image, alt, href };
    })
    .filter((item): item is NonNullable<typeof item> => item !== null);
}

export function TrustBarSection({ id, data }: TrustBarSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const subheading = readString(data.subheading);

  // New shape (Wave B). Fall back to legacy badge/logos if partners missing.
  const partners = readLogoItems(data.partners);
  const clients = readLogoItems(data.clients);
  const reviews = readLogoItems(data.reviews);
  const press = readLogoItems(data.press);

  const legacyBadge =
    data.badge && typeof data.badge === "object"
      ? (data.badge as Record<string, unknown>)
      : undefined;
  const legacyLogos = readLogoItems(data.logos);

  const partnerItems =
    partners.length > 0
      ? partners
      : legacyBadge
        ? [
            {
              label: readString(legacyBadge.label),
              image: readString(legacyBadge.image),
              alt: readString(legacyBadge.label),
              href: readString(legacyBadge.href) || undefined,
            },
            ...legacyLogos.filter(
              (logo) => !logo.image.includes("amazon-verified-partner"),
            ),
          ].filter((item) => item.label || item.image)
        : legacyLogos.filter(
            (logo) => !logo.image.includes("amazon-verified-partner"),
          );

  const reviewAndPress = [...reviews, ...press];

  return (
    <SectionShell id={id} tone="muted" className="py-8 sm:py-10">
      <div className="flex flex-col items-center gap-6 text-center">
        {eyebrow || subheading ? (
          <div className="max-w-2xl space-y-1">
            {eyebrow ? (
              <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">
                {eyebrow}
              </p>
            ) : null}
            {subheading ? (
              <p className="text-small text-text-secondary">{subheading}</p>
            ) : null}
          </div>
        ) : null}

        {partnerItems.length > 0 ? (
          <ul className="flex flex-wrap items-center justify-center gap-3">
            {partnerItems.map((item) => (
              <li key={`partner-${item.image || item.label}`}>
                <TrustLogo
                  label={item.label}
                  image={item.image}
                  alt={item.alt}
                  href={item.href}
                  variant="cert"
                />
              </li>
            ))}
          </ul>
        ) : null}

        {clients.length > 0 ? <TrustClientMarquee items={clients} /> : null}

        {reviewAndPress.length > 0 ? (
          <ul className="flex flex-wrap items-center justify-center gap-4 sm:gap-5">
            {reviewAndPress.map((item) => (
              <li key={`badge-${item.image || item.label}`}>
                <TrustLogo
                  label={item.label}
                  image={item.image}
                  alt={item.alt}
                  href={item.href}
                  variant="badge"
                />
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    </SectionShell>
  );
}

