import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { PrimaryButton } from "@/components/ui/primary-button";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionShell } from "./section-shell";

interface CreativeShowcaseSectionProps {
  id: string;
  data: Record<string, unknown>;
}

export function CreativeShowcaseSection({
  id,
  data,
}: CreativeShowcaseSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const items = readRecordArray(data.items);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  const visuals = items
    .map((item) => {
      const image = readString(item.image);
      const alt = readString(item.alt);
      const caption = readString(item.caption);
      if (!image) return null;
      return { image, alt, caption };
    })
    .filter((item): item is NonNullable<typeof item> => item !== null);

  // Part C2 / B5 gate: need at least one QA-passed still to render.
  if (visuals.length === 0) {
    return null;
  }

  return (
    <SectionShell id={id} ariaLabelledBy={headingId}>
      <div className="flex flex-col gap-8 lg:flex-row lg:items-end lg:justify-between">
        <SectionHeading
          heading={heading}
          subheading={subheading}
          headingId={headingId}
          className="mb-0 md:mb-0"
        />
        {cta ? (
          <PrimaryButton asChild variant="primary" className="w-full sm:w-auto">
            <Link href={cta.href}>
              {cta.label}
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </Link>
          </PrimaryButton>
        ) : null}
      </div>

      <ul
        className={
          visuals.length === 1
            ? "mt-8 grid gap-6 lg:grid-cols-[minmax(0,1.1fr)_minmax(0,0.9fr)] lg:items-center"
            : "mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"
        }
      >
        {visuals.map((item) => (
          <li key={item.image}>
            <figure className="overflow-hidden rounded-md border border-border bg-surface">
              <Image
                src={item.image}
                alt={item.alt || "Amazon listing creative example"}
                width={960}
                height={720}
                className="h-auto w-full object-cover"
                sizes={
                  visuals.length === 1
                    ? "(max-width: 1024px) 100vw, 55vw"
                    : "(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
                }
                quality={75}
                loading="lazy"
              />
              {item.caption ? (
                <figcaption className="border-t border-border px-4 py-3 text-small text-text-secondary">
                  {item.caption}
                </figcaption>
              ) : null}
            </figure>
          </li>
        ))}
        {visuals.length === 1 && cta ? (
          <li className="flex flex-col justify-center">
            <p className="text-body text-text-secondary text-pretty">
              Main images, secondary sets, and A+ modules are built for shopper
              clarity on Amazon product detail pages.
            </p>
            <Button variant="link" className="mt-4 self-start" asChild>
              <Link href={cta.href}>
                {cta.label}
                <ArrowRight className="h-4 w-4" aria-hidden="true" />
              </Link>
            </Button>
          </li>
        ) : null}
      </ul>
    </SectionShell>
  );
}

import { readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionIcon } from "./section-icon";
import { SectionShell } from "./section-shell";

interface BrandValuesSectionProps {
  id: string;
  data: Record<string, unknown>;
}

export function BrandValuesSection({ id, data }: BrandValuesSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const items = readRecordArray(data.items);
  const headingId = `${id}-heading`;

  return (
    <SectionShell id={id} tone="muted" ariaLabelledBy={headingId}>
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
      />
      <ul className="grid gap-6 sm:grid-cols-2">
        {items.map((item, index) => {
          const title = readString(item.title);
          const description = readString(item.description);
          const icon = readString(item.icon, "compass");
          const number = String(index + 1).padStart(2, "0");

          return (
            <li
              key={title}
              className="rounded-md border border-border bg-background p-6"
            >
              <div className="flex items-start gap-3">
                <SectionIcon name={icon} className="mt-0.5 shrink-0" />
                <div>
                  <p className="font-mono text-xs font-medium text-primary">
                    {number}
                  </p>
                  <h3 className="mt-2 text-h4">{title}</h3>
                  <p className="mt-2 text-body text-text-secondary">
                    {description}
                  </p>
                </div>
              </div>
            </li>
          );
        })}
      </ul>
    </SectionShell>
  );
}

