import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionIcon } from "./section-icon";
import { SectionShell } from "./section-shell";

interface SellerSegmentsSectionProps {
  id: string;
  data: Record<string, unknown>;
}

export function SellerSegmentsSection({ id, data }: SellerSegmentsSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const segments = readRecordArray(data.segments);
  const headingId = `${id}-heading`;

  return (
    <SectionShell id={id} ariaLabelledBy={headingId}>
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
      />
      <ul className="grid gap-6 md:grid-cols-3">
        {segments.map((segment) => {
          const segmentId = readString(segment.id);
          const title = readString(segment.title);
          const description = readString(segment.description);
          const icon = readString(segment.icon);
          const cta = readNavLink(segment.cta);
          const key = segmentId || title;

          return (
            <li key={key}>
              <Card className="h-full border-border">
                <CardContent className="flex h-full flex-col p-6">
                  {icon ? <SectionIcon name={icon} className="mb-3" /> : null}
                  <h3 className="text-h4">{title}</h3>
                  <p className="mt-3 flex-1 text-body text-text-secondary">
                    {description}
                  </p>
                  {cta ? (
                    <Button variant="link" className="mt-4 self-start" asChild>
                      <Link href={cta.href}>
                        {cta.label}
                        <ArrowRight className="h-4 w-4" aria-hidden="true" />
                      </Link>
                    </Button>
                  ) : null}
                </CardContent>
              </Card>
            </li>
          );
        })}
      </ul>
    </SectionShell>
  );
}

import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ElegantCard } from "@/components/ui/elegant-card";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionShell } from "./section-shell";

interface CaseStudiesSectionProps {
  id: string;
  data: Record<string, unknown>;
}

export function CaseStudiesSection({ id, data }: CaseStudiesSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const items = readRecordArray(data.items);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  return (
    <SectionShell id={id} tone="muted" ariaLabelledBy={headingId}>
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
      />
      <ul className="grid gap-6 lg:grid-cols-3">
        {items.map((item) => {
          const metric = readString(item.metric);
          const brand = readString(item.brand);
          const category = readString(item.category);
          const service = readString(item.service);
          const description = readString(item.description);
          const href = readString(item.href);
          const image = readString(item.image);
          const imageAlt = readString(item.imageAlt, brand);
          const key = `${brand}-${metric}`;

          return (
            <li key={key}>
              <ElegantCard className="h-full overflow-hidden bg-background">
                {image ? (
                  <div className="relative aspect-[16/10] border-b border-border bg-surface">
                    <Image
                      src={image}
                      alt={imageAlt || brand}
                      fill
                      className="object-contain p-6"
                      sizes="(max-width: 1024px) 100vw, 33vw"
                      quality={75}
                      loading="lazy"
                    />
                  </div>
                ) : null}
                <div className="flex h-full flex-col p-6">
                  <p className="text-stat text-accent-alt">{metric}</p>
                  <h3 className="mt-3 text-h4">{brand}</h3>
                  {category ? (
                    <p className="mt-1 text-small text-text-secondary">
                      {category}
                    </p>
                  ) : null}
                  {service ? (
                    <Badge variant="outline" className="mt-4 w-fit">
                      {service}
                    </Badge>
                  ) : null}
                  <p className="mt-4 flex-1 text-body text-text-secondary">
                    {description}
                  </p>
                  {href ? (
                    <Button variant="link" className="mt-4 self-start" asChild>
                      <Link href={href}>
                        Read case study <ArrowRight className="h-4 w-4" />
                      </Link>
                    </Button>
                  ) : null}
                </div>
              </ElegantCard>
            </li>
          );
        })}
      </ul>
      {cta ? (
        <div className="mt-10 text-center">
          <Button variant="secondary" asChild>
            <Link href={cta.href}>{cta.label}</Link>
          </Button>
        </div>
      ) : null}
    </SectionShell>
  );
}

import { BrowserMockup } from "@/components/browser-mockup";
import { readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionShell } from "./section-shell";

interface ProcessSectionProps {
  id: string;
  data: Record<string, unknown>;
}

export function ProcessSection({ id, data }: ProcessSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const steps = readRecordArray(data.steps);
  const assurances = readRecordArray(data.assurances);
  const showMockup = Boolean(data.showMockup);
  const mockupVariant =
    readString(data.mockupVariant, "macos") === "ios" ? "ios" : "macos";
  const mockupTabId = readString(data.mockupTabId) || undefined;
  const headingId = `${id}-heading`;

  return (
    <SectionShell id={id} ariaLabelledBy={headingId}>
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
      />
      <ol className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
        {steps.map((step) => {
          const number = readString(step.number);
          const title = readString(step.title);
          const description = readString(step.description);
          const key = `${number}-${title}`;

          return (
            <li
              key={key}
              className="relative rounded-md border border-border bg-surface p-6"
            >
              <p className="text-small font-mono font-medium text-primary">
                {number}
              </p>
              <h3 className="mt-3 text-h4">{title}</h3>
              <p className="mt-2 text-body text-text-secondary">{description}</p>
            </li>
          );
        })}
      </ol>

      {assurances.length > 0 ? (
        <ul className="mt-8 grid gap-3 sm:grid-cols-2">
          {assurances.map((item) => {
            const text = readString(item.text);
            if (!text) return null;
            return (
              <li
                key={text}
                className="rounded-md border border-border bg-background px-4 py-3 text-small text-text-secondary"
              >
                {text}
              </li>
            );
          })}
        </ul>
      ) : null}

      {showMockup ? (
        <div className="mt-10">
          <BrowserMockup variant={mockupVariant} tabId={mockupTabId} />
        </div>
      ) : null}
    </SectionShell>
  );
}

