() => {
  const submit = document.querySelector('#hero-audit-form button[type="submit"], #hero-lead-form button[type="submit"]');
  const form = document.querySelector('#hero-lead-form');
  const hero = document.querySelector('#hero');
  const consent = document.querySelector('#hero-audit-form input[type="checkbox"], #hero-lead-form input[type="checkbox"]');
  const announcement = document.querySelector('[aria-label*="AI assistant"], [role="region"]');
  const header = document.querySelector('header');
  const trust = document.querySelector('#trust-bar');

  function box(el) {
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height), width: Math.round(r.width) };
  }

  const vh = window.innerHeight;
  const vw = window.innerWidth;
  const submitBox = box(submit);
  const formBox = box(form);
  const consentBox = box(consent);

  return {
    viewport: { vw, vh },
    scrollY: window.scrollY,
    announcement: box(announcement),
    header: box(header),
    hero: box(hero),
    form: formBox,
    consent: consentBox,
    submit: submitBox,
    trustTop: trust ? Math.round(trust.getBoundingClientRect().top) : null,
    submitBelowFoldPx: submitBox ? Math.max(0, submitBox.bottom - vh) : null,
