async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3001/', { waitUntil: 'networkidle' });

  const pageQa = await page.evaluate(() => {
    const expectedOrder = [
      'hero','trust-bar','stats','services','creative-showcase','seller-segments',
      'case-studies','brand-values','process','comparison','testimonials',
      'blog-preview','faq','final-cta'
    ];
    const sections = [...document.querySelectorAll('main section[id], #hero, section[id]')]
      .map(s => s.id)
      .filter(Boolean);
    // unique preserve order
    const seen = new Set();
    const order = [];
    for (const id of sections) {
      if (!seen.has(id) && expectedOrder.includes(id)) {
        seen.add(id);
        order.push(id);
      }
    }

    const metaTitle = document.title;
    const metaDesc = document.querySelector('meta[name="description"]')?.getAttribute('content') || '';
    const canonical = document.querySelector('link[rel="canonical"]')?.getAttribute('href') || '';

    const faqQuestions = [...document.querySelectorAll('#faq button, #faq [data-state], #faq h3, #faq summary')]
      .map(el => el.textContent?.trim())
      .filter(Boolean);
    // better: accordion triggers
    const faqTriggers = [...document.querySelectorAll('#faq button')]
      .map(el => el.textContent?.replace(/\s+/g,' ').trim())
      .filter(t => t && t.length > 10);

    const ldScripts = [...document.querySelectorAll('script[type="application/ld+json"]')]
      .map(s => { try { return JSON.parse(s.textContent || ''); } catch { return null; } })
      .filter(Boolean);
    const flat = ldScripts.flatMap(x => Array.isArray(x) ? x : (x['@graph'] || [x]));
    const faqLd = flat.find(x => x && x['@type'] === 'FAQPage');
    const ldQuestions = (faqLd?.mainEntity || []).map(e => e.name);

    const rejected = [
      'ACHIEVE AMAZON SALES GOALS',
      "We're Real. We're Honest",
      'gives a damn',
      'cut the fluff',
      'Pro-level Amazon',
      'Claim your free audit',
      'High-Converting PPC Ads That Attract More Buyers'
    ];
    const bodyText = document.body.innerText;
    const rejectedFound = rejected.filter(r => bodyText.includes(r));

    const imgs = [...document.querySelectorAll('img')].map(img => ({
      src: img.currentSrc || img.src,
      complete: img.complete,
      naturalWidth: img.naturalWidth,
      alt: img.alt || ''
    }));
    const brokenImgs = imgs.filter(i => i.complete && i.naturalWidth === 0);

    const mockup = document.querySelector('#process [class*="browser"], #process [data-browser-mockup], #process');
    const processHasMockup = !!document.querySelector('#process')?.innerHTML.includes('browser') || !!document.querySelector('#process iframe') || !!document.querySelector('#process [class*="Browser"]');
    // check for mockup chrome dots or known structure
    const processMockupVisible = !!document.querySelector('#process .relative') && document.querySelector('#process')?.querySelectorAll('button, [role="tab"]').length >= 0;

    const trustMarquee = document.querySelector('[class*="trust-marquee"], .animate-trust-marquee, [class*="marquee"]');
    const comparisonTable = document.querySelector('#comparison table');
    const testimonials = document.querySelectorAll('#testimonials blockquote, #testimonials article, #testimonials li');

    const heroForm = document.querySelector('#hero-audit-form');
    const honeypot = heroForm?.querySelector('input[name="website"]');
    const consent = heroForm?.querySelector('input[name="consent"], input[type="checkbox"]');

    return {
      order,
      orderMatch: JSON.stringify(order) === JSON.stringify(expectedOrder),
      metaTitle,
      metaDesc,
      canonical,
      faqTriggerCount: faqTriggers.length,
      faqTriggers,
      ldQuestionCount: ldQuestions.length,
      ldQuestions,
      faqLdMatchesVisible: faqTriggers.length > 0 && ldQuestions.length === faqTriggers.length && faqTriggers.every((q,i) => q.includes(ldQuestions[i]?.slice(0,20) || '___') || ldQuestions[i] === q),
      rejectedFound,
      imgCount: imgs.length,
      brokenImgCount: brokenImgs.length,
      brokenImgs: brokenImgs.slice(0,5),
      testimonialCount: testimonials.length,
      hasComparisonTable: !!comparisonTable,
      hasHoneypot: !!honeypot,
      honeypotType: honeypot ? (honeypot.getAttribute('type') || honeypot.type) : null,
      honeypotHidden: honeypot ? (honeypot.getAttribute('tabindex') === '-1' || honeypot.offsetParent === null || getComputedStyle(honeypot).display === 'none' || honeypot.className.includes('hidden') || honeypot.getAttribute('aria-hidden') === 'true' || (honeypot.parentElement && getComputedStyle(honeypot.parentElement).display === 'none')) : false,
      hasConsent: !!consent,
      creativeItems: document.querySelectorAll('#creative-showcase img').length,
      brandValuesItems: document.querySelectorAll('#brand-values li, #brand-values article').length,
      diyLink: !!document.querySelector('#comparison a[href*="amazon-account-management-vs-diy"]'),
      browserMockupInProcess: !!document.querySelector('#process [class*="rounded"]') && document.querySelectorAll('#process img, #process canvas, #process svg').length >= 0 && !!document.querySelector('#process')
    };
  });

  // Better FAQ match: open accordion and get questions from buttons aria
  const faqDetail = await page.evaluate(() => {
    const buttons = [...document.querySelectorAll('#faq button')];
    const questions = buttons.map(b => b.textContent.replace(/\s+/g,' ').trim()).filter(Boolean);
    const ld = [...document.querySelectorAll('script[type="application/ld+json"]')]
      .map(s => { try { return JSON.parse(s.textContent || ''); } catch { return null; } })
      .filter(Boolean)
      .flatMap(x => Array.isArray(x) ? x : (x['@graph'] || [x]))
      .find(x => x && x['@type'] === 'FAQPage');
    const ldQ = (ld?.mainEntity || []).map(e => e.name);
    const match = questions.length === ldQ.length && questions.every((q, i) => q === ldQ[i]);
    return { questions, ldQ, match, count: questions.length };
  });

  // URL checks
  const paths = [
    '/full-service-amazon-agency/',
    '/amazon-ppc-management-agency/',
    '/amazon-listing-optimization/',
    '/amazon-content-writing/',
    '/amazon-visual-creativity/',
    '/amazon-catalog-management/',
    '/case-studies/',
    '/case-study-9/',
    '/case-study-1/',
    '/case-study-2/',
    '/blog/',
    '/when-should-you-use-sponsored-display-ads/',
    '/amazon-account-management-vs-diy/',
    '/free-audit-2/',
    '/amazon-visual-creativity/'
  ];
  const urlResults = [];
  for (const p of paths) {
    const res = await page.request.get('http://localhost:3001' + p);
    urlResults.push({ path: p, status: res.status() });
  }

  // Form smoke: submit without consent should fail; with consent should attempt
  await page.evaluate(() => window.scrollTo(0, 0));
  const formStatus = await page.evaluate(async () => {
    const form = document.querySelector('#hero-audit-form');
    if (!form) return { error: 'no form' };
    const name = form.querySelector('[name="name"]');
    const email = form.querySelector('[name="email"]');
    const phone = form.querySelector('[name="phone"]');
    const consent = form.querySelector('[name="consent"]');
    if (name) name.value = 'Wave F Tester';
    if (email) email.value = 'wavef-test@example.com';
    if (phone) phone.value = '3605550100';
    // ensure consent unchecked
    if (consent && consent.checked) consent.click();
    const submit = form.querySelector('button[type="submit"]');
    submit.click();
    await new Promise(r => setTimeout(r, 800));
    const statusEl = document.querySelector('#hero-audit-form-status');
    const validationMsg = form.querySelector('[aria-invalid="true"], .text-destructive, [role="alert"]');
    return {
      consentRequiredObserved: !consent?.checked,
      statusText: statusEl?.textContent?.trim()?.slice(0, 200) || '',
      alertText: validationMsg?.textContent?.trim()?.slice(0, 200) || '',
      stillOnPage: location.pathname === '/'
    };
  });

  // image lazy check for below-fold
  const imageLoading = await page.evaluate(() => {
    const heroImgs = [...document.querySelectorAll('#hero img')].map(i => i.getAttribute('loading') || (i.getAttribute('fetchpriority') === 'high' ? 'eager-ish' : 'default'));
    const below = [...document.querySelectorAll('#trust-bar img, #case-studies img, #creative-showcase img, #process img')]
      .slice(0, 15)
      .map(i => ({ src: (i.getAttribute('src')||'').slice(-40), loading: i.getAttribute('loading') }));
    return { heroImgs, below };
  });

  // reduced motion class presence
  const motion = await page.evaluate(() => {
    const el = document.querySelector('#trust-bar [class*="marquee"], #trust-bar [class*="animate"]');
    return {
      marqueeClass: el?.className || '',
      hasMotionSafe: !!(el && el.className.includes('motion-safe')),
      hasMotionReduce: !!(el && el.className.includes('motion-reduce'))
    };
  });

  return { pageQa, faqDetail, urlResults, formStatus, imageLoading, motion };
}

