  await lead.locator('#hero-audit-form-email').fill('wavef-test@example.com');
  await lead.locator('#hero-audit-form-phone').fill('+13605550100');
  await lead.locator('#hero-audit-form-consent').check();
  await lead.getByRole('button', { name: /free audit/i }).click();
  await page.waitForTimeout(3000);
  const result = await page.evaluate(() => {
    const status = document.querySelector('#hero-audit-form-status')?.textContent?.trim() || '';
    const errors = [...document.querySelectorAll('#hero-lead-form [id$="-error"]')].map(e => ({ id: e.id, text: e.textContent?.trim() }));
    return { status: status.slice(0, 400), errors };
  });

  // axe details
  await page.addScriptTag({ url: 'https://cdnjs.cloudflare.com/ajax/libs/axe-core/4.10.2/axe.min.js' });
  const axe = await page.evaluate(async () => {
    const results = await axe.run(document, { resultTypes: ['violations'], runOnly: ['wcag2a', 'wcag2aa'] });
    return results.violations.map(v => ({
      id: v.id,
      impact: v.impact,
      help: v.help,
      nodes: v.nodes.slice(0, 3).map(n => ({ html: n.html.slice(0, 120), target: n.target }))
    }));
  });

  // FAQ structure
  const faq = await page.evaluate(() => {
    const items = [...document.querySelectorAll('#faq [data-state], #faq button, #faq h3')].slice(0, 8).map(el => ({
      tag: el.tagName,
      role: el.getAttribute('role'),
      state: el.getAttribute('data-state'),
      expanded: el.getAttribute('aria-expanded'),
      controls: el.getAttribute('aria-controls'),
      text: el.textContent?.trim().slice(0, 60)
    }));
    return { html: document.querySelector('#faq')?.innerHTML.slice(0, 800), items };
  });

  return { result, axe, faq };
}

