"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof primaryButtonVariants> {
  asChild?: boolean;
}

const primaryButtonVariants = cva(
  [
    "relative inline-flex h-11 items-center justify-center gap-2 rounded-sm px-5 text-sm font-medium",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-50",
    // CSS motion avoids motion/react SSR hydration mismatches on form controls.
    "motion-safe:transition-[transform,box-shadow] motion-safe:duration-[250ms] motion-safe:ease-out",
    "motion-safe:hover:-translate-y-px motion-safe:active:translate-y-0 motion-safe:active:scale-[0.99]",
  ].join(" "),
  {
    variants: {
      variant: {
        /** Brand navy — forms, secondary bands */
        primary:
          "bg-primary text-text-on-dark shadow-sm transition-colors duration-300 ease-out hover:bg-accent-alt motion-safe:hover:shadow-[0_6px_20px_rgba(11,27,58,0.15)]",
        /**
         * Accent conversion CTA — header Free Audit.
         * Pattern: Tier C agencies (AMZ Dudes, SalesDuo) use high-contrast fill
         * distinct from navy chrome so the action stands out.
         */
        accent:
          "bg-accent text-primary shadow-sm transition-colors duration-300 ease-out hover:bg-accent-alt hover:text-text-on-dark motion-safe:hover:shadow-[0_6px_20px_rgba(228,121,17,0.28)]",
      },
    },
    defaultVariants: {
      variant: "primary",
    },
  },
);

/**
 * Primary CTA button.
 * Lift/shadow uses CSS + prefers-reduced-motion (not motion/react) so SSR HTML
 * matches the client — critical for hero audit form submit.
 */
const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  (
    { className, children, asChild = false, variant, type = "button", ...props },
    ref,
  ) => {
    const sharedClassName = cn(primaryButtonVariants({ variant }), className);

    if (asChild) {
      return (
        <Slot className={sharedClassName} ref={ref} {...props}>
          {children}
        </Slot>
      );
    }

    return (
      <button ref={ref} type={type} className={sharedClassName} {...props}>
        {children}
      </button>
    );
  },
);
PrimaryButton.displayName = "PrimaryButton";

export { PrimaryButton, primaryButtonVariants };

