      ok: true,
      path,
      height: box ? Math.round(box.height) : null,
      imgCount: await el.locator('img').count(),
      svgCount: await el.locator('svg').count(),
      textPreview: (await el.innerText()).replace(/\s+/g, ' ').slice(0, 160)
    });
  }

  return results;
}

