"use client";

import { useEffect, useState } from "react";

/**
 * Reads prefers-reduced-motion without motion/react's useReducedMotion,
 * which logs a noisy console warning when the OS preference is enabled.
 * Returns false until mounted so SSR/client first paint stay aligned.
 */
export function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(media.matches);
    sync();
    media.addEventListener("change", sync);
    return () => media.removeEventListener("change", sync);
  }, []);

  return reduced;
}

"use client";

import { useEffect, useState } from "react";
import { motion } from "motion/react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

/**
 * Soft ambient page wash + slow drifting orbs (competitor / Framer-light).
 * Opacity matched to Canopy radial blobs (fill-opacity ~0.15–0.20).
 * Orbs mount after hydration; reduced-motion users keep the static wash only.
 */
export function PageAtmosphere() {
  const [hydrated, setHydrated] = useState(false);
  const reduceMotion = usePrefersReducedMotion();

  useEffect(() => {
    setHydrated(true);
  }, []);

  const showOrbs = hydrated && !reduceMotion;

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 -z-10 overflow-hidden"
    >
      <div
        className="absolute inset-0 bg-background"
        style={{
          backgroundImage: "var(--brand-page-atmosphere)",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
        }}
      />

      {showOrbs ? (
        <>
          <motion.div
            className="absolute -left-[12%] -top-[18%] h-[52vmin] w-[52vmin] rounded-full bg-brand-cyan/[0.12] blur-[90px]"
            animate={{
              x: [0, 36, -14, 0],
              y: [0, 20, 36, 0],
              scale: [1, 1.08, 0.98, 1],
            }}
            transition={{
              duration: 24,
              repeat: Infinity,
              ease: "easeInOut",
            }}
          />
          <motion.div
            className="absolute -right-[10%] -top-[8%] h-[48vmin] w-[48vmin] rounded-full bg-accent/[0.1] blur-[90px]"
            animate={{
              x: [0, -30, 12, 0],
              y: [0, 28, 8, 0],
              scale: [1, 0.96, 1.06, 1],
            }}
            transition={{
              duration: 28,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 1.2,
            }}
          />
          <motion.div
            className="absolute bottom-[-22%] left-[28%] h-[56vmin] w-[56vmin] rounded-full bg-primary/[0.07] blur-[100px]"
            animate={{
              x: [0, 24, -18, 0],
              y: [0, -22, -8, 0],
              scale: [1, 1.05, 0.95, 1],
            }}
            transition={{
              duration: 30,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 0.6,
            }}
          />
        </>
      ) : null}
    </div>
  );
}

"use client";

import * as React from "react";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "./card";

interface ElegantCardProps {
  className?: string;
  title?: string;
  description?: string;
  children?: React.ReactNode;
}

const cardMotion = designSystem.motion.card as {
  lift: number;
  duration: number;
};

/**
 * Minimal card hover — CSS lift/shadow respects prefers-reduced-motion
 * without motion/react console warnings.
 */
export function ElegantCard({
  className,
  title,
  description,
  children,
}: ElegantCardProps) {
  const durationMs = cardMotion.duration;

  return (
    <div
      className={cn(
        "rounded-md border border-border transition-[transform,box-shadow,border-color] hover:border-primary/15",
        "motion-safe:hover:-translate-y-1 motion-safe:hover:shadow-[0_8px_24px_rgba(11,27,58,0.08)]",
        className,
      )}
      style={{ transitionDuration: `${durationMs}ms` }}
    >
      <Card className="border-0 shadow-none">
        {(title || description) && (
          <CardHeader>
            {title && <CardTitle>{title}</CardTitle>}
            {description && <CardDescription>{description}</CardDescription>}
          </CardHeader>
        )}
        {children && <CardContent>{children}</CardContent>}
      </Card>
    </div>
  );
}

import { BrowserMockup } from "@/components/browser-mockup";
import { readRecordArray, readString } from "./section-data";
