export function ProcessSection({ id, data }: ProcessSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const steps = readRecordArray(data.steps);
  const assurances = readRecordArray(data.assurances);
  const showMockup = Boolean(data.showMockup);
  const mockupVariant =
    readString(data.mockupVariant, "macos") === "ios" ? "ios" : "macos";
  const mockupTabId = readString(data.mockupTabId) || undefined;
  const headingId = `${id}-heading`;

  return (
    <SectionShell id={id} ariaLabelledBy={headingId}>
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
      />
      <ol className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
        {steps.map((step) => {
          const number = readString(step.number);
          const title = readString(step.title);
          const description = readString(step.description);
          const key = `${number}-${title}`;

          return (
            <li
              key={key}
              className="relative rounded-md border border-border bg-background p-6 shadow-sm"
            >
              <span
                className="inline-flex h-10 w-10 items-center justify-center rounded-md bg-accent/10 font-mono text-small font-semibold text-accent"
                aria-hidden="true"
              >
                {number}
              </span>
              <h3 className="mt-4 text-h4">{title}</h3>
              <p className="mt-2 text-body text-text-secondary">{description}</p>
            </li>
          );
        })}
      </ol>

      {assurances.length > 0 ? (
        <ul className="mt-8 grid gap-3 sm:grid-cols-2">
          {assurances.map((item) => {
            const text = readString(item.text);
