async (page) => {
  const warnings = [];
  const errors = [];
  page.on('console', (msg) => {
    const t = msg.type();
    const text = msg.text();
    if (t === 'warning') warnings.push(text.slice(0, 160));
    if (t === 'error') errors.push(text.slice(0, 200));
  });
  await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  const reducedMotionWarn = warnings.filter(w => /reduced motion/i.test(w));
  return {
    errors,
    reducedMotionWarn,
    otherWarnings: warnings.filter(w => !/reduced motion/i.test(w) && !/React DevTools/i.test(w)).slice(0, 5)
  };
}

