"use client";

import { TrustLogo } from "./trust-logo";

interface TrustClientItem {
  label: string;
  image: string;
  alt: string;
}

interface TrustClientMarqueeProps {
  items: TrustClientItem[];
}

/**
 * CSS marquee for client logos. Pauses on hover/focus-within.
 * prefers-reduced-motion: unique logos in a static wrap (no duplicated ticker track).
 */
export function TrustClientMarquee({ items }: TrustClientMarqueeProps) {
  if (items.length === 0) return null;

  const track = [...items, ...items];

  return (
    <div className="w-full">
      {/* Mobile + reduced-motion desktop: static unique logos */}
      <ul className="flex flex-wrap items-center justify-center gap-x-6 gap-y-3 md:hidden motion-reduce:md:flex">
        {items.map((item) => (
          <li key={`static-${item.image}`}>
            <TrustLogo
              label={item.label}
              image={item.image}
              alt={item.alt}
              variant="client"
            />
          </li>
        ))}
      </ul>

      {/* Desktop with motion allowed: continuous left-to-right ticker */}
      <div
        className="group relative hidden overflow-hidden motion-safe:md:block"
        aria-label="Client brand logos"
      >
        <div
          className="flex w-max items-center gap-10 animate-trust-marquee group-hover:[animation-play-state:paused] group-focus-within:[animation-play-state:paused]"
          tabIndex={0}
        >
          {track.map((item, index) => (
            <div
              key={`${item.image}-${index}`}
              className="shrink-0"
              aria-hidden={index >= items.length ? true : undefined}
            >
              <TrustLogo
                label={item.label}
                image={item.image}
                alt={index >= items.length ? "" : item.alt}
                variant="client"
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

