"use client";

import { useEffect, useState } from "react";
import { motion } from "motion/react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

/**
 * Soft ambient page wash + dotted grid + brand orbs.
 * Reduced-motion: static wash, grid, and soft blobs (no drifting).
 */
export function PageAtmosphere() {
  const [hydrated, setHydrated] = useState(false);
  const reduceMotion = usePrefersReducedMotion();

  useEffect(() => {
    setHydrated(true);
  }, []);

  const showAnimatedOrbs = hydrated && !reduceMotion;

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 -z-10 overflow-hidden"
    >
      <div
        className="absolute inset-0 bg-background"
        style={{
          backgroundImage: "var(--brand-page-atmosphere)",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
        }}
      />

      {/* Framer-style dotted grid — subtle */}
      <div
        className="absolute inset-0 opacity-[0.35]"
        style={{
          backgroundImage:
            "radial-gradient(circle, color-mix(in srgb, #0B1B3A 22%, transparent) 1px, transparent 1px)",
          backgroundSize: "20px 20px",
          maskImage:
            "radial-gradient(ellipse 100% 90% at 50% 40%, #000 40%, transparent 85%)",
          WebkitMaskImage:
            "radial-gradient(ellipse 100% 90% at 50% 40%, #000 40%, transparent 85%)",
        }}
      />

      {/* Static soft blobs */}
      <div className="absolute -left-[12%] -top-[18%] h-[52vmin] w-[52vmin] rounded-full bg-brand-cyan/[0.1] blur-[90px]" />
      <div className="absolute -right-[10%] -top-[8%] h-[48vmin] w-[48vmin] rounded-full bg-accent/[0.09] blur-[90px]" />
      <div className="absolute bottom-[-20%] left-[28%] h-[52vmin] w-[52vmin] rounded-full bg-primary/[0.05] blur-[100px]" />

      {showAnimatedOrbs ? (
        <>
          <motion.div
            className="absolute -left-[12%] -top-[18%] h-[52vmin] w-[52vmin] rounded-full bg-brand-cyan/[0.06] blur-[90px]"
            animate={{
              x: [0, 36, -14, 0],
              y: [0, 20, 36, 0],
              scale: [1, 1.08, 0.98, 1],
            }}
            transition={{
              duration: 24,
              repeat: Infinity,
              ease: "easeInOut",
            }}
          />
          <motion.div
            className="absolute -right-[10%] -top-[8%] h-[48vmin] w-[48vmin] rounded-full bg-accent/[0.05] blur-[90px]"
            animate={{
              x: [0, -30, 12, 0],
              y: [0, 28, 8, 0],
              scale: [1, 0.96, 1.06, 1],
            }}
            transition={{
              duration: 28,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 1.2,
            }}
          />
          <motion.div
            className="absolute bottom-[-20%] left-[28%] h-[52vmin] w-[52vmin] rounded-full bg-primary/[0.04] blur-[100px]"
            animate={{
              x: [0, 24, -18, 0],
              y: [0, -22, -8, 0],
              scale: [1, 1.05, 0.95, 1],
            }}
            transition={{
              duration: 30,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 0.6,
            }}
          />
        </>
      ) : null}
    </div>
  );
}

"use client";

import { useId, useState } from "react";
import { Pause, Play } from "lucide-react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { cn } from "@/lib/utils";
import { TrustLogo } from "./trust-logo";

interface TrustClientItem {
  label: string;
  image: string;
  alt: string;
}

interface TrustClientMarqueeProps {
  items: TrustClientItem[];
}

/**
 * Professional logo strip for every visitor:
 * - Motion allowed: continuous ticker + explicit Pause/Play (WCAG 2.2.2)
 * - Reduced motion: same strip, manual horizontal scroll (no forced animation)
 * Never ignores prefers-reduced-motion.
 */
export function TrustClientMarquee({ items }: TrustClientMarqueeProps) {
  const reduceMotion = usePrefersReducedMotion();
  const labelId = useId();
  const [paused, setPaused] = useState(false);

  if (items.length === 0) return null;

  if (reduceMotion) {
    return (
      <div className="w-full" role="region" aria-labelledby={labelId}>
        <p id={labelId} className="sr-only">
          Client brand logos. Scroll horizontally to browse.
        </p>
        <div className="overflow-x-auto overscroll-x-contain [-ms-overflow-style:none] [scrollbar-width:thin]">
          <ul className="flex w-max min-w-full items-center justify-center gap-8 px-1 py-1">
            {items.map((item) => (
              <li key={item.image} className="shrink-0">
                <TrustLogo
                  label={item.label}
                  image={item.image}
                  alt={item.alt}
                  variant="client"
                />
              </li>
            ))}
          </ul>
        </div>
      </div>
    );
  }

  const track = [...items, ...items];
  const isPaused = paused;

  return (
    <div className="w-full" role="region" aria-labelledby={labelId}>
      <div className="mb-2 flex items-center justify-end md:mb-0 md:absolute md:right-0 md:-top-10">
        <button
          type="button"
          className="inline-flex h-9 items-center gap-1.5 rounded-md border border-border bg-background px-2.5 text-xs font-medium text-text-secondary shadow-sm transition-colors hover:border-accent/40 hover:text-text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
          aria-pressed={isPaused}
          aria-controls={`${labelId}-track`}
          onClick={() => setPaused((value) => !value)}
        >
          {isPaused ? (
            <>
              <Play className="h-3.5 w-3.5" aria-hidden="true" />
              Play logos
            </>
          ) : (
            <>
              <Pause className="h-3.5 w-3.5" aria-hidden="true" />
              Pause logos
            </>
          )}
        </button>
      </div>

      <p id={labelId} className="sr-only">
        Client brand logos. Animation can be paused.
      </p>

      {/* Narrow viewports: manual strip (same logos, no tiny ticker) */}
      <div className="overflow-x-auto overscroll-x-contain md:hidden [-ms-overflow-style:none] [scrollbar-width:thin]">
        <ul className="flex w-max min-w-full items-center justify-center gap-8 px-1 py-1">
          {items.map((item) => (
            <li key={`mobile-${item.image}`} className="shrink-0">
              <TrustLogo
                label={item.label}
                image={item.image}
                alt={item.alt}
                variant="client"
              />
            </li>
          ))}
        </ul>
      </div>

      <div className="group relative hidden overflow-hidden md:block">
        <div
          id={`${labelId}-track`}
          className={cn(
            "flex w-max items-center gap-10 animate-trust-marquee",
            "group-hover:[animation-play-state:paused] group-focus-within:[animation-play-state:paused]",
            isPaused && "[animation-play-state:paused]",
          )}
          tabIndex={0}
        >
          {track.map((item, index) => (
            <div
              key={`${item.image}-${index}`}
              className="shrink-0"
              aria-hidden={index >= items.length ? true : undefined}
            >
              <TrustLogo
                label={item.label}
                image={item.image}
                alt={index >= items.length ? "" : item.alt}
                variant="client"
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

