"use client";

import { useEffect, useId, useRef, useState } from "react";
import { Pause, Play } from "lucide-react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { TrustLogo } from "./trust-logo";

interface TrustClientItem {
  label: string;
  image: string;
  alt: string;
}

interface TrustClientMarqueeProps {
  items: TrustClientItem[];
}

/**
 * Continuous client logo ticker (news-style).
 * Uses JS transform (not CSS animation) so it works even when the OS
 * prefers-reduced-motion kills CSS animations. Auto-plays for motion users;
 * reduced-motion users get a static strip until they press Play (explicit opt-in).
 * Pause always available (WCAG 2.2.2). No visible strip scrollbar.
 */
export function TrustClientMarquee({ items }: TrustClientMarqueeProps) {
  const reduceMotion = usePrefersReducedMotion();
  const labelId = useId();
  const trackRef = useRef<HTMLDivElement>(null);
  const offsetRef = useRef(0);
  const rafRef = useRef<number | null>(null);
  const [paused, setPaused] = useState(true);
  const [hoverPaused, setHoverPaused] = useState(false);

  useEffect(() => {
    // Motion users: start playing. Reduced-motion: stay paused until Play.
    setPaused(Boolean(reduceMotion));
  }, [reduceMotion]);

  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;

    const speedPxPerSec = 36;
    let last = performance.now();

    const tick = (now: number) => {
      const elapsed = now - last;
      last = now;

      if (!paused && !hoverPaused) {
        offsetRef.current -= (speedPxPerSec * elapsed) / 1000;
        const half = track.scrollWidth / 2;
        if (half > 0 && Math.abs(offsetRef.current) >= half) {
          offsetRef.current += half;
        }
        track.style.transform = `translate3d(${offsetRef.current}px, 0, 0)`;
      }

      rafRef.current = requestAnimationFrame(tick);
    };

    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    };
  }, [paused, hoverPaused, items.length]);

  if (items.length === 0) return null;

  const track = [...items, ...items];
  const isPaused = paused || hoverPaused;

  return (
    <div className="relative w-full" role="region" aria-labelledby={labelId}>
      <p id={labelId} className="sr-only">
        Client brand logos scrolling horizontally. Use Pause or Play to control
        the animation.
      </p>

      <div className="mb-3 flex justify-end">
        <button
          type="button"
          className="inline-flex h-9 items-center gap-1.5 rounded-md border border-border bg-background px-2.5 text-xs font-medium text-text-secondary shadow-sm transition-colors hover:border-accent/40 hover:text-text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
          aria-pressed={paused}
          onClick={() => setPaused((value) => !value)}
        >
          {paused ? (
            <>
              <Play className="h-3.5 w-3.5" aria-hidden="true" />
              Play logos
            </>
          ) : (
            <>
              <Pause className="h-3.5 w-3.5" aria-hidden="true" />
              Pause logos
            </>
          )}
        </button>
      </div>

      <div
        className="overflow-hidden"
        onMouseEnter={() => setHoverPaused(true)}
        onMouseLeave={() => setHoverPaused(false)}
        onFocusCapture={() => setHoverPaused(true)}
        onBlurCapture={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget as Node)) {
            setHoverPaused(false);
          }
        }}
      >
        <div
          ref={trackRef}
          className="flex w-max items-center gap-10 will-change-transform"
          style={{ transform: "translate3d(0,0,0)" }}
          aria-hidden={isPaused ? undefined : true}
        >
          {track.map((item, index) => (
            <div
              key={`${item.image}-${index}`}
              className="shrink-0"
              aria-hidden={index >= items.length ? true : undefined}
            >
              <TrustLogo
                label={item.label}
                image={item.image}
                alt={index >= items.length ? "" : item.alt}
                variant="client"
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

