"use client";

import { useId } from "react";
import { TrustLogo } from "./trust-logo";

interface TrustClientItem {
  label: string;
  image: string;
  alt: string;
}

interface TrustClientMarqueeProps {
  items: TrustClientItem[];
}

/**
 * Continuous seamless client logo ticker.
 * Duplicated track + translateX(-50%) CSS loop (no JS reset jitter).
 * Hover pauses briefly for readability. No play/pause chrome.
 */
export function TrustClientMarquee({ items }: TrustClientMarqueeProps) {
  const labelId = useId();

  if (items.length === 0) return null;

  const track = [...items, ...items];

  return (
    <div className="w-full" role="region" aria-labelledby={labelId}>
      <p id={labelId} className="sr-only">
        Client brand logos scrolling continuously.
      </p>

      <div className="group overflow-hidden">
        <div className="flex w-max items-center gap-5 animate-trust-marquee group-hover:[animation-play-state:paused] group-focus-within:[animation-play-state:paused]">
          {track.map((item, index) => (
            <div
              key={`${item.image}-${index}`}
              className="shrink-0"
              aria-hidden={index >= items.length ? true : undefined}
            >
              <TrustLogo
                label={item.label}
                image={item.image}
                alt={index >= items.length ? "" : item.alt}
                variant="client"
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

