 * Pattern reference: Reckap brand-chip (pill, gradient fill, micro-stars, edge light).
 * Colors stay eCom Gliders: cyan / navy / Amazon orange (no purple copy).
 */

const starDots = [
  [14, 12, 0.45, 0.75],
  [32, 26, 0.3, 0.5],
  [48, 10, 0.3, 0.75],
  [64, 24, 0.45, 0.5],
  [78, 14, 0.3, 0.75],
  [88, 28, 0.3, 0.5],
  [22, 30, 0.45, 0.75],
  [56, 32, 0.3, 0.5],
] as const;

type GlowVariant = "brand" | "accent" | "navy";

const fills: Record<GlowVariant, string> = {
  brand: "linear-gradient(90deg, #48cae4 0%, #E47911 55%, #CC6A00 100%)",
  accent: "linear-gradient(90deg, #E47911 0%, #CC6A00 100%)",
  navy: "linear-gradient(90deg, #0B1B3A 0%, #16305F 55%, #E47911 100%)",
};

interface ProposedGlowButtonProps {
  label: string;
  variant?: GlowVariant;
  className?: string;
}

export function ProposedGlowButton({
  label,
  variant = "brand",
  className,
}: ProposedGlowButtonProps) {
  const clipId = `chip-stars-${variant}`;

  return (
    <button
      type="button"
      className={cn(
        "group/chip relative inline-flex h-11 items-center justify-center overflow-hidden rounded-full px-8 text-sm font-semibold text-white",
        "isolation-isolate transition-opacity hover:opacity-95",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
        className,
      )}
    >
      {/* Soft edge lights (decorative) */}
      <span
        aria-hidden="true"
        className="pointer-events-none absolute -left-4 top-1/2 h-10 w-16 -translate-y-1/2 rounded-full bg-white/40 blur-md motion-safe:animate-pulse"
      />
      <span
        aria-hidden="true"
        className="pointer-events-none absolute -right-3 top-1/2 h-8 w-12 -translate-y-1/2 rounded-full bg-white/25 blur-md motion-safe:animate-pulse"
        style={{ animationDelay: "0.8s" }}
      />

      <span
        aria-hidden="true"
        className="absolute inset-[1.5px] z-[1] overflow-hidden rounded-[inherit] shadow-[inset_0_1px_0_rgba(255,255,255,0.35)]"
        style={{ backgroundImage: fills[variant] }}
      >
        <svg
          width="100%"
          height="100%"
          preserveAspectRatio="none"
          viewBox="0 0 100 40"
          fill="none"
          className="pointer-events-none absolute inset-0"
