import { z } from "zod";
import colorThemesJson from "../../content/config/color-themes.json";

const themeColorsSchema = z.record(z.string(), z.string());

const colorThemeSchema = z.object({
  id: z.string(),
  label: z.string(),
  description: z.string(),
  colors: themeColorsSchema,
  gradient: z.string(),
  pageAtmosphere: z.string(),
  ctaFill: z.string(),
  beamFrom: z.string(),
  beamTo: z.string(),
});

const colorThemesFileSchema = z.object({
  note: z.string().optional(),
  defaultThemeId: z.string(),
  themes: z.array(colorThemeSchema).min(1),
});

export type ColorTheme = z.infer<typeof colorThemeSchema>;

export const colorThemesConfig = colorThemesFileSchema.parse(colorThemesJson);

export const COLOR_THEME_STORAGE_KEY = "ecom-gliders-ds-color-theme";

export function getColorThemes(): ColorTheme[] {
  return colorThemesConfig.themes;
}

export function getColorThemeById(id: string): ColorTheme {
  return (
    colorThemesConfig.themes.find((theme) => theme.id === id) ??
    colorThemesConfig.themes[0]
  );
}

/** CSS custom properties applied when previewing a theme on /design-system */
export function themeToCssVariables(theme: ColorTheme): Record<string, string> {
  const vars: Record<string, string> = {};

  for (const [key, value] of Object.entries(theme.colors)) {
    vars[`--color-${key}`] = value;
  }

  vars["--brand-gradient"] = theme.gradient;
  vars["--brand-page-atmosphere"] = theme.pageAtmosphere;
  vars["--proposed-cta-fill"] = theme.ctaFill;
  vars["--beam-from"] = theme.beamFrom;
  vars["--beam-to"] = theme.beamTo;

  return vars;
}

export function applyThemeToDocument(theme: ColorTheme): void {
  if (typeof document === "undefined") return;
  const vars = themeToCssVariables(theme);
  for (const [key, value] of Object.entries(vars)) {
    document.documentElement.style.setProperty(key, value);
  }
  document.documentElement.dataset.colorTheme = theme.id;
}

"use client";

import { useEffect, useState } from "react";
import {
  COLOR_THEME_STORAGE_KEY,
  applyThemeToDocument,
  colorThemesConfig,
  getColorThemeById,
  getColorThemes,
  type ColorTheme,
} from "@/lib/color-themes";
import { cn } from "@/lib/utils";

/**
 * Sticky palette switcher for /design-system only.
 * Applies CSS variables to documentElement so the whole review page updates.
 */
export function ColorThemeSwitcher() {
  const themes = getColorThemes();
  const [activeId, setActiveId] = useState(colorThemesConfig.defaultThemeId);
  const active = getColorThemeById(activeId);

  useEffect(() => {
    const stored = window.localStorage.getItem(COLOR_THEME_STORAGE_KEY);
    const initial = stored
      ? getColorThemeById(stored)
      : getColorThemeById(colorThemesConfig.defaultThemeId);
    setActiveId(initial.id);
    // ThemeReset may apply base tokens on mount — re-apply after a tick.
    const timer = window.setTimeout(() => {
      applyThemeToDocument(initial);
    }, 0);
    return () => window.clearTimeout(timer);
  }, []);

  function selectTheme(theme: ColorTheme) {
    setActiveId(theme.id);
    applyThemeToDocument(theme);
    window.localStorage.setItem(COLOR_THEME_STORAGE_KEY, theme.id);
  }

  return (
    <div className="sticky top-[4.5rem] z-40 mb-8 rounded-md border border-border bg-background/95 p-4 shadow-sm backdrop-blur">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <p className="text-small font-semibold text-text-primary">
            Color theme switcher
          </p>
          <p className="text-small mt-1 max-w-xl text-text-secondary">
            Switch all five styles live on this page (tokens, buttons, cards,
            atmosphere). Active:{" "}
            <span className="font-medium text-text-primary">{active.label}</span>
          </p>
        </div>
      </div>

      <div
        className="mt-4 flex flex-wrap gap-2"
        role="tablist"
        aria-label="Color theme variants"
      >
        {themes.map((theme) => {
          const selected = theme.id === activeId;
          return (
            <button
              key={theme.id}
              type="button"
              role="tab"
              aria-selected={selected}
              onClick={() => selectTheme(theme)}
              className={cn(
                "inline-flex min-h-10 items-center gap-2 rounded-md border px-3 py-2 text-xs font-medium transition-colors",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
                selected
                  ? "border-accent bg-accent/10 text-text-primary"
                  : "border-border bg-surface text-text-secondary hover:border-accent/40 hover:text-text-primary",
              )}
            >
              <span className="flex items-center gap-1" aria-hidden="true">
                <span
                  className="h-3 w-3 rounded-full border border-border"
                  style={{ backgroundColor: theme.colors.primary }}
                />
                <span
                  className="h-3 w-3 rounded-full border border-border"
                  style={{ backgroundColor: theme.colors.accent }}
                />
                <span
                  className="h-3 w-3 rounded-full border border-border"
                  style={{ backgroundColor: theme.colors.brandCyan }}
                />
              </span>
              {theme.label}
            </button>
          );
        })}
      </div>

      <p className="text-small mt-3 text-text-secondary">{active.description}</p>
      {colorThemesConfig.note ? (
        <p className="text-small mt-2 text-text-secondary/80">
          {colorThemesConfig.note}
        </p>
      ) : null}
    </div>
  );
}

