"use client";

import { useEffect, useState } from "react";
import { cn } from "@/lib/utils";

export type AtmosphereMode = "white" | "soft" | "framer" | "framer-grid";

export const ATMOSPHERE_MODE_KEY = "ecom-gliders-ds-atmosphere-mode";

const MODE_OPTIONS: { id: AtmosphereMode; label: string }[] = [
  { id: "white", label: "White" },
  { id: "soft", label: "Soft gradient" },
  { id: "framer", label: "Framer mesh" },
  { id: "framer-grid", label: "Framer + grid" },
];

/**
 * Design-system-only page atmosphere.
 * Stronger Framer-style mesh so palette pairs are obvious while reviewing.
 */
export function DesignSystemAtmosphere({ mode }: { mode: AtmosphereMode }) {
  if (mode === "white") {
    return (
      <div
        aria-hidden="true"
        className="pointer-events-none fixed inset-0 -z-10 bg-white"
      />
    );
  }

  const showGrid = mode === "framer-grid";
  const strong = mode === "framer" || mode === "framer-grid";

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 -z-10 overflow-hidden"
    >
      {/* Base wash from active theme */}
      <div
        className="absolute inset-0"
        style={{
          backgroundColor: "var(--color-background)",
          backgroundImage:
            mode === "soft"
              ? "var(--brand-page-atmosphere)"
              : undefined,
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
        }}
      />

      {strong ? (
        <>
          {/* Framer-style mesh: large blurred orbs from theme primary/accent */}
          <div
            className="absolute -left-[20%] -top-[25%] h-[70vmin] w-[70vmin] rounded-full blur-[100px]"
            style={{
              background:
                "color-mix(in srgb, var(--color-primary) 45%, transparent)",
            }}
          />
          <div
            className="absolute -right-[18%] top-[-10%] h-[65vmin] w-[65vmin] rounded-full blur-[110px]"
            style={{
              background:
                "color-mix(in srgb, var(--color-accent) 55%, transparent)",
            }}
          />
          <div
            className="absolute bottom-[-20%] left-[20%] h-[60vmin] w-[60vmin] rounded-full blur-[120px]"
            style={{
              background:
                "color-mix(in srgb, var(--color-brand-cyan) 40%, transparent)",
            }}
          />
          <div
            className="absolute right-[10%] top-[40%] h-[40vmin] w-[40vmin] rounded-full blur-[90px]"
            style={{
              background:
                "color-mix(in srgb, var(--color-accent-alt) 30%, transparent)",
            }}
          />
          {/* Soft vignette so content stays readable */}
          <div
            className="absolute inset-0"
            style={{
              background:
                "radial-gradient(ellipse 80% 70% at 50% 40%, transparent 20%, color-mix(in srgb, var(--color-background) 55%, transparent) 100%)",
            }}
          />
        </>
      ) : null}

      {showGrid ? (
        <div
          className="absolute inset-0 opacity-50"
          style={{
            backgroundImage:
              "radial-gradient(circle, color-mix(in srgb, var(--color-primary) 35%, transparent) 1.1px, transparent 1.1px)",
            backgroundSize: "18px 18px",
            maskImage:
              "radial-gradient(ellipse 110% 100% at 50% 40%, #000 45%, transparent 90%)",
            WebkitMaskImage:
              "radial-gradient(ellipse 110% 100% at 50% 40%, #000 45%, transparent 90%)",
          }}
        />
      ) : null}
    </div>
  );
}

interface AtmosphereModeToggleProps {
  mode: AtmosphereMode;
  onChange: (mode: AtmosphereMode) => void;
}

export function AtmosphereModeToggle({
  mode,
  onChange,
}: AtmosphereModeToggleProps) {
  return (
    <div className="mt-4 border-t border-border pt-4">
      <p className="text-small font-semibold text-text-primary">
        Page background
      </p>
      <p className="text-small mt-1 text-text-secondary">
        Toggle white vs Framer-style mesh so palette pairs read clearly.
      </p>
      <div
        className="mt-3 flex flex-wrap gap-2"
        role="tablist"
        aria-label="Page background mode"
      >
        {MODE_OPTIONS.map((option) => {
          const selected = option.id === mode;
          return (
            <button
              key={option.id}
              type="button"
              role="tab"
              aria-selected={selected}
              onClick={() => onChange(option.id)}
              className={cn(
                "inline-flex min-h-9 items-center rounded-md border px-3 py-1.5 text-xs font-medium transition-colors",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
                selected
                  ? "border-accent bg-accent/10 text-text-primary"
                  : "border-border bg-surface text-text-secondary hover:border-accent/40 hover:text-text-primary",
              )}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

/** Combines color theme + atmosphere controls for /design-system */
export function useAtmosphereMode() {
  const [mode, setMode] = useState<AtmosphereMode>("framer-grid");

  useEffect(() => {
    const stored = window.localStorage.getItem(ATMOSPHERE_MODE_KEY);
    if (
      stored === "white" ||
      stored === "soft" ||
      stored === "framer" ||
      stored === "framer-grid"
    ) {
      setMode(stored);
    }
  }, []);

  function updateMode(next: AtmosphereMode) {
    setMode(next);
    window.localStorage.setItem(ATMOSPHERE_MODE_KEY, next);
  }

  return { mode, setMode: updateMode };
}

