import { useEffect, useState } from "react";
import {
  COLOR_THEME_STORAGE_KEY,
  applyThemeToDocument,
  colorThemesConfig,
  getColorThemeById,
  getColorThemes,
  type ColorTheme,
} from "@/lib/color-themes";
import { cn } from "@/lib/utils";
import {
  AtmosphereModeToggle,
  DesignSystemAtmosphere,
  useAtmosphereMode,
} from "./design-system-atmosphere";

/**
 * Sticky palette + background switcher for /design-system.
 * Applies CSS variables to documentElement; Framer mesh shows theme colors.
 */
export function ColorThemeSwitcher() {
  const themes = getColorThemes();
  const [activeId, setActiveId] = useState(colorThemesConfig.defaultThemeId);
  const active = getColorThemeById(activeId);
  const { mode, setMode } = useAtmosphereMode();

  useEffect(() => {
    const stored = window.localStorage.getItem(COLOR_THEME_STORAGE_KEY);
    const initial = stored
      ? getColorThemeById(stored)
      : getColorThemeById(colorThemesConfig.defaultThemeId);
    setActiveId(initial.id);
    const timer = window.setTimeout(() => {
      applyThemeToDocument(initial);
    }, 0);
    return () => window.clearTimeout(timer);
  }, []);

  function selectTheme(theme: ColorTheme) {
    setActiveId(theme.id);
    applyThemeToDocument(theme);
    window.localStorage.setItem(COLOR_THEME_STORAGE_KEY, theme.id);
  }

  return (
    <>
      <DesignSystemAtmosphere mode={mode} />

      <div className="sticky top-[4.5rem] z-40 mb-8 rounded-md border border-border bg-background/90 p-4 shadow-sm backdrop-blur-md">
