          <div>
            <p className="text-small font-semibold text-text-primary">
              Color theme switcher
            </p>
            <p className="text-small mt-1 max-w-xl text-text-secondary">
              Switch all five WhatsApp pairs live. Active:{" "}
              <span className="font-medium text-text-primary">
                {active.label}
              </span>
            </p>
          </div>
        </div>

        <div
          className="mt-4 flex flex-wrap gap-2"
          role="tablist"
          aria-label="Color theme variants"
        >
          {themes.map((theme) => {
            const selected = theme.id === activeId;
            return (
              <button
                key={theme.id}
                type="button"
                role="tab"
                aria-selected={selected}
                onClick={() => selectTheme(theme)}
                className={cn(
                  "inline-flex min-h-10 items-center gap-2 rounded-md border px-3 py-2 text-xs font-medium transition-colors",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
                  selected
                    ? "border-accent bg-accent/10 text-text-primary"
                    : "border-border bg-surface/80 text-text-secondary hover:border-accent/40 hover:text-text-primary",
                )}
              >
                <span className="flex items-center gap-1" aria-hidden="true">
                  <span
                    className="h-3 w-3 rounded-full border border-border"
                    style={{ backgroundColor: theme.colors.primary }}
                  />
                  <span
                    className="h-3 w-3 rounded-full border border-border"
                    style={{ backgroundColor: theme.colors.accent }}
                  />
                </span>
                {theme.label}
              </button>
            );
          })}
        </div>

        <p className="text-small mt-3 text-text-secondary">
          {active.description}
        </p>

        <AtmosphereModeToggle mode={mode} onChange={setMode} />
      </div>
    </>
  );
}

