"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof primaryButtonVariants> {
  asChild?: boolean;
}

const primaryButtonVariants = cva(
  [
    "btn-border-beam group relative inline-flex items-center justify-center rounded-full p-[2px]",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-50",
  ].join(" "),
  {
    variants: {
      variant: {
        /** Navy fill + rotating accent beam — default sitewide CTA */
        primary: "",
        /** Same beam treatment (kept for call-site compatibility) */
        accent: "",
      },
      size: {
        default: "h-11 min-h-11",
        sm: "h-10 min-h-10",
      },
    },
    defaultVariants: {
      variant: "primary",
      size: "default",
    },
  },
);

const primaryButtonFillVariants = cva(
  [
    "btn-border-beam-fill relative z-[1] inline-flex h-full w-full items-center justify-center gap-2 rounded-full",
    "text-text-on-dark",
    "motion-safe:transition-transform motion-safe:duration-200 motion-safe:ease-out",
    "motion-safe:group-hover:-translate-y-px motion-safe:group-active:translate-y-0",
  ].join(" "),
  {
    variants: {
      size: {
        default: "px-5 text-sm font-semibold",
        sm: "px-3 text-xs font-semibold",
      },
    },
    defaultVariants: {
      size: "default",
    },
  },
);

function renderFill(
  children: React.ReactNode,
  size: VariantProps<typeof primaryButtonFillVariants>["size"],
) {
  return (
    <span className={primaryButtonFillVariants({ size })}>{children}</span>
  );
}

/**
 * Sitewide primary CTA — Framer-style rotating border beam.
 * Navy body sheen; accent color travels the pill edge.
 * Lift uses CSS + prefers-reduced-motion (no motion/react) for SSR-safe forms.
 */
const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  (
    {
      className,
      children,
      asChild = false,
      variant,
      size,
      type = "button",
      ...props
    },
    ref,
  ) => {
    const outerClassName = cn(
      primaryButtonVariants({ variant, size }),
      className,
    );

    if (asChild) {
      if (!React.isValidElement(children)) {
        return null;
      }

      const child = children as React.ReactElement<{
        className?: string;
        children?: React.ReactNode;
      }>;

      return (
        <Slot
          className={cn(outerClassName, child.props.className)}
          ref={ref}
          {...props}
        >
          {React.cloneElement(child, {
            className: undefined,
            children: renderFill(child.props.children, size),
          })}
        </Slot>
      );
    }

    return (
      <button
        ref={ref}
        type={type}
        className={outerClassName}
        {...props}
      >
        {renderFill(children, size)}
      </button>
    );
  },
);
PrimaryButton.displayName = "PrimaryButton";

export { PrimaryButton, primaryButtonVariants };

