() => {
  const buttons = [...document.querySelectorAll('a, button')].filter(el => {
    const t = (el.textContent || '').toLowerCase();
    return t.includes('get started') || t.includes('contact') || t.includes('book') || t.includes('talk') || t.includes('audit') || t.includes('free') || /cta|btn/i.test(el.className);
  }).slice(0, 12);
  return buttons.map(el => {
    const s = getComputedStyle(el);
    return {
      text: (el.textContent || '').trim().slice(0, 60),
      tag: el.tagName,
      className: String(el.className).slice(0, 120),
      bg: s.backgroundImage || s.background,
      bgColor: s.backgroundColor,
      borderRadius: s.borderRadius,
      color: s.color,
      boxShadow: s.boxShadow.slice(0, 200),
      padding: s.padding,
      width: Math.round(el.getBoundingClientRect().width),
      height: Math.round(el.getBoundingClientRect().height),
    };
  });
}

() => {
  const el = [...document.querySelectorAll('a')].find(a => (a.textContent||'').trim() === 'Book a call' && a.className.includes('brand-chip'));
  if (!el) return { error: 'not found' };
  const kids = [...el.querySelectorAll('*')].slice(0, 20).map(k => {
    const s = getComputedStyle(k);
    return {
      tag: k.tagName,
      className: String(k.className).slice(0, 160),
      bg: (s.backgroundImage !== 'none' ? s.backgroundImage : s.backgroundColor).slice(0, 300),
      opacity: s.opacity,
      position: s.position,
      inset: [s.top, s.right, s.bottom, s.left].join(','),
      transform: s.transform,
      filter: s.filter,
    };
  });
  const s = getComputedStyle(el);
  return {
    outerBg: s.backgroundImage.slice(0, 300),
    outerClass: String(el.className).slice(0, 250),
    html: el.innerHTML.slice(0, 800),
    kids,
  };
}

