interface BouncyIconProps {
  children: React.ReactElement<{ className?: string; "aria-hidden"?: boolean | string }>;
  className?: string;
}

/**
 * Framer-style bouncy icon (https://bouncy.learnframer.site/):
 * on parent `.group` hover, icon exits up and a second copy enters from below.
 * Uses Tailwind group-hover so the motion always binds to PrimaryButton/Button.
 */
export function BouncyIcon({ children, className }: BouncyIconProps) {
  const childClassName = children.props.className;

  return (
    <span
      className={cn(
        "btn-bouncy-icon relative inline-flex shrink-0 items-center justify-center overflow-hidden",
        childClassName,
        className,
      )}
      aria-hidden="true"
    >
      {React.cloneElement(children, {
        className: cn(
          childClassName,
          "btn-bouncy-icon__face block size-full transition-transform duration-300 ease-out",
          "group-hover:-translate-y-[120%] group-focus-visible:-translate-y-[120%]",
          "group-hover/btn:-translate-y-[120%] group-focus-visible/btn:-translate-y-[120%]",
        ),
        "aria-hidden": true,
      })}
      {React.cloneElement(children, {
        className: cn(
          childClassName,
          "btn-bouncy-icon__face btn-bouncy-icon__face--in pointer-events-none absolute inset-0 block size-full transition-transform duration-300 ease-out",
          "translate-y-[120%]",
          "group-hover:translate-y-0 group-focus-visible:translate-y-0",
          "group-hover/btn:translate-y-0 group-focus-visible/btn:translate-y-0",
        ),
        "aria-hidden": true,
      })}
    </span>
  );
}

function isIconElement(
  child: React.ReactNode,
): child is React.ReactElement<{
  className?: string;
  "aria-hidden"?: boolean | string;
}> {
  if (!React.isValidElement(child)) return false;
  const type = child.type;
  if (typeof type === "string") return false;
  const props = child.props as { "aria-hidden"?: boolean | string };
  const name =
    (type as { displayName?: string; name?: string }).displayName ||
    (type as { displayName?: string; name?: string }).name ||
    "";
  if (props["aria-hidden"] === true || props["aria-hidden"] === "true") {
    return true;
  }
  return /Arrow|Chevron|Icon|Lucide|Plus|Check|External/i.test(name);
}

/** Wraps Lucide (and similar) icon children for bouncy hover inside buttons. */
export function wrapBouncyIcons(children: React.ReactNode): React.ReactNode {
  return React.Children.map(children, (child) => {
    if (!isIconElement(child)) return child;
    return <BouncyIcon>{child}</BouncyIcon>;
  });
}

