"use client";

import * as React from "react";
import {
  ArrowRightIcon,
  type ArrowRightIconHandle,
} from "lucide-animated";
import { cn } from "@/lib/utils";

interface CtaArrowIconProps {
  className?: string;
  /** Pixel size of the animated glyph. Slot stays fixed to avoid layout shift. */
  size?: number;
}

/**
 * Framer-style CTA trailing mark:
 * idle = filled dot (reserved slot, no layout shift)
 * hover = dot blends out, lucide-animated ArrowRight plays
 * @see https://bouncy.learnframer.site/
 * @see https://lucide-animated.com/
 */
export function CtaArrowIcon({ className, size = 16 }: CtaArrowIconProps) {
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const iconRef = React.useRef<ArrowRightIconHandle>(null);

  React.useEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    const host = root.closest("button, a, [data-cta-icon-host]") ?? root;

    const start = () => iconRef.current?.startAnimation();
    const stop = () => iconRef.current?.stopAnimation();

    host.addEventListener("mouseenter", start);
    host.addEventListener("mouseleave", stop);
    host.addEventListener("focusin", start);
    host.addEventListener("focusout", stop);

    return () => {
      host.removeEventListener("mouseenter", start);
      host.removeEventListener("mouseleave", stop);
      host.removeEventListener("focusin", start);
      host.removeEventListener("focusout", stop);
    };
  }, []);

  return (
    <span
      ref={rootRef}
      className={cn("btn-cta-icon", className)}
      aria-hidden="true"
    >
      <span className="btn-cta-icon__dot" />
      <ArrowRightIcon
        ref={iconRef}
        size={size}
        className="btn-cta-icon__glyph"
      />
    </span>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { CtaArrowIcon } from "@/components/ui/cta-arrow-icon";

export type IconMotionDirection = "ltr" | "rtl" | "ttb" | "btt";

interface BouncyIconProps {
  children: React.ReactElement<{ className?: string; "aria-hidden"?: boolean | string }>;
  className?: string;
  direction?: IconMotionDirection;
}

function iconName(
  type: string | React.JSXElementConstructor<unknown>,
): string {
  if (typeof type === "string") return type;
  const t = type as { displayName?: string; name?: string };
  return t.displayName || t.name || "";
}

function directionFromIconName(name: string): IconMotionDirection {
  if (/Left|ChevronLeft/i.test(name)) return "ltr";
  if (/Up|ChevronUp/i.test(name)) return "ttb";
  if (/Down|ChevronDown/i.test(name)) return "btt";
  return "rtl";
}

function sizeFromClassName(className?: string): number {
  if (!className) return 16;
  if (/\bh-5\b|\bw-5\b|\bsize-5\b/.test(className)) return 20;
  if (/\bh-3\.5\b|\bw-3\.5\b/.test(className)) return 14;
  if (/\bh-3\b|\bw-3\b|\bsize-3\b/.test(className)) return 12;
  return 16;
}

function isArrowRightIcon(
  child: React.ReactElement<{ className?: string }>,
): boolean {
  return /^(ArrowRight|ArrowRightIcon)$/i.test(iconName(child.type));
}

/**
 * Fallback for non-arrow icons: fixed slot, dot → glyph blend on hover.
 */
export function BouncyIcon({
  children,
  className,
  direction,
}: BouncyIconProps) {
  const childClassName = children.props.className;
  const name = iconName(children.type);
  const motion = direction ?? directionFromIconName(name);

  return (
    <span
      className={cn(
        "btn-cta-icon",
        `btn-bouncy-icon--${motion}`,
        childClassName,
        className,
      )}
      aria-hidden="true"
    >
      <span className="btn-cta-icon__dot" />
      <span className="btn-cta-icon__glyph btn-bouncy-icon__face">
        {React.cloneElement(children, {
          className: cn(childClassName, "size-full"),
          "aria-hidden": true,
        })}
      </span>
    </span>
  );
}

function isIconElement(
  child: React.ReactNode,
): child is React.ReactElement<{
  className?: string;
  "aria-hidden"?: boolean | string;
}> {
  if (!React.isValidElement(child)) return false;
  const type = child.type;
  if (typeof type === "string") return false;
  const props = child.props as { "aria-hidden"?: boolean | string };
  const name = iconName(type);
  if (props["aria-hidden"] === true || props["aria-hidden"] === "true") {
    return true;
  }
  return /Arrow|Chevron|Icon|Lucide|Plus|Check|External/i.test(name);
}

/**
 * Button trailing icons:
 * - ArrowRight → lucide-animated + dot blend ([lucide-animated.com](https://lucide-animated.com/))
 * - other icons → dot blend + directional reveal
 */
export function wrapBouncyIcons(children: React.ReactNode): React.ReactNode {
  return React.Children.map(children, (child) => {
    if (!isIconElement(child)) return child;
    if (isArrowRightIcon(child)) {
      return (
        <CtaArrowIcon
          className={child.props.className}
          size={sizeFromClassName(child.props.className)}
        />
      );
    }
    return <BouncyIcon>{child}</BouncyIcon>;
  });
}

