          const icon = readString(item.icon, "briefcase");
          const number = readString(item.number);

          const card = (
            <ElegantCard className="h-full bg-transparent">
              <div className="relative flex h-full flex-col p-5 sm:p-6">
                {number ? (
                  <span
                    className="pointer-events-none absolute right-4 top-3 font-mono text-4xl font-semibold leading-none text-primary/10 sm:right-5 sm:top-4 sm:text-5xl"
                    aria-hidden="true"
                  >
                    {number}
                  </span>
                ) : null}
                <SectionIcon name={icon} framed tone="primary" className="mb-3" />
                <h3 className="text-h4 pr-10 text-primary">{title}</h3>
                <p className="mt-2 flex-1 text-small text-text-secondary sm:text-body">
