                {href ? (
                  <span className="mt-3 inline-flex items-center gap-2 text-small font-semibold text-primary transition-colors group-hover:text-accent group-focus-visible:text-accent">
                    Learn more
                    <ArrowRight className="h-4 w-4" aria-hidden="true" />
                  </span>
                ) : null}
              </div>
            </ElegantCard>
          );

          return (
            <li key={title}>
              {href ? (
                <Link
                  href={href}
                  aria-label={`Learn more about ${title}`}
                  className="group block h-full rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                >
                  {card}
                </Link>
              ) : (
                card
              )}
            </li>
          );
        })}
      </ul>
    </SectionShell>
  );
}

