"use client";

import { useId } from "react";
import { cn } from "@/lib/utils";
import { TrustLogo } from "./trust-logo";

interface TrustClientItem {
  label: string;
  image: string;
  alt: string;
}

interface TrustClientMarqueeProps {
  items: TrustClientItem[];
}

function MarqueeRibbon({
  items,
  direction,
  labelId,
}: {
  items: TrustClientItem[];
  direction: "ltr" | "rtl";
  labelId?: string;
}) {
  if (items.length === 0) return null;

  const track = [...items, ...items];

  return (
    <div className="group overflow-hidden" {...(labelId ? { "aria-labelledby": labelId } : {})}>
      <div
        className={cn(
          "flex w-max items-center gap-5 group-hover:[animation-play-state:paused] group-focus-within:[animation-play-state:paused]",
          direction === "rtl"
            ? "animate-trust-marquee-reverse"
            : "animate-trust-marquee",
        )}
      >
        {track.map((item, index) => (
          <div
            key={`${direction}-${item.image}-${index}`}
            className="shrink-0"
            aria-hidden={index >= items.length ? true : undefined}
          >
            <TrustLogo
              label={item.label}
              image={item.image}
              alt={index >= items.length ? "" : item.alt}
              variant="client"
            />
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * Dual continuous client logo ribbons — opposite directions for visual depth.
 * Hover pauses the hovered ribbon. No play/pause chrome.
 */
export function TrustClientMarquee({ items }: TrustClientMarqueeProps) {
  const labelId = useId();

  if (items.length === 0) return null;

  const mid = Math.ceil(items.length / 2);
  const rowA = items.slice(0, mid);
  const rowB = items.slice(mid);

  // Single short list: still show two ribbons by reusing with reverse motion
  const topRow = rowA.length > 0 ? rowA : items;
  const bottomRow = rowB.length > 0 ? rowB : [...items].reverse();

  return (
    <div className="flex w-full flex-col gap-3" role="region" aria-labelledby={labelId}>
      <p id={labelId} className="sr-only">
        Client brand logos scrolling continuously in two rows.
      </p>
      <MarqueeRibbon items={topRow} direction="ltr" />
      <MarqueeRibbon items={bottomRow} direction="rtl" />
    </div>
  );
}

