"use client";

import { useId } from "react";
import { cn } from "@/lib/utils";
import { TrustLogo } from "./trust-logo";

interface TrustClientItem {
  label: string;
  image: string;
  alt: string;
}

interface TrustClientMarqueeProps {
  items: TrustClientItem[];
}

/** Repeat a set until long enough, then duplicate for seamless -50% loop. */
function buildSeamlessTrack(items: TrustClientItem[], minItems = 8): TrustClientItem[] {
  if (items.length === 0) return [];
  const cycle: TrustClientItem[] = [];
  while (cycle.length < minItems) {
    cycle.push(...items);
  }
  return [...cycle, ...cycle];
}

function MarqueeRibbon({
  items,
  direction,
}: {
  items: TrustClientItem[];
  direction: "ltr" | "rtl";
}) {
  if (items.length === 0) return null;

  const track = buildSeamlessTrack(items);
  const half = track.length / 2;

  return (
    <div className="group overflow-hidden">
      <div
        className={cn(
          "flex w-max items-center gap-6 group-hover:[animation-play-state:paused] group-focus-within:[animation-play-state:paused]",
          direction === "rtl"
            ? "animate-trust-marquee-reverse"
            : "animate-trust-marquee",
        )}
      >
        {track.map((item, index) => (
          <div
            key={`${direction}-${item.image}-${index}`}
            className="shrink-0"
            aria-hidden={index >= half ? true : undefined}
          >
            <TrustLogo
              label={item.label}
              image={item.image}
              alt={index >= half ? "" : item.alt}
              variant="client"
            />
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * Dual continuous client logo ribbons — opposite directions.
 * Track is padded + duplicated so the loop never shows a blank gap.
 */
export function TrustClientMarquee({ items }: TrustClientMarqueeProps) {
  const labelId = useId();

  if (items.length === 0) return null;

  const mid = Math.ceil(items.length / 2);
  const rowA = items.slice(0, mid);
  const rowB = items.slice(mid);
  const topRow = rowA.length > 0 ? rowA : items;
  const bottomRow = rowB.length > 0 ? rowB : [...items].reverse();

  return (
    <div className="flex w-full flex-col gap-3.5" role="region" aria-labelledby={labelId}>
      <p id={labelId} className="sr-only">
        Client brand logos scrolling continuously in two rows.
      </p>
      <MarqueeRibbon items={topRow} direction="ltr" />
      <MarqueeRibbon items={bottomRow} direction="rtl" />
    </div>
  );
}

