"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionShell } from "./section-shell";

interface ServicesSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface ServiceItem {
  title: string;
  description: string;
  href: string;
  number: string;
  image: string;
  imageAlt: string;
}

/**
 * Interactive service explorer — numbered rail + live preview panel.
 * Premium agency pattern: hover/focus swaps the large visual (OS-independent CSS).
 */
export function ServicesSection({ id, data }: ServicesSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const headingId = `${id}-heading`;

  const items: ServiceItem[] = readRecordArray(data.items)
    .map((item) => {
      const title = readString(item.title);
      const description = readString(item.description);
      const href = readString(item.href);
      const number = readString(item.number);
      const image = readString(item.image);
      const imageAlt = readString(item.imageAlt, title);
      if (!title) return null;
      return { title, description, href, number, image, imageAlt };
    })
    .filter((item): item is ServiceItem => item !== null);

  const [activeIndex, setActiveIndex] = useState(0);
  const active = items[activeIndex] ?? items[0];

  if (items.length === 0) return null;

  return (
    <SectionShell
      id={id}
      tone="muted"
      ariaLabelledBy={headingId}
      className="py-14 sm:py-16"
    >
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
        className="mb-10 max-w-2xl md:mb-12"
      />

      <div className="grid items-start gap-8 lg:grid-cols-12 lg:gap-12">
        {/* Preview — mobile first (above list), sticky on desktop */}
        <div className="order-1 lg:order-2 lg:col-span-7 lg:sticky lg:top-28">
          <div className="service-explorer-stage relative aspect-[4/3] overflow-hidden rounded-xl border border-border/60 bg-primary shadow-[0_20px_50px_rgba(11,27,58,0.12)] sm:aspect-[16/11]">
            {items.map((item, index) =>
              item.image ? (
                <Image
                  key={item.image}
                  src={item.image}
                  alt={item.imageAlt}
                  fill
                  sizes="(max-width: 1024px) 100vw, 58vw"
                  quality={80}
                  className={cn(
                    "object-cover transition-opacity duration-500 ease-out",
                    index === activeIndex ? "opacity-100" : "opacity-0",
                  )}
                  priority={index === 0}
                />
              ) : null,
            )}

            {/* Soft vignette + live caption */}
            <div
              className="pointer-events-none absolute inset-0 bg-gradient-to-t from-primary/80 via-primary/15 to-transparent"
              aria-hidden="true"
            />
            {active ? (
              <div className="absolute inset-x-0 bottom-0 z-10 p-5 sm:p-7">
                <p className="font-mono text-xs font-semibold tracking-[0.14em] text-text-on-dark/70">
                  {active.number || String(activeIndex + 1).padStart(2, "0")}
                </p>
                <p className="mt-1 text-h4 text-text-on-dark sm:text-h3">
                  {active.title}
                </p>
              </div>
            ) : null}
          </div>
        </div>

        {/* Interactive rail */}
        <ol className="order-2 divide-y divide-border/70 border-y border-border/70 lg:order-1 lg:col-span-5">
          {items.map((item, index) => {
            const isActive = index === activeIndex;
            const number =
              item.number || String(index + 1).padStart(2, "0");

            const rowClass = cn(
              "group/row flex w-full flex-col gap-2 py-4 text-left transition-colors duration-300 sm:py-5",
              isActive ? "bg-background/60" : "hover:bg-background/40",
            );

            const inner = (
              <>
                <div className="flex items-start gap-4 px-1 sm:gap-5 sm:px-2">
                  <span
                    className={cn(
                      "mt-0.5 font-mono text-xs font-semibold tracking-[0.14em] transition-colors",
                      isActive ? "text-accent" : "text-text-secondary",
                    )}
                  >
                    {number}
                  </span>
                  <div className="min-w-0 flex-1">
                    <span
                      className={cn(
                        "block text-h4 transition-colors",
                        isActive ? "text-primary" : "text-primary/80",
                      )}
                    >
                      {item.title}
                    </span>
                    <div
                      className={cn(
                        "grid transition-[grid-template-rows,opacity] duration-300 ease-out",
                        isActive
                          ? "grid-rows-[1fr] opacity-100"
                          : "grid-rows-[0fr] opacity-0",
                      )}
                    >
                      <div className="overflow-hidden">
                        <p className="pt-2 text-small leading-relaxed text-text-secondary">
                          {item.description}
                        </p>
                        {item.href ? (
                          <span className="mt-3 inline-flex items-center gap-2 text-small font-semibold text-primary group-hover/row:text-accent">
                            Learn more
                            <ArrowRight
                              className="h-4 w-4 transition-transform duration-300 group-hover/row:translate-x-0.5"
                              aria-hidden="true"
                            />
                          </span>
                        ) : null}
                      </div>
                    </div>
                  </div>
                </div>
                {/* Active indicator bar */}
                <span
                  className={cn(
                    "ml-1 block h-0.5 origin-left bg-accent transition-transform duration-300 sm:ml-2",
                    isActive ? "scale-x-100" : "scale-x-0",
                  )}
                  aria-hidden="true"
                />
              </>
            );

            return (
              <li key={item.title}>
                {item.href ? (
                  <Link
                    href={item.href}
                    className={cn(
                      rowClass,
                      "rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
                    )}
                    onMouseEnter={() => setActiveIndex(index)}
                    onFocus={() => setActiveIndex(index)}
                    aria-current={isActive ? "true" : undefined}
                  >
                    {inner}
                  </Link>
                ) : (
                  <button
                    type="button"
                    className={rowClass}
                    onMouseEnter={() => setActiveIndex(index)}
                    onFocus={() => setActiveIndex(index)}
                    aria-current={isActive ? "true" : undefined}
                  >
                    {inner}
                  </button>
                )}
              </li>
            );
          })}
        </ol>
      </div>
    </SectionShell>
  );
}

