"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionIcon } from "./section-icon";
import { SectionShell } from "./section-shell";

interface SellerSegmentsSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface SegmentItem {
  id: string;
  title: string;
  description: string;
  icon: string;
  ctaLabel: string;
  ctaHref: string;
}

/**
 * Growth Journey — connected stages for self-identification (not a flat card grid).
 * Default active = scaling-brands (middle / most common). Hover + focus update active.
 */
export function SellerSegmentsSection({ id, data }: SellerSegmentsSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const headingId = `${id}-heading`;

  const segments: SegmentItem[] = useMemo(
    () =>
      readRecordArray(data.segments)
        .map((segment) => {
          const segmentId = readString(segment.id);
          const title = readString(segment.title);
          const description = readString(segment.description);
          const icon = readString(segment.icon);
          const cta = readNavLink(segment.cta);
          if (!title) return null;
          return {
            id: segmentId || title,
            title,
            description,
            icon,
            ctaLabel: cta?.label ?? "Get a free audit",
            ctaHref: cta?.href ?? "#hero-lead-form",
          };
        })
        .filter((item): item is SegmentItem => item !== null),
    [data.segments],
  );

  const defaultIndex = Math.max(
    0,
    segments.findIndex((segment) => segment.id === "scaling-brands"),
  );
  const [activeIndex, setActiveIndex] = useState(
    defaultIndex >= 0 ? defaultIndex : 1,
  );

  if (segments.length === 0) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-14 sm:py-16"
    >
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
        className="mx-auto mb-10 max-w-2xl text-center md:mb-12"
      />

      <ol className="seller-journey relative mx-auto grid max-w-5xl gap-4 md:grid-cols-3 md:gap-5">
        {/* Desktop connector line behind stages */}
        <div
          className="pointer-events-none absolute left-[16%] right-[16%] top-[2.75rem] hidden h-0.5 md:block"
          aria-hidden="true"
        >
          <div className="h-full w-full rounded-full bg-border" />
          <div
            className="seller-journey-progress absolute inset-y-0 left-0 rounded-full bg-gradient-to-r from-primary via-primary to-accent"
            style={{
              width: `${(activeIndex / Math.max(segments.length - 1, 1)) * 100}%`,
            }}
          />
        </div>

        {segments.map((segment, index) => {
          const isActive = index === activeIndex;
          const step = String(index + 1).padStart(2, "0");

          return (
            <li key={segment.id} className="relative">
              <div
                role="button"
                tabIndex={0}
                aria-current={isActive ? "step" : undefined}
                aria-expanded={isActive}
                className={cn(
                  "seller-journey-stage group relative flex h-full cursor-pointer flex-col overflow-hidden rounded-xl border bg-background px-5 py-6 outline-none transition-[border-color,box-shadow,transform] duration-300",
                  "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
                  isActive
                    ? "border-primary/30 shadow-[0_18px_40px_rgba(11,27,58,0.10)] md:-translate-y-1"
                    : "border-border/80 hover:border-primary/20",
                )}
                onMouseEnter={() => setActiveIndex(index)}
                onFocus={() => setActiveIndex(index)}
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    setActiveIndex(index);
                  }
                  if (event.key === "ArrowRight" || event.key === "ArrowDown") {
                    event.preventDefault();
                    setActiveIndex((current) =>
                      Math.min(current + 1, segments.length - 1),
                    );
                  }
                  if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
                    event.preventDefault();
                    setActiveIndex((current) => Math.max(current - 1, 0));
                  }
                }}
              >
                {/* Stage marker on connector */}
                <span
                  className={cn(
                    "absolute left-1/2 top-0 hidden h-3 w-3 -translate-x-1/2 -translate-y-[1.35rem] rounded-full border-2 md:block",
                    isActive
                      ? "border-accent bg-accent"
                      : "border-border bg-background",
                  )}
                  aria-hidden="true"
                />

                <span
                  className="pointer-events-none absolute right-3 top-2 font-mono text-5xl font-semibold leading-none text-primary/[0.07]"
                  aria-hidden="true"
                >
                  {step}
                </span>

                {segment.icon ? (
                  <SectionIcon
                    name={segment.icon}
                    framed
                    tone={isActive ? "accent" : "primary"}
                    className="mb-4"
                  />
                ) : null}

                <p className="font-mono text-[11px] font-semibold tracking-[0.14em] text-text-secondary">
                  STAGE {step}
                </p>
                <h3 className="mt-1 text-h4 text-primary">{segment.title}</h3>

                <div
                  className={cn(
                    "seller-journey-panel grid transition-[grid-template-rows,opacity] duration-300 ease-out",
                    isActive
                      ? "grid-rows-[1fr] opacity-100"
                      : "grid-rows-[0fr] opacity-0 md:opacity-40",
                  )}
                >
                  <div className="overflow-hidden">
                    <p className="pt-3 text-small leading-relaxed text-text-secondary sm:text-body">
                      {segment.description}
                    </p>
                    <PrimaryButton
                      asChild
                      size="sm"
                      className="mt-5"
                      onClick={(event) => event.stopPropagation()}
                    >
                      <Link href={segment.ctaHref}>{segment.ctaLabel}</Link>
                    </PrimaryButton>
                  </div>
                </div>

                {/* Mobile vertical connector under card */}
                {index < segments.length - 1 ? (
                  <span
                    className="absolute bottom-0 left-8 h-4 w-0.5 translate-y-full bg-border md:hidden"
                    aria-hidden="true"
                  />
                ) : null}
              </div>
            </li>
          );
        })}
      </ol>
    </SectionShell>
  );
}

