                <span
                  className="pointer-events-none absolute right-3 top-2 font-mono text-5xl font-semibold leading-none text-primary/[0.07]"
                  aria-hidden="true"
                >
                  {step}
                </span>

                {segment.icon ? (
                  <SectionIcon
                    name={segment.icon}
                    framed
                    tone={isActive ? "accent" : "primary"}
                    className="mb-4"
                  />
                ) : null}

                <p className="font-mono text-[11px] font-semibold tracking-[0.14em] text-text-secondary">
                  STAGE {step}
                </p>
                <h3 className="mt-1 text-h4 text-primary">{segment.title}</h3>

                <div
                  className={cn(
                    "seller-journey-panel grid",
                    isActive
                      ? "grid-rows-[1fr] opacity-100"
                      : "grid-rows-[0fr] opacity-0",
                  )}
                >
                  <div className="overflow-hidden">
                    <p className="pt-3 text-small leading-relaxed text-text-secondary sm:text-body">
                      {segment.description}
                    </p>
                    {isActive ? (
                      <PrimaryButton asChild size="sm" className="mt-5">
                        <Link href={segment.ctaHref}>{segment.ctaLabel}</Link>
                      </PrimaryButton>
                    ) : null}
                  </div>
                </div>
              </div>

              {/* Mobile vertical connector between stages */}
              {index < segments.length - 1 ? (
                <span
                  className={cn(
                    "mx-auto mt-1 block h-4 w-0.5 md:hidden",
                    isActive ? "bg-accent" : "bg-border",
                  )}
                  aria-hidden="true"
                />
              ) : null}
            </li>
          );
        })}
      </ol>
    </SectionShell>
  );
}

