"use client";

import Image from "next/image";
import Link from "next/link";
import { useMemo, useState } from "react";
import { ArrowRight } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionShell } from "./section-shell";

interface CreativeShowcaseSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface CreativeVisual {
  image: string;
  alt: string;
  caption: string;
}

/**
 * Amazon listing-frame gallery — one large preview + thumbnail strip.
 * Familiar PDP pattern; distinct from Services explorer and Seller journey.
 */
export function CreativeShowcaseSection({
  id,
  data,
}: CreativeShowcaseSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  const visuals: CreativeVisual[] = useMemo(
    () =>
      readRecordArray(data.items)
        .map((item) => {
          const image = readString(item.image);
          const alt = readString(item.alt);
          const caption = readString(item.caption);
          if (!image) return null;
          return { image, alt, caption };
        })
        .filter((item): item is CreativeVisual => item !== null),
    [data.items],
  );

  const [activeIndex, setActiveIndex] = useState(0);
  const active = visuals[activeIndex] ?? visuals[0];

  if (!active) return null;

  const selectIndex = (index: number) => {
    setActiveIndex(Math.max(0, Math.min(index, visuals.length - 1)));
  };

  return (
    <SectionShell id={id} ariaLabelledBy={headingId}>
      <div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between lg:gap-10">
        <SectionHeading
          heading={heading}
          subheading={subheading}
          headingId={headingId}
          className="mb-0 md:mb-0"
        />
        {cta ? (
          <PrimaryButton asChild variant="primary" className="w-full sm:w-auto">
            <Link href={cta.href}>
              {cta.label}
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </Link>
          </PrimaryButton>
        ) : null}
      </div>

      <div className="mx-auto mt-8 max-w-3xl md:mt-10">
        {/* Listing-style frame */}
        <div
          className="creative-listing-frame rounded-xl border border-border bg-background p-3 shadow-[0_20px_50px_rgba(11,27,58,0.06)] sm:p-4"
          onKeyDown={(event) => {
            if (event.key === "ArrowRight") {
              event.preventDefault();
              selectIndex(activeIndex + 1);
            }
            if (event.key === "ArrowLeft") {
              event.preventDefault();
              selectIndex(activeIndex - 1);
            }
          }}
        >
          <div className="mb-3 flex items-center justify-between gap-3 px-1">
            <p className="font-mono text-[11px] font-semibold tracking-[0.14em] text-text-secondary">
              LISTING PREVIEW
            </p>
            <p className="text-small text-text-secondary" aria-live="polite">
              {String(activeIndex + 1).padStart(2, "0")} /{" "}
              {String(visuals.length).padStart(2, "0")}
            </p>
          </div>

          <div className="creative-listing-stage relative aspect-square overflow-hidden rounded-lg bg-surface sm:aspect-[5/4]">
            {visuals.map((item, index) => {
              const isActive = index === activeIndex;
              return (
                <Image
                  key={item.image}
                  src={item.image}
                  alt={item.alt || "Amazon listing creative example"}
                  fill
                  className={cn(
                    "object-cover transition-opacity duration-500 ease-out",
                    isActive ? "opacity-100" : "opacity-0",
                  )}
                  sizes="(max-width: 768px) 100vw, 768px"
                  quality={80}
                  priority={index === 0}
                  loading={index === 0 ? "eager" : "lazy"}
                />
              );
            })}
          </div>

          {active.caption ? (
            <p className="mt-3 px-1 text-body font-medium text-primary">
              {active.caption}
            </p>
          ) : null}

          {visuals.length > 1 ? (
            <ul
              className="mt-4 flex gap-2 overflow-x-auto pb-1 sm:gap-3"
              role="list"
              aria-label="Creative examples"
            >
              {visuals.map((item, index) => {
                const isActive = index === activeIndex;
                return (
                  <li key={item.image} className="shrink-0">
                    <button
                      type="button"
                      aria-label={item.caption || `Creative example ${index + 1}`}
                      aria-pressed={isActive}
                      className={cn(
                        "creative-listing-thumb relative h-16 w-16 overflow-hidden rounded-md border-2 bg-surface outline-none transition-[border-color,box-shadow] duration-300 sm:h-20 sm:w-20",
                        "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
                        isActive
                          ? "border-accent shadow-[0_0_0_1px_rgba(228,121,17,0.35)]"
                          : "border-border hover:border-primary/35",
                      )}
                      onMouseEnter={() => selectIndex(index)}
                      onFocus={() => selectIndex(index)}
                      onClick={() => selectIndex(index)}
                    >
                      <Image
                        src={item.image}
                        alt=""
                        fill
                        className="object-cover"
                        sizes="80px"
                        quality={70}
                        loading="lazy"
                      />
                    </button>
                  </li>
                );
              })}
            </ul>
          ) : null}
        </div>
      </div>
    </SectionShell>
  );
}

