"use client";

import Image from "next/image";
import Link from "next/link";
import { useMemo, useRef, useState } from "react";
import { ArrowRight } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionShell } from "./section-shell";

interface CreativeShowcaseSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface CreativeVisual {
  image: string;
  alt: string;
  caption: string;
}

/**
 * Amazon listing-frame gallery — full-width PDP layout (thumbs + stage).
 * No narrow centered card; stable height (image crossfade only).
 */
export function CreativeShowcaseSection({
  id,
  data,
}: CreativeShowcaseSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;
  const thumbRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const visuals: CreativeVisual[] = useMemo(
    () =>
      readRecordArray(data.items)
        .map((item) => {
          const image = readString(item.image);
          const alt = readString(item.alt);
          const caption = readString(item.caption);
          if (!image) return null;
          return { image, alt, caption };
        })
        .filter((item): item is CreativeVisual => item !== null),
    [data.items],
  );

  const [activeIndex, setActiveIndex] = useState(0);
  const active = visuals[activeIndex] ?? visuals[0];

  if (!active) return null;

  const selectIndex = (index: number, moveFocus = false) => {
    const next = Math.max(0, Math.min(index, visuals.length - 1));
    setActiveIndex(next);
    if (moveFocus) {
      thumbRefs.current[next]?.focus();
    }
  };

  return (
    <SectionShell id={id} ariaLabelledBy={headingId}>
      <div className="flex flex-col gap-5 sm:gap-6 lg:flex-row lg:items-end lg:justify-between lg:gap-10">
        <SectionHeading
          heading={heading}
          subheading={subheading}
          headingId={headingId}
          className="mb-0 max-w-3xl md:mb-0"
        />
        {cta ? (
          <PrimaryButton asChild variant="primary" className="w-full sm:w-auto">
            <Link href={cta.href}>
              {cta.label}
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </Link>
          </PrimaryButton>
        ) : null}
      </div>

      <div className="creative-listing-frame mt-8 w-full rounded-xl border border-border bg-background p-3 shadow-[0_20px_50px_rgba(11,27,58,0.06)] sm:mt-10 sm:p-5 lg:p-6">
        <div className="mb-3 flex items-center justify-between gap-3 px-0.5 sm:mb-4">
          <p className="font-mono text-[11px] font-semibold tracking-[0.14em] text-text-secondary">
            LISTING PREVIEW
          </p>
          <p className="text-small text-text-secondary" aria-live="polite">
            {String(activeIndex + 1).padStart(2, "0")} /{" "}
            {String(visuals.length).padStart(2, "0")}
          </p>
        </div>

        {/* Desktop: vertical thumbs + stage | Mobile: stage then equal-width thumbs */}
        <div className="grid gap-3 sm:gap-4 lg:grid-cols-[5.5rem_minmax(0,1fr)] lg:items-stretch">
          {visuals.length > 1 ? (
            <ul
              className="order-2 grid grid-cols-5 gap-2 lg:order-1 lg:grid-cols-1 lg:gap-2.5"
              role="list"
              aria-label="Creative examples"
            >
              {visuals.map((item, index) => {
                const isActive = index === activeIndex;
                return (
                  <li key={item.image} className="min-w-0">
                    <button
                      ref={(node) => {
                        thumbRefs.current[index] = node;
                      }}
                      type="button"
                      aria-label={
                        item.caption || `Creative example ${index + 1}`
                      }
                      aria-pressed={isActive}
                      className={cn(
                        "creative-listing-thumb relative aspect-square w-full overflow-hidden rounded-md border-2 bg-surface outline-none transition-[border-color,box-shadow] duration-300",
                        "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
                        isActive
                          ? "border-accent shadow-[0_0_0_1px_rgba(228,121,17,0.35)]"
                          : "border-border hover:border-primary/35",
                      )}
                      onMouseEnter={() => selectIndex(index)}
                      onFocus={() => selectIndex(index)}
                      onClick={() => selectIndex(index)}
                      onKeyDown={(event) => {
                        if (event.key === "ArrowRight" || event.key === "ArrowDown") {
                          event.preventDefault();
                          selectIndex(index + 1, true);
                        }
                        if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
                          event.preventDefault();
                          selectIndex(index - 1, true);
                        }
                      }}
                    >
                      <Image
                        src={item.image}
                        alt=""
                        fill
                        className="object-cover"
                        sizes="(max-width: 1024px) 20vw, 88px"
                        quality={70}
                        loading="lazy"
                      />
                    </button>
                  </li>
                );
              })}
            </ul>
          ) : null}

          <div className="order-1 min-w-0 lg:order-2">
            <div className="creative-listing-stage relative aspect-[4/3] w-full overflow-hidden rounded-lg bg-surface sm:aspect-[16/10] lg:aspect-auto lg:min-h-[26rem] xl:min-h-[30rem]">
              {visuals.map((item, index) => {
                const isActive = index === activeIndex;
                return (
                  <Image
                    key={item.image}
                    src={item.image}
                    alt={item.alt || "Amazon listing creative example"}
                    fill
                    className={cn(
                      "object-cover transition-opacity duration-500 ease-out",
                      isActive ? "opacity-100" : "opacity-0",
                    )}
                    sizes="(max-width: 1024px) 100vw, 90vw"
                    quality={80}
                    priority={index === 0}
                    loading={index === 0 ? undefined : "lazy"}
                  />
                );
              })}
            </div>

            {/* Fixed caption slot — prevents height jump when captions differ */}
            <p className="mt-3 min-h-[1.5rem] text-body font-medium text-primary sm:min-h-[1.75rem]">
              {active.caption || "\u00A0"}
            </p>
          </div>
        </div>
      </div>
    </SectionShell>
  );
}

"use client";

import Link from "next/link";
import { useMemo, useRef, useState } from "react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionIcon } from "./section-icon";
import { SectionShell } from "./section-shell";

interface SellerSegmentsSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface SegmentItem {
  id: string;
  title: string;
  description: string;
  icon: string;
  ctaLabel: string;
  ctaHref: string;
}

/**
 * Growth Journey — full-width equal-height stages (no expand CLS).
 * Active state is visual only; all copy + CTAs always rendered.
 */
export function SellerSegmentsSection({ id, data }: SellerSegmentsSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const headingId = `${id}-heading`;
  const stageRefs = useRef<Array<HTMLDivElement | null>>([]);

  const segments: SegmentItem[] = useMemo(
    () =>
      readRecordArray(data.segments)
        .map((segment) => {
          const segmentId = readString(segment.id);
          const title = readString(segment.title);
          const description = readString(segment.description);
          const icon = readString(segment.icon);
          const cta = readNavLink(segment.cta);
          if (!title) return null;
          return {
            id: segmentId || title,
            title,
            description,
            icon,
            ctaLabel: cta?.label ?? "Get a free audit",
            ctaHref: cta?.href ?? "#hero-lead-form",
          };
        })
        .filter((item): item is SegmentItem => item !== null),
    [data.segments],
  );

  const scalingIndex = segments.findIndex(
    (segment) => segment.id === "scaling-brands",
  );
  const [activeIndex, setActiveIndex] = useState(
    scalingIndex >= 0 ? scalingIndex : Math.min(1, segments.length - 1),
  );

  const activateStage = (index: number, moveFocus = false) => {
    setActiveIndex(index);
    if (moveFocus) {
      stageRefs.current[index]?.focus();
    }
  };

  if (segments.length === 0) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-14 sm:py-16"
    >
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
        className="mx-auto mb-8 max-w-2xl text-center md:mb-10"
      />

      <ol className="seller-journey relative grid w-full grid-cols-1 items-stretch gap-4 sm:gap-5 md:grid-cols-3 md:pt-8">
        <div
          className="pointer-events-none absolute left-[16%] right-[16%] top-[0.7rem] hidden h-0.5 md:block"
          aria-hidden="true"
        >
          <div className="h-full w-full rounded-full bg-border" />
          <div
            className="seller-journey-progress absolute inset-y-0 left-0 rounded-full bg-gradient-to-r from-primary via-primary to-accent"
            style={{
              width: `${(activeIndex / Math.max(segments.length - 1, 1)) * 100}%`,
            }}
          />
        </div>

        {segments.map((segment, index) => {
          const isActive = index === activeIndex;
          const step = String(index + 1).padStart(2, "0");

          return (
            <li key={segment.id} className="relative flex min-h-0">
              <span
                className={cn(
                  "absolute left-1/2 top-0 z-10 hidden h-3.5 w-3.5 -translate-x-1/2 rounded-full border-2 md:block",
                  isActive
                    ? "border-accent bg-accent"
                    : "border-border bg-background",
                )}
                aria-hidden="true"
              />

              {/* Mobile connector */}
              {index < segments.length - 1 ? (
                <span
                  className={cn(
                    "absolute bottom-0 left-6 z-0 h-4 w-0.5 translate-y-full md:hidden",
                    isActive ? "bg-accent" : "bg-border",
                  )}
                  aria-hidden="true"
                />
              ) : null}

              <div
                ref={(node) => {
                  stageRefs.current[index] = node;
                }}
                tabIndex={0}
                aria-current={isActive ? "step" : undefined}
                aria-label={`${segment.title}, stage ${step}`}
                className={cn(
                  "seller-journey-stage group relative flex w-full flex-1 cursor-pointer flex-col rounded-xl border bg-background px-5 py-6 outline-none transition-[border-color,box-shadow,opacity] duration-300",
                  "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
                  isActive
                    ? "border-primary/30 shadow-[0_18px_40px_rgba(11,27,58,0.10)]"
                    : "border-border/80 opacity-80 hover:border-primary/20 hover:opacity-100",
                )}
                onMouseEnter={() => activateStage(index)}
                onFocus={() => activateStage(index)}
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    activateStage(index);
                  }
                  if (event.key === "ArrowRight" || event.key === "ArrowDown") {
                    event.preventDefault();
                    activateStage(
                      Math.min(index + 1, segments.length - 1),
                      true,
                    );
                  }
                  if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
                    event.preventDefault();
                    activateStage(Math.max(index - 1, 0), true);
                  }
                }}
              >
                <span
                  className="pointer-events-none absolute right-3 top-2 font-mono text-5xl font-semibold leading-none text-primary/[0.07]"
                  aria-hidden="true"
                >
                  {step}
                </span>

                {segment.icon ? (
                  <SectionIcon
                    name={segment.icon}
                    framed
                    tone={isActive ? "accent" : "primary"}
                    className="mb-4"
                  />
                ) : null}

                <p className="font-mono text-[11px] font-semibold tracking-[0.14em] text-text-secondary">
                  STAGE {step}
                </p>
                <h3 className="mt-1 text-h4 text-primary">{segment.title}</h3>

                <p className="mt-3 flex-1 text-small leading-relaxed text-text-secondary sm:text-body">
                  {segment.description}
                </p>

                <PrimaryButton
                  asChild
                  size="sm"
                  className={cn(
                    "mt-5 w-full sm:w-auto",
                    !isActive && "pointer-events-none opacity-40",
                  )}
                  tabIndex={isActive ? 0 : -1}
                  aria-hidden={!isActive}
                >
                  <Link href={segment.ctaHref}>{segment.ctaLabel}</Link>
                </PrimaryButton>
              </div>
            </li>
          );
        })}
      </ol>
    </SectionShell>
  );
}

