  const stageH1 = stage.getBoundingClientRect().height;
  const thumbs = [...creative.querySelectorAll('.creative-listing-thumb')];
  thumbs[2]?.click();
  await new Promise(r => setTimeout(r, 120));
  const stageH2 = stage.getBoundingClientRect().height;
  const frameH2 = frame.getBoundingClientRect().height;

  segments.scrollIntoView({ block: 'center' });
  await new Promise(r => setTimeout(r, 80));
  const stages = [...segments.querySelectorAll('.seller-journey-stage')];
  const heightsBefore = stages.map(s => Math.round(s.getBoundingClientRect().height));
  const olBefore = Math.round(segments.querySelector('.seller-journey').getBoundingClientRect().height);
  stages[0].dispatchEvent(new MouseEvent('mouseenter', { bubbles: true }));
  await new Promise(r => setTimeout(r, 100));
  const heightsMid = stages.map(s => Math.round(s.getBoundingClientRect().height));
  const olMid = Math.round(segments.querySelector('.seller-journey').getBoundingClientRect().height);
  stages[2].dispatchEvent(new MouseEvent('mouseenter', { bubbles: true }));
  await new Promise(r => setTimeout(r, 100));
  const heightsAfter = stages.map(s => Math.round(s.getBoundingClientRect().height));
  const olAfter = Math.round(segments.querySelector('.seller-journey').getBoundingClientRect().height);

  const journeyW = segments.querySelector('.seller-journey').getBoundingClientRect().width;

  return {
    creative: {
      containerW: Math.round(containerW),
      frameW: Math.round(frameRect.width),
      fillRatio: Number((frameRect.width / containerW).toFixed(3)),
      stageHeightStable: stageH1 === stageH2,
      stageH: Math.round(stageH1),
      thumbCount: thumbs.length,
      caption: creative.querySelector('.creative-listing-frame .text-body')?.textContent?.trim()
    },
    segments: {
      journeyW: Math.round(journeyW),
      fillRatio: Number((journeyW / containerW).toFixed(3)),
      heightsBefore,
      heightsMid,
      heightsAfter,
      olBefore, olMid, olAfter,
      equalHeights: heightsAfter.every(h => h === heightsAfter[0]),
      noOlShift: olBefore === olMid && olMid === olAfter,
      allHaveCta: stages.every(s => !!s.querySelector('a'))
    }
  };
}

