async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3000/#case-studies', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  const result = await page.evaluate(() => {
    const section = document.getElementById('case-studies');
    if (!section) return { error: 'missing' };
    const cards = [...section.querySelectorAll('.case-proof-card')];
    const links = [...section.querySelectorAll('a')].map(a => ({
      text: a.textContent?.replace(/\s+/g, ' ').trim(),
      href: a.getAttribute('href')
    }));
    const metrics = [...section.querySelectorAll('.text-stat')].map(el => el.textContent?.trim());
    const brands = [...section.querySelectorAll('h3')].map(el => el.textContent?.trim());
    const heights = cards.map(c => Math.round(c.getBoundingClientRect().height));
    const imgs = [...section.querySelectorAll('img')].map(img => ({
      ok: img.naturalWidth > 0,
      src: img.currentSrc || img.src
    }));
    const container = section.querySelector('.container-page');
    const list = section.querySelector('ul');
    const fill = list && container
      ? Number((list.getBoundingClientRect().width / container.getBoundingClientRect().width).toFixed(3))
      : null;
    return {
      cardCount: cards.length,
      metrics,
      brands,
      links,
      heights,
      equalHeights: heights.length > 0 && heights.every(h => h === heights[0]),
      imgs,
      fill,
      heading: section.querySelector('h2')?.textContent?.trim()
    };
  });
  await page.locator('#case-studies').screenshot({ path: 'docs/qa/screenshots/case-studies-metric-board.png' });
  return result;
}

