import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionShell } from "./section-shell";

interface CaseStudiesSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface CaseItem {
  metric: string;
  brand: string;
  category: string;
  service: string;
  description: string;
  href: string;
  image: string;
  imageAlt: string;
  atmosphere: string;
  atmosphereAlt: string;
}

/**
 * Atmosphere proof cards — AI category scene + blur depth + hover zoom,
 * sharp brand mark badge, metric on media gradient.
 */
export function CaseStudiesSection({ id, data }: CaseStudiesSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  const items: CaseItem[] = readRecordArray(data.items)
    .map((item) => {
      const metric = readString(item.metric);
      const brand = readString(item.brand);
      if (!brand && !metric) return null;
      return {
        metric,
        brand,
        category: readString(item.category),
        service: readString(item.service),
        description: readString(item.description),
        href: readString(item.href),
        image: readString(item.image),
        imageAlt: readString(item.imageAlt, brand),
        atmosphere: readString(item.atmosphere),
        atmosphereAlt: readString(item.atmosphereAlt, brand),
      };
    })
    .filter((item): item is CaseItem => item !== null);

  if (items.length === 0) return null;

  return (
    <SectionShell id={id} ariaLabelledBy={headingId}>
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
        className="mx-auto max-w-2xl text-center"
      />

      <ul className="mt-8 grid w-full grid-cols-1 items-stretch gap-5 sm:mt-10 md:grid-cols-3 md:gap-6">
        {items.map((item) => {
          const key = `${item.brand}-${item.metric}`;
          const scene = item.atmosphere || item.image;
          const sceneAlt = item.atmosphereAlt || item.imageAlt || item.brand;

          return (
            <li key={key} className="flex min-h-0">
              <article
                className={cn(
                  "case-proof-card group flex w-full flex-1 flex-col overflow-hidden rounded-xl border border-border/80 bg-background",
                  "shadow-[0_12px_32px_rgba(11,27,58,0.05)] transition-[border-color,box-shadow] duration-300",
                  "hover:border-primary/25 hover:shadow-[0_18px_40px_rgba(11,27,58,0.08)]",
                  "focus-within:border-primary/25 focus-within:ring-2 focus-within:ring-accent focus-within:ring-offset-2",
                )}
              >
                {scene ? (
                  <div className="case-proof-media relative aspect-[16/10] w-full shrink-0 overflow-hidden bg-primary">
                    {/* Blur depth layer */}
                    <Image
                      src={scene}
                      alt=""
                      fill
                      aria-hidden="true"
                      className="case-proof-blur scale-125 object-cover opacity-70 blur-2xl"
                      sizes="(max-width: 768px) 100vw, 33vw"
                      quality={70}
                      loading="lazy"
                    />
                    {/* Sharp cover with hover zoom */}
                    <Image
                      src={scene}
                      alt={sceneAlt}
                      fill
                      className="media-hover-zoom object-cover"
                      sizes="(max-width: 768px) 100vw, 33vw"
                      quality={80}
                      loading="lazy"
                    />

                    {/* Soft navy wash for metric contrast */}
                    <div
                      className="pointer-events-none absolute inset-0 bg-gradient-to-t from-primary/85 via-primary/25 to-primary/10"
                      aria-hidden="true"
                    />

                    {/* Sharp brand mark badge */}
                    {item.image ? (
                      <div className="absolute left-3 top-3 z-10 rounded-md border border-white/40 bg-background/95 p-2 shadow-sm backdrop-blur-sm sm:left-4 sm:top-4 sm:p-2.5">
                        <div className="relative h-9 w-16 sm:h-10 sm:w-20">
                          <Image
                            src={item.image}
                            alt={item.imageAlt || item.brand}
                            fill
                            className="object-contain"
                            sizes="80px"
                            quality={80}
                            loading="lazy"
                          />
                        </div>
                      </div>
                    ) : null}

                    {/* Metric on media */}
                    {item.metric ? (
                      <p className="absolute bottom-3 left-3 right-3 z-10 text-stat text-accent drop-shadow-sm sm:bottom-4 sm:left-4 sm:right-4">
                        {item.metric}
                      </p>
                    ) : null}
                  </div>
                ) : null}

                <div className="flex flex-1 flex-col px-5 py-5 sm:px-6 sm:py-6">
                  {item.brand ? (
                    <h3 className="text-h4 text-primary">{item.brand}</h3>
                  ) : null}

                  {item.category ? (
                    <p className="mt-1 text-small text-text-secondary">
                      {item.category}
                    </p>
                  ) : null}

                  {item.service ? (
                    <p className="mt-3 w-fit rounded-full border border-border px-3 py-1 text-[11px] font-medium tracking-wide text-text-secondary">
                      {item.service}
                    </p>
                  ) : null}

                  {item.description ? (
                    <p className="mt-4 flex-1 text-small leading-relaxed text-text-secondary sm:text-body">
                      {item.description}
                    </p>
                  ) : null}

                  {item.href ? (
                    <PrimaryButton
                      asChild
                      size="sm"
                      className="mt-5 w-full sm:w-auto"
                    >
                      <Link href={item.href}>
                        Read case study
                        <ArrowRight className="h-4 w-4" aria-hidden="true" />
                      </Link>
                    </PrimaryButton>
                  ) : null}
                </div>
              </article>
            </li>
          );
        })}
      </ul>

      {cta ? (
        <div className="mt-10 flex justify-center">
          <PrimaryButton asChild>
            <Link href={cta.href}>
              {cta.label}
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </Link>
          </PrimaryButton>
        </div>
      ) : null}
    </SectionShell>
  );
}

