"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

export type TrustLogoVariant = "cert" | "client" | "badge";

interface TrustLogoProps {
  label: string;
  image: string;
  alt: string;
  href?: string;
  variant?: TrustLogoVariant;
  className?: string;
}

/**
 * Trust mark tile — blur fill + rounded contain plate (same language as case badges).
 */
export function TrustLogo({
  label,
  image,
  alt,
  href,
  variant = "cert",
  className,
}: TrustLogoProps) {
  const [imageFailed, setImageFailed] = useState(false);

  const frameClass =
    variant === "client"
      ? "h-12 w-[148px]"
      : variant === "badge"
        ? "h-12 w-[148px]"
        : "h-16 w-[168px]";

  const content = (
    <div
      className={cn(
        "trust-logo-tile relative overflow-hidden rounded-lg border border-border/80 bg-background shadow-sm",
        frameClass,
        className,
      )}
    >
      {!imageFailed && image ? (
        <>
          <Image
            src={image}
            alt=""
            fill
            aria-hidden="true"
            className="scale-150 object-cover opacity-80 blur-md"
            sizes="168px"
            quality={70}
            loading="lazy"
          />
          <div
            className="absolute inset-0 bg-background/30"
            aria-hidden="true"
          />
          <div className="absolute inset-[3px] overflow-hidden rounded-md bg-background/90">
            <div className="relative h-full w-full">
              <Image
                src={image}
                alt={alt || label}
                fill
                className="object-contain p-2"
                sizes="168px"
                quality={80}
                loading="lazy"
                onError={() => setImageFailed(true)}
              />
            </div>
          </div>
        </>
      ) : (
        <div className="flex h-full items-center justify-center px-2">
          <Badge variant="outline" className="whitespace-nowrap text-xs">
            {label}
          </Badge>
        </div>
      )}
    </div>
  );

  if (href) {
    return (
      <Link
        href={href}
        className="inline-flex transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
        target="_blank"
        rel="noopener noreferrer"
      >
        {content}
      </Link>
    );
  }

  return content;
}

