import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

export type TrustLogoVariant = "cert" | "client" | "badge";

interface TrustLogoProps {
  label: string;
  image: string;
  alt: string;
  href?: string;
  variant?: TrustLogoVariant;
  className?: string;
}

/**
 * Calm trust mark — single rounded plate + contain.
 * (Blur double-plate was too heavy for a dense logo wall.)
 */
export function TrustLogo({
  label,
  image,
  alt,
  href,
