  return content;
}

import { cn } from "@/lib/utils";
import { readRecordArray, readString } from "./section-data";
import { SectionHeading } from "./section-heading";
import { SectionIcon } from "./section-icon";
import { SectionShell } from "./section-shell";

interface BrandValuesSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface PrincipleItem {
  title: string;
  description: string;
  icon: string;
}

/**
 * Editorial principles board — calm 2x2 after Case proof, before Process steps.
 * Not a photo gallery, explorer, or journey; hairline cells + number watermarks.
 */
export function BrandValuesSection({ id, data }: BrandValuesSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const headingId = `${id}-heading`;

  const items: PrincipleItem[] = readRecordArray(data.items)
    .map((item) => {
      const title = readString(item.title);
      if (!title) return null;
      return {
        title,
        description: readString(item.description),
        icon: readString(item.icon, "compass"),
      };
    })
    .filter((item): item is PrincipleItem => item !== null);

  if (items.length === 0) return null;

  return (
    <SectionShell id={id} ariaLabelledBy={headingId}>
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
        className="mx-auto max-w-2xl text-center"
      />

      <ul className="mt-8 grid w-full grid-cols-1 items-stretch gap-4 sm:mt-10 sm:grid-cols-2 sm:gap-5">
        {items.map((item, index) => {
          const number = String(index + 1).padStart(2, "0");

          return (
            <li key={item.title} className="flex min-h-0">
              <article
                className={cn(
                  "brand-principle group relative flex w-full flex-1 flex-col overflow-hidden rounded-xl border border-border/70 bg-background px-5 py-6 sm:px-6 sm:py-7",
                  "border-l-[3px] border-l-primary/25 transition-[border-color,box-shadow] duration-300",
                  "hover:border-primary/30 hover:border-l-accent hover:shadow-[0_14px_36px_rgba(11,27,58,0.06)]",
                )}
              >
                <span
                  className="pointer-events-none absolute right-3 top-2 font-mono text-5xl font-semibold leading-none text-primary/[0.06] sm:text-6xl"
                  aria-hidden="true"
                >
                  {number}
                </span>

                <div className="relative flex items-center gap-3">
                  <SectionIcon
                    name={item.icon}
                    framed
                    tone="primary"
                    className="mb-0 shrink-0"
                  />
                  <p className="font-mono text-[11px] font-semibold tracking-[0.14em] text-text-secondary">
                    PRINCIPLE {number}
                  </p>
                </div>

                <h3 className="relative mt-4 text-h4 text-primary">
                  {item.title}
                </h3>

                {item.description ? (
                  <p className="relative mt-3 flex-1 text-small leading-relaxed text-text-secondary sm:text-body">
                    {item.description}
                  </p>
                ) : null}
              </article>
            </li>
          );
        })}
      </ul>
    </SectionShell>
  );
}

