    const section = document.getElementById('brand-values');
    if (!section) return { error: 'missing' };
    const cards = [...section.querySelectorAll('.brand-principle')];
    const titles = [...section.querySelectorAll('h3')].map(h => h.textContent?.trim());
    const locked = [
      'Strategy beyond isolated tactics',
      'Collaboration with your team',
      'Systems that sustain growth',
      'Clear, accountable execution'
    ];
    const heights = cards.map(c => Math.round(c.getBoundingClientRect().height));
    const container = section.querySelector('.container-page');
    const list = section.querySelector('ul');
    return {
      heading: section.querySelector('h2')?.textContent?.trim(),
      sub: section.querySelector('h2 + p')?.textContent?.trim() || section.querySelector('p')?.textContent?.trim(),
      count: cards.length,
      titles,
      lockedMatch: locked.every((t, i) => titles[i] === t),
      heights,
      equalHeights: heights.length === 4 && heights.every(h => h === heights[0]),
      fill: list && container ? Number((list.getBoundingClientRect().width / container.getBoundingClientRect().width).toFixed(3)) : null,
      hasWatermark: cards.every(c => /0[1-4]/.test(c.textContent || '')),
      leftAccent: cards.every(c => (c.className || '').includes('border-l'))
    };
  });
  await page.locator('#brand-values').screenshot({ path: 'docs/qa/screenshots/brand-values-editorial.png' });
  return result;
}

