() => {
  const nav = document.querySelector('nav, header, [class*="nav"]');
  const links = Array.from(document.querySelectorAll('a')).slice(0, 20).map(a => ({
    text: (a.innerText||'').trim().slice(0,40),
    bg: getComputedStyle(a).backgroundColor,
    color: getComputedStyle(a).color,
    font: getComputedStyle(a).fontFamily,
    weight: getComputedStyle(a).fontWeight,
    size: getComputedStyle(a).fontSize,
    radius: getComputedStyle(a).borderRadius,
    pad: getComputedStyle(a).padding,
  }));
  const body = getComputedStyle(document.body);
  const sticky = Array.from(document.querySelectorAll('*')).find(el => {
    const s = getComputedStyle(el);
    return (s.position === 'sticky' || s.position === 'fixed') && el.getBoundingClientRect().top <= 2 && el.getBoundingClientRect().height > 40 && el.getBoundingClientRect().height < 120;
  });
  const stickyStyles = sticky ? (() => {
    const s = getComputedStyle(sticky);
    return {
      tag: sticky.tagName,
      class: sticky.className?.toString?.().slice(0,120),
      bg: s.backgroundColor,
      height: sticky.getBoundingClientRect().height,
      color: s.color,
      font: s.fontFamily,
      backdrop: s.backdropFilter,
    };
  })() : null;
  return {
    bodyBg: body.backgroundColor,
    bodyFont: body.fontFamily,
    sticky: stickyStyles,
    sampleLinks: links.filter(l => l.text).slice(0,12)
  };
}

() => {
  // Find dark floating nav bar
  const candidates = Array.from(document.querySelectorAll('div,nav,header')).filter(el => {
    const r = el.getBoundingClientRect();
    const s = getComputedStyle(el);
    const bg = s.backgroundColor;
    return r.top >= 0 && r.top < 40 && r.height > 50 && r.height < 100 && r.width > 600 && bg.includes('rgb') && !bg.includes('250');
  }).map(el => {
    const s = getComputedStyle(el);
    return {
      bg: s.backgroundColor,
      radius: s.borderRadius,
      w: Math.round(el.getBoundingClientRect().width),
      h: Math.round(el.getBoundingClientRect().height),
      top: Math.round(el.getBoundingClientRect().top),
      class: (el.className||'').toString().slice(0,80),
      font: s.fontFamily,
      color: s.color,
      childrenText: (el.innerText||'').slice(0,120)
    };
  });
  // fonts from loaded stylesheets
  const fonts = Array.from(document.fonts || []).map(f => f.family).filter((v,i,a)=>a.indexOf(v)===i).slice(0,30);
  return { candidates: candidates.slice(0,8), fonts };
}

