import Image from "next/image";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";

interface BrandLogoProps {
  className?: string;
  width: number;
  height: number;
  alt?: string;
  /** Header / LCP: true. Footer and secondary: false (lazy). */
  priority?: boolean;
  /**
   * `onDark` — lighten mark for navy/charcoal chrome (logo assets are navy wordmark).
   * `default` — mark as authored for light surfaces.
   */
  surface?: "default" | "onDark";
}

export function BrandLogo({
  className,
  width,
  height,
  alt = `${designSystem.brand.name} logo`,
  priority = false,
  surface = "default",
}: BrandLogoProps) {
  const src =
    surface === "onDark"
      ? designSystem.brand.logo.dark
      : designSystem.brand.logo.light;

  return (
    <Image
      src={src}
      alt={alt}
      width={width}
      height={height}
      className={cn(
        surface === "onDark" && "brightness-0 invert",
        className,
      )}
      priority={priority}
      sizes={`${width}px`}
      quality={85}
    />
  );
}

"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { wrapBouncyIcons } from "@/components/ui/bouncy-icon";

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof primaryButtonVariants> {
  asChild?: boolean;
}

const primaryButtonVariants = cva(
  [
    "group relative inline-flex items-center justify-center gap-2 rounded-full",
    "font-semibold tracking-tight",
    "transition-colors duration-300 ease-out",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-50",
    "motion-safe:hover:-translate-y-px motion-safe:active:translate-y-0",
  ].join(" "),
  {
    variants: {
      variant: {
        /** Navy fill → orange punch on hover */
        primary: "bg-primary text-text-on-dark hover:bg-accent hover:text-primary",
        /** Orange punch (Project One lime role) — header / conversion */
        accent:
          "bg-accent text-primary hover:bg-accent-alt hover:text-text-on-dark",
        /** Light pill on dark chrome */
        onDark:
          "bg-text-on-dark text-primary hover:bg-accent hover:text-primary",
      },
      size: {
        default: "h-11 min-h-11 px-5 text-sm",
        sm: "h-10 min-h-10 px-3.5 text-xs",
        lg: "h-12 min-h-12 px-6 text-sm",
      },
    },
    defaultVariants: {
      variant: "primary",
      size: "default",
    },
  },
);

/**
 * Sitewide primary CTA.
 * Variants: primary (navy), accent (orange punch), onDark (light on navy).
 * Icons: fixed slot with idle filled dot; hover bounces to ArrowRight.
 */
const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  (
    {
      className,
      children,
      asChild = false,
      variant,
      size,
      type = "button",
      ...props
    },
    ref,
  ) => {
    const outerClassName = cn(
      primaryButtonVariants({ variant, size }),
      className,
    );

    if (asChild) {
      if (!React.isValidElement(children)) {
        return null;
      }

      const child = children as React.ReactElement<{
        className?: string;
        children?: React.ReactNode;
      }>;

      return (
        <Slot
          className={cn(outerClassName, child.props.className)}
          ref={ref}
          {...props}
        >
          {React.cloneElement(child, {
            className: undefined,
            children: wrapBouncyIcons(child.props.children),
          })}
        </Slot>
      );
    }

    return (
      <button
        ref={ref}
        type={type}
        className={outerClassName}
        {...props}
      >
        {wrapBouncyIcons(children)}
      </button>
    );
  },
);
PrimaryButton.displayName = "PrimaryButton";

export { PrimaryButton, primaryButtonVariants };

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { ArrowRight, Phone } from "lucide-react";
import type { NavigationConfig } from "@/domain/content/schemas";
import type { SiteConfig } from "@/domain/content/schemas";
