interface SiteHeaderShellProps {
  navigation: NavigationConfig;
  site: SiteConfig;
}

export function SiteHeaderShell({ navigation, site }: SiteHeaderShellProps) {
  const [scrolled, setScrolled] = useState(false);
  const { header } = navigation;

  useEffect(() => {
    const onScroll = () => {
      setScrolled(window.scrollY > 4);
    };

    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header
      className={cn(
        "pointer-events-none z-50 w-full",
        header.sticky && "sticky top-0",
      )}
    >
      {/* Floating dark pill — Project One chrome language, navy + orange */}
      <div
        className={cn(
          "pointer-events-auto mx-auto mt-3 max-w-[min(1280px,calc(100%-1.25rem))] rounded-full border border-white/10 bg-primary text-text-on-dark shadow-[0_8px_28px_rgba(11,27,58,0.28)] transition-shadow duration-300 sm:mt-4 sm:max-w-[min(1280px,calc(100%-2rem))]",
          scrolled && "shadow-[0_12px_36px_rgba(11,27,58,0.38)]",
        )}
      >
        <NavigationMenu
          delayDuration={200}
          className="relative flex w-full max-w-none flex-none flex-col items-stretch justify-start"
        >
          <div
            className="flex items-center justify-between gap-3 px-3 sm:gap-4 sm:px-5"
            style={{ minHeight: header.height }}
          >
            <div className="flex min-w-0 items-center gap-2 sm:gap-3">
              <MobileNav
                navigation={navigation}
                site={site}
                className="text-text-on-dark hover:text-accent"
              />
              <Link
                href={header.logoHref}
                className="flex shrink-0 items-center rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
                aria-label={`${site.name} home`}
              >
                <BrandLogo
                  surface="onDark"
                  width={140}
                  height={42}
                  className="h-7 w-auto sm:h-8"
                  priority
                />
              </Link>
            </div>

            <div className="flex flex-1 items-center justify-end gap-2 sm:gap-3 lg:gap-4">
              <HeaderNav
                items={header.items}
                megaMenus={navigation.megaMenus}
                tone="onDark"
              />

              <a
                href={`tel:${site.phone.tel}`}
                className="hidden items-center gap-1.5 text-sm font-medium text-text-on-dark/75 transition-colors hover:text-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary xl:inline-flex"
                aria-label={`Call ${site.phone.display}`}
              >
                <Phone className="h-4 w-4 text-accent" aria-hidden="true" />
                <span>{site.phone.display}</span>
              </a>

              <PrimaryButton
                asChild
                variant="accent"
                className="hidden min-h-11 lg:inline-flex"
              >
                <Link href={header.cta.href}>
                  {header.cta.label}
                  <ArrowRight className="h-4 w-4" aria-hidden="true" />
                </Link>
              </PrimaryButton>

              <PrimaryButton
                asChild
                variant="accent"
                size="sm"
                className="inline-flex lg:hidden"
              >
                <Link href={header.cta.href} aria-label={header.cta.label}>
                  Audit
                  <ArrowRight className="h-3.5 w-3.5" aria-hidden="true" />
                </Link>
              </PrimaryButton>
            </div>
          </div>
        </NavigationMenu>
      </div>
    </header>
  );
}

