"use client";

import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import { motion } from "motion/react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

/**
 * Quiet off-white canvas + optional navy/orange orbs (2-color lock).
 * Skipped on /design-system (local Framer mesh preview owns the background).
 */
export function PageAtmosphere() {
  const pathname = usePathname();
  const [hydrated, setHydrated] = useState(false);
  const reduceMotion = usePrefersReducedMotion();

  useEffect(() => {
    setHydrated(true);
  }, []);

  if (pathname?.startsWith("/design-system")) {
    return null;
  }

  const showAnimatedOrbs = hydrated && !reduceMotion;

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 -z-10 overflow-hidden"
    >
      <div
        className="absolute inset-0 bg-background"
        style={{
          backgroundImage: "var(--brand-page-atmosphere)",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
        }}
      />

      <div
        className="absolute inset-0 opacity-[0.22]"
        style={{
          backgroundImage:
            "radial-gradient(circle, color-mix(in srgb, #0B1B3A 18%, transparent) 1px, transparent 1px)",
          backgroundSize: "22px 22px",
          maskImage:
            "radial-gradient(ellipse 100% 90% at 50% 40%, #000 35%, transparent 85%)",
          WebkitMaskImage:
            "radial-gradient(ellipse 100% 90% at 50% 40%, #000 35%, transparent 85%)",
        }}
      />

      <div className="absolute -right-[10%] -top-[8%] h-[48vmin] w-[48vmin] rounded-full bg-accent/[0.07] blur-[90px]" />
      <div className="absolute bottom-[-20%] left-[20%] h-[52vmin] w-[52vmin] rounded-full bg-primary/[0.05] blur-[100px]" />

      {showAnimatedOrbs ? (
        <>
          <motion.div
            className="absolute -right-[10%] -top-[8%] h-[48vmin] w-[48vmin] rounded-full bg-accent/[0.05] blur-[90px]"
            animate={{
              x: [0, -30, 12, 0],
              y: [0, 28, 8, 0],
              scale: [1, 0.96, 1.06, 1],
            }}
            transition={{
              duration: 28,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 1.2,
            }}
          />
          <motion.div
            className="absolute bottom-[-20%] left-[20%] h-[52vmin] w-[52vmin] rounded-full bg-primary/[0.04] blur-[100px]"
            animate={{
              x: [0, 24, -18, 0],
              y: [0, -22, -8, 0],
              scale: [1, 1.05, 0.95, 1],
            }}
            transition={{
              duration: 30,
              repeat: Infinity,
              ease: "easeInOut",
              delay: 0.6,
            }}
          />
        </>
      ) : null}
    </div>
  );
}

