"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { ArrowRight, Phone } from "lucide-react";
import type { NavigationConfig } from "@/domain/content/schemas";
import type { SiteConfig } from "@/domain/content/schemas";
import { BrandLogo } from "@/components/design-system/brand-logo";
import { HeaderNav } from "@/components/layout/header-nav";
import { MobileNav } from "@/components/layout/mobile-nav";
import { PrimaryButton } from "@/components/ui/primary-button";
import { NavigationMenu } from "@/components/ui/navigation-menu";
import { cn } from "@/lib/utils";

interface SiteHeaderShellProps {
  navigation: NavigationConfig;
  site: SiteConfig;
}

/**
 * Project One chrome language: logo free on left; compact dark nav pill;
 * separate punch CTA (orange = their lime role).
 */
export function SiteHeaderShell({ navigation, site }: SiteHeaderShellProps) {
  const [scrolled, setScrolled] = useState(false);
  const { header } = navigation;

  useEffect(() => {
    const onScroll = () => {
      setScrolled(window.scrollY > 4);
    };

    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header
      className={cn(
        "z-50 w-full",
        header.sticky && "sticky top-0",
      )}
    >
      <div
        className={cn(
          "mx-auto flex max-w-[min(1280px,calc(100%-1.25rem))] items-center justify-between gap-3 py-3 transition-shadow duration-300 sm:max-w-[min(1280px,calc(100%-2rem))] sm:gap-4 sm:py-4",
          scrolled && "drop-shadow-sm",
        )}
      >
        <div className="flex min-w-0 items-center gap-2 sm:gap-3">
          <MobileNav
            navigation={navigation}
            site={site}
            className="rounded-full bg-primary text-text-on-dark hover:text-accent lg:hidden"
          />
          <Link
            href={header.logoHref}
            className="flex shrink-0 items-center rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
            aria-label={`${site.name} home`}
          >
            <BrandLogo
              width={140}
              height={42}
              className="h-7 w-auto sm:h-8"
              priority
            />
          </Link>
        </div>

        <div className="flex flex-1 items-center justify-end gap-2 sm:gap-3">
          {/* Dark nav pill — links only (desktop) */}
          <NavigationMenu
            delayDuration={200}
            className="relative hidden max-w-none flex-none items-stretch justify-start lg:flex"
          >
            <div
              className="flex items-center rounded-full border border-primary/20 bg-primary px-2 text-text-on-dark shadow-[0_8px_24px_rgba(11,27,58,0.22)]"
              style={{ minHeight: header.height }}
            >
              <HeaderNav
                items={header.items}
                megaMenus={navigation.megaMenus}
                tone="onDark"
              />
              <a
                href={`tel:${site.phone.tel}`}
                className="ml-1 mr-2 hidden items-center gap-1.5 border-l border-white/15 pl-3 text-sm font-medium text-text-on-dark/75 transition-colors hover:text-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary xl:inline-flex"
                aria-label={`Call ${site.phone.display}`}
              >
                <Phone className="h-3.5 w-3.5 text-accent" aria-hidden="true" />
                <span className="whitespace-nowrap">{site.phone.display}</span>
              </a>
            </div>
          </NavigationMenu>

          {/* Punch CTA — separate from nav pill */}
          <PrimaryButton
            asChild
            variant="accent"
            className="hidden min-h-11 shadow-[0_8px_20px_rgba(228,121,17,0.28)] lg:inline-flex"
          >
            <Link href={header.cta.href}>
              {header.cta.label}
              <span
                className="ml-0.5 inline-flex h-7 w-7 items-center justify-center rounded-md bg-primary text-text-on-dark"
                aria-hidden="true"
              >
                <ArrowRight className="h-3.5 w-3.5" />
              </span>
            </Link>
          </PrimaryButton>

          <PrimaryButton
            asChild
            variant="accent"
            size="sm"
            className="inline-flex shadow-[0_6px_16px_rgba(228,121,17,0.28)] lg:hidden"
          >
            <Link href={header.cta.href} aria-label={header.cta.label}>
              Audit
              <span
                className="inline-flex h-6 w-6 items-center justify-center rounded-md bg-primary text-text-on-dark"
                aria-hidden="true"
              >
                <ArrowRight className="h-3 w-3" />
              </span>
            </Link>
          </PrimaryButton>
        </div>
      </div>
    </header>
  );
}

