import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { submitAuditForm } from "@/app/(marketing)/free-audit-2/actions";
import { ConfigurableForm } from "@/components/forms/configurable-form";
import { PrimaryButton } from "@/components/ui/primary-button";
import { initialFormActionState } from "@/domain/forms/form-action-state";
import { readNavLink, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface HeroSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface HeroFormField {
  name: string;
  label: string;
  type: "text" | "email" | "tel" | "url" | "textarea" | "select";
  required: boolean;
  placeholder?: string;
  options?: { value: string; label: string }[];
}

function readHeroFormFields(value: unknown): HeroFormField[] {
  if (!Array.isArray(value)) return [];

  return value.flatMap((item) => {
    if (!item || typeof item !== "object") return [];
    const record = item as Record<string, unknown>;
    const name = readString(record.name);
    const label = readString(record.label);
    const type = readString(record.type, "text");
    if (!name || !label) return [];
    if (
      type !== "text" &&
      type !== "email" &&
      type !== "tel" &&
      type !== "url" &&
      type !== "textarea" &&
      type !== "select"
    ) {
      return [];
    }

    const options = Array.isArray(record.options)
      ? record.options.flatMap((option) => {
          if (!option || typeof option !== "object") return [];
          const opt = option as Record<string, unknown>;
          if (typeof opt.value !== "string" || typeof opt.label !== "string") {
            return [];
          }
          return [{ value: opt.value, label: opt.label }];
        })
      : undefined;

    return [
      {
        name,
        label,
        type,
        required: Boolean(record.required),
        placeholder: readString(record.placeholder) || undefined,
        options,
      },
    ];
  });
}

function CtaArrowChip({
  tone,
}: {
  tone: "onOrange" | "onNavy";
}) {
  return (
    <span
      className={
        tone === "onOrange"
          ? "inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-primary text-text-on-dark"
          : "inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-text-on-dark/15 text-text-on-dark"
      }
      aria-hidden="true"
    >
      <ArrowRight className="h-3.5 w-3.5" />
    </span>
  );
}

export function HeroSection({ id, data }: HeroSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const headline = readString(data.headline);
  const subheadline = readString(data.subheadline);
  const supportLine = readString(data.supportLine);
  const trustLine = readString(data.trustLine);
  const primaryCta = readNavLink(data.primaryCta);
  const secondaryCta = readNavLink(data.secondaryCta);
  const partnerBadge =
    data.partnerBadge && typeof data.partnerBadge === "object"
      ? (data.partnerBadge as Record<string, unknown>)
      : null;
  const partnerBadgeLabel = readString(partnerBadge?.label);
  const partnerBadgeImage = readString(partnerBadge?.image);
  const partnerBadgeHref = readString(partnerBadge?.href);

  const visual = data.visual as Record<string, unknown> | undefined;
  const visualType = readString(visual?.type, "leadForm");
  const formHeading = readString(visual?.formHeading, "Get your free audit");
  const formSubheading = readString(visual?.formSubheading);
  const submitLabel = readString(visual?.submitLabel, "Get your free audit");
  const consentLabel = readString(
    visual?.consentLabel,
    "I agree to the privacy policy and consent to being contacted about my audit request.",
  );
  const formFields = readHeroFormFields(visual?.fields);
  const showLeadForm = visualType === "leadForm" && formFields.length > 0;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={`${id}-heading`}
      className="relative overflow-hidden py-10 sm:py-14 lg:py-16 xl:py-20"
    >
      <div className="relative grid items-center gap-10 lg:grid-cols-[minmax(0,1.1fr)_minmax(0,0.9fr)] lg:gap-12 xl:gap-16">
        <div className="max-w-2xl lg:max-w-none">
          {eyebrow ? (
            <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
              {eyebrow}
            </p>
          ) : null}

          <h1
            id={`${id}-heading`}
            className="mt-4 text-hero text-text-primary text-balance sm:mt-5"
          >
            {headline}
          </h1>

          {subheadline ? (
            <p className="mt-5 max-w-xl text-base font-semibold leading-snug text-text-primary/80 text-pretty sm:mt-6 sm:text-lg">
              {subheadline}
            </p>
          ) : null}

          {primaryCta || secondaryCta ? (
            <div className="mt-8 flex flex-col gap-3 sm:mt-9 sm:flex-row sm:flex-wrap sm:items-center sm:gap-3">
              {primaryCta ? (
                <PrimaryButton
                  asChild
                  variant="accent"
                  size="lg"
                  className="w-full shadow-[0_10px_28px_rgba(228,121,17,0.28)] sm:w-auto"
                >
                  <Link href={primaryCta.href}>
                    {primaryCta.label}
                    <CtaArrowChip tone="onOrange" />
                  </Link>
                </PrimaryButton>
              ) : null}
              {secondaryCta ? (
                <PrimaryButton
                  asChild
                  variant="primary"
                  size="lg"
                  className="w-full sm:w-auto"
                >
                  <Link href={secondaryCta.href}>
                    {secondaryCta.label}
                    <CtaArrowChip tone="onNavy" />
                  </Link>
                </PrimaryButton>
              ) : null}
            </div>
          ) : null}

          {supportLine ? (
            <p className="mt-5 flex items-start gap-2 text-sm text-text-secondary sm:mt-6">
              <span
                className="mt-1.5 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-accent"
                aria-hidden="true"
              />
              <span>{supportLine}</span>
            </p>
          ) : null}

          {partnerBadgeImage || trustLine ? (
            <div className="mt-6 flex flex-wrap items-center gap-3 sm:mt-8">
              {partnerBadgeImage ? (
                partnerBadgeHref ? (
                  <a
                    href={partnerBadgeHref}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex min-h-11 items-center rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 sm:min-h-12"
                  >
                    <Image
                      src={partnerBadgeImage}
                      alt={partnerBadgeLabel || "Partner badge"}
                      width={200}
                      height={56}
                      className="h-11 w-auto sm:h-12"
                      sizes="200px"
                      quality={75}
                    />
                  </a>
                ) : (
                  <div className="inline-flex min-h-11 items-center sm:min-h-12">
                    <Image
                      src={partnerBadgeImage}
                      alt={partnerBadgeLabel || "Partner badge"}
                      width={200}
                      height={56}
                      className="h-11 w-auto sm:h-12"
                      sizes="200px"
                      quality={75}
                    />
                  </div>
                )
              ) : null}
              {partnerBadgeImage && trustLine ? (
                <span
                  className="hidden h-4 w-px bg-border sm:inline-block"
                  aria-hidden="true"
                />
              ) : null}
              {trustLine ? (
                <p className="text-small font-medium text-text-secondary">
                  {trustLine}
                </p>
              ) : null}
            </div>
          ) : null}
        </div>

        {showLeadForm ? (
          <div
            id="hero-lead-form"
            className="w-full scroll-mt-28 rounded-[1.35rem] border border-border/70 bg-background p-5 shadow-[0_18px_50px_rgba(11,27,58,0.08)] sm:p-6 lg:p-7"
          >
            <h2 className="text-xl font-bold tracking-tight text-text-primary sm:text-2xl">
              {formHeading}
            </h2>
            {formSubheading ? (
              <p className="mt-1.5 text-sm leading-snug text-text-secondary">
                {formSubheading}
              </p>
            ) : null}
            <div className="mt-5">
              <ConfigurableForm
                formId="hero-audit-form"
                fields={formFields}
                submitLabel={submitLabel}
                consentLabel={consentLabel}
                action={submitAuditForm}
                initialState={initialFormActionState}
                density="compact"
                columns={2}
                submitVariant="primary"
                submitFullWidth
              />
            </div>
          </div>
        ) : null}
      </div>
    </SectionShell>
  );
}

