"use client";

import { useId } from "react";
import { Check } from "lucide-react";
import { cn } from "@/lib/utils";
import { readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface ChecklistTickerSectionProps {
  id: string;
  data: Record<string, unknown>;
}

function readItems(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((item) => {
    if (typeof item === "string" && item.trim()) return [item.trim()];
    if (item && typeof item === "object") {
      const label = readString((item as Record<string, unknown>).label);
      return label ? [label] : [];
    }
    return [];
  });
}

function buildSeamlessTrack(items: string[], minItems = 10): string[] {
  if (items.length === 0) return [];
  const cycle: string[] = [];
  while (cycle.length < minItems) {
    cycle.push(...items);
  }
  return [...cycle, ...cycle];
}

function ChecklistChip({ label }: { label: string }) {
  return (
    <span className="inline-flex shrink-0 items-center gap-2.5 rounded-full border border-white/10 bg-white/[0.04] px-4 py-2.5">
      <span
        className="inline-flex h-5 w-5 items-center justify-center rounded-md bg-accent text-primary"
        aria-hidden="true"
      >
        <Check className="h-3.5 w-3.5 stroke-[2.5]" />
      </span>
      <span className="whitespace-nowrap text-sm font-medium tracking-tight text-text-on-dark/80">
        {label}
      </span>
    </span>
  );
}

function ChecklistRibbon({
  items,
  direction,
}: {
  items: string[];
  direction: "ltr" | "rtl";
}) {
  if (items.length === 0) return null;
  const track = buildSeamlessTrack(items);
  const half = track.length / 2;

  return (
    <div className="checklist-ticker-fade overflow-hidden">
      <div
        className={cn(
          "flex w-max items-center gap-3",
          direction === "rtl"
            ? "animate-checklist-ticker-reverse"
            : "animate-checklist-ticker",
        )}
      >
        {track.map((label, index) => (
          <ChecklistChip
            key={`${direction}-${label}-${index}`}
            label={label}
          />
        ))}
        {/* Duplicate half marked for a11y via aria-hidden on second half chips — chip itself has no interactive role */}
        <span className="sr-only">
          {half} checklist items duplicated for continuous scroll
        </span>
      </div>
    </div>
  );
}

/**
 * Project One–style scrolling launch checklist — Amazon ops items, navy + orange.
 */
export function ChecklistTickerSection({
  id,
  data,
}: ChecklistTickerSectionProps) {
  const labelId = useId();
  const eyebrow = readString(data.eyebrow);
  const items = readItems(data.items);

  if (items.length === 0) return null;

  const mid = Math.ceil(items.length / 2);
  const rowA = items.slice(0, mid);
  const rowB = items.slice(mid);
  const topRow = rowA.length > 0 ? rowA : items;
  const bottomRow = rowB.length > 0 ? rowB : [...items].reverse();

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={labelId}
      className="py-6 sm:py-8 lg:py-10"
    >
      <div className="overflow-hidden rounded-[1.75rem] bg-primary px-4 py-8 shadow-[0_18px_50px_rgba(11,27,58,0.18)] sm:rounded-[2rem] sm:px-6 sm:py-10 lg:px-8">
        {eyebrow ? (
          <p
            id={labelId}
            className="mb-6 text-center text-[11px] font-bold uppercase tracking-[0.16em] text-text-on-dark/55 sm:mb-8 sm:text-xs"
          >
            {eyebrow}
          </p>
        ) : (
          <p id={labelId} className="sr-only">
            Account operations checklist scrolling continuously
          </p>
        )}

        <div
          className="flex flex-col gap-3.5"
          role="region"
          aria-labelledby={labelId}
        >
          <ChecklistRibbon items={topRow} direction="ltr" />
          <ChecklistRibbon items={bottomRow} direction="rtl" />
        </div>
      </div>
    </SectionShell>
  );
}

