import { Check } from "lucide-react";
import { cn } from "@/lib/utils";
import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface BrandValuesSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface PrincipleItem {
  title: string;
  description: string;
}

/**
 * Project One “ONE” simple-props language: bold punch cards, check marks,
 * alternating orange / canvas. eCom pillar copy locked from config.
 */
export function BrandValuesSection({ id, data }: BrandValuesSectionProps) {
  const eyebrow = readString(data.eyebrow, "Partnership principles");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const headingId = `${id}-heading`;

  const items: PrincipleItem[] = readRecordArray(data.items)
    .map((item) => {
      const title = readString(item.title);
      if (!title) return null;
      return {
        title,
        description: readString(item.description),
      };
    })
    .filter((item): item is PrincipleItem => item !== null);

  if (items.length === 0) return null;

  return (
    <SectionShell id={id} ariaLabelledBy={headingId} className="py-12 sm:py-16 lg:py-20">
      <div className="flex flex-col gap-8 lg:flex-row lg:items-end lg:justify-between lg:gap-12">
        <div className="max-w-xl">
          {eyebrow ? (
            <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
              {eyebrow}
            </p>
          ) : null}
          <h2
            id={headingId}
            className="mt-3 text-[1.85rem] font-bold leading-[1.08] tracking-[-0.03em] text-text-primary text-balance sm:text-4xl lg:text-[2.75rem]"
          >
            {heading}
          </h2>
          {subheading ? (
            <p className="mt-4 max-w-md text-base font-medium leading-snug text-text-secondary sm:text-lg">
              {subheading}
            </p>
          ) : null}
        </div>
      </div>

      <ul className="mt-10 grid grid-cols-1 gap-3 sm:mt-12 sm:grid-cols-2 lg:grid-cols-4 lg:gap-4">
        {items.map((item, index) => {
          const punch = index % 2 === 0;
          return (
            <li key={item.title} className="flex min-h-0">
              <article
                className={cn(
                  "flex h-full w-full flex-col rounded-[10px] border-2 border-primary p-5 sm:p-6",
                  punch
                    ? "bg-accent text-primary"
                    : "bg-background text-primary",
                )}
              >
                <span
                  className={cn(
                    "inline-flex h-8 w-8 items-center justify-center rounded-full border-2 border-primary",
                    punch ? "bg-primary text-text-on-dark" : "bg-accent text-primary",
                  )}
                  aria-hidden="true"
                >
                  <Check className="h-4 w-4 stroke-[2.5]" />
                </span>

                <h3 className="mt-5 text-lg font-bold leading-snug tracking-tight sm:text-xl">
                  {item.title}
                </h3>
                {item.description ? (
                  <p
                    className={cn(
                      "mt-3 text-sm font-medium leading-relaxed",
                      punch ? "text-primary/80" : "text-text-secondary",
                    )}
                  >
                    {item.description}
                  </p>
                ) : null}
              </article>
            </li>
          );
        })}
      </ul>
    </SectionShell>
  );
}

