(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.projectone.website/', { waitUntil: 'networkidle', timeout: 90000 });
  await page.waitForTimeout(1200);
  await page.evaluate(() => {
    const el = Array.from(document.querySelectorAll('*')).find(e => /\$100|\/mo|pricing|Reserve your spot/i.test((e.innerText||'').trim()) && (e.innerText||'').length < 40);
    el?.scrollIntoView({ block: 'center' });
  });
  await page.waitForTimeout(500);
  const info = await page.evaluate(() => {
    const nodes = Array.from(document.querySelectorAll('*'));
    const price = nodes.find(el => /^\s*\$100/.test((el.innerText||'').trim()) || /\$100\s*\/\s*mo/i.test((el.innerText||'').trim()));
    const pick = (el) => {
      if (!el) return null;
      const s = getComputedStyle(el);
      let card = el;
      for (let i=0;i<8;i++) {
        if (!card.parentElement) break;
        card = card.parentElement;
        const cs = getComputedStyle(card);
