"use client";

import Image from "next/image";
import Link from "next/link";
import { useMemo, useRef, useState } from "react";
import { ArrowRight } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface CreativeShowcaseSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface CreativeVisual {
  image: string;
  alt: string;
  caption: string;
}

/**
 * Portfolio-language creative gallery — Project One work-frame chrome,
 * navy hard border, oversized type. Listing PDP interaction kept.
 */
export function CreativeShowcaseSection({
  id,
  data,
}: CreativeShowcaseSectionProps) {
  const eyebrow = readString(data.eyebrow, "Selected creative");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;
  const thumbRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const visuals: CreativeVisual[] = useMemo(
    () =>
      readRecordArray(data.items)
        .map((item) => {
          const image = readString(item.image);
          const alt = readString(item.alt);
          const caption = readString(item.caption);
          if (!image) return null;
          return { image, alt, caption };
        })
        .filter((item): item is CreativeVisual => item !== null),
    [data.items],
  );

  const [activeIndex, setActiveIndex] = useState(0);
  const active = visuals[activeIndex] ?? visuals[0];

  if (!active) return null;

  const selectIndex = (index: number, moveFocus = false) => {
    const next = Math.max(0, Math.min(index, visuals.length - 1));
    setActiveIndex(next);
    if (moveFocus) {
      thumbRefs.current[next]?.focus();
    }
  };

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between lg:gap-10">
        <div className="max-w-3xl">
          {eyebrow ? (
            <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
              {eyebrow}
            </p>
          ) : null}
          <h2
            id={headingId}
            className="mt-3 text-[1.85rem] font-bold leading-[1.08] tracking-[-0.03em] text-text-primary text-balance sm:text-4xl lg:text-[2.75rem]"
          >
            {heading}
          </h2>
          {subheading ? (
            <p className="mt-4 max-w-2xl text-base font-semibold leading-snug text-text-primary/75 sm:text-lg">
              {subheading}
            </p>
          ) : null}
        </div>
        {cta ? (
          <PrimaryButton
            asChild
            variant="accent"
            className="w-full shrink-0 sm:w-auto"
          >
            <Link href={cta.href}>
              {cta.label}
              <span
                className="inline-flex h-7 w-7 items-center justify-center rounded-md bg-primary text-text-on-dark"
                aria-hidden="true"
              >
                <ArrowRight className="h-3.5 w-3.5" />
              </span>
            </Link>
          </PrimaryButton>
        ) : null}
      </div>

      <div className="creative-listing-frame mt-10 w-full rounded-[1.25rem] border-2 border-primary bg-background p-3 shadow-[0_18px_50px_rgba(11,27,58,0.08)] sm:mt-12 sm:rounded-[1.5rem] sm:p-5 lg:p-6">
        <div className="mb-3 flex items-center justify-between gap-3 px-0.5 sm:mb-4">
          <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-text-secondary">
            Listing preview
          </p>
          <p className="font-mono text-small font-semibold text-primary" aria-live="polite">
            {String(activeIndex + 1).padStart(2, "0")} /{" "}
            {String(visuals.length).padStart(2, "0")}
          </p>
        </div>

        <div className="grid gap-3 sm:gap-4 lg:grid-cols-[5.5rem_minmax(0,1fr)] lg:items-stretch">
          {visuals.length > 1 ? (
            <ul
              className="order-2 grid grid-cols-5 gap-2 lg:order-1 lg:grid-cols-1 lg:gap-2.5"
              role="list"
              aria-label="Creative examples"
            >
              {visuals.map((item, index) => {
                const isActive = index === activeIndex;
                return (
                  <li key={item.image} className="min-w-0">
                    <button
                      ref={(node) => {
                        thumbRefs.current[index] = node;
                      }}
                      type="button"
                      aria-label={
                        item.caption || `Creative example ${index + 1}`
                      }
                      aria-pressed={isActive}
                      className={cn(
                        "creative-listing-thumb relative aspect-square w-full overflow-hidden rounded-[10px] border-2 bg-surface outline-none transition-[border-color,box-shadow] duration-300",
                        "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
                        isActive
                          ? "border-accent shadow-[0_0_0_1px_rgba(228,121,17,0.35)]"
                          : "border-primary/20 hover:border-primary/50",
                      )}
                      onMouseEnter={() => selectIndex(index)}
                      onFocus={() => selectIndex(index)}
                      onClick={() => selectIndex(index)}
                      onKeyDown={(event) => {
                        if (event.key === "ArrowRight" || event.key === "ArrowDown") {
                          event.preventDefault();
                          selectIndex(index + 1, true);
                        }
                        if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
                          event.preventDefault();
                          selectIndex(index - 1, true);
                        }
                      }}
                    >
                      <Image
                        src={item.image}
                        alt=""
                        fill
                        className="object-cover"
                        sizes="(max-width: 1024px) 20vw, 88px"
                        quality={70}
                        loading="lazy"
                      />
                    </button>
                  </li>
                );
              })}
            </ul>
          ) : null}

          <div className="order-1 min-w-0 lg:order-2">
            <div className="creative-listing-stage relative aspect-[4/3] w-full overflow-hidden rounded-[10px] border border-primary/15 bg-surface sm:aspect-[16/10] lg:aspect-auto lg:min-h-[26rem] xl:min-h-[30rem]">
              {visuals.map((item, index) => {
                const isActive = index === activeIndex;
                return (
                  <Image
                    key={item.image}
                    src={item.image}
                    alt={item.alt || "Amazon listing creative example"}
                    fill
                    className={cn(
                      "object-cover transition-opacity duration-500 ease-out",
                      isActive ? "opacity-100" : "opacity-0",
                    )}
                    sizes="(max-width: 1024px) 100vw, 90vw"
                    quality={80}
                    priority={index === 0}
                    loading={index === 0 ? undefined : "lazy"}
                  />
                );
              })}
            </div>

            <p className="mt-3 min-h-[1.5rem] text-base font-bold tracking-tight text-primary sm:min-h-[1.75rem] sm:text-lg">
              {active.caption || "\u00A0"}
            </p>
          </div>
        </div>
      </div>
    </SectionShell>
  );
}

import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface CaseStudiesSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface CaseItem {
  metric: string;
  brand: string;
  category: string;
  service: string;
  description: string;
  href: string;
  image: string;
  imageAlt: string;
  atmosphere: string;
  atmosphereAlt: string;
}

/**
 * Portfolio-row case cards — Project One “see work” language:
 * hard navy borders, media-first tiles, horizontal scroll on wide screens.
 */
export function CaseStudiesSection({ id, data }: CaseStudiesSectionProps) {
  const eyebrow = readString(data.eyebrow, "Selected results");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  const items: CaseItem[] = readRecordArray(data.items)
    .map((item) => {
      const metric = readString(item.metric);
      const brand = readString(item.brand);
      if (!brand && !metric) return null;
      return {
        metric,
        brand,
        category: readString(item.category),
        service: readString(item.service),
        description: readString(item.description),
        href: readString(item.href),
        image: readString(item.image),
        imageAlt: readString(item.imageAlt, brand),
        atmosphere: readString(item.atmosphere),
        atmosphereAlt: readString(item.atmosphereAlt, brand),
      };
    })
    .filter((item): item is CaseItem => item !== null);

  if (items.length === 0) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between lg:gap-10">
        <div className="max-w-2xl">
          {eyebrow ? (
            <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
              {eyebrow}
            </p>
          ) : null}
          <h2
            id={headingId}
            className="mt-3 text-[1.85rem] font-bold leading-[1.08] tracking-[-0.03em] text-text-primary text-balance sm:text-4xl lg:text-[2.75rem]"
          >
            {heading}
          </h2>
          {subheading ? (
            <p className="mt-4 text-base font-semibold leading-snug text-text-primary/75 sm:text-lg">
              {subheading}
            </p>
          ) : null}
        </div>
        {cta ? (
          <PrimaryButton
            asChild
            variant="primary"
            className="hidden w-full shrink-0 sm:inline-flex sm:w-auto"
          >
            <Link href={cta.href}>
              {cta.label}
              <span
                className="inline-flex h-7 w-7 items-center justify-center rounded-full bg-text-on-dark/15 text-text-on-dark"
                aria-hidden="true"
              >
                <ArrowRight className="h-3.5 w-3.5" />
              </span>
            </Link>
          </PrimaryButton>
        ) : null}
      </div>

      <ul className="mt-10 flex gap-4 overflow-x-auto pb-2 [-ms-overflow-style:none] [scrollbar-width:none] sm:mt-12 sm:gap-5 [&::-webkit-scrollbar]:hidden md:grid md:grid-cols-3 md:overflow-visible md:pb-0">
        {items.map((item) => {
          const key = `${item.brand}-${item.metric}`;
          const scene = item.atmosphere || item.image;
          const sceneAlt = item.atmosphereAlt || item.imageAlt || item.brand;

          return (
            <li
              key={key}
              className="flex w-[min(85vw,20rem)] shrink-0 md:w-auto md:min-w-0"
            >
              <article
                className={cn(
                  "case-proof-card group flex w-full flex-1 flex-col overflow-hidden rounded-[10px] border-2 border-primary bg-background",
                  "shadow-[0_14px_36px_rgba(11,27,58,0.08)] transition-[transform,box-shadow] duration-300",
                  "hover:-translate-y-0.5 hover:shadow-[0_20px_44px_rgba(11,27,58,0.12)]",
                  "focus-within:ring-2 focus-within:ring-accent focus-within:ring-offset-2",
                )}
              >
                {scene ? (
                  <div className="case-proof-media relative aspect-[4/3] w-full shrink-0 overflow-hidden bg-primary">
                    <Image
                      src={scene}
                      alt=""
                      fill
                      aria-hidden="true"
                      className="case-proof-blur scale-125 object-cover opacity-70 blur-2xl"
                      sizes="(max-width: 768px) 85vw, 33vw"
                      quality={70}
                      loading="lazy"
                    />
                    <Image
                      src={scene}
                      alt={sceneAlt}
                      fill
                      className="media-hover-zoom object-cover"
                      sizes="(max-width: 768px) 85vw, 33vw"
                      quality={80}
                      loading="lazy"
                    />
                    <div
                      className="pointer-events-none absolute inset-0 bg-gradient-to-t from-primary/90 via-primary/20 to-transparent"
                      aria-hidden="true"
                    />

                    {item.image ? (
                      <div className="absolute left-3 top-3 z-10 h-11 w-11 overflow-hidden rounded-[8px] border-2 border-primary bg-background shadow-sm sm:h-12 sm:w-12">
                        <Image
                          src={item.image}
                          alt={item.imageAlt || item.brand}
                          fill
                          className="object-contain p-1"
                          sizes="48px"
                          quality={80}
                          loading="lazy"
                        />
                      </div>
                    ) : null}

                    {item.metric ? (
                      <p className="absolute bottom-3 left-3 right-3 z-10 text-2xl font-bold tracking-tight text-accent sm:bottom-4 sm:left-4 sm:text-3xl">
                        {item.metric}
                      </p>
                    ) : null}
                  </div>
                ) : null}

                <div className="flex flex-1 flex-col px-4 py-4 sm:px-5 sm:py-5">
                  {item.brand ? (
                    <h3 className="text-lg font-bold tracking-tight text-primary sm:text-xl">
                      {item.brand}
                    </h3>
                  ) : null}

                  {(item.category || item.service) && (
                    <p className="mt-1 text-sm font-medium text-text-secondary">
                      {[item.category, item.service].filter(Boolean).join(" · ")}
                    </p>
                  )}

                  {item.description ? (
                    <p className="mt-3 flex-1 text-sm font-medium leading-relaxed text-text-secondary">
                      {item.description}
                    </p>
                  ) : null}

                  {item.href ? (
                    <Link
                      href={item.href}
                      className="mt-4 inline-flex min-h-11 items-center gap-2 text-sm font-bold text-primary underline-offset-4 transition-colors hover:text-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                    >
                      Read case study
                      <ArrowRight className="h-4 w-4" aria-hidden="true" />
                    </Link>
                  ) : null}
                </div>
              </article>
            </li>
          );
        })}
      </ul>

      {cta ? (
        <div className="mt-8 flex sm:hidden">
          <PrimaryButton asChild variant="primary" className="w-full">
            <Link href={cta.href}>
              {cta.label}
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </Link>
          </PrimaryButton>
        </div>
      ) : null}
    </SectionShell>
  );
}

