    const h2 = s?.querySelector('h2');
    const frame = s?.querySelector('.creative-listing-frame, [class*=\"listing\"]') || s?.querySelector('div.mt-10, div.mt-8');
    const fs = frame ? getComputedStyle(frame) : null;
    return {
      h2: h2 ? { text: h2.textContent.trim(), size: getComputedStyle(h2).fontSize, weight: getComputedStyle(h2).fontWeight } : null,
