  await page.goto('http://localhost:3000/#case-studies', { waitUntil: 'load', timeout: 120000 });
  await page.waitForTimeout(1000);
  const cases = await page.evaluate(() => {
    const s = document.querySelector('#case-studies');
    s?.scrollIntoView({ block: 'center' });
    const h2 = s?.querySelector('h2');
    const cards = Array.from(s.querySelectorAll('article'));
    const first = cards[0];
    const cs = first ? getComputedStyle(first) : null;
    const brand = first?.querySelector('h3');
    const metric = first ? Array.from(first.querySelectorAll('p')).find(p => /%|increase|growth/i.test(p.textContent||'')) : null;
    const links = Array.from(s.querySelectorAll('a')).map(a => a.getAttribute('href')).filter(Boolean);
    return {
      h2: h2 ? { text: h2.textContent.trim(), size: getComputedStyle(h2).fontSize, weight: getComputedStyle(h2).fontWeight } : null,
      cardCount: cards.length,
