import Link from "next/link";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface ComparisonSectionProps {
  id: string;
  data: Record<string, unknown>;
}

/**
 * Project One “Smarter Way” comparison language — oversized type,
 * hard navy borders, agency column punch highlight.
 */
export function ComparisonSection({ id, data }: ComparisonSectionProps) {
  const eyebrow = readString(data.eyebrow, "Clear comparison");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const columns = data.columns as Record<string, unknown> | undefined;
  const agencyColumn = readString(columns?.agency, "eCom Gliders");
  const alternativeColumn = readString(columns?.alternative, "DIY / In-house");
  const rows = readRecordArray(data.rows);
  const deepLink = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="max-w-3xl">
        {eyebrow ? (
          <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
            {eyebrow}
          </p>
        ) : null}
        <h2
          id={headingId}
          className="mt-3 text-[1.85rem] font-bold leading-[1.08] tracking-[-0.03em] text-text-primary text-balance sm:text-4xl lg:text-[2.75rem]"
        >
          {heading}
        </h2>
        {subheading ? (
          <p className="mt-4 text-base font-semibold leading-snug text-text-primary/75 sm:text-lg">
            {subheading}
          </p>
        ) : null}
      </div>

      <div className="mt-10 hidden overflow-hidden rounded-[1.25rem] border-2 border-primary bg-background shadow-[0_18px_50px_rgba(11,27,58,0.08)] md:mt-12 md:block">
        <table className="w-full text-left text-body">
          <thead>
            <tr className="bg-primary text-text-on-dark">
              <th
                scope="col"
                className="px-6 py-4 text-[11px] font-bold uppercase tracking-[0.14em] text-text-on-dark/70"
              >
                Feature
              </th>
              <th
                scope="col"
                className="bg-accent px-6 py-4 text-[11px] font-bold uppercase tracking-[0.14em] text-primary"
              >
                {agencyColumn}
              </th>
              <th
                scope="col"
                className="px-6 py-4 text-[11px] font-bold uppercase tracking-[0.14em] text-text-on-dark/70"
              >
                {alternativeColumn}
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => {
              const feature = readString(row.feature);
              const agency = readString(row.agency);
              const alternative = readString(row.alternative);

              return (
                <tr
                  key={feature}
                  className="border-t-2 border-primary/10 last:border-b-0"
                >
                  <th
                    scope="row"
                    className="px-6 py-4 text-sm font-bold text-primary"
                  >
                    {feature}
                  </th>
                  <td className="bg-accent/10 px-6 py-4 text-sm font-semibold text-primary">
                    {agency}
                  </td>
                  <td className="px-6 py-4 text-sm font-medium text-text-secondary">
                    {alternative}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <ul className="mt-8 space-y-3 md:hidden">
        {rows.map((row) => {
          const feature = readString(row.feature);
          const agency = readString(row.agency);
          const alternative = readString(row.alternative);

          return (
            <li
              key={feature}
              className="overflow-hidden rounded-[10px] border-2 border-primary bg-background"
            >
              <p className="bg-primary px-4 py-3 text-sm font-bold text-text-on-dark">
                {feature}
              </p>
              <dl className="space-y-3 p-4 text-sm">
                <div>
                  <dt className="text-[11px] font-bold uppercase tracking-[0.12em] text-accent">
                    {agencyColumn}
                  </dt>
                  <dd className="mt-1 font-semibold text-primary">{agency}</dd>
                </div>
                <div>
                  <dt className="text-[11px] font-bold uppercase tracking-[0.12em] text-text-secondary">
                    {alternativeColumn}
                  </dt>
                  <dd className="mt-1 font-medium text-text-secondary">
                    {alternative}
                  </dd>
                </div>
              </dl>
            </li>
          );
        })}
      </ul>

      {deepLink ? (
        <p className="mt-8 text-center text-sm">
          <Link
            href={deepLink.href}
            className="font-bold text-primary underline-offset-4 hover:text-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
          >
            {deepLink.label}
          </Link>
        </p>
      ) : null}
    </SectionShell>
  );
}

import { cn } from "@/lib/utils";
import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface StatsSectionProps {
  id: string;
  data: Record<string, unknown>;
}

/**
 * Project One trust-metric language — oversized values on punch / canvas tiles.
 */
export function StatsSection({ id, data }: StatsSectionProps) {
  const eyebrow = readString(data.eyebrow, "Verified proof");
  const items = readRecordArray(data.items);

  if (items.length === 0) return null;

  return (
    <SectionShell id={id} className="py-12 sm:py-16 lg:py-20">
      {eyebrow ? (
        <p className="mb-6 text-center text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:mb-8 sm:text-xs">
          {eyebrow}
        </p>
      ) : null}

      <ul className="grid grid-cols-2 gap-3 lg:grid-cols-4 lg:gap-4">
        {items.map((item, index) => {
          const value = readString(item.value);
          const label = readString(item.label);
          const key = `${value}-${label}`;
          const punch = index % 2 === 0;

          return (
            <li key={key} className="flex min-h-0">
              <article
                className={cn(
                  "flex w-full flex-col justify-between rounded-[10px] border-2 border-primary p-5 sm:p-6",
                  punch
                    ? "bg-accent text-primary"
                    : "bg-primary text-text-on-dark",
                )}
              >
                <p
                  className={cn(
                    "text-3xl font-bold tracking-tight sm:text-4xl lg:text-5xl",
                    punch ? "text-primary" : "text-accent",
                  )}
                >
                  {value}
                </p>
                <p
                  className={cn(
                    "mt-3 text-sm font-semibold leading-snug",
                    punch ? "text-primary/80" : "text-text-on-dark/75",
                  )}
                >
                  {label}
                </p>
              </article>
            </li>
          );
        })}
      </ul>
    </SectionShell>
  );
}

import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";
import { TrustClientMarquee } from "./trust-client-marquee";
import { TrustLogo } from "./trust-logo";

interface TrustBarSectionProps {
  id: string;
  data: Record<string, unknown>;
}

function readLogoItems(value: unknown) {
  return readRecordArray(value)
    .map((item) => {
      const label = readString(item.label);
      const image = readString(item.image);
      const alt = readString(item.alt, label);
      const href = readString(item.href) || undefined;
      if (!label && !image) return null;
      return { label, image, alt, href };
    })
    .filter((item): item is NonNullable<typeof item> => item !== null);
}

/**
 * Trust strip — Project One quiet proof chrome: strong eyebrow type,
 * navy-bordered cert tiles, existing client marquee retained.
 */
export function TrustBarSection({ id, data }: TrustBarSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const subheading = readString(data.subheading);

  const partners = readLogoItems(data.partners);
  const clients = readLogoItems(data.clients);
  const reviews = readLogoItems(data.reviews);
  const press = readLogoItems(data.press);

  const legacyBadge =
    data.badge && typeof data.badge === "object"
      ? (data.badge as Record<string, unknown>)
      : undefined;
  const legacyLogos = readLogoItems(data.logos);

  const partnerItems =
    partners.length > 0
      ? partners
      : legacyBadge
        ? [
            {
              label: readString(legacyBadge.label),
              image: readString(legacyBadge.image),
              alt: readString(legacyBadge.label),
              href: readString(legacyBadge.href) || undefined,
            },
            ...legacyLogos.filter(
              (logo) => !logo.image.includes("amazon-verified-partner"),
            ),
          ].filter((item) => item.label || item.image)
        : legacyLogos.filter(
            (logo) => !logo.image.includes("amazon-verified-partner"),
          );

  const reviewAndPress = [...reviews, ...press];

  return (
    <SectionShell id={id} className="py-10 sm:py-12 lg:py-14">
      <div className="flex flex-col items-center gap-6 text-center sm:gap-7">
        {eyebrow || subheading ? (
          <div className="max-w-2xl space-y-2">
            {eyebrow ? (
              <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
                {eyebrow}
              </p>
            ) : null}
            {subheading ? (
              <p className="text-base font-semibold text-text-primary/80 sm:text-lg">
                {subheading}
              </p>
            ) : null}
          </div>
        ) : null}

        {partnerItems.length > 0 ? (
          <ul className="flex flex-wrap items-center justify-center gap-3">
            {partnerItems.map((item) => (
              <li
                key={`partner-${item.image || item.label}`}
                className="rounded-[10px] border-2 border-primary/15 bg-background p-1 shadow-[0_8px_24px_rgba(11,27,58,0.05)]"
              >
                <TrustLogo
                  label={item.label}
                  image={item.image}
                  alt={item.alt}
                  href={item.href}
                  variant="cert"
                />
              </li>
            ))}
          </ul>
        ) : null}

        {clients.length > 0 ? <TrustClientMarquee items={clients} /> : null}

        {reviewAndPress.length > 0 ? (
          <ul className="flex flex-wrap items-center justify-center gap-3 sm:gap-4">
            {reviewAndPress.map((item) => (
              <li
                key={`badge-${item.image || item.label}`}
                className="rounded-[10px] border-2 border-primary/15 bg-background p-1"
              >
                <TrustLogo
                  label={item.label}
                  image={item.image}
                  alt={item.alt}
                  href={item.href}
                  variant="badge"
                />
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    </SectionShell>
  );
}

