import { readRecordArray, readString } from "./section-data";
import { FaqAccordion } from "./faq-accordion";
import { SectionShell } from "./section-shell";

interface FaqSectionProps {
  id: string;
  data: Record<string, unknown>;
}

/**
 * Project One FAQ language — oversized heading, hard-border accordion stack.
 */
export function FaqSection({ id, data }: FaqSectionProps) {
  const eyebrow = readString(data.eyebrow, "Answers");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const items = readRecordArray(data.items).map((item) => ({
    question: readString(item.question),
    answer: readString(item.answer),
  }));
  const headingId = `${id}-heading`;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="mx-auto max-w-3xl">
        <div className="max-w-2xl">
          {eyebrow ? (
            <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
              {eyebrow}
            </p>
          ) : null}
          <h2
            id={headingId}
            className="mt-3 text-[1.85rem] font-bold leading-[1.08] tracking-[-0.03em] text-text-primary text-balance sm:text-4xl lg:text-[2.75rem]"
          >
            {heading}
          </h2>
          {subheading ? (
            <p className="mt-4 text-base font-semibold leading-snug text-text-primary/75 sm:text-lg">
              {subheading}
            </p>
          ) : null}
        </div>

        <div className="mt-10 overflow-hidden rounded-[1.25rem] border-2 border-primary bg-background sm:mt-12">
          <FaqAccordion items={items} />
        </div>
      </div>
    </SectionShell>
  );
}

"use client";

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { cn } from "@/lib/utils";

interface FaqAccordionProps {
  items: Array<{ question: string; answer: string }>;
}

export function FaqAccordion({ items }: FaqAccordionProps) {
  return (
    <Accordion type="single" collapsible className="w-full max-w-none">
      {items.map((item, index) => {
        const itemValue = `faq-${index}`;
        const isLast = index === items.length - 1;

        return (
          <AccordionItem
            key={itemValue}
            value={itemValue}
            className={cn(
              "border-primary/15 px-4 sm:px-6",
              !isLast && "border-b-2",
              isLast && "border-b-0",
            )}
          >
            <AccordionTrigger className="py-5 text-left text-base font-bold tracking-tight text-primary hover:no-underline sm:text-lg [&[data-state=open]]:text-accent">
              {item.question}
            </AccordionTrigger>
            <AccordionContent>
              <p className="pb-2 text-sm font-medium leading-relaxed text-text-secondary sm:text-base">
                {item.answer}
              </p>
            </AccordionContent>
          </AccordionItem>
        );
      })}
    </Accordion>
  );
}

