import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { readNavLink, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface CtaSectionProps {
  id: string;
  data: Record<string, unknown>;
}

/**
 * Project One final-CTA language — oversized headline + hard-chrome conversion card.
 * eCom free-audit CTAs only (no PO copy, pricing, or contact form fields).
 */
export function CtaSection({ id, data }: CtaSectionProps) {
  const eyebrow = readString(data.eyebrow, "Next step");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const cardTitle = readString(data.cardTitle, "Free Amazon audit");
  const assurance = readString(
    data.assurance,
    "No obligation. Clear priorities from PPC, listings, and catalog review.",
  );
  const primaryCta = readNavLink(data.primaryCta);
  const secondaryCta = readNavLink(data.secondaryCta);
  const phone = data.phone as Record<string, unknown> | undefined;
  const phoneDisplay = readString(phone?.display);
  const phoneTel = readString(phone?.tel);
  const email = readString(data.email);
  const headingId = `${id}-heading`;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-14 sm:py-18 lg:py-24"
    >
      <div className="mx-auto max-w-4xl text-center">
        {eyebrow ? (
          <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
            {eyebrow}
          </p>
        ) : null}
        <h2
          id={headingId}
          className="mt-3 text-[1.85rem] font-bold leading-[1.08] tracking-[-0.03em] text-text-primary text-balance sm:text-4xl lg:text-[2.75rem]"
        >
          {heading}
        </h2>
        {subheading ? (
          <p className="mx-auto mt-4 max-w-2xl text-base font-semibold leading-snug text-text-primary/75 sm:text-lg">
            {subheading}
          </p>
        ) : null}

        <article className="relative mx-auto mt-10 max-w-xl overflow-hidden rounded-[1.25rem] border-2 border-primary bg-accent p-6 text-left shadow-[6px_6px_0_0_#0B1B3A] sm:mt-12 sm:rounded-[1.5rem] sm:p-8">
          <h3 className="text-2xl font-bold tracking-tight text-primary sm:text-[1.95rem]">
            {cardTitle}
          </h3>

