const { chromium } = require('playwright');
const out = 'docs/qa/screenshots';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  async function measure(width, height) {
    await page.setViewportSize({ width, height });
    await page.goto('http://localhost:3000/#final-cta', { waitUntil: 'load', timeout: 120000 });
    await page.waitForTimeout(1800);
    await page.evaluate(() => document.querySelector('#final-cta')?.scrollIntoView({ block: 'start' }));
    await page.waitForTimeout(500);

    const data = await page.evaluate(() => {
      const cta = document.querySelector('#final-cta');
      const footer = document.querySelector('footer');
      const pre = document.querySelector('[aria-labelledby="pre-footer-heading"]');
      const h2 = cta?.querySelector('h2');
      const card = cta?.querySelector('article');
      const cardTitle = card?.querySelector('h3');
      const preH2 = pre?.querySelector('h2');
      const hs = h2 ? getComputedStyle(h2) : null;
      const cs = card ? getComputedStyle(card) : null;
      const cts = cardTitle ? getComputedStyle(cardTitle) : null;
      const phs = preH2 ? getComputedStyle(preH2) : null;
      const fcs = footer ? getComputedStyle(footer) : null;
      const links = [...(cta?.querySelectorAll('a') || [])].map(a => ({
        t: a.textContent.replace(/\s+/g,' ').trim(),
        href: a.getAttribute('href'),
      }));
      const footLinks = [...(footer?.querySelectorAll('a') || [])].slice(0, 12).map(a => ({
        t: a.textContent.trim(),
        href: a.getAttribute('href'),
      }));
      const text = (cta?.innerText || '') + (footer?.innerText || '');
      return {
        overflowX: document.documentElement.scrollWidth > window.innerWidth + 1,
        ctaBg: cta ? getComputedStyle(cta).backgroundColor : null,
        h2: h2 ? { text: h2.textContent.trim(), size: hs.fontSize, weight: hs.fontWeight, font: hs.fontFamily.split(',')[0].replace(/"/g,''), color: hs.color } : null,
        card: card ? { bg: cs.backgroundColor, border: cs.border, radius: cs.borderRadius, shadow: cs.boxShadow } : null,
        cardTitle: cardTitle ? { text: cardTitle.textContent.trim(), size: cts.fontSize, weight: cts.fontWeight, color: cts.color } : null,
        links,
        preH2: preH2 ? { text: preH2.textContent.trim(), size: phs.fontSize, weight: phs.fontWeight, color: phs.color } : null,
        footer: footer ? { bg: fcs.backgroundColor, radius: fcs.borderRadius } : null,
        footLinks,
        hasPO: /Won.?t Build|Reserve Your Spot|KHULA|One plan\. One site/i.test(text),
        hasEcom: /free Amazon|eCom Gliders|free audit/i.test(text),
      };
    });

    const suffix = String(width);
    await page.locator('#final-cta').screenshot({ path: `${out}/po-pass10-ours-cta-after-${suffix}.png` });
    await page.locator('footer').screenshot({ path: `${out}/po-pass10-ours-footer-after-${suffix}.png` });
    return data;
  }

  const desktop = await measure(1440, 900);
  const mobile = await measure(390, 844);
  console.log(JSON.stringify({ desktop, mobile }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
