"use client";

import { useEffect, useId, useState } from "react";
import { cn } from "@/lib/utils";

interface SpawnedBubble {
  id: number;
  text: string;
  left: number;
  top: number;
  rotate: number;
}

interface PainSpawnBubblesProps {
  quotes: string[];
  className?: string;
}

const SLOT_PRESETS: Array<{ left: number; top: number; rotate: number }> = [
  { left: 6, top: 8, rotate: -6 },
  { left: 52, top: 4, rotate: 4 },
  { left: 28, top: 22, rotate: -3 },
  { left: 62, top: 28, rotate: 5 },
  { left: 12, top: 48, rotate: 3 },
  { left: 48, top: 52, rotate: -5 },
  { left: 70, top: 62, rotate: 2 },
  { left: 18, top: 68, rotate: -4 },
];

/**
 * Project One “Sound Familiar” speech-bubble language —
 * orange spawn popups with eCom seller friction copy only.
 */
export function PainSpawnBubbles({ quotes, className }: PainSpawnBubblesProps) {
  const reactId = useId();
  const [bubbles, setBubbles] = useState<SpawnedBubble[]>([]);
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduceMotion(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  useEffect(() => {
    if (quotes.length === 0) return;

    if (reduceMotion) {
      setBubbles(
        quotes.slice(0, 3).map((text, index) => {
          const slot = SLOT_PRESETS[index % SLOT_PRESETS.length];
          return {
            id: index,
            text,
            left: slot.left,
            top: slot.top,
            rotate: slot.rotate,
          };
        }),
      );
      return;
    }

    let seq = 0;
    let quoteCursor = 0;
    let slotCursor = Math.floor(Math.random() * SLOT_PRESETS.length);
    const timers: number[] = [];

    const spawn = () => {
      const text = quotes[quoteCursor % quotes.length];
      quoteCursor += 1;
      const slot = SLOT_PRESETS[slotCursor % SLOT_PRESETS.length];
      slotCursor += 1 + Math.floor(Math.random() * 2);
      const id = ++seq;
      const jitterLeft = slot.left + (Math.random() * 6 - 3);
      const jitterTop = slot.top + (Math.random() * 6 - 3);

      setBubbles((prev) => {
        const next = [
          ...prev,
          {
            id,
            text,
            left: Math.min(78, Math.max(2, jitterLeft)),
            top: Math.min(78, Math.max(2, jitterTop)),
            rotate: slot.rotate + (Math.random() * 4 - 2),
          },
        ];
        return next.slice(-5);
      });

      timers.push(
        window.setTimeout(() => {
          setBubbles((prev) => prev.filter((b) => b.id !== id));
        }, 3200 + Math.random() * 900),
      );
    };

    spawn();
    const interval = window.setInterval(spawn, 1100);
    return () => {
      window.clearInterval(interval);
      timers.forEach((t) => window.clearTimeout(t));
    };
  }, [quotes, reduceMotion]);

  if (quotes.length === 0) return null;

  return (
    <div
      className={cn(
        "pointer-events-none absolute inset-0 z-20 overflow-hidden",
        className,
      )}
      aria-hidden="true"
    >
      {bubbles.map((bubble) => (
        <span
          key={`${reactId}-${bubble.id}`}
          className={cn(
            "absolute max-w-[11.5rem] rounded-2xl bg-accent px-3 py-2 text-left text-[11px] font-bold leading-snug text-primary shadow-[0_10px_24px_rgba(228,121,17,0.35)] sm:max-w-[13rem] sm:px-3.5 sm:py-2.5 sm:text-xs",
            !reduceMotion && "animate-pain-bubble-spawn",
          )}
          style={{
            left: `${bubble.left}%`,
            top: `${bubble.top}%`,
            transform: `rotate(${bubble.rotate}deg)`,
          }}
        >
          {bubble.text}
          <span
            className="absolute -bottom-1.5 left-5 h-3 w-3 rotate-45 bg-accent"
