"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { ArrowUpRight } from "lucide-react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof primaryButtonVariants> {
  asChild?: boolean;
  /** Hide trailing arrow chip (rare — links that are not punch CTAs). */
  hideArrow?: boolean;
}

/**
 * Project One CTA anatomy (lime→orange):
 * soft-rect 10px shell, uppercase 12/700 label, asymmetric padding,
 * always-on square arrow chip on the right (not a hover-only dot).
 */
const primaryButtonVariants = cva(
  [
    "group relative inline-flex items-center justify-center",
    "rounded-[10px] text-[12px] font-bold uppercase tracking-[0.04em]",
    "transition-colors duration-200 ease-out",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-50",
    "motion-safe:hover:-translate-y-px motion-safe:active:translate-y-0",
  ].join(" "),
  {
    variants: {
      variant: {
        /** Navy shell + orange arrow chip (PO dark RESERVE) */
        primary:
          "bg-primary text-text-on-dark hover:bg-primary/90",
        /** Orange shell + navy arrow chip (PO lime RESERVE) */
        accent:
          "bg-accent text-primary hover:bg-accent-alt",
        /** Light shell on dark surfaces */
        onDark:
          "bg-text-on-dark text-primary hover:bg-text-on-dark/90",
      },
      size: {
        /** ~40px — header */
        sm: "h-10 min-h-10 gap-2 py-2 pl-4 pr-2",
        /** ~44px */
        default: "h-11 min-h-11 gap-2.5 py-2 pl-4 pr-2",
        /** ~48px — hero / conversion */
        lg: "h-12 min-h-12 gap-2.5 py-2 pl-6 pr-2",
      },
    },
    defaultVariants: {
      variant: "primary",
      size: "default",
    },
  },
);

function chipClasses(
  variant: "primary" | "accent" | "onDark" | null | undefined,
  size: "sm" | "default" | "lg" | null | undefined,
): string {
  const tone =
    variant === "accent"
      ? "bg-primary text-text-on-dark"
      : variant === "onDark"
        ? "bg-accent text-primary"
        : "bg-accent text-primary";

  const box =
    size === "lg"
      ? "h-8 w-8 rounded-[4px]"
      : size === "sm"
        ? "h-6 w-6 rounded-[5px]"
        : "h-7 w-7 rounded-[5px]";

  return cn(
    "inline-flex shrink-0 items-center justify-center",
    box,
    tone,
  );
}

function iconSize(size: "sm" | "default" | "lg" | null | undefined): number {
  if (size === "lg") return 16;
  if (size === "sm") return 14;
  return 15;
}

function isDecorativeArrowNode(node: React.ReactNode): boolean {
  if (!React.isValidElement(node)) return false;
  const type = node.type;
  const name =
    typeof type === "string"
      ? type
      : ((type as { displayName?: string; name?: string }).displayName ||
          (type as { name?: string }).name ||
          "");

  if (/^(ArrowRight|ArrowUpRight|ArrowRightIcon)$/i.test(name)) return true;

  const props = node.props as {
    "aria-hidden"?: boolean | string;
    children?: React.ReactNode;
    className?: string;
  };

  if (props["aria-hidden"] === true || props["aria-hidden"] === "true") {
    const kids = React.Children.toArray(props.children);
    if (kids.length === 0) return true;
    if (kids.every(isDecorativeArrowNode)) return true;
  }

  if (
    typeof props.className === "string" &&
    /inline-flex.*items-center.*justify-center/.test(props.className) &&
    React.Children.toArray(props.children).every(isDecorativeArrowNode)
  ) {
    return true;
  }

  return false;
}

/** Keep label text; drop manual arrow chips so we never double-render. */
function labelFromChildren(children: React.ReactNode): React.ReactNode {
  const kept = React.Children.toArray(children).filter(
    (child) => !isDecorativeArrowNode(child),
  );
  return kept.length === 1 ? kept[0] : kept;
}

function ArrowChip({
  variant,
  size,
}: {
  variant: "primary" | "accent" | "onDark" | null | undefined;
  size: "sm" | "default" | "lg" | null | undefined;
}) {
  return (
    <span className={chipClasses(variant, size)} aria-hidden="true">
      <ArrowUpRight
        size={iconSize(size)}
        strokeWidth={2.5}
        className="shrink-0"
      />
    </span>
  );
}

const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  (
    {
      className,
      children,
      asChild = false,
      variant = "primary",
      size = "default",
      hideArrow = false,
      type = "button",
      ...props
    },
    ref,
  ) => {
    const outerClassName = cn(
      primaryButtonVariants({ variant, size }),
      className,
    );

    if (asChild) {
      if (!React.isValidElement(children)) {
        return null;
      }

      const child = children as React.ReactElement<{
        className?: string;
        children?: React.ReactNode;
      }>;

      return (
        <Slot
          className={cn(outerClassName, child.props.className)}
          ref={ref}
          {...props}
        >
          {React.cloneElement(child, {
            className: undefined,
            children: (
              <>
                <span className="min-w-0 truncate">
                  {labelFromChildren(child.props.children)}
                </span>
                {hideArrow ? null : (
                  <ArrowChip variant={variant} size={size} />
                )}
              </>
            ),
          })}
        </Slot>
      );
    }

    return (
      <button
        ref={ref}
        type={type}
        className={outerClassName}
        {...props}
      >
        <span className="min-w-0 truncate">{labelFromChildren(children)}</span>
        {hideArrow ? null : <ArrowChip variant={variant} size={size} />}
      </button>
    );
  },
);
PrimaryButton.displayName = "PrimaryButton";

export { PrimaryButton, primaryButtonVariants };

