const { chromium } = require('playwright');
const out = 'docs/qa/screenshots';
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 120000 });
  await page.waitForTimeout(2000);

  const data = await page.evaluate(() => {
    const headerCta = [...document.querySelectorAll('header a')].find(a => /free audit|audit/i.test(a.textContent||'') && a.getBoundingClientRect().height > 30);
    const heroCtas = [...document.querySelectorAll('#hero a')].filter(a => a.getBoundingClientRect().height > 36);
    function dump(el) {
      if (!el) return null;
      const s = getComputedStyle(el);
      const chip = el.querySelector('span[aria-hidden="true"]');
      const cs = chip ? getComputedStyle(chip) : null;
      const svg = chip?.querySelector('svg');
      return {
        text: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0,40),
        h: Math.round(el.getBoundingClientRect().height),
        w: Math.round(el.getBoundingClientRect().width),
        radius: s.borderRadius,
        pad: s.padding,
        gap: s.gap,
        bg: s.backgroundColor,
        chip: chip ? {
          w: Math.round(chip.getBoundingClientRect().width),
          h: Math.round(chip.getBoundingClientRect().height),
          radius: cs.borderRadius,
          bg: cs.backgroundColor,
          hasSvg: !!svg,
        } : null,
      };
    }
    return {
      header: dump(headerCta),
      hero: heroCtas.slice(0,2).map(dump),
      overflowX: document.documentElement.scrollWidth > window.innerWidth + 1,
    };
  });

  await page.locator('header').screenshot({ path: out + '/po-btn-fixed-header-1440.png' });
  await page.locator('#hero').screenshot({ path: out + '/po-btn-fixed-hero-1440.png' });
  console.log(JSON.stringify(data, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
