const { chromium } = require('playwright');
const out = 'docs/qa/screenshots';
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 120000 });
  await page.waitForTimeout(2000);

  const dump = async (selectorLabel) => {
    return page.evaluate((label) => {
      const els = [...document.querySelectorAll('a,button')].filter(el => {
        const t = (el.innerText||'').replace(/\s+/g,' ').trim();
        const h = el.getBoundingClientRect().height;
        if (h < 36) return false;
        if (label === 'header') return /FREE AUDIT|^AUDIT$/i.test(t) && el.closest('header');
        if (label === 'heroAccent') return /GET YOUR FREE AUDIT/i.test(t);
        if (label === 'heroPrimary') return /SEE CLIENT RESULTS/i.test(t);
        return false;
      });
      const el = els[0];
      if (!el) return { label, missing: true };
      const s = getComputedStyle(el);
      const chip = el.querySelector('span[aria-hidden="true"]');
      const cs = chip ? getComputedStyle(chip) : null;
      const svg = chip?.querySelector('svg');
      const ss = svg ? getComputedStyle(svg) : null;
      return {
        label,
        text: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0,40),
        shadow: s.boxShadow,
        border: s.border,
        radius: s.borderRadius,
        chipRadius: cs?.borderRadius,
        chipBg: cs?.backgroundColor,
        arrowTransform: ss?.transform,
      };
    }, selectorLabel);
  };

  const before = {
    header: await dump('header'),
    heroAccent: await dump('heroAccent'),
    heroPrimary: await dump('heroPrimary'),
  };

  // hover hero accent
  const heroBtn = page.locator('#hero a', { hasText: /Get your free audit/i }).first();
  await heroBtn.hover();
  await page.waitForTimeout(300);
  const afterHover = await page.evaluate(() => {
    const el = [...document.querySelectorAll('#hero a')].find(a => /GET YOUR FREE AUDIT/i.test(a.innerText||''));
    const svg = el?.querySelector('svg');
    return svg ? getComputedStyle(svg).transform : null;
  });

  await page.locator('header').screenshot({ path: out + '/po-btn-hardshadow-header-1440.png' });
  await page.locator('#hero').screenshot({ path: out + '/po-btn-hardshadow-hero-1440.png' });

  console.log(JSON.stringify({ before, afterHover }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
