(async () => {
  const browser = await chromium.launch({ headless: true });
  // Emulate Windows reduce-motion
  const page = await browser.newPage({ reducedMotion: 'reduce' });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 120000 });
  await page.waitForTimeout(2500);

  const heroBtn = page.locator('#hero a').filter({ hasText: /Get your free audit/i }).first();
  await heroBtn.hover({ force: true });
  await page.waitForTimeout(350);

  const btn = await heroBtn.evaluate((el) => {
    const svg = el.querySelector('.po-btn-arrow');
    return {
      reduced: window.matchMedia('(prefers-reduced-motion: reduce)').matches,
      dataHover: el.getAttribute('data-po-hover'),
      arrowTransform: svg ? getComputedStyle(svg).transform : null,
      shadow: getComputedStyle(el).boxShadow,
      transition: svg ? getComputedStyle(svg).transitionDuration : null,
    };
  });

  await page.evaluate(() => document.querySelector('#pain-strip')?.scrollIntoView({ block: 'center' }));
  await page.waitForTimeout(2200);
  const bubbles = await page.evaluate(() => {
    const spans = [...document.querySelectorAll('#pain-strip span')].filter(el => {
      const s = getComputedStyle(el);
      return s.backgroundColor === 'rgb(228, 121, 17)' && (el.textContent||'').trim().length > 8;
    });
    return spans.slice(0, 3).map(el => ({
      text: el.textContent.trim().slice(0, 40),
      opacity: getComputedStyle(el).opacity,
      transform: getComputedStyle(el).transform,
    }));
  });

  console.log(JSON.stringify({ btn, bubbles }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
