"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Phone } from "lucide-react";
import type { NavigationConfig } from "@/domain/content/schemas";
import type { SiteConfig } from "@/domain/content/schemas";
import { BrandLogo } from "@/components/design-system/brand-logo";
import { HeaderNav } from "@/components/layout/header-nav";
import { MobileNav } from "@/components/layout/mobile-nav";
import { PrimaryButton } from "@/components/ui/primary-button";
import { NavigationMenu } from "@/components/ui/navigation-menu";
import { cn } from "@/lib/utils";

interface SiteHeaderShellProps {
  navigation: NavigationConfig;
  site: SiteConfig;
}

/**
 * Full floating navy bar — logo + nav + phone + Free Audit inside one pill.
 * Mega menu viewport spans the full bar width (fixes column overlap).
 */
export function SiteHeaderShell({ navigation, site }: SiteHeaderShellProps) {
  const [scrolled, setScrolled] = useState(false);
  const { header } = navigation;

  useEffect(() => {
    const onScroll = () => {
      setScrolled(window.scrollY > 4);
    };

    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header
      className={cn("z-50 w-full", header.sticky && "sticky top-0")}
    >
      <div className="mx-auto max-w-[min(1280px,calc(100%-1.25rem))] py-3 sm:max-w-[min(1280px,calc(100%-2rem))] sm:py-4">
        <NavigationMenu
          delayDuration={200}
          className="relative z-50 flex w-full max-w-none flex-1 items-stretch justify-start"
        >
          <div
            className={cn(
              "flex w-full items-center gap-2 rounded-[1.25rem] border-2 border-primary bg-primary px-2.5 text-text-on-dark shadow-[6px_6px_0_0_#0B1B3A] sm:gap-3 sm:rounded-[1.5rem] sm:px-3",
              scrolled && "shadow-[4px_4px_0_0_#0B1B3A]",
            )}
            style={{ minHeight: header.height }}
          >
            <MobileNav
              navigation={navigation}
              site={site}
              className="rounded-[10px] text-text-on-dark hover:text-accent lg:hidden"
            />

            <Link
              href={header.logoHref}
              className="flex shrink-0 items-center rounded-[8px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
              aria-label={`${site.name} home`}
            >
              <BrandLogo
                width={140}
                height={42}
                className="h-7 w-auto sm:h-8"
                priority
                surface="onDark"
              />
            </Link>

            <div className="hidden min-w-0 flex-1 items-center justify-center lg:flex">
              <HeaderNav
                items={header.items}
                megaMenus={navigation.megaMenus}
                tone="onDark"
              />
            </div>

            <div className="ml-auto flex shrink-0 items-center gap-2 sm:gap-2.5">
              <a
                href={`tel:${site.phone.tel}`}
                className="mr-0.5 hidden items-center gap-1.5 border-l border-white/15 pl-3 text-sm font-medium text-text-on-dark/75 transition-colors hover:text-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary xl:inline-flex"
                aria-label={`Call ${site.phone.display}`}
              >
                <Phone className="h-3.5 w-3.5 text-accent" aria-hidden="true" />
                <span className="whitespace-nowrap">{site.phone.display}</span>
              </a>

              <PrimaryButton
                asChild
                variant="accent"
                size="sm"
                className="hidden lg:inline-flex"
              >
                <Link href={header.cta.href}>{header.cta.label}</Link>
              </PrimaryButton>

              <PrimaryButton
                asChild
                variant="accent"
                size="sm"
                className="inline-flex lg:hidden"
              >
                <Link href={header.cta.href} aria-label={header.cta.label}>
                  Audit
                </Link>
              </PrimaryButton>
            </div>
          </div>
        </NavigationMenu>
      </div>
    </header>
  );
}

