"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

export type TrustLogoVariant = "cert" | "client" | "badge";

interface TrustLogoProps {
  label: string;
  image: string;
  alt: string;
  href?: string;
  variant?: TrustLogoVariant;
  className?: string;
}

/**
 * Quiet trust mark — Project One sparse proof language.
 * Client marks are frameless; cert/badge use a single thin soft-rect.
 */
export function TrustLogo({
  label,
  image,
  alt,
  href,
  variant = "cert",
  className,
}: TrustLogoProps) {
  const [imageFailed, setImageFailed] = useState(false);

  const frameClass =
    variant === "client"
      ? "h-10 w-[120px] border-0 bg-transparent"
      : variant === "badge"
        ? "h-10 w-[128px] border border-primary/15 bg-background"
        : "h-12 w-[140px] border border-primary/15 bg-background";

  const content = (
    <div
      className={cn(
        "trust-logo-tile relative overflow-hidden rounded-[10px]",
        frameClass,
        className,
      )}
    >
      {!imageFailed && image ? (
        <Image
          src={image}
          alt={alt || label}
          fill
          className={cn(
            "object-contain",
            variant === "client" ? "p-1.5 opacity-80" : "p-2.5",
          )}
          sizes="140px"
          quality={80}
          loading="lazy"
          onError={() => setImageFailed(true)}
        />
      ) : (
        <div className="flex h-full items-center justify-center px-2">
          <Badge variant="outline" className="whitespace-nowrap text-xs">
            {label}
          </Badge>
        </div>
      )}
    </div>
  );

  if (href) {
    return (
      <Link
        href={href}
        className="inline-flex transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
        target="_blank"
        rel="noopener noreferrer"
      >
        {content}
      </Link>
    );
  }

  return content;
}

"use client";

import { useId } from "react";
import { cn } from "@/lib/utils";
import { TrustLogo } from "./trust-logo";

interface TrustClientItem {
  label: string;
  image: string;
  alt: string;
}

interface TrustClientMarqueeProps {
  items: TrustClientItem[];
}

/** Repeat a set until long enough, then duplicate for seamless -50% loop. */
function buildSeamlessTrack(
  items: TrustClientItem[],
  minItems = 8,
): TrustClientItem[] {
  if (items.length === 0) return [];
  const cycle: TrustClientItem[] = [];
  while (cycle.length < minItems) {
    cycle.push(...items);
  }
  return [...cycle, ...cycle];
}

/**
 * Single continuous client logo ribbon — quieter than dual-row stacks.
 */
export function TrustClientMarquee({ items }: TrustClientMarqueeProps) {
  const labelId = useId();

  if (items.length === 0) return null;

  const track = buildSeamlessTrack(items);
  const half = track.length / 2;

  return (
    <div className="w-full" role="region" aria-labelledby={labelId}>
      <p id={labelId} className="sr-only">
        Client brand logos scrolling continuously.
      </p>
      <div className="trust-marquee-fade group overflow-hidden">
        <div
          className={cn(
            "flex w-max items-center gap-8 group-hover:[animation-play-state:paused] group-focus-within:[animation-play-state:paused]",
            "animate-trust-marquee",
          )}
        >
          {track.map((item, index) => (
            <div
              key={`client-${item.image}-${index}`}
              className="shrink-0"
              aria-hidden={index >= half ? true : undefined}
            >
              <TrustLogo
                label={item.label}
                image={item.image}
                alt={index >= half ? "" : item.alt}
                variant="client"
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";
import { TrustClientMarquee } from "./trust-client-marquee";
import { TrustLogo } from "./trust-logo";

interface TrustBarSectionProps {
  id: string;
  data: Record<string, unknown>;
}

function readLogoItems(value: unknown) {
  return readRecordArray(value)
    .map((item) => {
      const label = readString(item.label);
      const image = readString(item.image);
      const alt = readString(item.alt, label);
      const href = readString(item.href) || undefined;
      if (!label && !image) return null;
      return { label, image, alt, href };
    })
    .filter((item): item is NonNullable<typeof item> => item !== null);
}

/**
 * Quiet Project One–style proof strip — eyebrow + sparse logos.
 * No soft floating card stacks; eCom partner/client/review assets only.
 */
export function TrustBarSection({ id, data }: TrustBarSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const subheading = readString(data.subheading);

  const partners = readLogoItems(data.partners);
  const clients = readLogoItems(data.clients);
  const reviews = readLogoItems(data.reviews);
  const press = readLogoItems(data.press);

  const legacyBadge =
    data.badge && typeof data.badge === "object"
      ? (data.badge as Record<string, unknown>)
      : undefined;
  const legacyLogos = readLogoItems(data.logos);

  const partnerItems =
    partners.length > 0
      ? partners
      : legacyBadge
        ? [
            {
              label: readString(legacyBadge.label),
              image: readString(legacyBadge.image),
              alt: readString(legacyBadge.label),
              href: readString(legacyBadge.href) || undefined,
            },
            ...legacyLogos.filter(
              (logo) => !logo.image.includes("amazon-verified-partner"),
            ),
          ].filter((item) => item.label || item.image)
        : legacyLogos.filter(
            (logo) => !logo.image.includes("amazon-verified-partner"),
          );

  const reviewAndPress = [...reviews, ...press];

  return (
    <SectionShell id={id} className="py-10 sm:py-12 lg:py-14">
      <div className="flex flex-col items-center gap-5 text-center sm:gap-6">
        {eyebrow || subheading ? (
          <div className="max-w-xl space-y-2">
            {eyebrow ? (
              <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
                {eyebrow}
              </p>
            ) : null}
            {subheading ? (
              <p className="text-sm font-medium leading-snug text-text-primary/70 sm:text-base">
                {subheading}
              </p>
            ) : null}
          </div>
        ) : null}

        {partnerItems.length > 0 ? (
          <ul className="flex flex-wrap items-center justify-center gap-2.5 sm:gap-3">
            {partnerItems.map((item) => (
              <li key={`partner-${item.image || item.label}`}>
                <TrustLogo
                  label={item.label}
                  image={item.image}
                  alt={item.alt}
                  href={item.href}
                  variant="cert"
                />
              </li>
            ))}
          </ul>
        ) : null}

        {clients.length > 0 ? <TrustClientMarquee items={clients} /> : null}

        {reviewAndPress.length > 0 ? (
          <ul className="flex flex-wrap items-center justify-center gap-2.5 sm:gap-3">
            {reviewAndPress.map((item) => (
              <li key={`badge-${item.image || item.label}`}>
                <TrustLogo
                  label={item.label}
                  image={item.image}
                  alt={item.alt}
                  href={item.href}
                  variant="badge"
                />
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    </SectionShell>
  );
}

