        tag: el.tagName, cls: el.className?.toString?.().slice(0,60),
        text: (el.innerText||'').trim().slice(0,70),
        top: Math.round(r.top), left: Math.round(r.left), w: Math.round(r.width), h: Math.round(r.height),
        size: s.fontSize, weight: s.fontWeight, color: s.color, display: s.display,
      };
    });
    // max content width / columns
    const reserve = [...document.querySelectorAll('a')].find(a => /Reserve your spot/i.test(a.textContent||''));
    const rr = reserve?.getBoundingClientRect();
    // visual right side?
