node <<'NODE'
const { chromium } = require('playwright');
const out = 'docs/qa/screenshots';
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  async function shot(w, h) {
    await page.setViewportSize({ width: w, height: h });
    await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 120000 });
    await page.waitForTimeout(1600);
    await page.evaluate(() => document.querySelector('#hero')?.scrollIntoView({ block: 'start' }));
    await page.waitForTimeout(400);
    const data = await page.evaluate(() => {
      const s = document.querySelector('#hero');
      if (!s) return { missing: true };
      const h1 = s.querySelector('h1');
      const hs = getComputedStyle(h1);
      const eyebrow = [...s.querySelectorAll('p')].find(p => /Amazon Ads Verified/i.test(p.textContent||''));
      const es = eyebrow ? getComputedStyle(eyebrow) : null;
      const sub = [...s.querySelectorAll('p')].find(p => /We manage PPC/i.test(p.textContent||''));
      const ss = sub ? getComputedStyle(sub) : null;
      const form = s.querySelector('#hero-lead-form');
      const fs = form ? getComputedStyle(form) : null;
      const input = form?.querySelector('input');
      const is = input ? getComputedStyle(input) : null;
      const ctas = [...s.querySelectorAll('a')].filter(a => /free audit|client results/i.test(a.textContent||'')).map(a => {
        const st = getComputedStyle(a);
        const chip = a.querySelector('span,div');
        // find arrow chip
        const chipEl = [...a.querySelectorAll('span')].find(el => el.querySelector('svg'));
        const cs = chipEl ? getComputedStyle(chipEl) : null;
        return {
          text: a.textContent.trim().slice(0,40),
          href: a.getAttribute('href'),
          h: Math.round(a.getBoundingClientRect().height),
          radius: st.borderRadius,
          shadow: st.boxShadow,
          border: st.border,
          chipRadius: cs?.borderRadius,
          chipBg: cs?.backgroundColor,
        };
      });
      const fonts = {
        h1: hs.fontFamily,
        eyebrow: es?.fontFamily,
        sub: ss?.fontFamily,
        formH2: form ? getComputedStyle(form.querySelector('h2')).fontFamily : null,
      };
      return {
        h1: { size: hs.fontSize, weight: hs.fontWeight, lh: hs.lineHeight, tracking: hs.letterSpacing },
        eyebrow: eyebrow ? { size: es.fontSize, weight: es.fontWeight, radius: es.borderRadius, bg: es.backgroundColor, border: es.border, color: es.color } : null,
        sub: sub ? { size: ss.fontSize, weight: ss.fontWeight, color: ss.color } : null,
        form: form ? { radius: fs.borderRadius, border: fs.border, shadow: fs.boxShadow } : null,
        input: input ? { radius: is.borderRadius, border: is.border } : null,
        ctas,
        fonts,
        overflowX: document.documentElement.scrollWidth > window.innerWidth + 1,
        hasPO: /KHULA|ProjectOne|Reserve Your Spot|Your Website, Handled/i.test(s.innerText),
        privacy: !!s.querySelector('a[href*="privacy"]'),
      };
    });
    await page.locator('#hero').screenshot({ path: `${out}/po-repass-b-ours-hero-after-${w}.png` });
    return data;
  }

  const desktop = await shot(1440, 900);
  const mobile = await shot(390, 844);
  console.log(JSON.stringify({ desktop, mobile }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
