node <<'NODE'
const { chromium } = require('playwright');
const out = 'docs/qa/screenshots';
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1440, height: 900 });

  // Project One — find ticker-like / marquee / checklist strip
  await page.goto('https://www.projectone.website/', { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForTimeout(2500);
  const poProbe = await page.evaluate(() => {
    const candidates = [...document.querySelectorAll('section,div')].filter(el => {
      const r = el.getBoundingClientRect();
      const t = (el.innerText || '').slice(0, 200);
      const anim = getComputedStyle(el).animationName || '';
      const childAnim = [...el.querySelectorAll('*')].some(c => {
        const a = getComputedStyle(c).animationName;
        return a && a !== 'none';
      });
      return r.width > 800 && r.height > 40 && r.height < 280 && r.top > 200 &&
        (childAnim || /check|done|included|what you|features/i.test(t));
    }).slice(0, 12).map(el => {
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      return {
        top: Math.round(r.top), h: Math.round(r.height), w: Math.round(r.width),
        bg: s.backgroundColor, radius: s.borderRadius, border: s.border, shadow: s.boxShadow,
        text: (el.innerText||'').replace(/\s+/g,' ').slice(0,120),
      };
    });
    // also look for dark bands
    const dark = [...document.querySelectorAll('section,div')].filter(el => {
      const r = el.getBoundingClientRect();
      const bg = getComputedStyle(el).backgroundColor;
      return r.width > 900 && r.height > 60 && r.height < 320 && /rgb\(1[0-9]|rgb\(2[0-5]/.test(bg);
    }).slice(0, 8).map(el => {
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      return { top: Math.round(r.top), h: Math.round(r.height), bg: s.backgroundColor, radius: s.borderRadius, border: s.border, shadow: s.boxShadow, text: (el.innerText||'').replace(/\s+/g,' ').slice(0,100) };
    });
    return { candidates, dark };
  });
  // scroll to find marquee bands
  for (let y of [700, 1100, 1500, 2000, 2500]) {
    await page.evaluate((yy) => window.scrollTo(0, yy), y);
    await page.waitForTimeout(400);
  }
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.waitForTimeout(500);
  // Full fold + deeper capture of first dark marquee-like area
  await page.screenshot({ path: `${out}/po-repass-c-projectone-fold-1440.png`, fullPage: false });
  const poMarquee = await page.evaluate(() => {
    const moving = [...document.querySelectorAll('*')].filter(el => {
      const t = getComputedStyle(el).transform;
      const a = getComputedStyle(el).animationName;
      const r = el.getBoundingClientRect();
      return r.width > 200 && ((a && a !== 'none') || (t && t !== 'none' && t.includes('matrix'))) &&
        /check|✓|✔|done|seo|design|copy|hosting|support/i.test(el.innerText||'') ;
    }).slice(0, 10).map(el => {
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      const parent = el.closest('section') || el.parentElement;
      const ps = parent ? getComputedStyle(parent) : null;
      const pr = parent?.getBoundingClientRect();
      return {
        text: (el.innerText||'').replace(/\s+/g,' ').slice(0,80),
        anim: s.animationName, duration: s.animationDuration,
        transform: s.transform.slice(0,40),
        top: Math.round(r.top), h: Math.round(r.height),
        parent: parent ? { top: Math.round(pr.top), h: Math.round(pr.height), bg: ps.backgroundColor, radius: ps.borderRadius, border: ps.border, shadow: ps.boxShadow, pad: ps.padding } : null,
      };
    });
    return moving;
  });
  // try screenshot around first moving row parent
  if (poMarquee[0]?.parent) {
    await page.evaluate((top) => window.scrollTo(0, Math.max(0, top - 80)), poMarquee[0].parent.top + (await page.evaluate(() => window.scrollY)));
  }
  // Better: find by text patterns common on PO
  await page.evaluate(() => window.scrollTo(0, 900));
  await page.waitForTimeout(600);
  const band = await page.evaluate(() => {
    const el = [...document.querySelectorAll('section,div')].find(n => {
      const t = (n.innerText||'');
      return t.length < 800 && /Unlimited|Revisions|Hosting|SEO|Copywriting/i.test(t) && n.getBoundingClientRect().height < 300 && n.getBoundingClientRect().width > 800;
    });
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { top: r.top + window.scrollY, h: r.height };
  });
  if (band) {
    await page.evaluate((y) => window.scrollTo(0, y), Math.max(0, band.top - 40));
    await page.waitForTimeout(400);
    await page.screenshot({ path: `${out}/po-repass-c-projectone-ticker-1440.png`, fullPage: false, clip: { x: 0, y: 80, width: 1440, height: Math.min(420, Math.max(200, band.h + 120)) } });
  } else {
    await page.screenshot({ path: `${out}/po-repass-c-projectone-ticker-1440.png`, fullPage: false });
  }

  // Ours
  await page.goto('http://localhost:3000/#checklist-ticker', { waitUntil: 'load', timeout: 120000 });
  await page.waitForTimeout(1500);
  await page.evaluate(() => document.querySelector('#checklist-ticker')?.scrollIntoView({ block: 'center' }));
  await page.waitForTimeout(500);
  await page.locator('#checklist-ticker').screenshot({ path: `${out}/po-repass-c-ours-ticker-before-1440.png` });
  const ours = await page.evaluate(() => {
    const s = document.querySelector('#checklist-ticker');
    if (!s) return { missing: true };
    const root = getComputedStyle(s);
    const card = s.querySelector('[class*="rounded"], .container-page > div, div');
    // find dark panel
    const panels = [...s.querySelectorAll('div')].filter(el => {
      const bg = getComputedStyle(el).backgroundColor;
      return /rgb\(11,\s*27,\s*58\)|rgb\(19|oklab/.test(bg) || bg.includes('11, 27, 58');
    }).slice(0, 5).map(el => {
      const st = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      return { bg: st.backgroundColor, radius: st.borderRadius, border: st.border, shadow: st.boxShadow, pad: st.padding, w: Math.round(r.width), h: Math.round(r.height) };
    });
    const chips = [...s.querySelectorAll('li,span')].filter(el => {
      const r = el.getBoundingClientRect();
      return r.width > 40 && r.height > 20 && r.height < 60 && (el.textContent||'').trim().length > 2;
    }).slice(0, 6).map(el => {
      const st = getComputedStyle(el);
      return { text: el.textContent.trim().slice(0,40), size: st.fontSize, weight: st.fontWeight, color: st.color, bg: st.backgroundColor, radius: st.borderRadius, border: st.border, font: st.fontFamily.split(',')[0] };
    });
    const eyebrow = s.querySelector('p,span');
    const es = eyebrow ? getComputedStyle(eyebrow) : null;
    const marquees = [...s.querySelectorAll('[class*="marquee"], [class*="animate"]')].map(el => {
      const st = getComputedStyle(el);
      return { anim: st.animationName, dur: st.animationDuration, transform: st.transform.slice(0,50) };
    });
    return {
      sectionPad: root.padding,
      panels,
      chips,
      eyebrow: eyebrow ? { text: eyebrow.textContent.trim().slice(0,60), size: es.fontSize, weight: es.fontWeight, tracking: es.letterSpacing, color: es.color } : null,
      marquees: marquees.slice(0, 6),
      textSample: (s.innerText||'').replace(/\s+/g,' ').slice(0,200),
      hasPO: /KHULA|ProjectOne|Reserve|Unlimited revisions/i.test(s.innerText),
      overflowX: document.documentElement.scrollWidth > window.innerWidth + 1,
    };
  });

  console.log(JSON.stringify({ poProbe, poMarquee: poMarquee.slice(0,8), band, ours }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
