          bg: cs.backgroundColor, radius: cs.borderRadius, border: cs.border, pad: cs.padding, h: Math.round(c.getBoundingClientRect().height),
        };
      });
      return {
        top: Math.round(r.top), left: Math.round(r.left), w: Math.round(r.width), h: Math.round(r.height),
        bg: s.backgroundColor, radius: s.borderRadius, border: s.border, shadow: s.boxShadow, pad: s.padding,
