    if (!el) return null;
    const r = el.getBoundingClientRect();
    const s = getComputedStyle(el);
    const item = [...el.querySelectorAll('div,span,p')].find(c => (c.innerText||'').trim().length > 5 && c.getBoundingClientRect().height < 50);
    const is = item ? getComputedStyle(item) : null;
    return {
      h: Math.round(r.height), bg: s.backgroundColor, radius: s.borderRadius, shadow: s.boxShadow,
      item: item ? { text: item.innerText.trim().slice(0,40), size: is.fontSize, weight: is.fontWeight, color: is.color, tracking: is.letterSpacing } : null,
    };
  });
  await page.screenshot({ path: `${out}/po-repass-c-projectone-lime-marquee-1440.png`, fullPage: false });
  console.log('lime', JSON.stringify(lime, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
