import Link from "next/link";
import { Check } from "lucide-react";
import { BrowserMockup } from "@/components/browser-mockup";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface FreeAuditCardSectionProps {
  id: string;
  data: Record<string, unknown>;
}

/**
 * Mini status-browser float — PO hero/device chrome language,
 * eCom BrowserMockup content (PPC / analytics), decorative only.
 */
function StatusBrowserFloat({
  tabId,
  className,
}: {
  tabId: string;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "pointer-events-none absolute z-0 hidden w-[11.5rem] select-none lg:block",
        className,
      )}
      aria-hidden="true"
    >
      <div className="overflow-hidden rounded-[10px] border-2 border-primary bg-background shadow-[4px_4px_0_0_#0B1B3A] [&_.shadow-md]:shadow-none [&_figure]:m-0">
        <div className="origin-top-left scale-[0.42] [&_figure]:w-[27rem]">
          <BrowserMockup variant="macos" tabId={tabId} />
        </div>
      </div>
    </div>
  );
}

/**
 * Project One pricing-card UI language — mapped to a Free audit conversion card.
 * No dollar pricing or Project One plan copy.
 */
export function FreeAuditCardSection({ id, data }: FreeAuditCardSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const title = readString(data.title);
  const priceLabel = readString(data.priceLabel, "Free");
  const priceNote = readString(data.priceNote);
  const badge = readString(data.badge);
  const inclusionsHeading = readString(
    data.inclusionsHeading,
    "What the audit covers",
  );
  const primaryCta = readNavLink(data.primaryCta);
  const secondaryCta = readNavLink(data.secondaryCta);
  const headingId = `${id}-heading`;

  const inclusions = readRecordArray(data.inclusions)
    .map((item) => readString(item.label) || readString(item.text))
    .filter(Boolean);

  if (!title) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="relative mx-auto flex max-w-lg flex-col items-stretch">
        <StatusBrowserFloat
          tabId="ppc"
          className="-left-[12.5rem] top-10 -rotate-6"
        />
        <StatusBrowserFloat
          tabId="analytics"
          className="-right-[12.5rem] bottom-16 rotate-[5deg]"
        />

        <article className="relative z-10 overflow-hidden rounded-[10px] border-2 border-primary bg-primary p-6 text-text-on-dark shadow-[6px_6px_0_0_#0B1B3A] sm:p-8">
          <div className="flex items-start justify-between gap-3">
            <div>
              {eyebrow ? (
                <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-on-dark/55 sm:text-xs">
                  {eyebrow}
                </p>
              ) : null}
              <h2
                id={headingId}
                className="mt-2 text-xl font-extrabold tracking-tight text-text-on-dark sm:text-2xl"
              >
                {title}
              </h2>
            </div>
            {badge ? (
              <span className="shrink-0 rounded-[10px] border-2 border-primary bg-accent px-3 py-1 text-[11px] font-bold uppercase tracking-wide text-primary shadow-[3px_3px_0_0_#0B1B3A]">
                {badge}
              </span>
            ) : null}
          </div>

          <div className="mt-8 flex items-end gap-2 border-b border-white/10 pb-6">
            <p className="text-6xl font-extrabold leading-none tracking-[-0.04em] text-text-on-dark sm:text-7xl">
              {priceLabel}
            </p>
            {priceNote ? (
              <p className="mb-2 max-w-[11rem] text-sm font-normal leading-snug text-text-on-dark/65">
                {priceNote}
              </p>
            ) : null}
          </div>

          {primaryCta ? (
            <PrimaryButton
              asChild
              variant="accent"
              size="lg"
              className="mt-6 w-full"
            >
              <Link href={primaryCta.href}>{primaryCta.label}</Link>
            </PrimaryButton>
          ) : null}

          {secondaryCta ? (
            <p className="mt-4 text-center">
              <Link
                href={secondaryCta.href}
                className="text-sm font-normal text-text-on-dark/70 underline-underline-offset-4 transition-colors hover:text-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
              >
                {secondaryCta.label}
              </Link>
            </p>
          ) : null}

          {inclusions.length > 0 ? (
            <div className="mt-8">
              <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-text-on-dark/50">
                {inclusionsHeading}
              </p>
              <ul className="mt-4 space-y-3">
                {inclusions.map((item) => (
                  <li key={item} className="flex items-start gap-3">
                    <span
                      className="mt-0.5 inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-[5px] bg-accent text-primary"
                      aria-hidden="true"
                    >
                      <Check className="h-3.5 w-3.5 stroke-[2.5]" />
                    </span>
                    <span className="text-sm font-normal leading-snug text-text-on-dark/85">
                      {item}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
        </article>
      </div>
    </SectionShell>
  );
}

