      const floatBoxes = floats.map(el => {
        const box = el.firstElementChild ? getComputedStyle(el.firstElementChild) : null;
        const r = el.firstElementChild?.getBoundingClientRect();
        return box && r ? { w: Math.round(r.width), h: Math.round(r.height), radius: box.borderRadius, border: box.border, shadow: box.boxShadow, display: getComputedStyle(el).display } : null;
      });
      const cta = s.querySelector('a[href="#hero-lead-form"]');
      const secondary = s.querySelector('a[href="/case-studies/"]');
      const softBlur = [...s.querySelectorAll('*')].filter(el => {
        const sh = getComputedStyle(el).boxShadow;
        return sh && sh !== 'none' && /\d+px\s+\d+px\s+([1-9]\d*)px/.test(sh.replace(/rgba?\([^)]+\)/g,'x'));
      }).length;
      return {
        article: article ? { radius: as.borderRadius, border: as.border, shadow: as.boxShadow, bg: as.backgroundColor } : null,
        h2: h2 ? { size: hs.fontSize, weight: hs.fontWeight, font: hs.fontFamily } : null,
        badge: badge ? { radius: bs.borderRadius, shadow: bs.boxShadow, bg: bs.backgroundColor, border: bs.border } : null,
        price: price ? { size: ps.fontSize, weight: ps.fontWeight } : null,
        checkRadius: check ? getComputedStyle(check).borderRadius : null,
        floats: floatBoxes,
        cta: cta ? { href: cta.getAttribute('href'), text: cta.textContent.trim().slice(0,40) } : null,
        secondary: secondary ? { href: secondary.getAttribute('href') } : null,
        softBlurish: softBlur,
        hasPO: /KHULA|ProjectOne|\$100|\$199|24 months|Reserve Your Spot/i.test(s.innerText),
        overflowX: document.documentElement.scrollWidth > window.innerWidth + 1,
      };
    });
    await page.locator('#free-audit-card').screenshot({ path: `${out}/po-repass-g-ours-audit-after-${w}.png` });
    return data;
  }

  const desktop = await shot(1440, 900);
  const mobile = await shot(390, 844);
  console.log(JSON.stringify({ desktop, mobile }, null, 2));
