  let bestY = 1600;
  for (const y of [1400, 1800, 2200, 2600, 3000, 3400, 3800, 4200, 5000, 6000, 7000]) {
    await page.evaluate((yy) => window.scrollTo(0, yy), y);
    await page.waitForTimeout(250);
    const hit = await page.evaluate(() => {
      const imgs = [...document.querySelectorAll('img')].filter(img => {
        const r = img.getBoundingClientRect();
        return r.width > 180 && r.height > 140 && r.top > 80 && r.top < 800;
      });
      if (imgs.length >= 3) {
        const parents = imgs.slice(0,4).map(img => {
          let n = img.parentElement;
          for (let i=0;i<5;i++) {
            const s = getComputedStyle(n);
            if (parseFloat(s.borderWidth) >= 1 || s.boxShadow !== 'none') break;
            if (!n.parentElement) break;
