async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.projectone.website/', { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForTimeout(2500);
  const detail = await page.evaluate(() => {
    const h1 = document.querySelector('h1');
    const nodes = [];
    // walk near hero: collect positioned/rotated frames
    const all = Array.from(document.querySelectorAll('div, figure, img, p, a, span'));
    for (const el of all) {
      const r = el.getBoundingClientRect();
      if (r.bottom < 0 || r.top > 900 || r.width < 20) continue;
      const cs = getComputedStyle(el);
      const transform = cs.transform;
      const rotated = transform && transform !== 'none' && transform.includes('matrix');
      const hasShadow = cs.boxShadow && cs.boxShadow !== 'none';
      const isImg = el.tagName === 'IMG';
      const isNearFold = r.top < 850 && r.bottom > 80;
      if (!isNearFold) continue;
      if (isImg || (rotated && r.width > 80) || (hasShadow && r.width > 120 && r.height > 80 && el.children.length <= 5)) {
        nodes.push({
          tag: el.tagName.toLowerCase(),
          text: (el.textContent||'').replace(/\s+/g,' ').trim().slice(0,60),
          x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height),
          transform: transform === 'none' ? null : transform.slice(0,80),
          radius: cs.borderRadius,
          shadow: hasShadow ? cs.boxShadow.slice(0,100) : null,
          bg: cs.backgroundColor,
          border: cs.border,
          fontSize: cs.fontSize,
          weight: cs.fontWeight,
          align: cs.textAlign,
          z: cs.zIndex,
        });
      }
    }
    // CTAs near hero
    const ctas = Array.from(document.querySelectorAll('a,button')).filter(el => {
      const r = el.getBoundingClientRect();
      const t = (el.textContent||'').replace(/\s+/g,' ').trim();
      return r.top > 200 && r.top < 700 && /reserve|pricing|spot|start|book/i.test(t);
    }).map(el => {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return {
        text: (el.textContent||'').replace(/\s+/g,' ').trim().slice(0,40),
        x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height),
        bg: cs.backgroundColor, color: cs.color, shadow: cs.boxShadow.slice(0,80), radius: cs.borderRadius,
        fontSize: cs.fontSize, weight: cs.fontWeight, tracking: cs.letterSpacing
      };
    });
    // sub under h1
    let sub = null;
    if (h1) {
      let n = h1.nextElementSibling;
      for (let i=0;i<5 && n;i++) {
        if ((n.textContent||'').trim().length > 20) {
          const cs = getComputedStyle(n);
          const r = n.getBoundingClientRect();
          sub = { text: (n.textContent||'').trim().slice(0,160), size: cs.fontSize, weight: cs.fontWeight, color: cs.color, align: cs.textAlign, y: Math.round(r.y), w: Math.round(r.width) };
          break;
        }
        n = n.nextElementSibling;
      }
    }
    const eyebrowCandidates = Array.from(document.querySelectorAll('p,span,div')).filter(el => {
      const r = el.getBoundingClientRect();
      const t = (el.textContent||'').trim();
      return r.top > 250 && r.top < 400 && t.length > 5 && t.length < 40 && /framer|expert|built|for/i.test(t);
    }).slice(0,5).map(el => ({ text: el.textContent.trim().slice(0,50), y: Math.round(el.getBoundingClientRect().y) }));
    return { sub, ctas: ctas.slice(0,6), nodes: nodes.slice(0,40), eyebrowCandidates };
  });
  return detail;
}

