import Image from "next/image";
import Link from "next/link";
import { submitAuditForm } from "@/app/(marketing)/free-audit-2/actions";
import { ConfigurableForm } from "@/components/forms/configurable-form";
import { PrimaryButton } from "@/components/ui/primary-button";
import { initialFormActionState } from "@/domain/forms/form-action-state";
import {
  HeroOrbitMedia,
  type HeroOrbitItem,
} from "./hero-orbit-media";
import { readNavLink, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface HeroSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface HeroFormField {
  name: string;
  label: string;
  type: "text" | "email" | "tel" | "url" | "textarea" | "select";
  required: boolean;
  placeholder?: string;
  options?: { value: string; label: string }[];
}

function readHeroFormFields(value: unknown): HeroFormField[] {
  if (!Array.isArray(value)) return [];

  return value.flatMap((item) => {
    if (!item || typeof item !== "object") return [];
    const record = item as Record<string, unknown>;
    const name = readString(record.name);
    const label = readString(record.label);
    const type = readString(record.type, "text");
    if (!name || !label) return [];
    if (
      type !== "text" &&
      type !== "email" &&
      type !== "tel" &&
      type !== "url" &&
      type !== "textarea" &&
      type !== "select"
    ) {
      return [];
    }

    const options = Array.isArray(record.options)
      ? record.options.flatMap((option) => {
          if (!option || typeof option !== "object") return [];
          const opt = option as Record<string, unknown>;
          if (typeof opt.value !== "string" || typeof opt.label !== "string") {
            return [];
          }
          return [{ value: opt.value, label: opt.label }];
        })
      : undefined;

    return [
      {
        name,
        label,
        type,
        required: Boolean(record.required),
        placeholder: readString(record.placeholder) || undefined,
        options,
      },
    ];
  });
}

function readOrbitItems(value: unknown): HeroOrbitItem[] | undefined {
  if (!Array.isArray(value) || value.length === 0) return undefined;

  const items = value.flatMap((item, index) => {
    if (!item || typeof item !== "object") return [];
    const record = item as Record<string, unknown>;
    const src = readString(record.src) || readString(record.image);
    const label = readString(record.label);
    if (!src || !label) return [];
    return [
      {
        src,
        alt: readString(record.alt, label),
        label,
        place: readString(record.place) || DEFAULT_PLACES[index] || DEFAULT_PLACES[0],
        rotate: readString(record.rotate) || DEFAULT_ROTATES[index] || "rotate-0",
      },
    ];
  });

  return items.length > 0 ? items : undefined;
}

const DEFAULT_PLACES = [
  "left-[10%] top-[-2%] w-[168px] xl:w-[190px]",
  "left-[-1%] top-[34%] w-[176px] xl:w-[200px]",
  "left-[12%] bottom-[-4%] w-[220px] xl:w-[250px]",
  "right-[4%] top-[8%] w-[200px] xl:w-[230px]",
  "right-[2%] top-[48%] w-[190px] xl:w-[215px]",
];

const DEFAULT_ROTATES = [
  "rotate-[-7deg]",
  "rotate-[11deg]",
  "rotate-[-32deg]",
  "rotate-[38deg]",
  "rotate-[-14deg]",
];

export function HeroSection({ id, data }: HeroSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const headline = readString(data.headline);
  const subheadline = readString(data.subheadline);
  const supportLine = readString(data.supportLine);
  const trustLine = readString(data.trustLine);
  const primaryCta = readNavLink(data.primaryCta);
  const secondaryCta = readNavLink(data.secondaryCta);
  const partnerBadge =
    data.partnerBadge && typeof data.partnerBadge === "object"
      ? (data.partnerBadge as Record<string, unknown>)
      : null;
  const partnerBadgeLabel = readString(partnerBadge?.label);
  const partnerBadgeImage = readString(partnerBadge?.image);
  const partnerBadgeHref = readString(partnerBadge?.href);

  const visual = data.visual as Record<string, unknown> | undefined;
  const visualType = readString(visual?.type, "leadForm");
  const formHeading = readString(visual?.formHeading, "Get your free audit");
  const formSubheading = readString(visual?.formSubheading);
  const submitLabel = readString(visual?.submitLabel, "Get your free audit");
  const consentLabel = readString(
    visual?.consentLabel,
    "I agree to the privacy policy and consent to being contacted about my audit request.",
  );
  const formFields = readHeroFormFields(visual?.fields);
  const showLeadForm = visualType === "leadForm" && formFields.length > 0;
  const orbitItems = readOrbitItems(data.orbitItems);

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={`${id}-heading`}
      className="relative overflow-hidden py-8 sm:py-10 lg:py-12 xl:py-14"
    >
      {/* Centered fold + orbit (PO layout language) */}
      <div className="relative mx-auto flex min-h-[min(78vh,720px)] max-w-5xl flex-col items-center justify-center px-1 py-10 text-center sm:min-h-[min(82vh,780px)] sm:py-14 lg:min-h-[min(88vh,860px)] lg:py-16">
        <HeroOrbitMedia items={orbitItems} />

        <div className="relative z-10 mx-auto flex w-full max-w-2xl flex-col items-center">
          {eyebrow ? (
            <p className="inline-flex max-w-full items-center rounded-full border-2 border-primary bg-primary px-3.5 py-1.5 text-[11px] font-bold uppercase tracking-[0.14em] text-text-on-dark sm:text-xs">
              {eyebrow}
            </p>
          ) : null}

          <h1
            id={`${id}-heading`}
            className="mt-5 text-hero text-text-primary text-balance sm:mt-6"
          >
            {headline}
          </h1>

          {subheadline ? (
            <p className="mt-5 max-w-xl text-base font-normal leading-relaxed text-text-secondary text-pretty sm:mt-6 sm:text-lg">
              {subheadline}
            </p>
          ) : null}

          {primaryCta || secondaryCta ? (
            <div className="mt-8 flex w-full flex-col items-stretch justify-center gap-3 sm:mt-9 sm:w-auto sm:flex-row sm:items-center sm:gap-3">
              {primaryCta ? (
                <PrimaryButton
                  asChild
                  variant="accent"
                  size="lg"
                  className="w-full sm:w-auto"
                >
                  <Link href={primaryCta.href}>{primaryCta.label}</Link>
                </PrimaryButton>
              ) : null}
              {secondaryCta ? (
                <PrimaryButton
                  asChild
                  variant="primary"
                  size="lg"
                  className="w-full sm:w-auto"
                >
                  <Link href={secondaryCta.href}>{secondaryCta.label}</Link>
                </PrimaryButton>
              ) : null}
            </div>
          ) : null}

          {trustLine ? (
            <p className="mt-5 text-sm font-medium text-text-secondary sm:mt-6">
              {trustLine}
            </p>
          ) : null}

          {supportLine ? (
            <p className="mt-3 max-w-lg text-sm font-normal leading-relaxed text-text-secondary/90">
              {supportLine}
            </p>
          ) : null}

          {partnerBadgeImage ? (
            <div className="mt-6 flex justify-center sm:mt-7">
              {partnerBadgeHref ? (
                <a
                  href={partnerBadgeHref}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex min-h-11 items-center rounded-[8px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                >
                  <Image
                    src={partnerBadgeImage}
                    alt={partnerBadgeLabel || "Partner badge"}
                    width={200}
                    height={56}
                    className="h-10 w-auto sm:h-11"
                    sizes="200px"
                    quality={75}
                  />
                </a>
              ) : (
                <div className="inline-flex min-h-11 items-center">
                  <Image
                    src={partnerBadgeImage}
                    alt={partnerBadgeLabel || "Partner badge"}
                    width={200}
                    height={56}
                    className="h-10 w-auto sm:h-11"
                    sizes="200px"
                    quality={75}
                  />
                </div>
              )}
            </div>
          ) : null}
        </div>
      </div>

      {/* Lead form preserved under fold — conversion path for Free Audit */}
      {showLeadForm ? (
        <div
          id="hero-lead-form"
          className="relative z-10 mx-auto mt-4 w-full max-w-3xl scroll-mt-28 rounded-[10px] border-2 border-primary bg-background p-5 shadow-[6px_6px_0_0_#131311] sm:mt-6 sm:p-6 lg:p-7 [&_button[role=combobox]]:rounded-[10px] [&_button[role=combobox]]:border [&_button[role=combobox]]:border-primary/40 [&_input]:rounded-[10px] [&_input]:border [&_input]:border-primary/40 [&_textarea]:rounded-[10px] [&_textarea]:border [&_textarea]:border-primary/40"
        >
          <h2 className="text-center text-xl font-bold tracking-tight text-text-primary sm:text-2xl">
            {formHeading}
          </h2>
          {formSubheading ? (
            <p className="mt-1.5 text-center text-sm leading-snug text-text-secondary">
              {formSubheading}
            </p>
          ) : null}
          <div className="mt-5">
            <ConfigurableForm
              formId="hero-audit-form"
              fields={formFields}
              submitLabel={submitLabel}
              consentLabel={consentLabel}
              action={submitAuditForm}
              initialState={initialFormActionState}
              density="compact"
              columns={2}
              submitVariant="primary"
              submitFullWidth
            />
          </div>
        </div>
      ) : null}
    </SectionShell>
  );
}

