    }).filter(x => x.h > 280 && x.w > 800 && (/rgb\(19,\s*19,\s*17\)/.test(x.bg) || /rgb\(0,\s*0,\s*0\)/.test(x.bg) || /rgb\(1[0-8],/.test(x.bg)));
    candidates.sort((a,b) => b.h - a.h);
