async (page) => {
  const out = 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots';
  await page.setViewportSize({ width: 1440, height: 900 });
  if (!page.url().includes('projectone')) {
    await page.goto('https://www.projectone.website/', { waitUntil: 'domcontentloaded', timeout: 90000 });
    await page.waitForTimeout(2500);
  }

  const hit = await page.evaluate(() => {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    const hits = [];
    while (walker.nextNode()) {
      const t = (walker.currentNode.textContent || '').trim();
      if (!t || t.length > 80) continue;
      if (/^(SEO|Hosting|Copywriting|Analytics|Launch|Custom Design|Unlimited|Everything included|What.?s included)/i.test(t) || /Everything you need|One simple|Included/i.test(t)) {
        const el = walker.currentNode.parentElement;
        if (!el) continue;
        const r = el.getBoundingClientRect();
        hits.push({ t, y: Math.round(r.top + window.scrollY), tag: el.tagName });
      }
    }
    return hits.slice(0, 30);
  });

  const targetY = hit[0]?.y || 1600;
  await page.evaluate((y) => window.scrollTo(0, Math.max(0, y - 200)), targetY);
  await page.waitForTimeout(700);

  const detail = await page.evaluate(() => {
    // Find elements with short titles like SEO
    const titleEls = Array.from(document.querySelectorAll('h3,h4,p,div,span')).filter(el => {
      const t = (el.textContent || '').trim();
      const r = el.getBoundingClientRect();
      return r.top > 80 && r.top < 800 && t.length > 2 && t.length < 40 && /SEO|Hosting|Copywriting|Analytics|Launch|Design|Revisions|Support|CMS|Forms/i.test(t) && el.children.length <= 2;
    });
    const cards = [];
    for (const titleEl of titleEls) {
      let el = titleEl;
      for (let i = 0; i < 6; i++) {
        if (!el.parentElement) break;
        el = el.parentElement;
        const r = el.getBoundingClientRect();
        const cs = getComputedStyle(el);
        if (r.width > 280 && r.width < 480 && r.height > 140 && r.height < 360) {
          const bg = cs.backgroundColor;
          if (/198,\s*253,\s*80|250,\s*250,\s*250|255,\s*255,\s*255|242,\s*242/.test(bg)) {
            if (!cards.some(c => Math.abs(c.x - r.x) < 40 && Math.abs(c.y - r.y) < 40)) {
              cards.push({
                t: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0,140),
                w: Math.round(r.width), h: Math.round(r.height),
                x: Math.round(r.x), y: Math.round(r.y),
                bg, radius: cs.borderRadius, shadow: cs.boxShadow.slice(0,120), border: cs.border,
                titleSize: getComputedStyle(titleEl).fontSize,
                titleWeight: getComputedStyle(titleEl).fontWeight,
                titleFont: getComputedStyle(titleEl).fontFamily,
              });
            }
            break;
          }
        }
      }
      if (cards.length >= 6) break;
    }
    const headings = Array.from(document.querySelectorAll('h2')).filter(h => {
      const r = h.getBoundingClientRect();
      return r.top > -50 && r.top < 900;
    }).map(h => {
      const cs = getComputedStyle(h);
      return { t: h.textContent?.trim().slice(0,100), size: cs.fontSize, weight: cs.fontWeight, align: cs.textAlign, y: Math.round(h.getBoundingClientRect().top) };
    });
    return { cards, headings, visibleText: document.body.innerText.slice(0,0) };
  });

  await page.screenshot({ path: out + '/po-v3-projectone-props-1440.png', fullPage: false });
  return { hit, targetY, detail };
}

async (page) => {
  const out = 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots';
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.projectone.website/', { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForTimeout(2500);
  // Scroll to Custom Designed props zone
  await page.evaluate(() => {
    const el = Array.from(document.querySelectorAll('p,h2,h3,div')).find(e => /Custom Designed\. No Template/i.test(e.textContent||''));
    el?.scrollIntoView({ block: 'center' });
  });
  await page.waitForTimeout(800);
  const detail = await page.evaluate(() => {
    const title = Array.from(document.querySelectorAll('p,h2,h3,div,span')).find(e => /^Custom Designed\. No Template$/i.test((e.textContent||'').trim()) || /Custom Designed\. No Template/i.test((e.textContent||'').trim()) && (e.textContent||'').trim().length < 40);
    let card = title;
    for (let i=0;i<8 && card;i++) {
      const r = card.getBoundingClientRect();
      const bg = getComputedStyle(card).backgroundColor;
      if (r.width > 300 && r.height > 150 && (/198,\s*253,\s*80/.test(bg) || /250,\s*250/.test(bg))) break;
      card = card.parentElement;
    }
    // collect siblings grid
    const parent = card?.parentElement;
    const kids = parent ? Array.from(parent.children).filter(el => {
      const r = el.getBoundingClientRect();
      return r.width > 280 && r.height > 140;
    }).slice(0,8).map(el => {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return {
        t: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0,100),
        w: Math.round(r.width), h: Math.round(r.height),
        x: Math.round(r.x), y: Math.round(r.y),
        bg: cs.backgroundColor, radius: cs.borderRadius,
        shadow: cs.boxShadow.slice(0,130), border: cs.border,
      };
    }) : [];
    // section heading above
    const h2 = Array.from(document.querySelectorAll('h2')).filter(h => {
      const r = h.getBoundingClientRect();
      return r.top > -100 && r.top < 500;
    }).map(h => {
      const cs = getComputedStyle(h);
      return { t: h.textContent?.trim().slice(0,120), size: cs.fontSize, weight: cs.fontWeight, align: cs.textAlign, font: cs.fontFamily };
    });
    const sampleCard = kids[0] || (card ? (() => { const r = card.getBoundingClientRect(); const cs = getComputedStyle(card); return { t:(card.innerText||'').slice(0,80), w:Math.round(r.width),h:Math.round(r.height),bg:cs.backgroundColor,radius:cs.borderRadius,shadow:cs.boxShadow.slice(0,130),border:cs.border}; })() : null);
    // icon circle measure
    let icon = null;
    if (card) {
      const circ = Array.from(card.querySelectorAll('div,span')).find(el => {
        const r = el.getBoundingClientRect();
        return r.width > 28 && r.width < 56 && Math.abs(r.width - r.height) < 4;
      });
      if (circ) {
        const cs = getComputedStyle(circ);
        icon = { w: Math.round(circ.getBoundingClientRect().width), bg: cs.backgroundColor, radius: cs.borderRadius, border: cs.border };
      }
    }
    return { kids, h2, sampleCard, icon, kidCount: kids.length };
  });
  await page.screenshot({ path: out + '/po-v3-projectone-props-1440.png', fullPage: false });
  return detail;
}

