async (page) => {
  const out = 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots';
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.projectone.website/', { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForTimeout(2500);
  // Find 'We Build' lime step
  await page.evaluate(() => {
    const el = Array.from(document.querySelectorAll('div,p,h3')).find(e => /^We Build$/i.test((e.textContent||'').trim()) || /We Build/.test(e.textContent||'') && (e.textContent||'').length < 40);
    el?.scrollIntoView({ block: 'center' });
  });
  await page.waitForTimeout(700);
  const detail = await page.evaluate(() => {
    const titles = ['Discovery','We Build','Revisions','Launch','Handoff','Support','Design','Copy'];
    const cards = [];
    for (const label of titles) {
      const titleEl = Array.from(document.querySelectorAll('div,p,h3,h4,span')).find(e => (e.textContent||'').trim() === label || new RegExp('^' + label + '\\b').test((e.textContent||'').trim()) && (e.textContent||'').trim().length < 30);
      if (!titleEl) continue;
      let el = titleEl;
      for (let i=0;i<8;i++) {
        if (!el.parentElement) break;
        el = el.parentElement;
        const r = el.getBoundingClientRect();
        const cs = getComputedStyle(el);
        if (r.width > 280 && r.width < 700 && r.height > 60 && r.height < 200 && cs.boxShadow !== 'none') {
          cards.push({
            label,
            t: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0,120),
            x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height),
            bg: cs.backgroundColor, radius: cs.borderRadius, shadow: cs.boxShadow.slice(0,120),
            fontSize: getComputedStyle(titleEl).fontSize,
            fontWeight: getComputedStyle(titleEl).fontWeight,
          });
          break;
        }
      }
    }
    // unique
    const uniq = [];
    for (const c of cards) {
      if (uniq.some(u => Math.abs(u.x-c.x)<30 && Math.abs(u.y-c.y)<30)) continue;
      uniq.push(c);
    }
    uniq.sort((a,b) => a.y - b.y || a.x - b.x);
    return {
      cards: uniq,
      staggerXs: uniq.map(c => c.x),
      staggerYs: uniq.map(c => c.y),
    };
  });
  await page.screenshot({ path: out + '/po-v4-projectone-process-1440.png', fullPage: false });
  return detail;
}

