import { Check } from "lucide-react";
import { BrowserMockup } from "@/components/browser-mockup";
import { cn } from "@/lib/utils";
import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface ProcessSectionProps {
  id: string;
  data: Record<string, unknown>;
}

/** Desktop staircase offsets — Project One staggered process language. */
const STAGGER_TOP = [
  "lg:mt-0",
  "lg:mt-10",
  "lg:mt-20",
  "lg:mt-[7.5rem]",
] as const;

/**
 * Project One process language: phase headers + lime staggered step cards.
 * eCom Gliders steps / assurances / mockup locked from config.
 */
export function ProcessSection({ id, data }: ProcessSectionProps) {
  const eyebrow = readString(data.eyebrow, "Engagement flow");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const steps = readRecordArray(data.steps);
  const assurances = readRecordArray(data.assurances);
  const showMockup = Boolean(data.showMockup);
  const mockupVariant =
    readString(data.mockupVariant, "macos") === "ios" ? "ios" : "macos";
  const mockupTabId = readString(data.mockupTabId) || undefined;
  const headingId = `${id}-heading`;

  const parsedSteps = steps
    .map((step) => {
      const number = readString(step.number);
      const title = readString(step.title);
      const description = readString(step.description);
      if (!title) return null;
      return { number, title, description };
    })
    .filter(
      (step): step is { number: string; title: string; description: string } =>
        step !== null,
    );

  const parsedAssurances = assurances
    .map((item) => readString(item.text))
    .filter(Boolean);

  const colCount = Math.min(4, Math.max(1, parsedSteps.length));

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="mx-auto max-w-2xl text-center">
        {eyebrow ? (
          <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
            {eyebrow}
          </p>
        ) : null}
        <h2
          id={headingId}
          className="mt-3 text-[1.85rem] font-black leading-[1.1] tracking-[-0.02em] text-text-primary text-balance sm:text-[2.35rem] lg:text-[40px] lg:leading-[1.15]"
        >
          {heading}
        </h2>
        {subheading ? (
          <p className="mt-4 text-base font-normal leading-relaxed text-text-secondary sm:text-lg">
            {subheading}
          </p>
        ) : null}
      </div>

      {parsedSteps.length > 0 ? (
        <div className="mt-10 sm:mt-12">
          {/* Phase headers — desktop */}
          <div
            className={cn(
              "mb-4 hidden border-y border-primary/15 lg:grid",
              colCount === 4 && "lg:grid-cols-4",
              colCount === 3 && "lg:grid-cols-3",
              colCount === 2 && "lg:grid-cols-2",
              colCount === 1 && "lg:grid-cols-1",
            )}
            aria-hidden="true"
          >
            {parsedSteps.map((step, index) => (
              <div
                key={`phase-${step.title}`}
                className={cn(
                  "px-3 py-3 text-center text-[11px] font-bold uppercase tracking-[0.12em] text-text-secondary",
                  index > 0 && "border-l border-primary/15",
                )}
              >
                {step.title}
              </div>
            ))}
          </div>

          <ol
            className={cn(
              "grid gap-4 sm:grid-cols-2 lg:items-start lg:gap-5",
              colCount === 4 && "lg:grid-cols-4",
              colCount === 3 && "lg:grid-cols-3",
              colCount === 2 && "lg:grid-cols-2",
            )}
          >
            {parsedSteps.map((step, index) => {
              const n = step.number || String(index + 1).padStart(2, "0");
              return (
                <li
                  key={`${n}-${step.title}`}
                  className={cn(
                    "flex min-h-0",
                    STAGGER_TOP[index] ?? "lg:mt-0",
                  )}
                >
                  <article className="relative flex h-full w-full flex-col rounded-[10px] border-2 border-primary bg-accent p-5 text-primary shadow-[4px_4px_0_0_#131311] sm:min-h-[168px] sm:p-6">
                    <span
                      className="absolute right-4 top-4 inline-flex h-7 w-7 items-center justify-center rounded-full bg-primary text-[11px] font-bold text-text-on-dark"
                      aria-hidden="true"
                    >
                      {n.replace(/^0/, "") || String(index + 1)}
                    </span>
                    <h3 className="pr-10 text-lg font-bold tracking-tight sm:text-xl">
                      {step.title}
                    </h3>
                    {step.description ? (
                      <p className="mt-2.5 text-sm font-normal leading-relaxed text-primary/80">
                        {step.description}
                      </p>
                    ) : null}
                  </article>
                </li>
              );
            })}
          </ol>
        </div>
      ) : null}

      {parsedAssurances.length > 0 ? (
        <ul className="mt-10 grid gap-3 sm:grid-cols-2">
          {parsedAssurances.map((text) => (
            <li
              key={text}
              className="flex items-start gap-3 rounded-[10px] border-2 border-primary bg-background px-4 py-3.5 shadow-[4px_4px_0_0_#131311]"
            >
              <span
                className="mt-0.5 inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-accent text-primary"
                aria-hidden="true"
              >
                <Check className="h-3.5 w-3.5 stroke-[2.5]" />
              </span>
              <span className="text-sm font-medium leading-snug text-text-primary">
                {text}
              </span>
            </li>
          ))}
        </ul>
      ) : null}

      {showMockup ? (
        <div className="mt-10 overflow-hidden rounded-[10px] border-2 border-primary shadow-[6px_6px_0_0_#131311] sm:mt-12 [&_.shadow-md]:shadow-none [&_.shadow-sm]:shadow-none">
          <BrowserMockup variant={mockupVariant} tabId={mockupTabId} />
        </div>
      ) : null}
    </SectionShell>
  );
}

