  await page.setViewportSize({ width: 1440, height: 900 });

  // PO pricing cards
  await page.goto('https://www.projectone.website/', { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForTimeout(2800);
  await page.evaluate(() => {
    const el = Array.from(document.querySelectorAll('h2,h3,p')).find(e => /simple pricing|pricing|\$/i.test(e.textContent||''));
    el?.scrollIntoView({ block: 'center' });
  });
  await page.waitForTimeout(600);
  let found = null;
  for (let y = 3500; y < 6200; y += 280) {
    await page.evaluate(yy => window.scrollTo(0, yy), y);
    await page.waitForTimeout(150);
    found = await page.evaluate(() => {
      const cards = Array.from(document.querySelectorAll('div')).filter(el => {
        const r = el.getBoundingClientRect();
        if (r.top < 60 || r.top > 750 || r.width < 280 || r.width > 520 || r.height < 280 || r.height > 700) return false;
        const t = (el.innerText||'').replace(/\s+/g,' ').trim();
        const cs = getComputedStyle(el);
        const hasPrice = /\$\d|month|plan|included/i.test(t);
        const hard = cs.boxShadow !== 'none' || parseFloat(cs.borderWidth) > 0;
        return hasPrice && hard && t.length > 40 && t.length < 600;
      });
      const uniq = [];
      for (const el of cards) {
        const r = el.getBoundingClientRect();
        if (uniq.some(u => Math.abs(u.x - r.x) < 40 && Math.abs(u.y - r.y) < 40)) continue;
        const cs = getComputedStyle(el);
        uniq.push({
          t: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0,160),
          w: Math.round(r.width), h: Math.round(r.height), x: Math.round(r.x), y: Math.round(r.y),
          bg: cs.backgroundColor, radius: cs.borderRadius, shadow: cs.boxShadow.slice(0,120), border: cs.border,
        });
        if (uniq.length >= 3) break;
      }
      if (uniq.length < 1) return null;
      const h2 = Array.from(document.querySelectorAll('h2')).filter(h => {
        const r = h.getBoundingClientRect();
        return r.top > -40 && r.top < 500;
      }).map(h => {
        const cs = getComputedStyle(h);
        return { t: h.textContent?.trim().slice(0,80), size: cs.fontSize, weight: cs.fontWeight, align: cs.textAlign };
      });
      return { cards: uniq, h2, scrollY: window.scrollY };
    });
    if (found && found.cards.length >= 1) break;
  }
  if (found) await page.evaluate(y => window.scrollTo(0, Math.max(0, y - 80)), found.scrollY);
  await page.waitForTimeout(400);
  await page.screenshot({ path: out + '/po-v7-projectone-pricing-1440.png', fullPage: false });

  // Ours free-audit-card
  await page.goto('http://localhost:3000/#free-audit-card', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(1000);
  await page.evaluate(() => document.querySelector('#free-audit-card')?.scrollIntoView({ block: 'center' }));
  await page.waitForTimeout(500);
  const ours = await page.evaluate(() => {
    const s = document.querySelector('#free-audit-card');
    if (!s) return { missing: true };
    const h2 = s.querySelector('h2');
    const h2cs = h2 ? getComputedStyle(h2) : null;
    const card = [...s.querySelectorAll('article,div')].find(el => {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return r.width > 280 && r.width < 700 && r.height > 200 && (cs.boxShadow !== 'none' || parseFloat(cs.borderWidth) > 0);
    });
    const ccs = card ? getComputedStyle(card) : null;
    const cta = Array.from(s.querySelectorAll('a,button')).find(a => /audit|start|submit/i.test(a.textContent||''));
    return {
      text: (s.innerText||'').replace(/\s+/g,' ').trim().slice(0,280),
      h2: h2?.textContent?.trim().slice(0,100),
      h2Size: h2cs?.fontSize, h2Weight: h2cs?.fontWeight, h2Align: h2cs?.textAlign, h2Font: h2cs?.fontFamily,
      card: card ? {
        bg: ccs.backgroundColor, radius: ccs.borderRadius, shadow: ccs.boxShadow.slice(0,120), border: ccs.border,
        w: Math.round(card.getBoundingClientRect().width), h: Math.round(card.getBoundingClientRect().height),
      } : null,
      ctaHref: cta?.getAttribute('href') || null,
      ctaBg: cta ? getComputedStyle(cta).backgroundColor : null,
      classSnippet: s.className.slice(0,160),
    };
  });
  await page.screenshot({ path: out + '/po-v7-ours-audit-before-1440.png', fullPage: false });
  return { found, ours };
}

async (page) => {
  const out = 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots';
