import Link from "next/link";
import { Check } from "lucide-react";
import { BrowserMockup } from "@/components/browser-mockup";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface FreeAuditCardSectionProps {
  id: string;
  data: Record<string, unknown>;
}

function StatusBrowserFloat({
  tabId,
  className,
}: {
  tabId: string;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "pointer-events-none absolute z-0 hidden select-none lg:block",
        className,
      )}
      aria-hidden="true"
    >
      <div className="h-[7.75rem] w-[12rem] overflow-hidden rounded-[10px] border-2 border-primary bg-background shadow-[4px_4px_0_0_#131311] [&_.shadow-md]:shadow-none [&_figure]:m-0">
        <div className="origin-top-left scale-[0.42] [&_figure]:w-[28.5rem]">
          <BrowserMockup variant="macos" tabId={tabId} />
        </div>
      </div>
    </div>
  );
}

/**
 * Project One pricing-card chrome — light hard card, lime pill + CTA.
 * eCom free-audit offer only (no dollar plans or PO claims).
 */
export function FreeAuditCardSection({ id, data }: FreeAuditCardSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const title = readString(data.title);
  const priceLabel = readString(data.priceLabel, "Free");
  const priceNote = readString(data.priceNote);
  const badge = readString(data.badge);
  const inclusionsHeading = readString(
    data.inclusionsHeading,
    "What the audit covers",
  );
  const primaryCta = readNavLink(data.primaryCta);
  const secondaryCta = readNavLink(data.secondaryCta);
  const headingId = `${id}-heading`;

  const inclusions = readRecordArray(data.inclusions)
    .map((item) => readString(item.label) || readString(item.text))
    .filter(Boolean);

  if (!title) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="mx-auto max-w-2xl text-center">
        {eyebrow ? (
          <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
            {eyebrow}
          </p>
        ) : null}
        <h2
          id={headingId}
          className="mt-3 text-[1.85rem] font-black leading-[1.1] tracking-[-0.02em] text-text-primary text-balance sm:text-[2.5rem] lg:text-[44px] lg:leading-[1.1]"
        >
          {title}
        </h2>
        {priceNote ? (
          <p className="mx-auto mt-4 max-w-md text-base font-normal leading-relaxed text-text-secondary sm:text-lg">
            {priceNote}
          </p>
        ) : null}
      </div>

      <div className="relative mx-auto mt-10 flex max-w-md flex-col items-stretch sm:mt-12">
        <StatusBrowserFloat
          tabId="ppc"
          className="-left-[12.5rem] top-10 -rotate-6"
        />
        <StatusBrowserFloat
          tabId="analytics"
          className="-right-[12.5rem] bottom-16 rotate-[5deg]"
        />

        <article className="relative z-10 overflow-hidden rounded-[16px] border-2 border-primary bg-[#F4F4F4] p-6 text-primary shadow-[4px_4px_0_0_#131311] sm:p-8">
          <div className="flex flex-wrap items-center gap-2">
            <span className="inline-flex rounded-full bg-accent px-3 py-1 text-[11px] font-bold uppercase tracking-[0.12em] text-primary">
              {badge || "Free audit"}
            </span>
          </div>

          <div className="mt-6 flex items-end gap-3 border-b-2 border-primary/10 pb-6">
            <p className="text-6xl font-black leading-none tracking-[-0.04em] text-primary sm:text-7xl">
              {priceLabel}
            </p>
            <p className="mb-1.5 text-sm font-medium uppercase tracking-[0.08em] text-text-secondary">
              No obligation
            </p>
          </div>

          {primaryCta ? (
            <PrimaryButton
              asChild
              variant="accent"
              size="lg"
              className="mt-6 w-full"
            >
              <Link href={primaryCta.href}>{primaryCta.label}</Link>
            </PrimaryButton>
          ) : null}

          {secondaryCta ? (
            <p className="mt-4 text-center">
              <Link
                href={secondaryCta.href}
                className="text-sm font-medium text-text-secondary underline-offset-4 transition-colors hover:text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
              >
                {secondaryCta.label}
              </Link>
            </p>
          ) : null}

          {inclusions.length > 0 ? (
            <div className="mt-8">
              <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-text-secondary">
                {inclusionsHeading}
              </p>
              <ul className="mt-4 space-y-3">
                {inclusions.map((item) => (
                  <li key={item} className="flex items-start gap-3">
                    <span
                      className="mt-0.5 inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-accent text-primary"
                      aria-hidden="true"
                    >
                      <Check className="h-3.5 w-3.5 stroke-[2.5]" />
                    </span>
                    <span className="text-sm font-normal leading-snug text-primary/90">
                      {item}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
        </article>
      </div>
    </SectionShell>
  );
}

