  const meta = await page.evaluate(() => {
    const h = Array.from(document.querySelectorAll('h1,h2,h3,h4,p')).find(el =>
      /^See Work$/i.test((el.textContent||'').trim())
    );
    if (!h) return { missing: true };
    h.scrollIntoView({ block: 'start' });
    // climb for section-ish container
    let node = h;
    for (let i = 0; i < 8 && node.parentElement; i++) {
      node = node.parentElement;
      const r = node.getBoundingClientRect();
      if (r.height > 400 && r.width > 800) break;
    }
    const r = node.getBoundingClientRect();
    const cs = getComputedStyle(node);
    const hcs = getComputedStyle(h);
    // collect nearby cards / images
    const imgs = Array.from(node.querySelectorAll('img')).slice(0, 8).map(img => ({
      w: Math.round(img.getBoundingClientRect().width),
      h: Math.round(img.getBoundingClientRect().height),
      alt: img.alt?.slice(0,40),
    }));
    const texts = Array.from(node.querySelectorAll('h3,h4,p,a,button')).slice(0, 30).map(el =>
      (el.textContent||'').replace(/\s+/g,' ').trim().slice(0,60)
    ).filter(Boolean);
    // look at first project card-like child
    const cards = Array.from(node.querySelectorAll('*')).filter(el => {
      const st = getComputedStyle(el);
      const br = el.getBoundingClientRect();
      return br.width > 200 && br.height > 200 && br.height < 700 &&
        (st.borderWidth !== '0px' || st.boxShadow !== 'none');
    }).slice(0, 6).map(el => {
      const st = getComputedStyle(el);
      return {
        tag: el.tagName,
        w: Math.round(el.getBoundingClientRect().width),
        h: Math.round(el.getBoundingClientRect().height),
        bg: st.backgroundColor,
        radius: st.borderRadius,
        border: st.border,
        shadow: st.boxShadow.slice(0,80),
        className: (el.className||'').toString().slice(0,60),
      };
    });
    return {
      hText: h.textContent?.trim(),
      hSize: hcs.fontSize, hWeight: hcs.fontWeight, hAlign: hcs.textAlign, hFont: hcs.fontFamily,
      sectionH: Math.round(r.height), sectionBg: cs.backgroundColor,
      imgs, texts, cards,
      y: Math.round(h.getBoundingClientRect().top + window.scrollY),
    };
  });

  await page.waitForTimeout(800);
