      el.childNodes.length && Array.from(el.childNodes).some(n => n.nodeType === 3 && /^See Work$/i.test((n.textContent||'').trim()))
      || (el.children.length === 0 && /^See Work$/i.test((el.textContent||'').trim()))
    );
    // better: exact text match on leaf-ish
    const candidates = Array.from(document.querySelectorAll('h1,h2,h3,h4,p,div,span')).filter(el =>
      /^See Work$/i.test((el.textContent||'').trim())
    );
    return candidates.map(el => {
      const parent = el.parentElement;
      const gp = parent?.parentElement;
      const siblings = parent ? Array.from(parent.children).map(c => ({
        tag: c.tagName,
        text: (c.textContent||'').replace(/\s+/g,' ').trim().slice(0,50),
        h: Math.round(c.getBoundingClientRect().height),
        w: Math.round(c.getBoundingClientRect().width),
      })) : [];
      // next sections after this y
      const y = el.getBoundingClientRect().top + window.scrollY;
      // find images near this y (same viewport band + below)
      const nearbyImgs = Array.from(document.querySelectorAll('img')).filter(img => {
