        className: (el.className||'').toString().slice(0,80),
        y: Math.round(y),
        size: getComputedStyle(el).fontSize,
        weight: getComputedStyle(el).fontWeight,
        parentTag: parent?.tagName,
        parentClass: (parent?.className||'').toString().slice(0,80),
        gpClass: (gp?.className||'').toString().slice(0,80),
        siblings,
        nearbyImgs: nearbyImgs.slice(0, 12),
      };
    });
  });
  return info;
}

async (page) => {
  const out = 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots';
  await page.setViewportSize({ width: 1440, height: 900 });

  const detail = await page.evaluate(() => {
    const h = Array.from(document.querySelectorAll('h3')).find(el =>
      /^See Work$/i.test((el.textContent||'').trim())
    );
    if (!h) return { missing: true };

    // Walk up until we find a dark-ish container or large enough block that contains work links
    let node = h.parentElement;
    let dark = null;
    for (let i = 0; i < 12 && node; i++) {
      const bg = getComputedStyle(node).backgroundColor;
      const r = node.getBoundingClientRect();
      const m = bg.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
      const lum = m ? (Number(m[1])+Number(m[2])+Number(m[3]))/3 : 255;
      if (lum < 80 && r.height > 200) { dark = node; break; }
      node = node.parentElement;
    }
    const root = dark || h.closest('section') || h.parentElement?.parentElement?.parentElement;
    if (!root) return { noRoot: true };
    root.scrollIntoView({ block: 'center' });

    const rcs = getComputedStyle(root);
    const rr = root.getBoundingClientRect();
    const links = Array.from(root.querySelectorAll('a')).map(a => {
      const st = getComputedStyle(a);
      const br = a.getBoundingClientRect();
      return {
        text: (a.textContent||'').replace(/\s+/g,' ').trim().slice(0,50),
        href: a.getAttribute('href')?.slice(0,60),
        w: Math.round(br.width), h: Math.round(br.height),
        radius: st.borderRadius,
        border: st.border,
        bg: st.backgroundColor,
        color: st.color,
        shadow: st.boxShadow.slice(0,50),
      };
    }).filter(l => l.w > 40);

    const allText = (root.innerText||'').replace(/\s+/g,' ').trim().slice(0,500);
    const hcs = getComputedStyle(h);
    const sub = Array.from(root.querySelectorAll('p,div')).map(el => (el.textContent||'').trim()).find(t => /live sites/i.test(t));

    return {
      rootBg: rcs.backgroundColor,
      rootRadius: rcs.borderRadius,
      rootBorder: rcs.border,
      rootShadow: rcs.boxShadow.slice(0,80),
      rootW: Math.round(rr.width), rootH: Math.round(rr.height),
      hSize: hcs.fontSize, hWeight: hcs.fontWeight, hColor: hcs.color,
      sub,
      links: links.slice(0, 20),
      allText,
      y: Math.round(rr.top + window.scrollY),
    };
  });

  await page.waitForTimeout(600);
  await page.evaluate((y) => window.scrollTo(0, Math.max(0, y - 40)), detail.y || 5200);
  await page.waitForTimeout(400);
  await page.screenshot({ path: out + '/po-v8-projectone-seework-1440.png', fullPage: false });
  return detail;
}

async (page) => {
