"use client";

import Image from "next/image";
import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import { useMemo, useRef, useState } from "react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface CreativeShowcaseSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface CreativeVisual {
  image: string;
  alt: string;
  caption: string;
}

/**
 * Project One “See Work” chrome — dark soft-rect panel, white type,
 * outlined work pills. eCom creative media only (no PO project names).
 */
export function CreativeShowcaseSection({
  id,
  data,
}: CreativeShowcaseSectionProps) {
  const eyebrow = readString(data.eyebrow, "See work");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;
  const thumbRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const visuals: CreativeVisual[] = useMemo(
    () =>
      readRecordArray(data.items)
        .map((item) => {
          const image = readString(item.image);
          const alt = readString(item.alt);
          const caption = readString(item.caption);
          if (!image) return null;
          return { image, alt, caption };
        })
        .filter((item): item is CreativeVisual => item !== null),
    [data.items],
  );

  const [activeIndex, setActiveIndex] = useState(0);
  const active = visuals[activeIndex] ?? visuals[0];

  if (!active) return null;

  const selectIndex = (index: number, moveFocus = false) => {
    const next = Math.max(0, Math.min(index, visuals.length - 1));
    setActiveIndex(next);
    if (moveFocus) {
      thumbRefs.current[next]?.focus();
    }
  };

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="overflow-hidden rounded-[16px] bg-[#2A2A27] px-5 py-8 text-canvas sm:px-8 sm:py-10 lg:px-10 lg:py-12">
        <div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between lg:gap-10">
          <div className="max-w-2xl">
            {eyebrow ? (
              <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-canvas/55 sm:text-xs">
                {eyebrow}
              </p>
            ) : null}
            <h2
              id={headingId}
              className="mt-3 text-[1.85rem] font-black leading-[1.05] tracking-[-0.04em] text-canvas text-balance sm:text-[2.5rem] lg:text-[3rem] lg:leading-[1.05]"
            >
              {heading}
            </h2>
            {subheading ? (
              <p className="mt-4 max-w-xl text-base font-normal leading-relaxed text-canvas/70 sm:text-lg">
                {subheading}
              </p>
            ) : null}
          </div>
          {cta ? (
            <PrimaryButton
              asChild
              variant="accent"
              className="w-full shrink-0 sm:w-auto"
            >
              <Link href={cta.href}>{cta.label}</Link>
            </PrimaryButton>
          ) : null}
        </div>

        {visuals.length > 1 ? (
          <ul
            className="mt-8 flex flex-wrap gap-2.5 sm:mt-10 sm:gap-3"
            role="list"
            aria-label="Creative examples"
          >
            {visuals.map((item, index) => {
              const isActive = index === activeIndex;
              const label = item.caption || `Creative ${index + 1}`;
              return (
                <li key={item.image}>
                  <button
                    ref={(node) => {
                      thumbRefs.current[index] = node;
                    }}
                    type="button"
                    aria-pressed={isActive}
                    aria-label={label}
                    className={cn(
                      "inline-flex min-h-12 items-center gap-2 rounded-[10px] border px-3.5 py-2.5 text-left text-[11px] font-bold uppercase tracking-[0.08em] transition-colors duration-200 sm:px-4 sm:text-xs",
                      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-[#2A2A27]",
                      isActive
                        ? "border-accent bg-accent text-primary"
                        : "border-canvas/35 bg-transparent text-canvas hover:border-canvas/70",
                    )}
                    onClick={() => selectIndex(index)}
                    onKeyDown={(event) => {
                      if (
                        event.key === "ArrowRight" ||
                        event.key === "ArrowDown"
                      ) {
                        event.preventDefault();
                        selectIndex(index + 1, true);
                      }
                      if (
                        event.key === "ArrowLeft" ||
                        event.key === "ArrowUp"
                      ) {
                        event.preventDefault();
                        selectIndex(index - 1, true);
                      }
                    }}
                  >
                    <span>{label}</span>
                    <ArrowUpRight
                      className="h-3.5 w-3.5 shrink-0 opacity-80"
                      aria-hidden="true"
                    />
                  </button>
                </li>
              );
            })}
          </ul>
        ) : null}

        <div className="creative-listing-frame mt-8 overflow-hidden rounded-[10px] border border-canvas/20 bg-[#1C1C1A] p-3 sm:mt-10 sm:p-4 lg:p-5">
          <div className="mb-3 flex items-center justify-between gap-3 px-0.5 sm:mb-4">
            <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-canvas/50">
              Listing preview
            </p>
            <p
              className="font-mono text-small font-semibold text-canvas/80"
              aria-live="polite"
            >
              {String(activeIndex + 1).padStart(2, "0")} /{" "}
              {String(visuals.length).padStart(2, "0")}
            </p>
          </div>

          <div className="relative aspect-[4/3] w-full overflow-hidden rounded-[10px] border border-canvas/15 bg-[#131311] sm:aspect-[16/10] lg:aspect-[16/9] lg:min-h-[22rem]">
            {visuals.map((item, index) => {
              const isActive = index === activeIndex;
              return (
                <Image
                  key={item.image}
                  src={item.image}
                  alt={item.alt || "Amazon listing creative example"}
                  fill
                  className={cn(
                    "object-cover transition-opacity duration-500 ease-out",
                    isActive ? "opacity-100" : "opacity-0",
                  )}
                  sizes="(max-width: 1024px) 100vw, 90vw"
                  quality={80}
                  priority={index === 0}
                  loading={index === 0 ? undefined : "lazy"}
                />
              );
            })}
          </div>
        </div>
      </div>
    </SectionShell>
  );
}

import Image from "next/image";
import Link from "next/link";
import { ArrowRight, ArrowUpRight } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface CaseStudiesSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface CaseItem {
  metric: string;
  brand: string;
  category: string;
  service: string;
  description: string;
  href: string;
  image: string;
  imageAlt: string;
  atmosphere: string;
  atmosphereAlt: string;
}

/**
 * See Work companion — quiet hard case cards + soft-rect brand pills.
 * eCom metrics and brands only.
 */
export function CaseStudiesSection({ id, data }: CaseStudiesSectionProps) {
  const eyebrow = readString(data.eyebrow, "Selected results");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  const items: CaseItem[] = readRecordArray(data.items)
    .map((item) => {
      const metric = readString(item.metric);
      const brand = readString(item.brand);
      if (!brand && !metric) return null;
      return {
        metric,
        brand,
        category: readString(item.category),
        service: readString(item.service),
        description: readString(item.description),
        href: readString(item.href),
        image: readString(item.image),
        imageAlt: readString(item.imageAlt, brand),
        atmosphere: readString(item.atmosphere),
        atmosphereAlt: readString(item.atmosphereAlt, brand),
      };
    })
    .filter((item): item is CaseItem => item !== null);

  if (items.length === 0) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between lg:gap-10">
        <div className="max-w-2xl">
          {eyebrow ? (
            <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
              {eyebrow}
            </p>
          ) : null}
          <h2
            id={headingId}
            className="mt-3 text-[1.85rem] font-black leading-[1.05] tracking-[-0.04em] text-primary text-balance sm:text-[2.5rem] lg:text-[3rem] lg:leading-[1.05]"
          >
            {heading}
          </h2>
          {subheading ? (
            <p className="mt-4 text-base font-normal leading-relaxed text-text-secondary sm:text-lg">
              {subheading}
            </p>
          ) : null}
        </div>
        {cta ? (
          <PrimaryButton
            asChild
            variant="primary"
            className="hidden w-full shrink-0 sm:inline-flex sm:w-auto"
          >
            <Link href={cta.href}>{cta.label}</Link>
          </PrimaryButton>
        ) : null}
      </div>

      <ul
        className="mt-8 flex flex-wrap gap-2.5 sm:mt-10 sm:gap-3"
        aria-label="Case study brands"
      >
        {items.map((item) => {
          const label = item.brand || item.metric;
          if (!label) return null;
          const inner = (
            <>
              <span>{label}</span>
              <ArrowUpRight
                className="h-3.5 w-3.5 shrink-0 opacity-70"
                aria-hidden="true"
              />
            </>
          );
          const chipClass =
            "inline-flex min-h-11 items-center gap-2 rounded-[10px] border-2 border-primary bg-background px-3.5 py-2 text-[11px] font-bold uppercase tracking-[0.08em] text-primary shadow-[3px_3px_0_0_#131311] transition-transform hover:-translate-y-0.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 sm:text-xs";

          return (
            <li key={`pill-${label}`}>
              {item.href ? (
                <Link href={item.href} className={chipClass}>
                  {inner}
                </Link>
              ) : (
                <span className={chipClass}>{inner}</span>
              )}
            </li>
          );
        })}
      </ul>

      <ul className="mt-8 flex gap-4 overflow-x-auto pb-2 [-ms-overflow-style:none] [scrollbar-width:none] sm:mt-10 sm:gap-5 [&::-webkit-scrollbar]:hidden md:grid md:grid-cols-3 md:overflow-visible md:pb-0">
        {items.map((item) => {
          const key = `${item.brand}-${item.metric}`;
          const scene = item.atmosphere || item.image;
          const sceneAlt = item.atmosphereAlt || item.imageAlt || item.brand;

          return (
            <li
              key={key}
              className="flex w-[min(85vw,20rem)] shrink-0 md:w-auto md:min-w-0"
            >
              <article
                className={cn(
                  "case-proof-card group flex w-full flex-1 flex-col overflow-hidden rounded-[16px] border-2 border-primary bg-[#F4F4F4]",
                  "shadow-[4px_4px_0_0_#131311] transition-transform duration-300",
                  "hover:-translate-y-0.5",
                  "focus-within:ring-2 focus-within:ring-accent focus-within:ring-offset-2",
                )}
              >
                {scene ? (
                  <div className="case-proof-media relative aspect-[4/3] w-full shrink-0 overflow-hidden bg-primary">
                    <Image
                      src={scene}
                      alt=""
                      fill
                      aria-hidden="true"
                      className="case-proof-blur scale-125 object-cover opacity-70 blur-2xl"
                      sizes="(max-width: 768px) 85vw, 33vw"
                      quality={70}
                      loading="lazy"
                    />
                    <Image
                      src={scene}
                      alt={sceneAlt}
                      fill
                      className="media-hover-zoom object-cover"
                      sizes="(max-width: 768px) 85vw, 33vw"
                      quality={80}
                      loading="lazy"
                    />
                    <div
                      className="pointer-events-none absolute inset-0 bg-gradient-to-t from-primary/90 via-primary/20 to-transparent"
                      aria-hidden="true"
                    />

                    {item.image ? (
                      <div className="absolute left-3 top-3 z-10 h-11 w-11 overflow-hidden rounded-[5px] border-2 border-primary bg-background shadow-[3px_3px_0_0_#131311] sm:h-12 sm:w-12">
                        <Image
                          src={item.image}
                          alt={item.imageAlt || item.brand}
                          fill
                          className="object-contain p-1"
                          sizes="48px"
                          quality={80}
                          loading="lazy"
                        />
                      </div>
                    ) : null}

                    {item.metric ? (
                      <p className="absolute bottom-3 left-3 right-3 z-10 text-2xl font-black tracking-tight text-accent sm:bottom-4 sm:left-4 sm:text-3xl">
                        {item.metric}
                      </p>
                    ) : null}
                  </div>
                ) : null}

                <div className="flex flex-1 flex-col px-4 py-4 sm:px-5 sm:py-5">
                  {item.brand ? (
                    <h3 className="text-lg font-bold tracking-tight text-primary sm:text-xl">
                      {item.brand}
                    </h3>
                  ) : null}

                  {(item.category || item.service) && (
                    <p className="mt-1 text-sm font-normal text-text-secondary">
                      {[item.category, item.service]
                        .filter(Boolean)
                        .join(" · ")}
                    </p>
                  )}

                  {item.description ? (
                    <p className="mt-3 line-clamp-2 flex-1 text-sm font-normal leading-relaxed text-text-secondary">
                      {item.description}
                    </p>
                  ) : null}

                  {item.href ? (
                    <Link
                      href={item.href}
                      className="mt-4 inline-flex min-h-11 items-center gap-2 text-sm font-bold text-primary underline-offset-4 transition-colors hover:text-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                    >
                      Read case study
                      <ArrowRight className="h-4 w-4" aria-hidden="true" />
                    </Link>
                  ) : null}
                </div>
              </article>
            </li>
          );
        })}
      </ul>

      {cta ? (
        <div className="mt-8 flex sm:hidden">
          <PrimaryButton asChild variant="primary" className="w-full">
            <Link href={cta.href}>{cta.label}</Link>
          </PrimaryButton>
        </div>
      ) : null}
    </SectionShell>
  );
}

