import Link from "next/link";
import { Check, X } from "lucide-react";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface ComparisonSectionProps {
  id: string;
  data: Record<string, unknown>;
}

/**
 * Project One comparison chrome — centered type, soft-rect header pills,
 * quiet hairline rows. eCom agency vs DIY copy only.
 */
export function ComparisonSection({ id, data }: ComparisonSectionProps) {
  const eyebrow = readString(data.eyebrow, "Clear comparison");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const columns = data.columns as Record<string, unknown> | undefined;
  const agencyColumn = readString(columns?.agency, "eCom Gliders");
  const alternativeColumn = readString(columns?.alternative, "DIY / In-house");
  const rows = readRecordArray(data.rows);
  const deepLink = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="mx-auto max-w-3xl text-center">
        {eyebrow ? (
          <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
            {eyebrow}
          </p>
        ) : null}
        <h2
          id={headingId}
          className="mt-3 text-[1.85rem] font-black leading-[1.05] tracking-[-0.04em] text-primary text-balance sm:text-[2.75rem] lg:text-[3.8rem] lg:leading-[1.05]"
        >
          {heading}
        </h2>
        {subheading ? (
          <p className="mx-auto mt-4 max-w-2xl text-base font-normal leading-relaxed text-text-secondary sm:text-lg">
            {subheading}
          </p>
        ) : null}
      </div>

      <div className="mt-10 hidden md:mt-14 md:block">
        <table className="w-full border-collapse text-left">
          <thead>
            <tr>
              <th scope="col" className="w-[28%] pb-6 pr-4" />
              <th scope="col" className="w-[36%] pb-6 pr-4 text-center">
                <span className="inline-flex rounded-[10px] bg-accent px-3.5 py-2 text-[11px] font-bold uppercase tracking-[0.12em] text-primary">
                  {agencyColumn}
                </span>
              </th>
              <th scope="col" className="w-[36%] pb-6 text-center">
                <span className="inline-flex rounded-[10px] bg-primary px-3.5 py-2 text-[11px] font-bold uppercase tracking-[0.12em] text-text-on-dark">
                  {alternativeColumn}
                </span>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => {
              const feature = readString(row.feature);
              const agency = readString(row.agency);
              const alternative = readString(row.alternative);

              return (
                <tr
                  key={feature}
                  className="border-t border-primary/10 first:border-t-0"
                >
                  <th
                    scope="row"
                    className="py-5 pr-4 align-middle text-[11px] font-bold uppercase tracking-[0.12em] text-primary sm:text-xs"
                  >
                    {feature}
                  </th>
                  <td className="py-5 pr-4 align-middle">
                    <div className="flex items-start justify-center gap-2.5 text-center">
                      <span
                        className="mt-0.5 inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-accent text-primary"
                        aria-hidden="true"
                      >
                        <Check className="h-3 w-3 stroke-[2.5]" />
                      </span>
                      <span className="text-sm font-bold leading-snug text-primary">
                        {agency}
                      </span>
                    </div>
                  </td>
                  <td className="py-5 align-middle">
                    <div className="flex items-start justify-center gap-2.5 text-center">
                      <span
                        className="mt-0.5 inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10 text-text-secondary"
                        aria-hidden="true"
                      >
                        <X className="h-3 w-3 stroke-[2.5]" />
                      </span>
                      <span className="text-sm font-normal leading-snug text-text-secondary">
                        {alternative}
                      </span>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <ul className="mt-8 space-y-3 md:hidden">
        {rows.map((row) => {
          const feature = readString(row.feature);
          const agency = readString(row.agency);
          const alternative = readString(row.alternative);

          return (
            <li
              key={feature}
              className="overflow-hidden rounded-[16px] border border-primary/15 bg-[#F4F4F4] p-4"
            >
              <p className="text-[11px] font-bold uppercase tracking-[0.12em] text-primary">
                {feature}
              </p>
              <dl className="mt-4 space-y-4 text-sm">
                <div className="flex items-start gap-2.5">
                  <span
                    className="mt-0.5 inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-accent text-primary"
                    aria-hidden="true"
                  >
                    <Check className="h-3 w-3 stroke-[2.5]" />
                  </span>
                  <div>
                    <dt className="text-[11px] font-bold uppercase tracking-[0.12em] text-primary">
                      {agencyColumn}
                    </dt>
                    <dd className="mt-1 font-bold text-primary">{agency}</dd>
                  </div>
                </div>
                <div className="flex items-start gap-2.5">
                  <span
                    className="mt-0.5 inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10 text-text-secondary"
                    aria-hidden="true"
                  >
                    <X className="h-3 w-3 stroke-[2.5]" />
                  </span>
                  <div>
                    <dt className="text-[11px] font-bold uppercase tracking-[0.12em] text-text-secondary">
                      {alternativeColumn}
                    </dt>
                    <dd className="mt-1 font-normal text-text-secondary">
                      {alternative}
                    </dd>
                  </div>
                </div>
              </dl>
            </li>
          );
        })}
      </ul>

      {deepLink ? (
        <p className="mt-10 text-center text-sm text-text-secondary sm:mt-12">
          <Link
            href={deepLink.href}
            className="font-bold text-primary underline-offset-4 transition-colors hover:text-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
          >
            {deepLink.label}
          </Link>
        </p>
      ) : null}
    </SectionShell>
  );
}

