        tileH: tile ? Math.round(tile.getBoundingClientRect().height) : null,
      };
    });

    const sectionText = (root?.innerText || '').replace(/\s+/g,' ').trim().slice(0,400);
    return {
      hText: (h.textContent||'').replace(/\s+/g,' ').trim().slice(0,80),
      hSize: hcs.fontSize, hWeight: hcs.fontWeight, hAlign: hcs.textAlign, hFont: hcs.fontFamily, hColor: hcs.color,
      metrics,
      sectionText,
      y,
    };
  });

  await page.evaluate((y) => window.scrollTo(0, Math.max(0, y - 40)), po.y);
  await page.waitForTimeout(600);
  await page.screenshot({ path: out + '/po-v10-projectone-trust-1440.png', fullPage: false });
  await page.evaluate((y) => window.scrollTo(0, (y||0) + 450), po.y);
  await page.waitForTimeout(400);
  await page.screenshot({ path: out + '/po-v10-projectone-trust-b-1440.png', fullPage: false });

  // Ours trust-bar
  await page.goto('http://localhost:3000/#trust-bar', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(1000);
  await page.evaluate(() => document.querySelector('#trust-bar')?.scrollIntoView({ block: 'start' }));
  await page.waitForTimeout(500);

  const ours = await page.evaluate(() => {
    const s = document.querySelector('#trust-bar');
    if (!s) return { missing: true };
    const h2 = s.querySelector('h2,h3,p');
    const headings = Array.from(s.querySelectorAll('h2,h3,p')).slice(0,6).map(el => ({
      tag: el.tagName,
      text: (el.textContent||'').trim().slice(0,60),
      size: getComputedStyle(el).fontSize,
      weight: getComputedStyle(el).fontWeight,
    }));
    const cards = Array.from(s.querySelectorAll('[class*="rounded"], article, li')).slice(0,8).map(el => {
      const st = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      if (r.height < 40 || r.width < 60) return null;
      return {
        bg: st.backgroundColor,
        radius: st.borderRadius,
        border: st.border,
        shadow: st.boxShadow?.slice(0,60),
        w: Math.round(r.width), h: Math.round(r.height),
      };
    }).filter(Boolean);
    return {
      headings,
      sample: (s.innerText||'').replace(/\s+/g,' ').trim().slice(0,350),
      cards: cards.slice(0,6),
      imgCount: s.querySelectorAll('img').length,
    };
  });
  await page.screenshot({ path: out + '/po-v10-ours-trust-before-1440.png', fullPage: false });

  return { po, ours };
}

async (page) => {
  // Deeper PO trust layout: dark bg? grid? copy block?
  await page.setViewportSize({ width: 1440, height: 900 });
  return page.evaluate(() => {
    const h = Array.from(document.querySelectorAll('h2,h3')).find(el => /Why Trust Us/i.test(el.textContent||''));
    if (!h) return { missing: true };
    let node = h;
    let dark = null;
    for (let i = 0; i < 12 && node; i++) {
      const bg = getComputedStyle(node).backgroundColor;
      const m = bg.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
      const lum = m ? (Number(m[1])+Number(m[2])+Number(m[3]))/3 : 255;
      const r = node.getBoundingClientRect();
      if (lum < 80 && r.height > 400) { dark = node; break; }
      node = node.parentElement;
    }
    const root = dark || h.parentElement;
    const rcs = root ? getComputedStyle(root) : null;
    const rr = root?.getBoundingClientRect();
    // all lime tiles
    const tiles = Array.from((root||document).querySelectorAll('div')).filter(el => {
      const st = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      return st.backgroundColor === 'rgb(198, 253, 80)' && r.width > 200 && r.height > 200 && r.height < 400;
    }).map(el => {
      const st = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      return {
        w: Math.round(r.width), h: Math.round(r.height),
        radius: st.borderRadius,
        text: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0,80),
        x: Math.round(r.left), y: Math.round(r.top),
      };
    });
    // unique by y,x
    const uniq = [];
    for (const t of tiles) {
      if (!uniq.some(u => Math.abs(u.x-t.x)<20 && Math.abs(u.y-t.y)<20)) uniq.push(t);
    }
    return {
      rootBg: rcs?.backgroundColor,
      rootRadius: rcs?.borderRadius,
      rootW: rr ? Math.round(rr.width) : null,
      rootH: rr ? Math.round(rr.height) : null,
      tiles: uniq.slice(0,8),
      hColor: getComputedStyle(h).color,
    };
  });
}

