import Image from "next/image";
import Link from "next/link";
import { cn } from "@/lib/utils";
import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface TrustBarSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface LogoItem {
  label: string;
  image: string;
  alt: string;
  href?: string;
}

interface MetricItem {
  value: string;
  label: string;
  note: string;
}

function readLogoItems(value: unknown): LogoItem[] {
  return readRecordArray(value)
    .map((item) => {
      const label = readString(item.label);
      const image = readString(item.image);
      const alt = readString(item.alt, label);
      const href = readString(item.href) || undefined;
      if (!label && !image) return null;
      return { label, image, alt, href };
    })
    .filter((item): item is LogoItem => item !== null);
}

function MetricTile({ item }: { item: MetricItem }) {
  return (
    <div className="flex min-h-[11rem] flex-col justify-between rounded-[10px] bg-accent p-5 text-primary sm:min-h-[13rem] sm:p-6">
      <p className="text-[2.75rem] font-black leading-none tracking-[-0.04em] sm:text-[3.5rem] lg:text-[3.8rem]">
        {item.value}
      </p>
      <div className="mt-4 space-y-1">
        <p className="text-sm font-bold leading-snug sm:text-base">{item.label}</p>
        {item.note ? (
          <p className="text-xs font-normal leading-relaxed text-primary/70 sm:text-sm">
            {item.note}
          </p>
        ) : null}
      </div>
    </div>
  );
}

function LogoTile({ item }: { item: LogoItem }) {
  const inner = (
    <div className="relative flex min-h-[11rem] items-center justify-center overflow-hidden rounded-[10px] bg-[#2A2A27] p-6 sm:min-h-[13rem]">
      {item.image ? (
        <div className="relative h-16 w-full max-w-[10rem] sm:h-20">
          <Image
            src={item.image}
            alt={item.alt || item.label}
            fill
            className="object-contain brightness-0 invert opacity-90"
            sizes="160px"
            quality={80}
            loading="lazy"
          />
        </div>
      ) : (
        <p className="text-center text-sm font-bold uppercase tracking-[0.08em] text-text-on-dark">
          {item.label}
        </p>
      )}
    </div>
  );

  if (item.href) {
    return (
      <Link
        href={item.href}
        target="_blank"
        rel="noopener noreferrer"
        className="block focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
      >
        {inner}
      </Link>
    );
  }

  return inner;
}

/**
 * Project One trust bento — dark ink field, lime soft-rect metrics,
 * logo tiles. eCom verified claims and assets only.
 */
export function TrustBarSection({ id, data }: TrustBarSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const headingId = `${id}-heading`;

  const metrics: MetricItem[] = readRecordArray(data.metrics)
    .map((item) => {
      const value = readString(item.value);
      const label = readString(item.label);
      if (!value || !label) return null;
      return {
        value,
        label,
        note: readString(item.note),
      };
    })
    .filter((item): item is MetricItem => item !== null);

  const partners = readLogoItems(data.partners);
  const clients = readLogoItems(data.clients).slice(0, 4);
  const reviews = readLogoItems(data.reviews);
  const press = readLogoItems(data.press).slice(0, 2);
  const logoTiles = [...partners, ...reviews, ...press, ...clients];

  type BentoCell =
    | { kind: "metric"; item: MetricItem; key: string }
    | { kind: "logo"; item: LogoItem; key: string };

  const cells: BentoCell[] = [];
  const maxLen = Math.max(metrics.length, logoTiles.length);
  for (let i = 0; i < maxLen; i += 1) {
    if (metrics[i]) {
      cells.push({
        kind: "metric",
        item: metrics[i],
        key: `metric-${metrics[i].value}`,
      });
    }
    if (logoTiles[i]) {
      cells.push({
        kind: "logo",
        item: logoTiles[i],
        key: `logo-${logoTiles[i].image || logoTiles[i].label}`,
      });
    }
  }

  if (cells.length === 0 && !heading && !eyebrow) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={heading || eyebrow ? headingId : undefined}
      tone="primary"
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className={cn("mx-auto max-w-3xl text-center")}>
        {eyebrow ? (
          <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-accent sm:text-xs">
            {eyebrow}
          </p>
        ) : null}
        {heading ? (
          <h2
            id={headingId}
            className="mt-3 text-[1.85rem] font-black leading-[1.05] tracking-[-0.04em] text-text-on-dark text-balance sm:text-[2.5rem] lg:text-[3rem] lg:leading-[1.05]"
          >
            {heading}
          </h2>
        ) : eyebrow ? (
          <span id={headingId} className="sr-only">
            {eyebrow}
          </span>
        ) : null}
        {subheading ? (
          <p className="mx-auto mt-4 max-w-2xl text-base font-normal leading-relaxed text-white/65 sm:text-lg">
            {subheading}
          </p>
        ) : null}
      </div>

      {cells.length > 0 ? (
        <ul className="mt-10 grid grid-cols-2 gap-3 sm:mt-12 sm:gap-4 lg:grid-cols-4">
          {cells.map((cell) => (
            <li key={cell.key}>
              {cell.kind === "metric" ? (
                <MetricTile item={cell.item} />
              ) : (
                <LogoTile item={cell.item} />
              )}
            </li>
          ))}
        </ul>
      ) : null}
    </SectionShell>
  );
}

