      sectionRadius: dark ? getComputedStyle(dark).borderRadius : null,
      quoteSize: quoteEl ? getComputedStyle(quoteEl).fontSize : null,
      quoteWeight: quoteEl ? getComputedStyle(quoteEl).fontWeight : null,
      nameEls: nameEls.slice(0,6),
      grid: (() => {
        // how many cream cards in row
        const cards = Array.from(document.querySelectorAll('div')).filter(el => {
          const st = getComputedStyle(el);
          const r = el.getBoundingClientRect();
          return st.backgroundColor === 'rgb(243, 242, 234)' && st.boxShadow.includes('4px') && r.width > 300 && r.height > 200;
        });
        const uniq = [];
        for (const c of cards) {
          const r = c.getBoundingClientRect();
          if (!uniq.some(u => Math.abs(u.x-r.left)<20 && Math.abs(u.y-r.top)<20)) uniq.push({ x: r.left, y: r.top, w: Math.round(r.width) });
        }
        return uniq.slice(0,8);
      })(),
    };
  });
}

