              <figure
                className={cn(
                  "relative flex h-full w-full flex-col overflow-hidden rounded-[10px]",
                  "bg-[#F3F2EA] p-5 text-primary shadow-[4px_4px_0_0_#131311] sm:p-6",
                )}
              >
                <span
                  className="pointer-events-none absolute right-4 top-3 text-5xl font-black leading-none text-primary/15 sm:right-5 sm:text-6xl"
                  aria-hidden="true"
                >
                  &rdquo;
                </span>

                <blockquote className="relative z-[1] flex-1 pr-8">
                  <p className="text-lg font-black leading-snug tracking-[-0.02em] text-primary sm:text-[1.35rem] sm:leading-snug lg:text-[1.55rem]">
                    {quote}
                  </p>
                </blockquote>

                {attribution ? (
                  <figcaption className="relative z-[1] mt-6 pt-1">
                    <p className="text-sm font-medium text-primary/80 sm:text-base">
                      {attribution}
                    </p>
                    {role && company ? (
                      <p className="mt-0.5 text-xs font-normal text-primary/55 sm:text-sm">
                        {role}
                      </p>
                    ) : null}
                  </figcaption>
                ) : null}
              </figure>
            </li>
          );
        })}
      </ul>
    </SectionShell>
  );
}

