        rowShadow: rs.boxShadow.slice(0,50),
        rowH: Math.round(row.getBoundingClientRect().height),
        rowBorderBottom: rs.borderBottom,
      };
    });

    // Separators - lines inside lime
    const lime = Array.from(document.querySelectorAll('div')).find(el => {
      const st = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      return st.backgroundColor === 'rgb(198, 253, 80)' && r.height > 800 && r.width > 1000;
