      if ((lum < 80 || bg === 'rgb(198, 253, 80)') && r.height > 250) { dark = root; break; }
      root = root.parentElement;
    }

    const rcs = dark ? getComputedStyle(dark) : null;
    const ctas = Array.from((dark||document).querySelectorAll('a,button')).filter(el => {
      const r = el.getBoundingClientRect();
      const t = (el.textContent||'').trim();
      return r.width > 80 && r.height > 30 && /reserve|book|start|contact|call/i.test(t);
    }).slice(0, 6).map(el => {
      const st = getComputedStyle(el);
      return {
        text: (el.textContent||'').replace(/\s+/g,' ').trim().slice(0,50),
        bg: st.backgroundColor,
        color: st.color,
        radius: st.borderRadius,
        shadow: st.boxShadow.slice(0,60),
        border: st.border,
      };
    });

    return {
      hText: (h.textContent||'').replace(/\s+/g,' ').trim().slice(0,90),
      hSize: hcs.fontSize, hWeight: hcs.fontWeight, hAlign: hcs.textAlign, hFont: hcs.fontFamily, hColor: hcs.color,
      sectionBg: rcs?.backgroundColor,
      sectionRadius: rcs?.borderRadius,
      sectionH: dark ? Math.round(dark.getBoundingClientRect().height) : null,
      ctas,
      y,
      sample: (dark||h.parentElement)?.innerText?.replace(/\s+/g,' ').trim().slice(0,350),
      nearbyHeadings: candidates.filter(c => Math.abs(c.y - y) < 800).slice(0, 10),
    };
  });

  if (po.y) {
    await page.evaluate((y) => window.scrollTo(0, Math.max(0, y - 80)), po.y);
    await page.waitForTimeout(600);
  }
  await page.screenshot({ path: out + '/po-v13-projectone-finalcta-1440.png', fullPage: false });

  // Ours
  await page.goto('http://localhost:3000/#final-cta', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(1000);
  await page.evaluate(() => document.querySelector('#final-cta')?.scrollIntoView({ block: 'start' }));
  await page.waitForTimeout(500);

  const ours = await page.evaluate(() => {
    const s = document.querySelector('#final-cta');
    if (!s) return { missing: true };
    const h2 = s.querySelector('h2');
    const h2cs = h2 ? getComputedStyle(h2) : null;
    const scs = getComputedStyle(s);
    const links = Array.from(s.querySelectorAll('a')).map(a => ({
      text: (a.textContent||'').replace(/\s+/g,' ').trim().slice(0,50),
      href: a.getAttribute('href'),
      bg: getComputedStyle(a).backgroundColor,
      radius: getComputedStyle(a).borderRadius,
      shadow: getComputedStyle(a).boxShadow.slice(0,50),
    }));
    return {
      h2: h2?.textContent?.trim(),
      h2Size: h2cs?.fontSize, h2Weight: h2cs?.fontWeight, h2Align: h2cs?.textAlign, h2Font: h2cs?.fontFamily, h2Color: h2cs?.color,
      sectionBg: scs.backgroundColor,
      links,
      sample: (s.innerText||'').replace(/\s+/g,' ').trim().slice(0,300),
    };
  });
  await page.screenshot({ path: out + '/po-v13-ours-finalcta-before-1440.png', fullPage: false });

  return { po, ours };
}

async (page) => {
  const out = 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots';
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.projectone.website/', { waitUntil: 'domcontentloaded', timeout: 90000 });
