  const po = await page.evaluate(() => {
    const h = Array.from(document.querySelectorAll('h1,h2,h3')).find(el =>
      /Your Site Won.?t Build Itself/i.test((el.textContent||'').trim())
    );
    if (!h) return { missing: true };
    const y = Math.round(h.getBoundingClientRect().top + window.scrollY);
    h.scrollIntoView({ block: 'start' });

    // Find surrounding block - look for lime CTA button nearby
    const nearby = Array.from(document.querySelectorAll('a,button,div,p,h3')).filter(el => {
      const ey = el.getBoundingClientRect().top + window.scrollY;
      return ey > y - 40 && ey < y + 700;
    }).slice(0, 40).map(el => {
      const st = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      return {
        tag: el.tagName,
        text: (el.textContent||'').replace(/\s+/g,' ').trim().slice(0,70),
        bg: st.backgroundColor,
        color: st.color,
        size: st.fontSize,
        weight: st.fontWeight,
        radius: st.borderRadius,
        shadow: st.boxShadow.slice(0,50),
        w: Math.round(r.width), h: Math.round(r.height),
        y: Math.round(r.top + window.scrollY),
      };
    }).filter(x => x.text && x.w > 40 && x.h > 20 && x.h < 200);

    // climb for panel
    let node = h.parentElement;
    let panel = null;
    for (let i = 0; i < 10 && node; i++) {
      const r = node.getBoundingClientRect();
      const bg = getComputedStyle(node).backgroundColor;
      if (r.height > 280 && r.width > 800 && bg !== 'rgba(0, 0, 0, 0)') { panel = node; break; }
      node = node.parentElement;
    }
    const pcs = panel ? getComputedStyle(panel) : null;
    const hcs = getComputedStyle(h);

    return {
      hText: (h.textContent||'').replace(/\s+/g,' ').trim(),
      hSize: hcs.fontSize, hWeight: hcs.fontWeight, hAlign: hcs.textAlign, hColor: hcs.color, hFont: hcs.fontFamily,
      panelBg: pcs?.backgroundColor, panelRadius: pcs?.borderRadius,
      panelH: panel ? Math.round(panel.getBoundingClientRect().height) : null,
      nearby: nearby.filter(n => /reserve|sign|plan|site|zero|good thing|won|build|contact/i.test(n.text) || n.bg === 'rgb(198, 253, 80)' || n.bg === 'rgb(19, 19, 17)').slice(0, 15),
      y,
    };
  });

  await page.evaluate((y) => window.scrollTo(0, Math.max(0, y - 60)), po.y);
  await page.waitForTimeout(600);
  await page.screenshot({ path: out + '/po-v13-projectone-finalcta-1440.png', fullPage: false });
  return po;
}

async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
