  await page.goto('https://www.projectone.website/', { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForTimeout(2000);
  return page.evaluate(() => {
    const h = Array.from(document.querySelectorAll('h1,h2,h3')).find(el =>
      /Your Site Won.?t Build Itself/i.test((el.textContent||'').trim())
    );
    if (!h) return { missing: true };
    const y = h.getBoundingClientRect().top + window.scrollY;
    // Find lime buttons near this CTA
    const limeBtns = Array.from(document.querySelectorAll('a,button,div')).filter(el => {
      const ey = el.getBoundingClientRect().top + window.scrollY;
      const st = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      return ey > y && ey < y + 500 && st.backgroundColor === 'rgb(198, 253, 80)' && r.height > 36 && r.width > 100;
    }).map(el => ({
      text: (el.textContent||'').replace(/\s+/g,' ').trim().slice(0,60),
      tag: el.tagName,
      w: Math.round(el.getBoundingClientRect().width),
      h: Math.round(el.getBoundingClientRect().height),
      radius: getComputedStyle(el).borderRadius,
      shadow: getComputedStyle(el).boxShadow.slice(0,60),
      size: getComputedStyle(el).fontSize,
      weight: getComputedStyle(el).fontWeight,
    }));
    // unique
    const uniq = [];
    for (const b of limeBtns) {
      if (!uniq.some(u => u.text === b.text && u.w === b.w)) uniq.push(b);
    }
    const sub = Array.from(document.querySelectorAll('p')).find(el => {
      const ey = el.getBoundingClientRect().top + window.scrollY;
      return ey > y && ey < y + 300 && /One plan|Sign up|dream/i.test(el.textContent||'');
    });
    return {
      sub: sub ? {
        text: (sub.textContent||'').trim().slice(0,120),
        size: getComputedStyle(sub).fontSize,
        weight: getComputedStyle(sub).fontWeight,
        align: getComputedStyle(sub).textAlign,
      } : null,
      limeBtns: uniq.slice(0,5),
      hAlign: getComputedStyle(h).textAlign,
    };
  });
}

