async (page) => {
  const out = 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots';

  async function measure() {
    await page.evaluate(() => {
      const f = document.querySelector('footer');
      f?.scrollIntoView({ block: 'start' });
    });
    await page.waitForTimeout(500);
    return page.evaluate(() => {
      const f = document.querySelector('footer');
      if (!f) return { missing: true };
      const fcs = getComputedStyle(f);
      const h2 = f.querySelector('h2');
      const h2cs = h2 ? getComputedStyle(h2) : null;
      const cta = Array.from(f.querySelectorAll('a')).find(a => /free audit|request a free/i.test(a.textContent||''));
      const privacy = Array.from(f.querySelectorAll('a')).find(a => /privacy/i.test(a.textContent||''));
      const serviceLink = Array.from(f.querySelectorAll('a')).find(a => /Amazon PPC/i.test(a.textContent||''));
      const watermark = Array.from(f.querySelectorAll('p')).find(p => p.getAttribute('aria-hidden') === 'true');
      const leak = /KHULA|Framer Expert|Reserve Your Spot|Chilliwack|Hungry For Life|Money-Back/i.test(f.innerText||'');
      return {
        overflowX: document.documentElement.scrollWidth > document.documentElement.clientWidth + 2,
        bg: fcs.backgroundColor,
        radius: fcs.borderRadius,
        h2: h2?.textContent?.trim(),
        h2Size: h2cs?.fontSize, h2Weight: h2cs?.fontWeight, h2Font: h2cs?.fontFamily,
        ctaHref: cta?.getAttribute('href') || null,
        ctaBg: cta ? getComputedStyle(cta).backgroundColor : null,
        privacyHref: privacy?.getAttribute('href') || null,
        privacyDecoration: privacy ? getComputedStyle(privacy).textDecorationLine : null,
        serviceSize: serviceLink ? getComputedStyle(serviceLink).fontSize : null,
        serviceWeight: serviceLink ? getComputedStyle(serviceLink).fontWeight : null,
        watermark: watermark?.textContent?.trim() || null,
        accent: document.documentElement.getAttribute('style')?.match(/--color-accent:\s*([^;]+)/)?.[1],
        primary: document.documentElement.getAttribute('style')?.match(/--color-primary:\s*([^;]+)/)?.[1],
        leak,
        linkCount: f.querySelectorAll('a').length,
      };
    });
  }

  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3000/', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(1200);
  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
  await page.waitForTimeout(600);
  const d1440 = await measure();
  await page.screenshot({ path: out + '/po-v14-ours-footer-after-1440.png', fullPage: false });

  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('http://localhost:3000/', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(800);
  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
  await page.waitForTimeout(500);
  const d390 = await measure();
  await page.screenshot({ path: out + '/po-v14-ours-footer-after-390.png', fullPage: false });

  return { d1440, d390 };
}

