}

import { cn } from "@/lib/utils";
import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface TestimonialsSectionProps {
  id: string;
  data: Record<string, unknown>;
}

/**
 * Project One testimonial chrome — dark band, cream hard cards with
 * border + solid offset shadow. Horizontal scroll on small screens;
 * denser wrap on desktop so five quotes do not leave an empty cell.
 */
export function TestimonialsSection({ id, data }: TestimonialsSectionProps) {
  const eyebrow = readString(data.eyebrow, "Client voices");
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const items = readRecordArray(data.items);
  const headingId = `${id}-heading`;

  if (!heading || items.length === 0) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      tone="primary"
      className="py-12 sm:py-16 lg:py-20"
    >
      <div className="max-w-3xl">
        {eyebrow ? (
          <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-accent sm:text-xs">
            {eyebrow}
          </p>
        ) : null}
        <h2
          id={headingId}
          className="mt-3 text-[1.85rem] font-black leading-[1.05] tracking-[-0.04em] text-text-on-dark text-balance sm:text-[2.5rem] lg:text-[3rem] lg:leading-[1.05]"
        >
          {heading}
        </h2>
        {subheading ? (
          <p className="mt-4 max-w-2xl text-base font-normal leading-relaxed text-white/65 sm:text-lg">
            {subheading}
          </p>
        ) : null}
      </div>

      <ul
        className={cn(
          "mt-10 flex gap-4 overflow-x-auto pb-3 [-ms-overflow-style:none] [scrollbar-width:none] sm:mt-12 sm:gap-5",
          "[&::-webkit-scrollbar]:hidden",
          "md:flex md:flex-wrap md:justify-center md:overflow-visible md:pb-0",
        )}
      >
        {items.map((item) => {
          const quote = readString(item.quote);
          const name = readString(item.name);
          const role = readString(item.role);
          const company = readString(item.company);
          const key = `${name}-${company}`;
          const attribution = [name, company || role].filter(Boolean).join(" | ");

          return (
            <li
              key={key}
              className="flex w-[min(85vw,22rem)] shrink-0 md:w-[calc(50%-0.625rem)] lg:w-[calc(33.333%-0.875rem)]"
            >
              <figure
                className={cn(
                  "relative flex h-full w-full flex-col overflow-hidden rounded-[10px]",
                  "border-2 border-primary bg-[#F3F2EA] p-5 text-primary shadow-[4px_4px_0_0_#131311] sm:p-6",
                )}
              >
                <span
                  className="pointer-events-none absolute right-4 top-3 text-5xl font-black leading-none text-primary/15 sm:right-5 sm:text-6xl"
                  aria-hidden="true"
                >
                  &rdquo;
                </span>

                <blockquote className="relative z-[1] flex-1 pr-8">
                  <p className="text-base font-bold leading-relaxed tracking-[-0.01em] text-primary sm:text-lg sm:leading-relaxed">
                    {quote}
                  </p>
                </blockquote>

                {attribution ? (
                  <figcaption className="relative z-[1] mt-6 border-t border-primary/10 pt-4">
                    <p className="text-sm font-bold text-primary sm:text-base">
                      {attribution}
                    </p>
                    {role && company ? (
                      <p className="mt-0.5 text-xs font-normal text-primary/55 sm:text-sm">
                        {role}
                      </p>
                    ) : null}
                  </figcaption>
                ) : null}
              </figure>
            </li>
          );
        })}
      </ul>
    </SectionShell>
  );
}

import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { formatPublishedDate } from "./format-date";
import { SectionHeading } from "./section-heading";
import { SectionShell } from "./section-shell";

interface BlogPreviewSectionProps {
  id: string;
  data: Record<string, unknown>;
}

export function BlogPreviewSection({ id, data }: BlogPreviewSectionProps) {
  const heading = readString(data.heading);
  const subheading = readString(data.subheading);
  const posts = readRecordArray(data.posts);
  const cta = readNavLink(data.cta);
  const headingId = `${id}-heading`;

  return (
    <SectionShell id={id} ariaLabelledBy={headingId} className="py-12 sm:py-16">
      <SectionHeading
        heading={heading}
        subheading={subheading}
        headingId={headingId}
      />
      <ul className="grid gap-5 lg:grid-cols-3 lg:gap-6">
        {posts.map((post) => {
          const slug = readString(post.slug);
          const title = readString(post.title);
          const date = readString(post.date);
          const excerpt = readString(post.excerpt);
          const href = readString(post.href, slug ? `/${slug}/` : "/blog/");
          const image = readString(post.image);
          const imageAlt = readString(post.imageAlt, title);
          const key = slug || title;

          return (
            <li key={key}>
              <article className="flex h-full flex-col overflow-hidden rounded-[10px] border-2 border-primary bg-background shadow-[4px_4px_0_0_#131311]">
                <div className="relative aspect-[16/10] border-b-2 border-primary bg-surface">
                  {image ? (
                    <Image
                      src={image}
                      alt={imageAlt || title}
                      fill
                      className="object-cover"
                      sizes="(max-width: 1024px) 100vw, 33vw"
                      quality={75}
                      loading="lazy"
                    />
                  ) : (
                    <div className="flex h-full items-end bg-gradient-to-br from-accent/40 via-surface to-primary/10 px-5 py-4">
                      <span className="text-small font-bold uppercase tracking-[0.1em] text-primary">
                        Article
                      </span>
                    </div>
                  )}
                </div>
                <div className="flex flex-1 flex-col p-5 sm:p-6">
                  {date ? (
                    <time
                      dateTime={date}
                      className="text-[11px] font-bold uppercase tracking-[0.12em] text-text-secondary"
                    >
                      {formatPublishedDate(date)}
                    </time>
                  ) : null}
                  <h3 className="mt-2 text-lg font-black leading-snug tracking-tight text-primary">
                    <Link
                      href={href}
                      className="hover:text-link-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
                    >
                      {title}
                    </Link>
                  </h3>
                  <p className="mt-3 flex-1 text-sm leading-relaxed text-text-secondary">
                    {excerpt}
                  </p>
                  <Link
                    href={href}
                    className="mt-4 inline-flex items-center gap-1.5 text-sm font-bold text-primary underline-offset-4 hover:underline"
                  >
                    Read article
                    <ArrowRight className="h-4 w-4" aria-hidden="true" />
                  </Link>
                </div>
              </article>
            </li>
          );
        })}
      </ul>
      {cta ? (
        <div className="mt-10 text-center">
          <PrimaryButton asChild variant="primary" size="lg">
            <Link href={cta.href}>{cta.label}</Link>
          </PrimaryButton>
        </div>
      ) : null}
    </SectionShell>
  );
}

