    const trust = Array.from(document.querySelectorAll('p, span, div')).find(el => /Helping sellers since 2018/.test(el.textContent || '') && el.children.length < 3);
    if (!trust) return { found: false };
    const r = trust.getBoundingClientRect();
    const cx = r.left + r.width/2, cy = r.top + r.height/2;
    const top = document.elementFromPoint(cx, cy);
    return {
      found: true,
      text: trust.textContent?.slice(0,80),
      opacity: getComputedStyle(trust).opacity,
      color: getComputedStyle(trust).color,
      topTag: top?.tagName,
      topText: top?.textContent?.slice(0,60),
      coveredBySelf: top === trust || trust.contains(top),
    };
