async (page) => {
  await page.locator('#testimonials').scrollIntoViewIfNeeded();
  const styles = await page.evaluate(() => {
    const fig = document.querySelector('#testimonials figure');
    if (!fig) return null;
    const s = getComputedStyle(fig);
    return {
      border: s.border,
      boxShadow: s.boxShadow,
      background: s.backgroundColor,
      borderRadius: s.borderRadius,
    };
  });
  await page.locator('#hero-lead-form').scrollIntoViewIfNeeded();
  const form = await page.evaluate(() => {
    const el = document.querySelector('#hero-lead-form');
    const s = getComputedStyle(el);
    return { bg: s.backgroundColor, border: s.border, shadow: s.boxShadow };
  });
  // find large discs
  const discs = await page.evaluate(() => {
    return Array.from(document.querySelectorAll('div')).filter(d => {
      const s = getComputedStyle(d);
      const w = parseFloat(s.width);
      return s.borderRadius.includes('50%') || parseFloat(s.borderRadius) > w/2 - 2;
    }).filter(d => {
      const r = d.getBoundingClientRect();
      return r.width > 400;
    }).slice(0,8).map(d => ({
      className: d.className.slice(0,120),
      w: Math.round(d.getBoundingClientRect().width),
      h: Math.round(d.getBoundingClientRect().height),
      bg: getComputedStyle(d).backgroundColor,
    }));
  });
  return { styles, form, discs };
}

