async (page) => {
  await page.locator('#hero-lead-form').scrollIntoViewIfNeeded();
  await page.waitForTimeout(300);
  return await page.evaluate(() => {
    const form = document.querySelector('#hero-lead-form');
    const support = Array.from(document.querySelectorAll('p')).find(el => /Dedicated specialists/.test(el.textContent || ''));
    const sr = support.getBoundingClientRect();
    // sample points around support text
    const samples = [];
    for (const [dx,dy] of [[0,-40],[0,0],[0,40],[-200,0],[200,0]]) {
      const x = sr.left + sr.width/2 + dx;
      const y = sr.top + sr.height/2 + dy;
      const el = document.elementFromPoint(x,y);
      samples.push({
        dx, dy,
        tag: el?.tagName,
        cls: (el?.className || '').toString().slice(0,100),
        bg: el ? getComputedStyle(el).backgroundColor : null,
      });
    }
    // look for any large light rounded elements in hero
    const hero = document.querySelector('#hero') || document.querySelector('section');
    const lightCircles = Array.from(document.querySelectorAll('section .rounded-full, [class*="F4F4F4"], [class*="F2F2F2"]')).map(el => {
      const r = el.getBoundingClientRect();
      return { cls: el.className.toString().slice(0,120), w: Math.round(r.width), h: Math.round(r.height), top: Math.round(r.top) };
    }).filter(x => x.w > 80);
    return { samples, lightCircles, supportColor: getComputedStyle(support).color, formTop: form.getBoundingClientRect().top };
  });
}

async (page) => {
  // Find comparison / partner section
  const hit = await page.evaluate(() => {
    const els = Array.from(document.querySelectorAll('h1,h2,h3,p,div,span'));
    const el = els.find(e => /Why Partner With Us|Smarter Way to Get Online|no-brainer/i.test(e.textContent || ''));
    if (el) {
      el.scrollIntoView({ block: 'center' });
      return el.textContent?.slice(0, 80);
    }
    return null;
  });
  await page.waitForTimeout(800);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.screenshot({ path: 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots/po-comparison-ref-1440.png', fullPage: false });
  // gather structure
  const structure = await page.evaluate(() => {
    const heading = Array.from(document.querySelectorAll('h1,h2,h3')).find(h => /Smarter Way|Partner/i.test(h.textContent || ''));
    const section = heading?.closest('section') || heading?.parentElement?.parentElement;
    if (!section) return { found: false };
    const texts = Array.from(section.querySelectorAll('p,h2,h3,span,th,td,div')).slice(0, 80).map(e => (e.textContent || '').trim().slice(0, 60)).filter(Boolean);
    const unique = [...new Set(texts)].slice(0, 40);
    return { found: true, unique };
  });
  return { hit, structure };
}

async (page) => {
  // scroll further to capture table
  await page.evaluate(() => {
    const el = Array.from(document.querySelectorAll('h1,h2,h3')).find(h => /Smarter Way/i.test(h.textContent || ''));
    el?.scrollIntoView({ block: 'start' });
  });
  await page.waitForTimeout(500);
  await page.evaluate(() => window.scrollBy(0, 280));
  await page.waitForTimeout(400);
  await page.screenshot({ path: 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots/po-comparison-table-1440.png', fullPage: false });
  const tableBits = await page.evaluate(() => {
    const labels = ['PROJECTONE','AGENCY','FREELANCER','DO IT YOURSELF','TIMELINE','PRICE','GUARANTEE','no-brainer'];
    const found = {};
    for (const l of labels) {
      const el = Array.from(document.querySelectorAll('*')).find(e => (e.childNodes.length && Array.from(e.childNodes).some(n => n.nodeType===3 && n.textContent.trim()===l)) || e.textContent?.trim()===l);
      found[l] = !!el;
    }
    // get computed style of PROJECTONE header if any
    const po = Array.from(document.querySelectorAll('*')).find(e => e.textContent?.trim() === 'PROJECTONE' && e.children.length === 0);
    if (po) {
      const s = getComputedStyle(po);
      const p = getComputedStyle(po.parentElement || po);
      found.poStyle = { color: s.color, bg: p.backgroundColor, border: p.border, font: s.fontFamily, size: s.fontSize, weight: s.fontWeight };
    }
    return found;
  });
  return tableBits;
}

