import { cn } from "@/lib/utils";

type SwingArrow = "down-left" | "down-right";
type SwingTone = "ink" | "onDark" | "lime";

interface SwingCalloutProps {
  text: string;
  /** Placement via Tailwind absolute/relative classes from the parent. */
  className?: string;
  arrow?: SwingArrow;
  tone?: SwingTone;
  /** Extra rotate applied on top of the gentle swing animation. */
  tilt?: string;
}

const toneClass: Record<SwingTone, string> = {
  ink: "text-primary",
  onDark: "text-accent",
  lime: "text-accent",
};

function ArrowSvg({ direction }: { direction: SwingArrow }) {
  if (direction === "down-left") {
    return (
      <svg
        className="mt-0.5 h-[4.25rem] w-[7.5rem] text-current"
        viewBox="0 0 140 90"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
      >
        <path
          d="M118 14 C 98 18, 62 28, 42 52 C 32 64, 28 74, 34 82"
          stroke="currentColor"
          strokeWidth="2.4"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M48 68 L34 82 L56 78"
          stroke="currentColor"
          strokeWidth="2.4"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    );
  }

  return (
    <svg
      className="mt-0.5 ml-1 h-[4.25rem] w-[7.5rem] text-current"
      viewBox="0 0 140 90"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M22 14 C 42 18, 78 28, 98 52 C 108 64, 112 74, 106 82"
        stroke="currentColor"
        strokeWidth="2.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path
        d="M92 68 L106 82 L84 78"
        stroke="currentColor"
        strokeWidth="2.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * Handwritten PO-style callout — decorative only (aria-hidden).
 * Use sparingly; one per section max.
 */
export function SwingCallout({
  text,
  className,
  arrow = "down-left",
  tone = "ink",
  tilt = "-rotate-6",
}: SwingCalloutProps) {
  if (!text) return null;

  return (
    <aside
      className={cn(
        "pointer-events-none z-[2] hidden w-[11.5rem] select-none xl:block",
        "origin-top motion-safe:animate-[comparison-swing_3.8s_ease-in-out_infinite]",
        tilt,
        toneClass[tone],
        className,
      )}
      aria-hidden="true"
    >
      <p
        className="text-[1.35rem] font-semibold leading-[1.15] tracking-[-0.01em]"
        style={{ fontFamily: "var(--font-hand)" }}
      >
        {text}
      </p>
      <ArrowSvg direction={arrow} />
    </aside>
  );
}

