    if (!start) return null;
    const s = start.getBoundingClientRect();
    const e = end ? end.getBoundingClientRect() : s;
    return { x: 40, y: Math.max(0, s.top - 80), width: 1360, height: Math.min(900, Math.max(e.bottom, s.bottom) - s.top + 160) };
  });
  if (box) await page.screenshot({ path: 'C:/Users/faizan/.playwright-mcp/po-process-structure.png', clip: box, scale: 'css' });
  return { count: structure.length, structure, box };
}

async (page) => {
  // Get exact process card texts + phase labels + footer line
  const data = await page.evaluate(() => {
    const phases = [...document.querySelectorAll('*')]
      .filter(e => {
        const t = (e.textContent||'').trim();
        return ['INITIAL DISCOVERY','MOODBOARD & WIREFRAME','UI DESIGN & FEEDBACK','Framer Development'].includes(t) && e.children.length === 0;
      })
      .map(e => {
        const r = e.getBoundingClientRect();
        return { t: e.textContent.trim(), x: Math.round(r.left), y: Math.round(r.top), w: Math.round(r.width) };
      });

    // Cards: look for number circles pattern - text starting with known titles
    const titles = ['Onboarding','We Build','First Look','Revisions','Framer Development','Launch'];
    const cards = [];
    for (const title of titles) {
      const el = [...document.querySelectorAll('*')].find(e => {
        const t = (e.textContent||'').trim();
        return t.startsWith(title) && t.length > 20 && t.length < 250 && getComputedStyle(e).backgroundColor.includes('198');
      }) || [...document.querySelectorAll('*')].find(e => {
        const t = (e.textContent||'').trim();
        return t === title;
      });
      if (!el) continue;
      // climb to lime card
      let node = el;
      for (let i=0;i<8;i++) {
        const bg = getComputedStyle(node).backgroundColor;
        if (/rgb\(19[0-9],\s*25[0-9]/.test(bg) || /rgb\(198/.test(bg)) break;
        if (!node.parentElement) break;
        node = node.parentElement;
      }
      const r = node.getBoundingClientRect();
      cards.push({ title, text: (node.textContent||'').replace(/\s+/g,' ').trim().slice(0,200), x: Math.round(r.left), y: Math.round(r.top), w: Math.round(r.width), h: Math.round(r.height) });
    }
    const footer = [...document.querySelectorAll('*')].find(e => /We build it, we host it/i.test((e.textContent||'').trim()) && (e.textContent||'').length < 100);
    return { phases, cards, footer: footer?.textContent?.trim() };
  });
  return data;
}

