    const heading = [...document.querySelectorAll('*')].find(e => (e.textContent||'').trim() === 'Your Website, Handled.');
    // Find nearby floating frames - elements with rotate transform containing images
    const floats = [...document.querySelectorAll('img')].filter(img => {
      const r = img.getBoundingClientRect();
      return r.width > 80 && r.height > 80 && r.top > 50 && r.top < 850 && r.left < 1400;
