import Image from "next/image";
import Link from "next/link";
import { Check } from "lucide-react";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { readNavLink, readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface FreeAuditCardSectionProps {
  id: string;
  data: Record<string, unknown>;
}

interface FloatPolaroid {
  image: string;
  caption: string;
  alt: string;
  className: string;
}

/**
 * Project One pricing fill — main offer card + side stack.
 * Side polaroids use real creative/case stills (not tiny browser mockups).
 */
export function FreeAuditCardSection({ id, data }: FreeAuditCardSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const title = readString(data.title);
  const priceNote = readString(data.priceNote);
  const badge = readString(data.badge);
  const inclusionsHeading = readString(
    data.inclusionsHeading,
    "What the audit covers",
  );
  const primaryCta = readNavLink(data.primaryCta);
  const secondaryCta = readNavLink(data.secondaryCta);
  const sideTitle = readString(data.sideTitle, "What happens next");
  const sideBody = readString(data.sideBody);
  const sideItems = readRecordArray(data.sideItems)
    .map((item) => readString(item.label) || readString(item.text))
    .filter(Boolean);
  const proofTitle = readString(data.proofTitle);
  const proofBody = readString(data.proofBody);
  const headingId = `${id}-heading`;

  const inclusions = readRecordArray(data.inclusions)
    .map((item) => readString(item.label) || readString(item.text))
    .filter(Boolean);

  const polaroids = readRecordArray(data.polaroids)
    .map((item, index) => {
      const image = readString(item.image);
      if (!image) return null;
      const caption = readString(item.caption);
      const alt = readString(item.alt, caption || "Amazon creative sample");
      const presets = [
        "left-[2%] top-[8%] -rotate-[8deg] xl:left-[4%]",
        "right-[1%] top-[6%] rotate-[7deg] xl:right-[3%]",
        "bottom-[6%] left-[3%] rotate-[5deg] xl:left-[5%]",
        "bottom-[10%] right-[2%] -rotate-[6deg] xl:right-[4%]",
      ] as const;
      return {
        image,
        caption,
        alt,
        className: presets[index] ?? presets[0],
      } satisfies FloatPolaroid;
    })
    .filter((item): item is FloatPolaroid => item !== null);

  if (!title) return null;

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={headingId}
      className="overflow-x-clip py-12 sm:py-16 lg:py-20"
    >
      <div className="mx-auto max-w-2xl text-center">
        {eyebrow ? (
          <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
            {eyebrow}
          </p>
        ) : null}
        <h2
          id={headingId}
          className="mt-3 text-[1.85rem] font-black leading-[1.05] tracking-[-0.04em] text-primary text-balance sm:text-[2.75rem] lg:text-[3.8rem] lg:leading-[1.05]"
        >
          {title}
        </h2>
        {priceNote ? (
          <p className="mx-auto mt-4 max-w-md text-base font-normal leading-relaxed text-text-secondary sm:text-lg">
            {priceNote}
          </p>
        ) : null}
      </div>

      <div className="relative mx-auto mt-10 max-w-5xl sm:mt-12">
        {polaroids.map((item) => (
          <aside
            key={`${item.image}-${item.caption}`}
            className={cn(
              "pointer-events-none absolute z-0 hidden w-[9.5rem] select-none xl:block 2xl:w-[11rem]",
              item.className,
            )}
            aria-hidden="true"
          >
            <div className="rounded-[12px] border-2 border-primary bg-background p-2 shadow-[4px_4px_0_0_#131311]">
              <div className="relative aspect-[4/3] overflow-hidden rounded-[8px] bg-surface-muted">
                <Image
                  src={item.image}
                  alt=""
                  fill
                  className="object-cover"
                  sizes="176px"
                />
              </div>
              {item.caption ? (
                <p className="mt-2 px-0.5 text-center text-[11px] font-bold tracking-tight text-primary">
                  {item.caption}
                </p>
              ) : null}
            </div>
          </aside>
        ))}

        <div className="relative z-10 grid items-start gap-5 lg:grid-cols-[minmax(0,1.15fr)_minmax(0,0.85fr)] lg:gap-6">
          <article className="overflow-hidden rounded-[16px] border-2 border-primary bg-background p-6 text-left text-primary shadow-[4px_4px_0_0_#131311] sm:p-8">
            <div className="flex flex-wrap items-center gap-2">
              <span className="inline-flex rounded-full bg-accent px-3 py-1 text-[11px] font-bold uppercase tracking-[0.12em] text-primary">
                Free audit
              </span>
              {badge ? (
                <span className="text-[11px] font-bold uppercase tracking-[0.12em] text-text-secondary">
                  {badge}
                </span>
              ) : null}
            </div>

            <p className="mt-5 text-xl font-black tracking-[-0.02em] text-primary sm:text-2xl">
              Written priorities for your Amazon account
            </p>
            <p className="mt-2 text-sm leading-relaxed text-text-secondary">
              No obligation. A strategist follows up within one business day.
            </p>

            {primaryCta ? (
              <PrimaryButton
                asChild
                variant="accent"
                size="lg"
                className="mt-6 w-full"
              >
                <Link href={primaryCta.href}>{primaryCta.label}</Link>
              </PrimaryButton>
            ) : null}

            {secondaryCta ? (
              <p className="mt-4 text-center">
                <Link
                  href={secondaryCta.href}
                  className="text-sm font-medium text-text-secondary underline-offset-4 transition-colors hover:text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                >
                  {secondaryCta.label}
                </Link>
              </p>
            ) : null}

            {inclusions.length > 0 ? (
              <div className="mt-8 border-t-2 border-primary/10 pt-6">
                <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-text-secondary">
                  {inclusionsHeading}
                </p>
                <ul className="mt-4 w-full space-y-3 text-left">
                  {inclusions.map((item) => (
                    <li
                      key={item}
                      className="flex w-full items-start gap-3 text-left"
                    >
                      <span
                        className="mt-0.5 inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-accent text-primary"
                        aria-hidden="true"
                      >
                        <Check className="h-3.5 w-3.5 stroke-[2.5]" />
                      </span>
                      <span className="text-sm font-normal leading-snug text-primary/90">
                        {item}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}
          </article>

          <div className="flex flex-col gap-5">
            <article className="rounded-[16px] border-2 border-primary bg-accent p-6 text-primary shadow-[4px_4px_0_0_#131311] sm:p-7">
              <p className="inline-flex rounded-[6px] bg-primary px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.12em] text-text-on-dark">
                After you submit
              </p>
              <h3 className="mt-4 text-xl font-black tracking-[-0.02em] sm:text-2xl">
                {sideTitle}
              </h3>
              {sideBody ? (
                <p className="mt-2 text-sm leading-relaxed text-primary/80">
                  {sideBody}
                </p>
              ) : null}
              {sideItems.length > 0 ? (
                <ul className="mt-5 space-y-3">
                  {sideItems.map((item) => (
                    <li key={item} className="flex items-start gap-3">
                      <span
                        className="mt-0.5 inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary text-accent"
                        aria-hidden="true"
                      >
                        <Check className="h-3.5 w-3.5 stroke-[2.5]" />
                      </span>
                      <span className="text-sm font-medium leading-snug">
                        {item}
                      </span>
                    </li>
                  ))}
                </ul>
              ) : null}
            </article>

            {(proofTitle || proofBody) && (
              <article className="rounded-[16px] border-2 border-primary bg-surface-muted p-6 text-primary shadow-[4px_4px_0_0_#131311] sm:p-7">
                {proofTitle ? (
                  <h3 className="text-lg font-black tracking-[-0.02em] sm:text-xl">
                    {proofTitle}
                  </h3>
                ) : null}
                {proofBody ? (
                  <p className="mt-2 text-sm leading-relaxed text-text-secondary">
                    {proofBody}
                  </p>
                ) : null}
                {secondaryCta ? (
                  <Link
                    href={secondaryCta.href}
                    className="mt-4 inline-flex text-sm font-bold text-primary underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                  >
                    {secondaryCta.label}
                  </Link>
                ) : null}
              </article>
            )}
          </div>
        </div>
      </div>
    </SectionShell>
  );
}

import Link from "next/link";
