async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3000/?t=' + Date.now() + '#testimonials', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(1000);
  await page.evaluate(() => document.querySelector('#testimonials')?.scrollIntoView({ block: 'center' }));
  await page.waitForTimeout(400);

  const before = await page.evaluate(() => {
    const ul = document.querySelector('#testimonials ul');
    if (!ul) return null;
    const style = getComputedStyle(ul);
    return {
      scrollLeft: ul.scrollLeft,
      scrollbarWidth: style.scrollbarWidth,
      overflowX: style.overflowX,
      webkitScrollbarHidden: true,
    };
  });

  // Wait for auto-advance (~3.2s)
  await page.waitForTimeout(3800);
  const after = await page.evaluate(() => {
    const ul = document.querySelector('#testimonials ul');
    return ul ? { scrollLeft: ul.scrollLeft } : null;
  });

  // Check vertical scroll still works over section
  const y0 = await page.evaluate(() => window.scrollY);
  await page.mouse.move(720, 500);
  await page.mouse.wheel(0, 400);
  await page.waitForTimeout(300);
  const y1 = await page.evaluate(() => window.scrollY);

  const clip = await page.evaluate(() => {
    const r = document.querySelector('#testimonials').getBoundingClientRect();
    return { x: 0, y: Math.max(0, r.top), width: 1440, height: Math.min(700, r.height) };
  });
  await page.screenshot({ path: 'C:/Users/faizan/.playwright-mcp/ours-testimonials-autoscroll.png', clip, scale: 'css' });

  return { before, after, pageScrolled: y1 > y0, y0, y1 };
}

