    // brand pills were uppercase with arrow - check for chip list
    const uls = section.querySelectorAll('ul');
    const cards = section.querySelectorAll('article.case-proof-card, article');
    const bottoms = [...cards].map(c => Math.round(c.getBoundingClientRect().bottom));
    return {
      hasChipWordsNearArrow: chips.length,
      ulCount: uls.length,
