async (page) => {
  const viewports = [
    { name: '390', w: 390, h: 844 },
    { name: '768', w: 768, h: 1024 },
    { name: '1024', w: 1024, h: 900 },
  ];
  const results = [];

  for (const vp of viewports) {
    await page.setViewportSize({ width: vp.w, height: vp.h });
    await page.goto('http://localhost:3000/?t=' + Date.now(), { waitUntil: 'domcontentloaded', timeout: 60000 });
    await page.waitForTimeout(1200);

    const info = await page.evaluate((viewportW) => {
      const docW = document.documentElement.scrollWidth;
      const overflowX = docW > viewportW + 2;

      // Find overflowing elements
      const offenders = [];
      for (const el of document.querySelectorAll('body *')) {
        const r = el.getBoundingClientRect();
        if (r.width < 1) continue;
        if (r.right > viewportW + 8 || r.left < -8) {
          const tag = el.tagName.toLowerCase();
          const id = el.id ? '#' + el.id : '';
          const cls = typeof el.className === 'string' ? el.className.split(' ').slice(0, 3).join('.') : '';
          offenders.push({
            sel: tag + id + (cls ? '.' + cls : ''),
            left: Math.round(r.left),
            right: Math.round(r.right),
            w: Math.round(r.width),
          });
          if (offenders.length >= 12) break;
        }
      }

      const header = document.querySelector('header');
      const hr = header?.getBoundingClientRect();
      const headerBar = header?.querySelector('[class*="rounded"]');
      const barR = headerBar?.getBoundingClientRect();

      const announce = document.querySelector('[aria-label*="Ask an AI"]');
      const announceH = announce ? Math.round(announce.getBoundingClientRect().height) : 0;

      // Section heights / issues
      const sections = [...document.querySelectorAll('main section, main [id]')].slice(0, 20).map(s => ({
        id: s.id || s.getAttribute('aria-labelledby') || '',
        overflow: s.scrollWidth > s.clientWidth + 4,
      }));

      return {
        docW,
        overflowX,
        offenders,
        headerH: hr ? Math.round(hr.height) : null,
        barH: barR ? Math.round(barR.height) : null,
        barW: barR ? Math.round(barR.width) : null,
        announceH,
        sectionsOverflow: sections.filter(s => s.overflow),
      };
    }, vp.w);

    await page.screenshot({
      path: `C:/Users/faizan/.playwright-mcp/resp-${vp.name}-top.png`,
      fullPage: false,
      scale: 'css',
    });

    results.push({ vp: vp.name, ...info });
  }

  return results;
}

