import { z } from "zod";
import { faqItemSchema } from "./faq.schema";
import { navLinkSchema } from "./nav-link.schema";
import { pageSeoSchema } from "./page-seo.schema";

const servicePointSchema = z.object({
  title: z.string(),
  description: z.string(),
});

const serviceStepSchema = z.object({
  title: z.string(),
  description: z.string(),
});

const serviceResultSchema = z.object({
  metric: z.string(),
  brand: z.string(),
  description: z.string(),
  href: z.string(),
});

const relatedServiceCardSchema = z.object({
  title: z.string(),
  description: z.string(),
  href: z.string(),
  icon: z.string().optional(),
});

const serviceSectionSchema = z.object({
  heading: z.string(),
  points: z.array(servicePointSchema),
});

export const servicePageConfigSchema = z.object({
  slug: z.string(),
  breadcrumbLabel: z.string(),
  hero: z.object({
    title: z.string(),
    subtitle: z.string(),
    cta: navLinkSchema,
  }),
  stats: z.array(
    z.object({
      label: z.string(),
      value: z.string(),
    }),
  ),
  problem: serviceSectionSchema,
  /** Who this service is for — conversion architecture section */
  audience: serviceSectionSchema.optional(),
  solution: z.object({
    heading: z.string(),
    steps: z.array(serviceStepSchema),
  }),
  deliverables: z.object({
    heading: z.string(),
    items: z.array(servicePointSchema),
  }),
  /** Differentiation vs typical agency / DIY approaches */
  differ: serviceSectionSchema.optional(),
  results: z.object({
    heading: z.string(),
    items: z.array(serviceResultSchema),
  }),
  faq: z.array(faqItemSchema),
  relatedServices: z.array(relatedServiceCardSchema),
  cta: z.object({
    heading: z.string(),
    subheading: z.string().optional(),
    button: navLinkSchema,
  }),
  seo: pageSeoSchema,
});

export type ServicePageConfig = z.infer<typeof servicePageConfigSchema>;

import type { ServicePageConfig, SiteConfig } from "@/domain/content/schemas";
import { absoluteUrl, getSiteUrl } from "./site-url";

/**
 * Official Amazon Seller Central markets supported on homepage FAQ.
 * Keep in sync with content/config/homepage.json markets + FAQ answer.
 */
const AMAZON_SELLER_CENTRAL_MARKETS = [
  "United States",
  "Canada",
  "Mexico",
  "Brazil",
  "United Kingdom",
  "Germany",
  "France",
  "Italy",
  "Spain",
  "Netherlands",
  "Belgium",
  "Ireland",
  "Sweden",
  "Poland",
  "Turkey",
  "United Arab Emirates",
  "Saudi Arabia",
  "Egypt",
  "South Africa",
  "India",
  "Japan",
  "Australia",
  "Singapore",
] as const;

interface BuildServicePageJsonLdInput {
  service: ServicePageConfig;
  site: SiteConfig;
}

export function buildServicePageJsonLd({
  service,
  site,
}: BuildServicePageJsonLdInput): Record<string, unknown> {
  const pageUrl = absoluteUrl(service.seo.canonical);
  const organizationId = `${getSiteUrl()}/#organization`;

  const serviceNode: Record<string, unknown> = {
    "@type": "Service",
    name: service.hero.title,
    description: service.hero.subtitle,
    url: pageUrl,
    provider: {
      "@type": "Organization",
      "@id": organizationId,
      name: site.name,
      url: getSiteUrl(),
    },
    areaServed: AMAZON_SELLER_CENTRAL_MARKETS.map((name) => ({
      "@type": "Country",
      name,
    })),
    serviceType: service.breadcrumbLabel,
  };

  const graph: Record<string, unknown>[] = [serviceNode];

  if (service.faq.length > 0) {
    graph.push({
      "@type": "FAQPage",
      "@id": `${pageUrl}#faq`,
      url: pageUrl,
      mainEntity: service.faq.map((item) => ({
        "@type": "Question",
        name: item.question,
        acceptedAnswer: {
          "@type": "Answer",
          text: item.answer,
        },
      })),
    });
  }

  return {
    "@context": "https://schema.org",
    "@graph": graph,
  };
}

import Link from "next/link";
import type { ServicePageConfig, SiteConfig } from "@/domain/content/schemas";
import { BlogPostCta } from "@/components/blog/blog-post-cta";
import { FaqAccordion } from "@/components/sections/faq-accordion";
import { SectionHeading } from "@/components/sections/section-heading";
import { SectionShell } from "@/components/sections/section-shell";
import { ServicesSection } from "@/components/sections/services-section";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";
import { ServiceBreadcrumb } from "./service-breadcrumb";

interface ServicePageTemplateProps {
  service: ServicePageConfig;
  site: SiteConfig;
}

const hardPanel =
  "rounded-[16px] border-2 border-primary bg-background p-6 text-primary shadow-[4px_4px_0_0_#131311] sm:p-7";

const hardPanelMuted =
  "rounded-[16px] border-2 border-primary bg-surface-muted p-6 text-primary shadow-[4px_4px_0_0_#131311] sm:p-7";

const hardPanelLime =
  "rounded-[16px] border-2 border-primary bg-accent p-6 text-primary shadow-[4px_4px_0_0_#131311] sm:p-7";

export function ServicePageTemplate({ service, site }: ServicePageTemplateProps) {
  return (
    <>
      <ServiceBreadcrumb label={service.breadcrumbLabel} />

      <SectionShell id="service-hero" ariaLabelledBy="service-hero-heading">
        <div className="mx-auto max-w-3xl">
          <p className="inline-flex items-center rounded-[10px] border-2 border-primary bg-primary px-3 py-1 text-[11px] font-bold uppercase tracking-[0.14em] text-text-on-dark">
            {service.breadcrumbLabel}
          </p>
          <h1
            id="service-hero-heading"
            className="mt-5 text-h1 text-primary"
          >
            {service.hero.title}
          </h1>
          <p className="mt-4 text-body text-text-secondary">
            {service.hero.subtitle}
          </p>
          <div className="mt-8">
            <PrimaryButton asChild>
              <Link href={service.hero.cta.href}>{service.hero.cta.label}</Link>
            </PrimaryButton>
          </div>
        </div>
      </SectionShell>

      <SectionShell id="service-stats" tone="muted">
        <ul className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {service.stats.map((stat, index) => (
            <li key={`${stat.value}-${stat.label}`}>
              <article
                className={cn(
                  "h-full",
                  index % 2 === 0 ? hardPanel : hardPanelLime,
                )}
              >
                <p className="text-stat text-primary">{stat.value}</p>
                <p className="mt-2 text-small font-medium text-primary/80">
                  {stat.label}
                </p>
              </article>
            </li>
          ))}
        </ul>
      </SectionShell>

      <SectionShell id="service-problem" ariaLabelledBy="service-problem-heading">
        <SectionHeading
          heading={service.problem.heading}
          headingId="service-problem-heading"
        />
        <ul className="mt-8 grid gap-4 md:grid-cols-2">
          {service.problem.points.map((point) => (
            <li key={point.title} className={hardPanel}>
              <h3 className="text-h4 text-primary">{point.title}</h3>
              <p className="mt-2 text-body text-text-secondary">
                {point.description}
              </p>
            </li>
          ))}
        </ul>
      </SectionShell>

      {service.audience ? (
        <SectionShell
          id="service-audience"
          tone="muted"
          ariaLabelledBy="service-audience-heading"
        >
          <SectionHeading
            heading={service.audience.heading}
            headingId="service-audience-heading"
          />
          <ul className="mt-8 grid gap-4 md:grid-cols-2">
            {service.audience.points.map((point) => (
              <li key={point.title} className={hardPanelMuted}>
                <h3 className="text-h4 text-primary">{point.title}</h3>
                <p className="mt-2 text-body text-text-secondary">
                  {point.description}
                </p>
              </li>
            ))}
          </ul>
        </SectionShell>
      ) : null}

      <SectionShell
        id="service-solution"
        tone={service.audience ? "default" : "muted"}
        ariaLabelledBy="service-solution-heading"
      >
        <SectionHeading
          heading={service.solution.heading}
          headingId="service-solution-heading"
        />
        <ol className="mt-8 space-y-4">
          {service.solution.steps.map((step, index) => (
            <li key={step.title} className={cn("flex gap-4", hardPanel)}>
              <span
                aria-hidden="true"
                className="flex h-10 w-10 shrink-0 items-center justify-center rounded-[10px] border-2 border-primary bg-accent text-small font-bold text-primary shadow-[3px_3px_0_0_#131311]"
              >
                {index + 1}
              </span>
              <div>
                <h3 className="text-h4 text-primary">{step.title}</h3>
                <p className="mt-2 text-body text-text-secondary">
                  {step.description}
                </p>
              </div>
            </li>
          ))}
        </ol>
      </SectionShell>

      <SectionShell
        id="service-deliverables"
        tone="muted"
        ariaLabelledBy="service-deliverables-heading"
      >
        <SectionHeading
          heading={service.deliverables.heading}
          headingId="service-deliverables-heading"
        />
        <ul className="mt-8 grid gap-4 md:grid-cols-2">
          {service.deliverables.items.map((item) => (
            <li key={item.title} className={cn("flex gap-3", hardPanel)}>
              <span
