arguments.function:
() => {
  const title = document.title;
  const meta = document.querySelector('meta[name="description"]')?.getAttribute('content') || '';
  const h1 = document.querySelector('h1')?.textContent?.trim() || '';
  const scripts = [...document.querySelectorAll('script[type="application/ld+json"]')].map(s => {
    try { return JSON.parse(s.textContent || ''); } catch { return null; }
  }).filter(Boolean);
  const graph = scripts.flatMap(s => s['@graph'] || [s]);
  const service = graph.find(n => n['@type'] === 'Service');
  const faq = graph.find(n => n['@type'] === 'FAQPage');
  const areaCount = Array.isArray(service?.areaServed) ? service.areaServed.length : 0;
  const hardChrome = document.querySelectorAll('[class*="shadow-[4px_4px_0_0_#131311]"]').length;
  const bodyText = document.body.innerText;
  const poLeak = /Project One|PO fidelity|lorem ipsum/i.test(bodyText);
  const related = [...document.querySelectorAll('a')].filter(a => /amazon-ppc-management-agency|amazon-listing-optimization|amazon-reporting-analytics/.test(a.getAttribute('href') || '')).map(a => a.getAttribute('href'));
  return { title, meta, h1, types: graph.map(n => n['@type']), areaCount, faqCount: faq?.mainEntity?.length || 0, hardChrome, poLeak, related: [...new Set(related)] };
}

() => {
  const h1 = document.querySelector('h1');
  const rect = h1?.getBoundingClientRect();
  const overflowX = document.documentElement.scrollWidth > document.documentElement.clientWidth + 2;
  return {
    h1Visible: !!h1 && (rect?.width || 0) > 0,
    h1: h1?.textContent?.trim(),
    overflowX,
    viewport: { w: window.innerWidth, h: window.innerHeight }
  };
}

() => {
  const h1 = [...document.querySelectorAll('h1')].map(e => e.innerText.trim());
  const h2 = [...document.querySelectorAll('h2')].map(e => e.innerText.trim()).slice(0, 15);
  const title = document.title;
  const meta = document.querySelector('meta[name="description"]')?.content || '';
  const faqs = [...document.querySelectorAll('details, .faq, [class*="faq"]')].slice(0, 5).map(e => e.innerText.slice(0, 120));
  return { title, meta: meta.slice(0, 200), h1, h2, faqs };
}

() => ({
  title: document.title,
  meta: (document.querySelector('meta[name="description"]')?.content || '').slice(0, 240),
  h1: [...document.querySelectorAll('h1')].map(e => e.innerText.trim()).slice(0, 3),
  h2: [...document.querySelectorAll('h2')].map(e => e.innerText.trim()).filter(Boolean).slice(0, 12)
})

