arguments.function:
() => {
  const title = document.title;
  const meta = document.querySelector('meta[name="description"]')?.getAttribute('content') || '';
  const h1 = document.querySelector('h1')?.textContent?.trim() || '';
  const scripts = [...document.querySelectorAll('script[type="application/ld+json"]')].map(s => { try { return JSON.parse(s.textContent||''); } catch { return null; } }).filter(Boolean);
  const graph = scripts.flatMap(s => s['@graph'] || [s]);
  const service = graph.find(n => n['@type'] === 'Service');
  const faq = graph.find(n => n['@type'] === 'FAQPage');
  const markets = (faq?.mainEntity || []).find(q => /marketplaces/i.test(q.name));
  const body = document.body.innerText;
  const links = ['/free-audit-2/','/amazon-video-creative/','/amazon-content-writing/','/amazon-listing-optimization/','/case-study-4/','/case-study-9/'].map(href => ({ href, ok: !!document.querySelector(`a[href="${href}"]`) }));
  return {
    title, meta, h1,
    hasAudience: /Who Amazon visual creativity is for/i.test(body),
    hasDiffer: /How eCom Gliders visual creativity differs/i.test(body),
    types: graph.map(n => n['@type']),
    areaCount: Array.isArray(service?.areaServed) ? service.areaServed.length : 0,
    faqCount: (faq?.mainEntity || []).length,
    marketsHasUS: /United States, Canada, Mexico, Brazil/.test(markets?.acceptedAnswer?.text || ''),
    poLeak: /Project One|PO fidelity|lorem ipsum|Under the Canopy/i.test(body),
    fakeClaim: /89% order increase|38%\s*average conversion/i.test(body),
    links,
    hardChrome: document.querySelectorAll('[class*="shadow-[4px_4px_0_0_#131311]"]').length
  };
}

() => {
  const h1 = document.querySelector('h1');
  const rect = h1?.getBoundingClientRect();
  return {
    h1: h1?.textContent?.trim(),
    h1Visible: !!h1 && (rect?.width||0) > 0,
    overflowX: document.documentElement.scrollWidth > document.documentElement.clientWidth + 2,
    viewport: { w: window.innerWidth, h: window.innerHeight }
  };
}

