() => {
  const meta = document.querySelector('meta[name="description"]')?.content || '';
  const canonical = document.querySelector('link[rel="canonical"]')?.href || '';
  const h1 = [...document.querySelectorAll('h1')].map(e => e.innerText.trim());
  const scripts = [...document.querySelectorAll('script[type="application/ld+json"]')].map(s => {
    try { return JSON.parse(s.textContent || ''); } catch { return null; }
  }).filter(Boolean);
  const types = scripts.flatMap(s => Array.isArray(s) ? s.map(x => x['@type']) : [s['@type']]);
  const faq = scripts.find(s => s['@type'] === 'FAQPage' || (Array.isArray(s['@graph']) && s['@graph'].some(g => g['@type'] === 'FAQPage')));
  const service = scripts.find(s => s['@type'] === 'Service' || (Array.isArray(s['@graph']) && s['@graph'].some(g => g['@type'] === 'Service')));
  const body = document.body.innerText;
  const hrefs = [...document.querySelectorAll('a[href]')].map(a => a.getAttribute('href'));
  const needed = ['/free-audit-2/', '/amazon-visual-creativity/', '/amazon-dsp-management/', '/amazon-ppc-management-agency/', '/case-study-4/', '/case-study-9/'];
  const poLeak = /(pattern\s*objects|hard\s*chrome|ink\/?lime|\bPO\b)/i.test(body);
  const fakeClaims = /(AMC|min(?:imum)?\s*spend|\d+%\s*CTR|video\s*CTR|guaranteed\s*ROAS)/i.test(body);
  return {
    title: document.title,
    meta: meta.slice(0, 220),
    canonical,
    h1,
    schemaTypes: types,
    hasService: !!service || types.includes('Service'),
    hasFAQ: !!faq || types.includes('FAQPage'),
    faqCount: (scripts.find(s => s['@type'] === 'FAQPage')?.mainEntity || []).length,
    linksPresent: Object.fromEntries(needed.map(h => [h, hrefs.includes(h)])),
    poLeak,
    fakeClaims,
    heroSubtitle: (document.querySelector('h1')?.parentElement?.innerText || '').slice(0, 280),
    sections: [...document.querySelectorAll('h2')].map(e => e.innerText.trim()).slice(0, 12)
  };
}

() => {
  const scripts = [...document.querySelectorAll('script[type="application/ld+json"]')].map(s => JSON.parse(s.textContent || '{}'));
  const flatten = (n, acc=[]) => {
    if (!n) return acc;
    if (Array.isArray(n)) { n.forEach(x => flatten(x, acc)); return acc; }
    acc.push({ type: n['@type'], keys: Object.keys(n) });
    if (n['@graph']) flatten(n['@graph'], acc);
    if (n.mainEntity) {
      const me = n.mainEntity;
      acc.push({ type: 'mainEntityCount', count: Array.isArray(me) ? me.length : 1 });
    }
    if (n.areaServed) acc.push({ type: 'areaServedCount', count: Array.isArray(n.areaServed) ? n.areaServed.length : 1 });
    return acc;
  };
  return scripts.map(s => flatten(s));
}

() => {
  const h1 = document.querySelector('h1');
  const rect = h1?.getBoundingClientRect();
  const overflowX = document.documentElement.scrollWidth > document.documentElement.clientWidth + 1;
  const ctas = [...document.querySelectorAll('a')].filter(a => /free audit/i.test(a.innerText)).length;
  return {
    viewport: { w: window.innerWidth, h: window.innerHeight },
    h1Visible: !!h1 && (rect?.width || 0) > 0,
    h1Text: h1?.innerText.trim(),
    overflowX,
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
    freeAuditCtas: ctas
  };
}

() => {
  const body = document.body.innerText;
  const hardChrome = document.querySelectorAll('[class*="chrome"], [data-surface="hard-chrome"], .hard-chrome').length;
  const classHints = [...document.querySelectorAll('[class]')].slice(0, 200).map(e => e.className).join(' ');
  const hasInk = /bg-ink|text-ink|--ink|ink-/.test(classHints);
  const hasLime = /lime|accent/.test(classHints);
  const markets = /United States[\s\S]{0,80}Canada[\s\S]{0,80}Mexico/.test(body);
  const singapore = /Singapore/.test(body);
  const videoCtr = /video\s*CTR|\d+%\s*CTR/i.test(body);
  return { hardChrome, hasInk, hasLime, markets, singapore, videoCtr, classSample: classHints.slice(0, 400) };
}

() => {
  const data = JSON.parse(document.querySelector('script[type="application/ld+json"]').textContent || '{}');
  const faq = (data['@graph'] || []).find(n => n['@type'] === 'FAQPage');
  const qs = (faq?.mainEntity || []).map(e => e.name);
  const marketsA = (faq?.mainEntity || []).find(e => /marketplace/i.test(e.name))?.acceptedAnswer?.text || '';
  const service = (data['@graph'] || []).find(n => n['@type'] === 'Service');
  return {
    faqQuestions: qs,
    marketsAnswerHasUS: /United States/.test(marketsA),
    marketsAnswerHasSingapore: /Singapore/.test(marketsA),
    areaServed: Array.isArray(service?.areaServed) ? service.areaServed.length : 0,
    panels: document.querySelectorAll('section').length,
    borderClasses: [...document.querySelectorAll('section, article, div')].filter(e => /border|ring|chrome|ink/.test(e.className)).length
  };
}

