() => {
  const meta = document.querySelector('meta[name="description"]')?.content || '';
  const canonical = document.querySelector('link[rel="canonical"]')?.href || '';
  const h1 = [...document.querySelectorAll('h1')].map(e => e.innerText.trim());
  const data = JSON.parse(document.querySelector('script[type="application/ld+json"]')?.textContent || '{}');
  const graph = data['@graph'] || [];
  const service = graph.find(n => n['@type'] === 'Service');
  const faq = graph.find(n => n['@type'] === 'FAQPage');
  const lawA = (faq?.mainEntity || []).find(e => /legal or tax/i.test(e.name))?.acceptedAnswer?.text || '';
  const marketsA = (faq?.mainEntity || []).find(e => /marketplace/i.test(e.name))?.acceptedAnswer?.text || '';
  const hrefs = [...document.querySelectorAll('a[href]')].map(a => a.getAttribute('href'));
  const needed = ['/free-audit-2/', '/amazon-trademark-brand-registry/', '/full-service-amazon-agency/', '/amazon-product-sourcing/', '/case-study-1/', '/case-study-9/'];
  const body = document.body.innerText;
  const classHints = [...document.querySelectorAll('[class]')].slice(0, 120).map(e => e.className).join(' ');
  return {
    title: document.title,
    meta,
    canonical,
    h1,
    hasService: !!service,
    hasFAQ: !!faq,
    faqCount: (faq?.mainEntity || []).length,
    areaServed: Array.isArray(service?.areaServed) ? service.areaServed.length : 0,
    notLegalTax: /^No\./i.test(lawA) || /do not provide legal|No\. We provide process/i.test(lawA),
    marketsUS: /United States/.test(marketsA),
    marketsSingapore: /Singapore/.test(marketsA),
    usEntityNote: /US-entity focused/i.test(marketsA),
    linksPresent: Object.fromEntries(needed.map(h => [h, hrefs.includes(h)])),
    poLeak: /(pattern\s*objects|hard\s*chrome|ink\/?lime|\bPO\b)/i.test(body),
    fakeClaims: /(100% legally compliant|PAN|TAN|first attempt|3-5%|150\+ countries|Wyoming is the most)/i.test(body),
    sections: [...document.querySelectorAll('h2')].map(e => e.innerText.trim()).slice(0, 12),
    hasInk: /bg-ink|text-ink|--ink|ink-/.test(classHints),
    hasLime: /lime|accent/.test(classHints)
  };
}

() => {
  const body = document.body.innerText;
  const patterns = ['100% legally compliant', 'PAN', 'TAN', 'first attempt', '3-5%', '150+ countries', 'Wyoming is the most'];
  return patterns.map(p => {
    const re = new RegExp(p.replace(/[+]/g, '\\$&'), 'i');
    const m = body.match(re);
    const idx = m ? body.indexOf(m[0]) : -1;
    return { p, found: !!m, snippet: idx >= 0 ? body.slice(Math.max(0, idx - 40), idx + 40) : null };
  });
}

() => {
  const body = document.body.innerText;
  return {
    indiaPanTan: /\bPAN\b|\bTAN\b|private limited company|LLP/i.test(body),
    hundredCompliant: /100%\s*legally\s*compliant/i.test(body),
    firstAttempt: /first attempt/i.test(body),
    conversionFee: /3-5%/i.test(body),
    wyomingClaim: /Wyoming is the most/i.test(body),
    countriesClaim: /150\+ countries/i.test(body)
  };
}

() => {
  const h1 = document.querySelector('h1');
  const rect = h1?.getBoundingClientRect();
  return {
    viewport: { w: window.innerWidth, h: window.innerHeight },
    h1Visible: !!h1 && (rect?.width || 0) > 0,
    h1Text: h1?.innerText.trim(),
    overflowX: document.documentElement.scrollWidth > document.documentElement.clientWidth + 1
  };
}

