  const slug = j.slug;
  const required = ['hero','stats','problem','audience','solution','deliverables','differ','results','faq','relatedServices','cta','seo'];
  for (const k of required) {
    if (j[k] == null) missingSections.push({slug, missing: k});
  }
  if (!j.faq || j.faq.length < 8) issues.push({slug, type: 'faq-count', detail: j.faq?.length});
  if (!j.audience) issues.push({slug, type: 'no-audience'});
  if (!j.differ) issues.push({slug, type: 'no-differ'});
  const links = [];
  for (const r of j.relatedServices || []) links.push({kind:'related', href:r.href, title:r.title});
  if (j.cta?.button?.href) links.push({kind:'cta', href:j.cta.button.href});
  if (j.hero?.cta?.href) links.push({kind:'hero-cta', href:j.hero.cta.href});
  for (const r of j.results?.items || []) if (r.href) links.push({kind:'result', href:r.href, brand:r.brand});
  graph[slug] = links.map(l => l.href);
  for (const l of links) {
    const href = l.href;
    if (!href.startsWith('/')) { issues.push({slug, type:'external-or-bad', href}); continue; }
    if (knownOk.has(href)) continue;
    const m = href.match(/^\/([a-z0-9-]+)\/$/);
    if (!m) { issues.push({slug, type:'malformed', href}); continue; }
    if (!slugs.has(m[1]) && !m[1].startsWith('case-study')) {
      issues.push({slug, type:'missing-target', href});
    } else if (m[1].startsWith('case-study') && !knownOk.has(href)) {
      // check case study exists later
      issues.push({slug, type:'case-check', href});
    }
  }
}
// inbound: which services are never linked from relatedServices?
const inbound = Object.fromEntries([...slugs].map(s => [s, 0]));
for (const [from, hrefs] of Object.entries(graph)) {
  for (const href of hrefs) {
    const m = href.match(/^\/([a-z0-9-]+)\/$/);
    if (m && inbound[m[1]] != null) inbound[m[1]]++;
  }
}
const noInboundRelated = [...slugs].filter(s => {
  // count only related inbound from other services' relatedServices
  let n = 0;
  for (const [from, hrefs] of Object.entries(graph)) {
    if (from === s) continue;
    // re-read related only - approximate: if any service links to it in graph and it's a service slug
  }
  return false;
});
// better inbound related-only
const relatedInbound = Object.fromEntries([...slugs].map(s => [s, []]));
for (const file of files) {
  const j = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
  for (const r of j.relatedServices || []) {
    const m = (r.href||'').match(/^\/([a-z0-9-]+)\/$/);
    if (m && relatedInbound[m[1]]) relatedInbound[m[1]].push(j.slug);
  }
}
const orphans = [...slugs].filter(s => relatedInbound[s].length === 0);
console.log(JSON.stringify({
  serviceCount: files.length,
  missingSections,
  issues,
  orphansRelatedInbound: orphans,
  relatedInbound,
  sampleGraph: Object.fromEntries(Object.entries(graph).slice(0,3))
}, null, 2));
EOF

