arguments.function:
() => {
  const hero = document.querySelector('#service-hero');
  const h1 = document.querySelector('#service-hero-heading');
  const crumb = document.querySelector('[aria-label="Breadcrumb"]');
  const heroRect = hero?.getBoundingClientRect();
  const crumbRect = crumb?.getBoundingClientRect();
  const h1Style = h1 ? getComputedStyle(h1) : null;
  return {
    heroHeight: heroRect ? Math.round(heroRect.height) : null,
    h1FontSize: h1Style?.fontSize,
    crumbAfterForm: crumbRect && heroRect ? crumbRect.top > (document.querySelector('#service-lead-form')?.getBoundingClientRect().bottom ?? 0) - 2 : null,
    crumbText: crumb?.textContent?.replace(/\s+/g,' ').trim(),
  };
}

