import { SectionHeading } from "@/components/sections/section-heading";
import { SectionShell } from "@/components/sections/section-shell";

interface ServiceModuleShellProps {
  id: string;
  heading?: string;
  subheading?: string;
  tone?: "default" | "muted";
  children: React.ReactNode;
}

export function ServiceModuleShell({
  id,
  heading,
  subheading,
  tone = "default",
  children,
}: ServiceModuleShellProps) {
  const headingId = heading ? `${id}-heading` : undefined;

  return (
    <SectionShell id={id} tone={tone} ariaLabelledBy={headingId}>
      {heading ? (
        <SectionHeading
          heading={heading}
          subheading={subheading}
          headingId={headingId}
        />
      ) : null}
      <div className={heading ? "mt-8" : undefined}>{children}</div>
    </SectionShell>
  );
}

import Image from "next/image";
import type { ServicePageConfig } from "@/domain/content/schemas";
import { cn } from "@/lib/utils";
import { ServiceModuleShell } from "./service-module-shell";

type ServiceModule = NonNullable<ServicePageConfig["modules"]>[number];

const hardPanel =
  "rounded-[16px] border-2 border-primary bg-background p-5 text-primary shadow-[4px_4px_0_0_#131311] sm:p-6";

interface ServiceModulesProps {
  modules: ServiceModule[];
}

export function ServiceModules({ modules }: ServiceModulesProps) {
  return (
    <>
      {modules.map((module, index) => {
        const tone = index % 2 === 0 ? "muted" : "default";

        switch (module.type) {
          case "browserProof":
            return (
              <ServiceModuleShell
                key={module.id}
                id={module.id}
                heading={module.heading}
                subheading={module.subheading}
                tone={tone}
              >
                <ul
                  className={cn(
                    "grid gap-4",
                    module.images.length > 1
                      ? "md:grid-cols-2"
                      : "md:grid-cols-1",
                  )}
                >
                  {module.images.map((image) => (
                    <li key={image.src} className={hardPanel}>
                      <div className="overflow-hidden rounded-[10px] border-2 border-primary bg-[#F2F2F2] shadow-[3px_3px_0_0_#131311]">
                        <div className="flex items-center gap-1.5 border-b-2 border-primary bg-primary px-3 py-2">
                          <span
                            aria-hidden="true"
                            className="h-2.5 w-2.5 rounded-full bg-accent"
                          />
                          <span
                            aria-hidden="true"
                            className="h-2.5 w-2.5 rounded-full bg-text-on-dark/40"
                          />
                          <span
                            aria-hidden="true"
                            className="h-2.5 w-2.5 rounded-full bg-text-on-dark/25"
                          />
                          <span className="ml-2 text-[11px] font-medium text-text-on-dark/80">
                            Seller Central / Ads proof
                          </span>
                        </div>
                        <Image
                          src={image.src}
                          alt={image.alt}
                          width={960}
                          height={600}
                          className="h-auto w-full object-cover"
                          sizes="(max-width: 768px) 100vw, 50vw"
                        />
                      </div>
                      {image.caption ? (
                        <p className="mt-3 text-small text-text-secondary">
                          {image.caption}
                        </p>
                      ) : null}
                    </li>
                  ))}
                </ul>
              </ServiceModuleShell>
            );

          case "comparisonTable":
            return (
              <ServiceModuleShell
                key={module.id}
                id={module.id}
                heading={module.heading}
                subheading={module.subheading}
                tone={tone}
              >
                <div className={cn(hardPanel, "overflow-x-auto")}>
                  <table className="w-full min-w-[520px] border-collapse text-left">
                    <thead>
                      <tr className="border-b-2 border-primary">
                        <th className="py-3 pr-4 text-small font-bold text-primary">
                          Factor
                        </th>
                        {module.columns.map((column) => (
                          <th
                            key={column}
                            className="py-3 pr-4 text-small font-bold text-primary last:pr-0"
                          >
                            {column}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {module.rows.map((row) => (
                        <tr
                          key={row.label}
                          className="border-b border-primary/15 last:border-b-0"
                        >
                          <th
                            scope="row"
                            className="py-3 pr-4 text-small font-semibold text-primary"
                          >
                            {row.label}
                          </th>
                          {row.values.map((value, valueIndex) => (
                            <td
                              key={`${row.label}-${valueIndex}`}
                              className="py-3 pr-4 text-small text-text-secondary last:pr-0"
                            >
                              {value}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </ServiceModuleShell>
            );

          case "processSteps":
            return (
              <ServiceModuleShell
                key={module.id}
                id={module.id}
                heading={module.heading}
                subheading={module.subheading}
                tone={tone}
              >
                <ol className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
                  {module.steps.map((step, stepIndex) => (
                    <li key={step.title} className={hardPanel}>
                      <span
                        aria-hidden="true"
                        className="inline-flex h-9 w-9 items-center justify-center rounded-[10px] border-2 border-primary bg-accent text-small font-bold shadow-[3px_3px_0_0_#131311]"
                      >
                        {stepIndex + 1}
                      </span>
                      <h3 className="mt-3 text-h4 text-primary">{step.title}</h3>
                      <p className="mt-2 text-body text-text-secondary">
                        {step.description}
                      </p>
                    </li>
                  ))}
                </ol>
              </ServiceModuleShell>
            );

          case "metricChart":
            return (
              <ServiceModuleShell
                key={module.id}
                id={module.id}
                heading={module.heading}
                subheading={module.subheading}
                tone={tone}
              >
                <div className={hardPanel}>
                  <p className="text-small font-semibold text-primary">
                    {module.chartLabel}
                  </p>
                  <ul className="mt-5 space-y-3">
                    {module.points.map((point) => {
                      const max = Math.max(
                        ...module.points.map((entry) => entry.value),
                        1,
                      );
                      const width = Math.max(8, Math.round((point.value / max) * 100));
                      return (
                        <li key={point.label}>
                          <div className="mb-1 flex items-baseline justify-between gap-3">
                            <span className="text-small text-text-secondary">
                              {point.label}
                            </span>
                            <span className="text-small font-bold text-primary">
                              {point.value}
                            </span>
                          </div>
                          <div className="h-3 overflow-hidden rounded-[4px] border-2 border-primary bg-surface-muted">
                            <div
                              className="h-full bg-accent"
                              style={{ width: `${width}%` }}
                            />
                          </div>
                        </li>
                      );
                    })}
                  </ul>
                  <p className="mt-4 text-xs text-text-secondary">
                    {module.footnote}
                  </p>
                </div>
              </ServiceModuleShell>
            );

          case "proofGallery":
            return (
              <ServiceModuleShell
                key={module.id}
                id={module.id}
                heading={module.heading}
                subheading={module.subheading}
                tone={tone}
              >
                <ul className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                  {module.items.map((item) => (
                    <li key={item.src} className={hardPanel}>
                      <div className="overflow-hidden rounded-[10px] border-2 border-primary shadow-[3px_3px_0_0_#131311]">
                        <Image
                          src={item.src}
                          alt={item.alt}
                          width={640}
                          height={480}
                          className="h-auto w-full object-cover"
                          sizes="(max-width: 1024px) 50vw, 33vw"
                        />
                      </div>
                      {item.caption ? (
                        <p className="mt-3 text-small text-text-secondary">
                          {item.caption}
                        </p>
                      ) : null}
                    </li>
                  ))}
                </ul>
              </ServiceModuleShell>
            );

          case "checklistMatrix":
            return (
              <ServiceModuleShell
                key={module.id}
                id={module.id}
                heading={module.heading}
                subheading={module.subheading}
                tone={tone}
              >
                <ul className="grid gap-4 md:grid-cols-2">
                  {module.groups.map((group) => (
                    <li key={group.title} className={hardPanel}>
                      <h3 className="text-h4 text-primary">{group.title}</h3>
                      <ul className="mt-3 space-y-2">
                        {group.items.map((item) => (
                          <li
                            key={item}
                            className="flex gap-2 text-body text-text-secondary"
                          >
                            <span
                              aria-hidden="true"
                              className="mt-1.5 h-2.5 w-2.5 shrink-0 rounded-[2px] border-2 border-primary bg-accent"
                            />
                            <span>{item}</span>
                          </li>
                        ))}
                      </ul>
                    </li>
                  ))}
                </ul>
              </ServiceModuleShell>
            );

          default:
            return null;
        }
      })}
    </>
  );
}

