async (page) => {
  const responses = [];
  page.on('response', r => {
    if (r.url().includes('creative') || r.url().includes('images')) {
      responses.push({ url: r.url().slice(0, 160), status: r.status() });
    }
  });
  await page.goto('http://localhost:3000/tiktok-shop-ads/', { waitUntil: 'networkidle' });
  await page.locator('#service-gallery').scrollIntoViewIfNeeded();
  await page.waitForTimeout(2000);
  const direct = await page.evaluate(async () => {
    const urls = [
      '/images/creative/creative-hero-product-v2.png',
      '/_next/image/?url=%2Fimages%2Fcreative%2Fcreative-hero-product-v2.png&w=640&q=75'
    ];
    const out = [];
    for (const u of urls) {
      try {
        const res = await fetch(u);
        out.push({ u, status: res.status, type: res.headers.get('content-type'), len: res.headers.get('content-length') });
      } catch (e) {
        out.push({ u, error: String(e) });
      }
    }
    const imgs = [...document.querySelectorAll('#service-gallery img')].map(i => ({
      src: i.currentSrc || i.src,
      nw: i.naturalWidth,
      complete: i.complete,
      err: i.getAttribute('data-error')
    }));
    return { out, imgs };
  });
  return { responses: responses.slice(0, 20), direct };
}

