() => {
  const body = document.body.innerText;
  const patterns = [/\$30/gi, /\$50/gi, /\$400M/gi, /500 brands/gi, /Master Elite/gi, /\$30.?\$?50/gi];
  return patterns.map(p => {
    const m = body.match(p);
    if (!m) return { p: p.toString(), matches: [] };
    const idx = body.search(p);
    return { p: p.toString(), matches: m.slice(0,5), context: body.slice(Math.max(0, idx-40), idx+60) };
  });
}

