import Link from "next/link";
import type { ServicesIndexConfig } from "@/domain/content/schemas";
import { Button } from "@/components/ui/button";
import { SectionShell } from "@/components/sections/section-shell";

interface ServicesIndexHeroProps {
  hero: ServicesIndexConfig["hero"];
}

export function ServicesIndexHero({ hero }: ServicesIndexHeroProps) {
  return (
    <SectionShell
      id="services-hero"
      ariaLabelledBy="services-hero-heading"
      className="py-14 sm:py-16 lg:py-20"
    >
      <div className="max-w-3xl">
        <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs">
          eCom Gliders services
        </p>
        <h1 id="services-hero-heading" className="mt-3 text-h1 text-primary">
          {hero.title}
        </h1>
        <p className="mt-4 max-w-2xl text-body text-text-secondary">
          {hero.subtitle}
        </p>
        <div className="mt-8 flex flex-wrap items-center gap-4">
          <Button variant="primary" asChild>
            <Link href={hero.primaryCta.href}>{hero.primaryCta.label}</Link>
          </Button>
          {hero.secondaryCta ? (
            <Button variant="secondary" asChild>
              <Link href={hero.secondaryCta.href}>{hero.secondaryCta.label}</Link>
            </Button>
          ) : null}
        </div>
      </div>
    </SectionShell>
  );
}

import type { ServicesIndexCategory } from "@/domain/content/schemas";
import { SectionShell } from "@/components/sections/section-shell";

interface ServicesIndexNavProps {
  categories: ServicesIndexCategory[];
}

export function ServicesIndexNav({ categories }: ServicesIndexNavProps) {
  return (
    <SectionShell
      id="services-capability-nav"
      ariaLabelledBy="services-capability-nav-heading"
      tone="muted"
      className="py-8 sm:py-10"
    >
      <p
        id="services-capability-nav-heading"
        className="text-[11px] font-bold uppercase tracking-[0.16em] text-text-secondary sm:text-xs"
      >
        Browse by capability
      </p>
      <nav aria-label="Service capability groups" className="mt-4">
        <ul className="flex flex-wrap gap-3">
          {categories.map((category) => (
            <li key={category.id}>
              <a
                href={`#${category.id}`}
                className="inline-flex rounded-[10px] border-2 border-primary bg-background px-4 py-2 text-small font-semibold text-primary shadow-[3px_3px_0_0_#131311] transition-colors hover:bg-accent"
              >
                {category.title}
              </a>
            </li>
          ))}
        </ul>
      </nav>
    </SectionShell>
  );
}

