import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import type { ServicesIndexCategory } from "@/domain/content/schemas";
import { SectionIcon } from "@/components/sections/section-icon";
import { SectionShell } from "@/components/sections/section-shell";
import { cn } from "@/lib/utils";

interface ServicesIndexCategoriesProps {
  categories: ServicesIndexCategory[];
}

const hardPanel =
  "rounded-[16px] border-2 border-primary bg-background p-5 text-primary shadow-[4px_4px_0_0_#131311] transition-colors hover:bg-accent/20 sm:p-6";

export function ServicesIndexCategories({
  categories,
}: ServicesIndexCategoriesProps) {
  return (
    <>
      {categories.map((category, index) => (
        <SectionShell
          key={category.id}
          id={category.id}
          ariaLabelledBy={`${category.id}-heading`}
          tone={index % 2 === 0 ? "muted" : "default"}
          className="py-12 sm:py-16"
        >
          <div className="max-w-2xl">
            <h2 id={`${category.id}-heading`} className="text-h2 text-primary">
              {category.title}
            </h2>
            <p className="mt-3 text-body text-text-secondary">
              {category.description}
            </p>
          </div>
          <ul className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
            {category.services.map((service) => (
              <li key={service.id} id={service.id}>
                <Link href={service.href} className={cn(hardPanel, "block h-full")}>
                  <div className="flex items-start justify-between gap-3">
                    <SectionIcon
                      name={service.icon ?? "briefcase"}
                      framed
                      tone="primary"
                    />
                    <ArrowUpRight
                      aria-hidden="true"
                      className="h-5 w-5 shrink-0 text-primary"
                    />
                  </div>
                  <h3 className="mt-4 text-h4 text-primary">{service.title}</h3>
                  <p className="mt-2 text-body text-text-secondary">
                    {service.description}
                  </p>
                  {service.featured ? (
                    <p className="mt-4 text-[11px] font-bold uppercase tracking-[0.14em] text-text-secondary">
                      Flagship
                    </p>
                  ) : null}
                </Link>
              </li>
            ))}
          </ul>
        </SectionShell>
      ))}
    </>
  );
}

import type { ServicesIndexConfig } from "@/domain/content/schemas";
import { SectionHeading } from "@/components/sections/section-heading";
import { SectionShell } from "@/components/sections/section-shell";

interface ServicesIndexStackProps {
  stack: ServicesIndexConfig["stack"];
}

const hardPanel =
  "rounded-[16px] border-2 border-primary bg-background p-5 text-primary shadow-[4px_4px_0_0_#131311] sm:p-6";

export function ServicesIndexStack({ stack }: ServicesIndexStackProps) {
  return (
    <SectionShell
      id="services-stack"
      ariaLabelledBy="services-stack-heading"
      tone="muted"
      className="py-12 sm:py-16"
    >
      <SectionHeading
        heading={stack.heading}
        subheading={stack.subheading}
        headingId="services-stack-heading"
      />
      <ol className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        {stack.steps.map((step, index) => (
          <li key={step.title} className={hardPanel}>
            <span
              aria-hidden="true"
              className="inline-flex h-9 w-9 items-center justify-center rounded-[10px] border-2 border-primary bg-accent text-small font-bold shadow-[3px_3px_0_0_#131311]"
            >
              {index + 1}
            </span>
            <h3 className="mt-3 text-h4 text-primary">{step.title}</h3>
            <p className="mt-2 text-body text-text-secondary">{step.description}</p>
          </li>
        ))}
      </ol>
    </SectionShell>
  );
}

