import type { ServicesIndexConfig, SiteConfig } from "@/domain/content/schemas";
import { absoluteUrl, getSiteUrl } from "./site-url";

interface BuildServicesIndexJsonLdInput {
  index: ServicesIndexConfig;
  site: SiteConfig;
}

export function buildServicesIndexJsonLd({
  index,
  site,
}: BuildServicesIndexJsonLdInput): Record<string, unknown> {
  const pageUrl = absoluteUrl(index.seo.canonical);
  const services = index.categories.flatMap((category) => category.services);

  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "CollectionPage",
        name: index.hero.title,
        description: index.seo.metaDescription,
        url: pageUrl,
        isPartOf: {
          "@type": "WebSite",
          name: site.name,
          url: getSiteUrl(),
        },
        mainEntity: {
          "@type": "ItemList",
          itemListElement: services.map((service, position) => ({
            "@type": "ListItem",
            position: position + 1,
            name: service.title,
            url: absoluteUrl(service.href),
          })),
        },
      },
      {
        "@type": "FAQPage",
        mainEntity: index.faq.map((item) => ({
          "@type": "Question",
          name: item.question,
          acceptedAnswer: {
            "@type": "Answer",
            text: item.answer,
          },
        })),
      },
    ],
  };
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { ServicesIndexTemplate } from "@/components/services/services-index-template";
import { getContentRepository } from "@/infrastructure/content/get-content-repository";
import { JsonLdScript } from "@/lib/seo/json-ld-script";
import { pageSeoToMetadata } from "@/lib/seo/page-metadata";
import { buildServicesIndexJsonLd } from "@/lib/seo/services-index-json-ld";

export async function generateMetadata(): Promise<Metadata> {
  const repository = getContentRepository();
  const index = await repository.getServicesIndex();

  if (!index) {
    return {
      title: "Amazon Growth Services | eCom Gliders",
    };
  }

  return pageSeoToMetadata(index.seo);
}

export default async function ServicesIndexPage() {
  const repository = getContentRepository();
  const [index, site] = await Promise.all([
    repository.getServicesIndex(),
    repository.getSiteConfig(),
  ]);

  if (!index) {
    notFound();
  }

  const jsonLd = buildServicesIndexJsonLd({ index, site });

  return (
    <>
      <JsonLdScript data={jsonLd} />
      <main id="main-content">
        <ServicesIndexTemplate index={index} site={site} />
      </main>
    </>
  );
}

