() => {
  const body = document.body.innerText;
  const hrefs = [...document.querySelectorAll('main a[href]')].map(a => a.getAttribute('href'));
  const expected = [
    '/full-service-amazon-agency/','/amazon-ppc-management-agency/','/amazon-dsp-management/','/amazon-reporting-analytics/',
    '/amazon-listing-optimization/','/amazon-content-writing/','/amazon-visual-creativity/','/amazon-video-creative/','/amazon-catalog-management/',
