    '/shopify-website-development/','/tiktok-shop-ads/','/email-retention-marketing/'
  ];
  const missing = expected.filter(h => !hrefs.includes(h));
  const schemas = [...document.querySelectorAll('script[type="application/ld+json"]')].flatMap(s => {
    try { const j = JSON.parse(s.textContent||''); return j['@graph'] ? j['@graph'].map(x=>x['@type']) : [j['@type']]; } catch { return ['parse-error']; }
  });
  const cats = ['advertising-growth','catalog-content','brand-operations','channels-dtc'].map(id => ({id, present: !!document.getElementById(id)}));
  return {
    title: document.title,
    h1: document.querySelector('#services-hero-heading')?.textContent?.trim(),
    canonical: document.querySelector('link[rel=canonical]')?.href,
    schemas,
    cats,
    missing,
    linkCount: expected.length - missing.length,
    formOrCta: hrefs.includes('/free-audit-2/'),
    faqPresent: !!document.getElementById('services-faq'),
    poLeak: /project one|framer|soft card/i.test(body),
    invented: /\$400M|500 brands|Master Elite|27% CVR/i.test(body),
    overflowX: document.documentElement.scrollWidth > window.innerWidth,
  };
}

