async (page) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.locator('#channels-dtc').scrollIntoViewIfNeeded();
  const mobile = await page.evaluate(() => ({
    overflowX: document.documentElement.scrollWidth > window.innerWidth,
    channelsVisible: (() => {
      const el = document.getElementById('channels-dtc');
      if (!el) return false;
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    })(),
  }));
  // Check mega footer link via navigation config rendered in page footer
  await page.goto('http://localhost:3001/');
  await page.waitForLoadState('domcontentloaded');
  const home = await page.evaluate(() => {
    const viewAll = [...document.querySelectorAll('a')].find(a => /view all services/i.test(a.textContent||''));
    const footerAll = [...document.querySelectorAll('footer a, [class*=footer] a')].find(a => /^all services$/i.test((a.textContent||'').trim()));
    return {
      homeViewAllHref: viewAll?.getAttribute('href') || null,
      footerAllHref: footerAll?.getAttribute('href') || null,
    };
  });
  // sitemap
  const sitemapRes = await page.request.get('http://localhost:3001/sitemap.xml');
  const sitemapText = await sitemapRes.text();
  await page.setViewportSize({ width: 1440, height: 900 });
  return {
    mobile,
    home,
    sitemapHasServices: sitemapText.includes('https://ecomgliders.com/services/') || sitemapText.includes('/services/'),
    sitemapStatus: sitemapRes.status(),
  };
}

async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3001/');
  const servicesTrigger = page.getByRole('button', { name: /services/i }).or(page.getByRole('link', { name: /^services$/i })).first();
  await servicesTrigger.hover().catch(() => {});
  await page.waitForTimeout(500);
  // try click if hover didn't open
  const viewAll = page.getByRole('link', { name: /view all services/i });
  const count = await viewAll.count();
  let href = null;
  if (count > 0) {
    href = await viewAll.first().getAttribute('href');
  } else {
    // force open via keyboard/focus
    await servicesTrigger.focus();
    await page.keyboard.press('Enter');
    await page.waitForTimeout(400);
    href = await page.getByRole('link', { name: /view all services/i }).first().getAttribute('href').catch(() => null);
  }
  return { count, href };
}

