import Image from "next/image";
import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import type { ServicesIndexCategory } from "@/domain/content/schemas";
import { SectionShell } from "@/components/sections/section-shell";
import { cn } from "@/lib/utils";

interface ServicesIndexCategoriesProps {
  categories: ServicesIndexCategory[];
}

export function ServicesIndexCategories({
  categories,
}: ServicesIndexCategoriesProps) {
  return (
    <>
      {categories.map((category, index) => (
        <SectionShell
          key={category.id}
          id={category.id}
          ariaLabelledBy={`${category.id}-heading`}
          tone={index % 2 === 0 ? "muted" : "default"}
          className="py-12 sm:py-16"
        >
          <div className="max-w-2xl">
            <h2 id={`${category.id}-heading`} className="text-h2 text-primary">
              {category.title}
            </h2>
            <p className="mt-3 text-body text-text-secondary">
              {category.description}
            </p>
          </div>
          <ul className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
            {category.services.map((service) => {
              const punch = Boolean(service.featured);
              return (
                <li key={service.id} id={service.id} className="flex min-h-0">
                  <Link
                    href={service.href}
                    className="flex h-full w-full rounded-[10px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                  >
                    <article
                      className={cn(
                        "group flex h-full w-full flex-col overflow-hidden rounded-[10px] border-2 border-primary",
                        "transition-[transform,box-shadow] duration-200",
                        "hover:-translate-y-0.5 hover:shadow-[6px_6px_0_0_#131311]",
                        punch
                          ? "bg-primary text-text-on-dark"
                          : "bg-background text-primary",
                      )}
                    >
                      {service.image ? (
                        <div className="relative aspect-[16/10] w-full shrink-0 overflow-hidden border-b-2 border-primary">
                          <Image
                            src={service.image}
                            alt={service.imageAlt ?? service.title}
                            fill
                            sizes="(max-width: 640px) 100vw, (max-width: 1280px) 50vw, 33vw"
                            quality={80}
                            className={cn(
                              "object-cover transition-transform duration-500 ease-out",
                              "group-hover:scale-[1.03]",
                              punch && "opacity-90",
                            )}
                            loading="lazy"
                          />
                          <div
                            className={cn(
                              "pointer-events-none absolute inset-0",
                              punch
                                ? "bg-gradient-to-t from-primary/50 to-transparent"
                                : "bg-gradient-to-t from-background/20 to-transparent",
                            )}
                            aria-hidden="true"
                          />
                        </div>
                      ) : null}

                      <div className="flex flex-1 flex-col p-5 sm:p-6">
                        <div className="flex items-start justify-between gap-3">
                          <h3 className="text-lg font-bold leading-snug tracking-tight sm:text-xl">
                            {service.title}
                          </h3>
                          <ArrowUpRight
                            aria-hidden="true"
                            className={cn(
                              "mt-0.5 h-5 w-5 shrink-0",
                              punch ? "text-accent" : "text-primary",
                            )}
                          />
                        </div>
                        <p
                          className={cn(
                            "mt-3 flex-1 text-sm font-medium leading-relaxed",
                            punch ? "text-text-on-dark/75" : "text-text-secondary",
                          )}
                        >
                          {service.description}
                        </p>
                        {service.featured ? (
                          <p className="mt-4 text-[11px] font-bold uppercase tracking-[0.14em] text-accent">
                            Flagship
                          </p>
                        ) : (
                          <span
                            className={cn(
                              "mt-5 inline-flex items-center gap-2 text-[12px] font-bold uppercase tracking-[0.04em]",
                              punch ? "text-accent" : "text-primary",
                            )}
                          >
                            Learn more
                          </span>
                        )}
                      </div>
                    </article>
                  </Link>
                </li>
              );
            })}
          </ul>
        </SectionShell>
      ))}
    </>
  );
}

