"use client";

import { useEffect, useState } from "react";
import type { ServicesIndexCategory } from "@/domain/content/schemas";
import { cn } from "@/lib/utils";

interface ServicesIndexCatalogRailProps {
  categories: Pick<ServicesIndexCategory, "id" | "title">[];
}

export function ServicesIndexCatalogRail({
  categories,
}: ServicesIndexCatalogRailProps) {
  const [activeId, setActiveId] = useState(categories[0]?.id ?? "");

  useEffect(() => {
    if (categories.length === 0) return;

    const elements = categories
      .map((category) => document.getElementById(category.id))
      .filter((node): node is HTMLElement => node !== null);

    if (elements.length === 0) return;

    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((entry) => entry.isIntersecting)
          .sort(
            (a, b) =>
              (b.intersectionRatio ?? 0) - (a.intersectionRatio ?? 0),
          );

        if (visible[0]?.target?.id) {
          setActiveId(visible[0].target.id);
        }
      },
      {
        rootMargin: "-30% 0px -55% 0px",
        threshold: [0, 0.15, 0.35, 0.55],
      },
    );

    elements.forEach((element) => observer.observe(element));
    return () => observer.disconnect();
  }, [categories]);

  return (
    <div className="sticky top-[4.5rem] z-30 border-b-2 border-primary bg-background/95 backdrop-blur-sm sm:top-[5.25rem]">
      <nav
        aria-label="Service capability groups"
        className="container-page py-3"
      >
        <ul className="flex gap-1 overflow-x-auto [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          {categories.map((category) => {
            const active = category.id === activeId;
            return (
              <li key={category.id} className="shrink-0">
                <a
                  href={`#${category.id}`}
                  aria-current={active ? "true" : undefined}
                  className={cn(
                    "relative inline-flex min-h-10 items-center px-3 text-small font-semibold transition-colors",
                    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
                    active
                      ? "text-primary"
                      : "text-text-secondary hover:text-primary",
                  )}
                >
                  {category.title}
                  <span
                    aria-hidden="true"
                    className={cn(
                      "absolute inset-x-3 bottom-0 h-0.5 origin-left bg-accent transition-transform duration-200",
                      active ? "scale-x-100" : "scale-x-0",
                    )}
                  />
                </a>
              </li>
            );
          })}
        </ul>
      </nav>
    </div>
  );
}

import Image from "next/image";
import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import type { ServicesIndexCategory } from "@/domain/content/schemas";
import { SectionShell } from "@/components/sections/section-shell";
import { ServicesIndexCatalogRail } from "./services-index-catalog-rail";
import { cn } from "@/lib/utils";

interface ServicesIndexCategoriesProps {
  categories: ServicesIndexCategory[];
}

function splitFeatured(category: ServicesIndexCategory) {
  const featured =
    category.services.find((service) => service.featured) ??
    category.services[0];
  const siblings = category.services.filter(
    (service) => service.id !== featured.id,
  );
  return { featured, siblings };
}

export function ServicesIndexCategories({
  categories,
}: ServicesIndexCategoriesProps) {
  return (
    <div id="services-catalog">
      <ServicesIndexCatalogRail
        categories={categories.map(({ id, title }) => ({ id, title }))}
      />

      {categories.map((category, index) => {
        const { featured, siblings } = splitFeatured(category);

        return (
          <SectionShell
            key={category.id}
            id={category.id}
            ariaLabelledBy={`${category.id}-heading`}
            tone={index % 2 === 0 ? "muted" : "default"}
            className="py-12 sm:py-16"
          >
            <div className="max-w-2xl">
              <h2 id={`${category.id}-heading`} className="text-h2 text-primary">
                {category.title}
              </h2>
              <p className="mt-3 text-body text-text-secondary">
                {category.description}
              </p>
            </div>

            <ul className="mt-8 space-y-4">
              <li id={featured.id}>
                <Link
                  href={featured.href}
                  className="block rounded-[10px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                >
                  <article
                    className={cn(
                      "group grid overflow-hidden rounded-[10px] border-2 border-primary bg-primary text-text-on-dark",
                      "transition-[transform,box-shadow] duration-200",
                      "hover:-translate-y-0.5 hover:shadow-[6px_6px_0_0_#9FE870]",
                      "lg:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)]",
                    )}
                  >
                    {featured.image ? (
                      <div className="relative aspect-[16/10] w-full overflow-hidden border-b-2 border-primary lg:aspect-auto lg:min-h-[240px] lg:border-b-0 lg:border-r-2">
                        <Image
                          src={featured.image}
                          alt={featured.imageAlt ?? featured.title}
                          fill
                          sizes="(max-width: 1024px) 100vw, 50vw"
                          quality={80}
                          className="object-cover transition-transform duration-500 ease-out group-hover:scale-[1.03]"
                          loading={index === 0 ? "eager" : "lazy"}
                        />
                        <div
                          className="pointer-events-none absolute inset-0 bg-gradient-to-t from-primary/55 to-transparent lg:bg-gradient-to-r"
                          aria-hidden="true"
                        />
                      </div>
                    ) : null}
                    <div className="flex flex-col justify-center p-5 sm:p-7 lg:p-8">
                      {featured.featured ? (
                        <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-accent">
                          Flagship
                        </p>
                      ) : null}
                      <div className="mt-2 flex items-start justify-between gap-3">
                        <h3 className="text-xl font-bold leading-snug tracking-tight sm:text-2xl">
                          {featured.title}
                        </h3>
                        <ArrowUpRight
                          aria-hidden="true"
                          className="mt-1 h-5 w-5 shrink-0 text-accent"
                        />
                      </div>
                      <p className="mt-3 text-sm font-medium leading-relaxed text-text-on-dark/75 sm:text-base">
                        {featured.description}
                      </p>
                      <span className="mt-5 inline-flex items-center gap-2 text-[12px] font-bold uppercase tracking-[0.04em] text-accent">
                        Explore
                      </span>
                    </div>
                  </article>
                </Link>
              </li>

              {siblings.map((service) => (
                <li key={service.id} id={service.id}>
                  <Link
                    href={service.href}
                    className="block rounded-[10px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                  >
                    <article
                      className={cn(
                        "group flex items-start justify-between gap-4 rounded-[10px] border-2 border-primary bg-background px-4 py-4 sm:px-5 sm:py-5",
                        "transition-[transform,box-shadow] duration-200",
                        "hover:-translate-y-0.5 hover:shadow-[4px_4px_0_0_#131311]",
                      )}
                    >
                      <div className="min-w-0 flex-1">
                        <h3 className="text-base font-bold leading-snug tracking-tight text-primary sm:text-lg">
                          {service.title}
                        </h3>
                        <p className="mt-1.5 text-sm font-medium leading-relaxed text-text-secondary">
