async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3000/services/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(800);
  const data = await page.evaluate(() => {
    const header = document.querySelector('header');
    const hero = document.querySelector('#services-hero');
    const hr = header.getBoundingClientRect();
    const he = hero.getBoundingClientRect();
    // sample pixel between header top and pill - should be ink not white
    const x = Math.floor(window.innerWidth / 2);
    const y = Math.floor(hr.top + 8);
    const el = document.elementFromPoint(x, y);
    let bg = null;
    let node = el;
    while (node && node !== document.body) {
      const c = getComputedStyle(node).backgroundColor;
      if (c && c !== 'rgba(0, 0, 0, 0)' && c !== 'transparent') { bg = c; break; }
      node = node.parentElement;
    }
    return {
      headerTop: hr.top,
      heroTop: he.top,
      heroUnderHeader: he.top <= hr.top + 1,
      sampleY: y,
      sampleBg: bg,
      sampleEl: el?.tagName + (el?.id ? '#' + el.id : '') + (el?.className ? '.' + String(el.className).slice(0,40) : ''),
    };
  });
  await page.screenshot({ path: 'docs/qa/screenshots/services-hub-nav-over-ink.png', fullPage: false });

  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('http://localhost:3000/services/', { waitUntil: 'domcontentloaded' });
