    const he = hero.getBoundingClientRect();
    return { headerTop: hr.top, heroTop: he.top, heroUnderHeader: he.top <= hr.top + 1 };
  });
  await page.screenshot({ path: 'docs/qa/screenshots/services-hub-nav-over-ink-mobile.png', fullPage: false });
  return { desktop: data, mobile };
