import Image from "next/image";
import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import type {
  ServicesIndexCategory,
  ServicesIndexServiceCard,
} from "@/domain/content/schemas";
import { SectionShell } from "@/components/sections/section-shell";
import { ServicesIndexCatalogRail } from "./services-index-catalog-rail";
import { cn } from "@/lib/utils";

interface ServicesIndexCategoriesProps {
  categories: ServicesIndexCategory[];
}

type CardRole = "flagship" | "lead" | "standard";

function cardRole(
  service: ServicesIndexServiceCard,
  index: number,
): CardRole {
  if (service.featured) return "flagship";
  if (index === 0) return "lead";
  return "standard";
}

/**
 * Desktop stagger spans on a 12-col grid.
 * Patterns locked per counsel for 3 / 4 / 5 item categories.
 */
function desktopSpanClass(count: number, index: number): string {
  if (count === 5) {
    return (
      [
        "lg:col-span-6 lg:row-span-2",
        "lg:col-span-6",
        "lg:col-span-6",
        "lg:col-span-6",
        "lg:col-span-6",
      ][index] ?? "lg:col-span-6"
    );
  }

  if (count === 4) {
    return (
      [
        "lg:col-span-7 lg:row-span-2",
        "lg:col-span-5",
        "lg:col-span-5",
        "lg:col-span-8",
      ][index] ?? "lg:col-span-6"
    );
  }

  // 3-item (and fallback): L-shape lead + stacked pair
  return (
    [
      "lg:col-span-7 lg:row-span-2",
      "lg:col-span-5",
      "lg:col-span-5",
    ][index] ?? "lg:col-span-6"
  );
}

function ServiceCard({
  service,
  role,
  spanClass,
  priority,
}: {
  service: ServicesIndexServiceCard;
  role: CardRole;
  spanClass: string;
  priority?: boolean;
}) {
  const isFlagship = role === "flagship";
  const isWideLead = role === "flagship" || role === "lead";

  return (
    <li
      id={service.id}
      className={cn("min-h-0 md:col-span-1", spanClass, {
        "md:col-span-2": isWideLead,
      })}
    >
      <Link
        href={service.href}
        className="flex h-full rounded-[10px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
      >
        <article
          className={cn(
            "group flex h-full w-full flex-col overflow-hidden rounded-[10px] border-2 border-primary",
            "transition-[transform,box-shadow] duration-200",
            "hover:-translate-y-0.5",
            isFlagship
              ? "bg-primary text-text-on-dark hover:shadow-[6px_6px_0_0_#9FE870] lg:flex-row"
              : "bg-background text-primary hover:shadow-[6px_6px_0_0_#131311]",
          )}
        >
          {service.image ? (
            <div
              className={cn(
                "relative w-full shrink-0 overflow-hidden border-b-2 border-primary",
                isFlagship
                  ? "aspect-[16/10] lg:aspect-auto lg:w-[52%] lg:border-b-0 lg:border-r-2 lg:min-h-full"
                  : isWideLead
                    ? "aspect-[16/10] lg:aspect-auto lg:min-h-[220px] lg:flex-1"
                    : "aspect-[3/2]",
              )}
            >
              <Image
                src={service.image}
                alt={service.imageAlt ?? service.title}
                fill
                sizes={
                  isWideLead
                    ? "(max-width: 768px) 100vw, (max-width: 1024px) 100vw, 50vw"
                    : "(max-width: 768px) 100vw, (max-width: 1024px) 50vw, 33vw"
                }
                quality={80}
                className="object-cover transition-transform duration-500 ease-out group-hover:scale-[1.03]"
                loading={priority ? "eager" : "lazy"}
                priority={priority}
              />
              <div
                className={cn(
                  "pointer-events-none absolute inset-0",
                  isFlagship
                    ? "bg-gradient-to-t from-primary/50 to-transparent lg:bg-gradient-to-r"
                    : "bg-gradient-to-t from-background/25 to-transparent",
                )}
                aria-hidden="true"
              />
            </div>
          ) : null}

          <div
            className={cn(
              "flex flex-1 flex-col p-4 sm:p-5",
              isFlagship && "lg:justify-center lg:p-7",
            )}
          >
            {isFlagship ? (
              <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-accent">
                Flagship
              </p>
            ) : null}
            <div
              className={cn(
                "flex items-start justify-between gap-3",
                isFlagship && "mt-2",
              )}
            >
              <h3
                className={cn(
                  "font-bold leading-snug tracking-tight",
                  isFlagship
                    ? "text-xl sm:text-2xl"
                    : "text-base sm:text-lg",
                )}
              >
                {service.title}
              </h3>
              <ArrowUpRight
                aria-hidden="true"
                className={cn(
                  "mt-0.5 h-5 w-5 shrink-0",
                  isFlagship ? "text-accent" : "text-primary",
                )}
              />
            </div>
            <p
              className={cn(
                "mt-2 flex-1 text-sm font-medium leading-relaxed",
                isFlagship ? "text-text-on-dark/75" : "text-text-secondary",
              )}
            >
              {service.description}
            </p>
            <span
              className={cn(
                "mt-4 inline-flex items-center gap-2 text-[12px] font-bold uppercase tracking-[0.04em]",
                isFlagship ? "text-accent" : "text-primary",
              )}
            >
              Explore
            </span>
          </div>
        </article>
      </Link>
    </li>
  );
}

export function ServicesIndexCategories({
  categories,
}: ServicesIndexCategoriesProps) {
  return (
    <div id="services-catalog">
      <ServicesIndexCatalogRail
        categories={categories.map(({ id, title }) => ({ id, title }))}
      />

      {categories.map((category, categoryIndex) => {
        const count = category.services.length;

        return (
          <SectionShell
            key={category.id}
            id={category.id}
            ariaLabelledBy={`${category.id}-heading`}
            tone={categoryIndex % 2 === 0 ? "muted" : "default"}
            className="py-12 sm:py-16"
          >
            <div className="max-w-2xl">
              <h2 id={`${category.id}-heading`} className="text-h2 text-primary">
                {category.title}
              </h2>
              <p className="mt-3 text-body text-text-secondary">
                {category.description}
              </p>
            </div>

            <ul
              className={cn(
                "mt-8 grid grid-cols-1 gap-4",
                "md:grid-cols-2",
                "lg:grid-cols-12 lg:auto-rows-[minmax(160px,auto)]",
              )}
            >
              {category.services.map((service, index) => (
                <ServiceCard
                  key={service.id}
                  service={service}
                  role={cardRole(service, index)}
                  spanClass={desktopSpanClass(count, index)}
                  priority={categoryIndex === 0 && index === 0}
                />
              ))}
            </ul>
          </SectionShell>
        );
      })}
    </div>
  );
}

