import Image from "next/image";
import { cn } from "@/lib/utils";

export interface BrowserProofImage {
  src: string;
  alt: string;
  caption?: string;
}

interface BrowserProofStageProps {
  images: BrowserProofImage[];
  /** Honesty line shown under the stage (module subheading). */
  disclaimer?: string;
}

function DesktopFrame({
  image,
  className,
}: {
  image: BrowserProofImage;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "overflow-hidden rounded-[10px] border-2 border-primary bg-background",
        "shadow-[6px_6px_0_0_#131311]",
        "transition-transform duration-300 ease-out motion-safe:hover:-translate-y-0.5",
        className,
      )}
    >
      <div className="flex h-9 items-center gap-1.5 border-b-2 border-primary bg-primary px-3">
        <span
          aria-hidden="true"
          className="h-2.5 w-2.5 rounded-full bg-accent"
        />
        <span
          aria-hidden="true"
          className="h-2.5 w-2.5 rounded-full bg-text-on-dark/35"
        />
        <span
          aria-hidden="true"
          className="h-2.5 w-2.5 rounded-full bg-text-on-dark/20"
        />
        <span
          aria-hidden="true"
          className="ml-2 h-px flex-1 bg-accent/40"
        />
      </div>
      <div className="relative aspect-[16/10] w-full bg-surface-muted">
        <Image
          src={image.src}
          alt={image.alt}
          fill
          className="object-cover object-top"
          sizes="(max-width: 768px) 100vw, 70vw"
          quality={85}
        />
      </div>
    </div>
  );
}

function PhoneFrame({
  image,
  className,
}: {
  image: BrowserProofImage;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "overflow-hidden rounded-[1.35rem] border-2 border-primary bg-primary",
        "shadow-[8px_8px_0_0_#9FE870]",
        "transition-transform duration-300 ease-out motion-safe:hover:-translate-y-1",
        className,
      )}
    >
      <div
        className="flex justify-center bg-primary pt-2.5 pb-1.5"
        aria-hidden="true"
      >
        <span className="h-1.5 w-16 rounded-full bg-text-on-dark/25" />
      </div>
      <div className="relative mx-1.5 mb-1.5 aspect-[9/16] overflow-hidden rounded-[0.9rem] border border-white/10 bg-background">
        <Image
          src={image.src}
          alt={image.alt}
          fill
          className="object-cover object-top"
          sizes="(max-width: 768px) 60vw, 28vw"
          quality={85}
        />
      </div>
    </div>
  );
}

/**
 * Hero Stage + Corroborating Device — desktop owns the composition;
 * optional phone overlaps as secondary proof (never equal twin cards).
 */
export function BrowserProofStage({
  images,
  disclaimer,
}: BrowserProofStageProps) {
  const desktop = images[0];
  const phone = images[1];

  if (!desktop) return null;

  const stageCaption = desktop.caption;
  const secondaryNote =
    phone?.caption && phone.caption !== stageCaption ? phone.caption : null;

  return (
    <div>
      <div
        className={cn(
          "relative overflow-hidden rounded-[16px] border-2 border-primary bg-primary",
          "shadow-[6px_6px_0_0_#131311]",
          "px-5 py-8 sm:px-8 sm:py-10 lg:px-12 lg:py-12",
        )}
      >
        <div
          className="pointer-events-none absolute inset-0 opacity-40"
          aria-hidden="true"
          style={{
            backgroundImage:
              "radial-gradient(ellipse 80% 60% at 30% 40%, rgba(159,232,112,0.12), transparent 55%), radial-gradient(circle at 1px 1px, rgba(255,255,255,0.06) 1px, transparent 0)",
            backgroundSize: "100% 100%, 22px 22px",
