"use client";

import { useEffect, useState } from "react";
import { cn } from "@/lib/utils";
import { ContainedMedia } from "./contained-media";
import {
  ImagePreviewDialog,
  useImagePreview,
  type PreviewableImage,
} from "./image-preview-dialog";

export interface BrowserProofImage {
  src: string;
  alt: string;
  caption?: string;
}

interface BrowserProofStageProps {
  images: BrowserProofImage[];
  disclaimer?: string;
}

type FrameKind = "browser" | "phone";

interface SizedImage extends BrowserProofImage {
  kind: FrameKind;
  width: number;
  height: number;
}

function classify(width: number, height: number): FrameKind {
  return width >= height ? "browser" : "phone";
}

function useSizedImages(images: BrowserProofImage[]): {
  sized: SizedImage[];
  ready: boolean;
} {
  const [sized, setSized] = useState<SizedImage[]>([]);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      const results = await Promise.all(
        images.map(
          (image) =>
            new Promise<SizedImage>((resolve) => {
              const img = new window.Image();
              img.onload = () => {
                const width = img.naturalWidth || 16;
                const height = img.naturalHeight || 10;
                resolve({
                  ...image,
                  width,
                  height,
                  kind: classify(width, height),
                });
              };
              img.onerror = () => {
                resolve({
                  ...image,
                  width: 16,
                  height: 10,
                  kind: "browser",
                });
              };
              img.src = image.src;
            }),
        ),
      );

      if (!cancelled) {
        setSized(results);
        setReady(true);
      }
    }

    setReady(false);
    void load();
    return () => {
      cancelled = true;
    };
  }, [images]);

  return { sized, ready };
}

function DesktopFrame({
  image,
  className,
  onPreview,
}: {
  image: PreviewableImage;
  className?: string;
  onPreview: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onPreview}
      aria-label={`Preview: ${image.alt}`}
      className={cn(
        "block w-full overflow-hidden rounded-[10px] border-2 border-primary bg-background text-left",
        "shadow-[6px_6px_0_0_#131311]",
