function PhoneFrame({
  image,
  className,
  onPreview,
}: {
  image: PreviewableImage;
  className?: string;
  onPreview: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onPreview}
      aria-label={`Preview: ${image.alt}`}
      className={cn(
        "block w-full overflow-hidden rounded-[1.35rem] border-2 border-primary bg-primary text-left",
        "shadow-[8px_8px_0_0_#9FE870]",
        "transition-transform duration-300 ease-out motion-safe:hover:-translate-y-1",
