async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });

  // Gallery: video creative
  await page.goto('http://localhost:3000/amazon-video-creative/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(1500);
  await page.getByRole('heading', { name: /Visual contexts|storyboard|video/i }).first().scrollIntoViewIfNeeded().catch(() => {});
  await page.waitForTimeout(400);

  const gallery = await page.evaluate(() => {
    const buttons = [...document.querySelectorAll('button[aria-label^="Preview:"]')];
    const mediaBoxes = buttons.map((b) => {
      const box = b.querySelector('.aspect-\\[4\\/3\\], [class*="aspect-"]');
      const r = (box || b).getBoundingClientRect();
      return { h: Math.round(r.height), w: Math.round(r.width) };
    });
    const heights = [...new Set(mediaBoxes.map((m) => m.h))];
    return { previewButtons: buttons.length, mediaHeights: mediaBoxes.map(m => m.h), uniform: heights.length <= 1 };
  });

  if (gallery.previewButtons > 0) {
    await page.locator('button[aria-label^="Preview:"]').first().click();
    await page.waitForTimeout(500);
  }
  const dialogOpen = await page.locator('[role="dialog"]').count();
  await page.screenshot({ path: 'docs/qa/screenshots/proof-gallery-preview.png', fullPage: false });
  if (dialogOpen) {
    await page.locator('[aria-label="Close preview"]').click();
    await page.waitForTimeout(300);
  }

  // Browser proof
  await page.goto('http://localhost:3000/amazon-ppc-management-agency/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(2000);
  await page.getByRole('heading', { name: /Advertising-led sales movement/i }).scrollIntoViewIfNeeded();
  await page.waitForTimeout(800);
  const proof = await page.evaluate(() => {
    const section = [...document.querySelectorAll('h2')].find(h => /Advertising-led/i.test(h.textContent||''))?.closest('section');
    const buttons = section ? [...section.querySelectorAll('button[aria-label^="Preview:"]')] : [];
    return { proofButtons: buttons.length, oldLabel: (section?.textContent||'').includes('Seller Central / Ads proof') };
  });
  await page.locator('section button[aria-label^="Preview:"]').first().click();
  await page.waitForTimeout(500);
  const proofDialog = await page.locator('[role="dialog"]').count();
  await page.screenshot({ path: 'docs/qa/screenshots/browser-proof-preview.png', fullPage: false });

  return { gallery, dialogOpen, proof, proofDialog };
}

