    for (let x = 0; x < w; x++) {
      const ai = (y * w + x) * ch + 3;
      data[ai] = Math.round(data[ai] * fade);
    }
  }
  // Soft left edge into ink
  for (let x = 0; x < Math.floor(w * 0.12); x++) {
    const fade = x / (w * 0.12);
    for (let y = 0; y < h; y++) {
      const ai = (y * w + x) * ch + 3;
      data[ai] = Math.round(data[ai] * fade);
