async (page) => {
  await page.goto('https://myamazonguy.com/', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.waitForTimeout(2000);

  const sliders = await page.evaluate(() => {
    const roots = [...document.querySelectorAll(
      '.swiper, .slick-slider, .splide, [class*="carousel"], [class*="slider"], [class*="swiper"], [data-settings*="slideshow"], .elementor-swiper, .e-n-carousel, .elementor-image-carousel-wrapper, .elementor-widget-image-carousel, .elementor-widget-media-carousel, .elementor-widget-slides, .elementor-slides-wrapper'
    )];
    return roots.map((el, i) => {
      const r = el.getBoundingClientRect();
      const slides = el.querySelectorAll('.swiper-slide, .slick-slide, .splide__slide, .elementor-slide, .swiper-slide-inner, figure, img');
      const imgs = [...el.querySelectorAll('img')].slice(0, 12).map((img) => ({
        alt: (img.alt || '').slice(0, 80),
        src: ((img.currentSrc || img.src || '').split('/').pop() || '').slice(0, 90),
        w: Math.round(img.getBoundingClientRect().width),
        h: Math.round(img.getBoundingClientRect().height),
      }));
      return {
        i,
        className: (el.className || '').toString().slice(0, 160),
        top: Math.round(r.top + scrollY),
        h: Math.round(r.height),
        w: Math.round(r.width),
        slideCount: slides.length,
        text: (el.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 200),
        imgs,
      };
    }).filter((s) => s.w > 200);
  });

  // Also find Elementor slideshow widgets via data-settings
  const elementorSlides = await page.evaluate(() => {
    const out = [];
    for (const el of document.querySelectorAll('[data-settings]')) {
      const raw = el.getAttribute('data-settings') || '';
      if (!/slideshow|carousel|slider|swiper/i.test(raw) && !/slideshow|carousel|slider|swiper/i.test(el.className || '')) continue;
      const r = el.getBoundingClientRect();
      if (r.width < 200) continue;
      out.push({
        className: (el.className || '').toString().slice(0, 140),
        top: Math.round(r.top + scrollY),
        h: Math.round(r.height),
        settingsSnippet: raw.slice(0, 220),
        text: (el.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 160),
        imgCount: el.querySelectorAll('img').length,
      });
    }
    return out.slice(0, 20);
  });

  return { sliderCount: sliders.length, sliders: sliders.slice(0, 15), elementorSlides };
}

async (page) => {
  const base = 'e:/Desktop/Projects/ecomGliders/docs/qa/screenshots';
  await page.goto('https://myamazonguy.com/', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.waitForTimeout(1500);

  // Scroll to carousel
  await page.evaluate(() => {
    const el = document.querySelector('.elementor-widget-exad-logo-carousel');
    if (el) el.scrollIntoView({ block: 'center' });
  });
  await page.waitForTimeout(500);

  const details = await page.evaluate(() => {
    const root = document.querySelector('.elementor-widget-exad-logo-carousel');
    if (!root) return null;
    const items = [...root.querySelectorAll('a, .exad-logo-carousel-item, .slick-slide, .swiper-slide')];
    const unique = [];
    for (const item of items) {
      const img = item.querySelector('img');
      if (!img) continue;
      const alt = (img.alt || '').trim();
      const href = item.closest('a')?.href || item.getAttribute('href') || null;
      const src = img.currentSrc || img.src;
      if (unique.some((u) => u.alt === alt || u.src === src)) continue;
      unique.push({
        alt,
        href,
        src: src.split('/').pop(),
        naturalW: img.naturalWidth,
        naturalH: img.naturalHeight,
      });
    }
    const r = root.getBoundingClientRect();
    const dots = root.querySelectorAll('.slick-dots li, .swiper-pagination-bullet, [class*="dot"]').length;
    const arrows = !!root.querySelector('.slick-arrow, .swiper-button-next, .exad-carousel-nav, [class*="arrow"]');
    return {
      top: Math.round(r.top + scrollY),
      h: Math.round(r.height),
      w: Math.round(r.width),
      slideCount: unique.length,
      slides: unique,
      dots,
      arrows,
      afterHero: true,
    };
  });

  // Capture each slide by clicking next if available, else wait autoplay
  const shots = [];
  for (let i = 0; i < 4; i++) {
    await page.waitForTimeout(i === 0 ? 200 : 2800);
    const label = await page.evaluate(() => {
      const root = document.querySelector('.elementor-widget-exad-logo-carousel');
      const active = root?.querySelector('.slick-current img, .swiper-slide-active img, .exad-logo-carousel-item img');
      return (active?.alt || active?.currentSrc || '').toString().slice(0, 80);
    });
    const path = `${base}/research-mag-banner-slide-${i}.png`;
    const box = await page.evaluate(() => {
      const root = document.querySelector('.elementor-widget-exad-logo-carousel');
      const r = root.getBoundingClientRect();
      return { x: r.x, y: r.y, width: r.width, height: Math.min(r.height + 20, 160) };
    });
    await page.screenshot({ path, fullPage: false, clip: { x: Math.max(0, box.x), y: Math.max(0, box.y - 10), width: box.width, height: Math.max(120, box.height) } });
    shots.push({ i, label, path });

    // try next
    const clicked = await page.evaluate(() => {
      const root = document.querySelector('.elementor-widget-exad-logo-carousel');
      const next = root?.querySelector('.slick-next, .swiper-button-next, .exad-carousel-nav-next, button[aria-label*="Next" i]');
      if (next instanceof HTMLElement) { next.click(); return true; }
      return false;
    });
    if (!clicked) {
      // force slick/swiper if present
      await page.evaluate((idx) => {
        const root = document.querySelector('.exad-logo-carousel');
        // @ts-ignore
        if (root && window.jQuery && window.jQuery(root).slick) {
          // @ts-ignore
          window.jQuery(root).slick('slickGoTo', idx + 1);
        }
      }, i);
    }
  }

  return { details, shots };
}

