  if (m) {
    try { config = JSON.parse(m[1]); } catch(e) {}
  }
  if (!config) {
    try {
      const res = await fetch(location.href + '/config', { credentials: 'include' });
      if (res.ok) config = await res.json();
      else return { status: res.status, title: document.title };
    } catch (e) {
      return { err: String(e), title: document.title };
    }
  }
  const files = config?.request?.files || {};
  const progressive = (files.progressive || []).map(f => ({ quality: f.quality, width: f.width, url: f.url }));
  return {
    title: config?.video?.title,
    duration: config?.video?.duration,
    progressive: progressive.slice(0, 3),
    hls: files.hls?.url || files.hls?.cdns?.akfire_interconnect_quic?.url || null
  };
}

