  btn?.dispatchEvent(new MouseEvent('mouseenter', { bubbles: true }));
  await new Promise(r => setTimeout(r, 500));
  const iframe = section.querySelector('iframe');
  return {
    covers: imgs.slice(0, 6),
    hoverIframe: iframe ? iframe.src : null,
    names: [...section.querySelectorAll('li button')].map(b => b.querySelectorAll('span')[b.querySelectorAll('span').length-1]?.textContent || b.innerText).slice(0,3)
  };
}

