              {index.proofSubheading ? (
                <p className="mt-4 text-body text-text-secondary">{index.proofSubheading}</p>
              ) : null}
            </div>
          </SectionShell>
        ) : null}

        <CaseStudyFreeAuditCta
          heading={index.cta?.heading}
          body={index.cta?.body}
        />
      </main>
    </>
  );
}

