async (page) => {
  const buf = await page.screenshot({ type: 'png' });
  // Use sharp if available, else parse via page canvas
  const colors = await page.evaluate(async () => {
    // Draw current page isn't available; use getComputedStyle of what's behind
    const points = [[40, 12], [40, 40], [40, 100], [200, 12], [640, 12]];
    return points.map(([x, y]) => {
      const el = document.elementFromPoint(x, y);
      let node = el;
      let bg = 'transparent';
      while (node && node !== document.documentElement) {
        const c = getComputedStyle(node).backgroundColor;
        if (c && c !== 'rgba(0, 0, 0, 0)' && c !== 'transparent') { bg = c; break; }
        node = node.parentElement;
      }
      // Also check if hero section contains this point
      const hero = document.querySelector('#case-study-hero');
      const hr = hero?.getBoundingClientRect();
      const inHero = hr ? x >= hr.left && x <= hr.right && y >= hr.top && y <= hr.bottom : false;
      return { x, y, tag: el?.tagName, bg, inHero, heroTop: hr?.top };
    });
  });
  return colors;
}

async (page) => {
  const path = require('path');
  const fs = require('fs');
  const out = path.join(process.cwd(), 'tmp-case-hero.png');
  await page.screenshot({ path: out, type: 'png' });
  // sample pixels via pngjs or pure decode
  let sharp;
  try { sharp = require('sharp'); } catch { sharp = null; }
  if (!sharp) {
    return { out, note: 'no sharp', size: fs.statSync(out).size };
  }
  const { data, info } = await sharp(out).raw().ensureAlpha().toBuffer({ resolveWithObject: true });
  const sample = (x, y) => {
    const i = (y * info.width + x) * info.channels;
    return { x, y, r: data[i], g: data[i+1], b: data[i+2] };
  };
  return {
    dim: info,
    samples: [
      sample(40, 8),
      sample(40, 30),
      sample(40, 90),
      sample(40, 120),
      sample(Math.floor(info.width/2), 20),
      sample(Math.floor(info.width/2), 100),
    ],
  };
}

async (page) => {
  const buffer = await page.screenshot({ type: 'png' });
  const b64 = buffer.toString('base64');
  const samples = await page.evaluate(async (b64) => {
    const img = new Image();
    const loaded = new Promise((res, rej) => { img.onload = res; img.onerror = rej; });
    img.src = 'data:image/png;base64,' + b64;
    await loaded;
    const canvas = document.createElement('canvas');
    canvas.width = img.width;
    canvas.height = img.height;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const pick = (x, y) => {
      const [r,g,b] = ctx.getImageData(x, y, 1, 1).data;
      return { x, y, r, g, b, bright: r + g + b };
    };
    return {
      w: img.width,
      h: img.height,
      samples: [
        pick(40, 8),
        pick(40, 28),
        pick(40, 70),
        pick(40, 100),
        pick(40, 130),
        pick(Math.floor(img.width / 2), 16),
        pick(Math.floor(img.width / 2), 90),
      ],
    };
  }, b64);
  return samples;
}

