    const parent = img.closest('[class*="aspect"], figure, div');
    return {
      file: decodeURIComponent((img.currentSrc||img.src||'').match(/url=%2F([^&]+)/)?.[1]||'').slice(0,80),
      h: Math.round(r.height), w: Math.round(r.width),
      parentClass: (parent?.className||'').toString().match(/aspect-[^\s]+|grid-cols-[^\s]+|max-w-[^\s]+|w-\[[^\]]+\]/g)?.join(' ')
    };
  });
  return { imgs, title: document.title };
}

() => {
  const imgs = [...document.querySelectorAll('img')].filter(i => i.getBoundingClientRect().height > 80).slice(0, 20).map(img => ({
    alt: (img.alt||'').slice(0,55),
    h: Math.round(img.getBoundingClientRect().height),
    w: Math.round(img.getBoundingClientRect().width),
    src: (img.currentSrc||img.src||'').split('/').slice(-1)[0].slice(0,55)
  }));
  const hs = [...document.querySelectorAll('h1,h2')].map(h => h.textContent.trim().replace(/\s+/g,' ').slice(0,55)).slice(0,18);
  return { title: document.title, hs, imgs, textLen: document.body.innerText.length };
}

() => {
  const imgs = [...document.querySelectorAll('img')].filter(i => i.getBoundingClientRect().height > 100).slice(0, 12).map(img => ({
    alt: (img.alt||'').slice(0,50),
    h: Math.round(img.getBoundingClientRect().height),
    w: Math.round(img.getBoundingClientRect().width)
  }));
  return { imgs, viewport: { w: window.innerWidth, h: window.innerHeight } };
}

() => {
  const imgs = [...document.querySelectorAll('main img')].filter(i => i.getBoundingClientRect().height > 20).map(img => ({
    alt: (img.alt||'').slice(0,40),
    file: decodeURIComponent((img.currentSrc||img.src||'').match(/url=%2F([^&]+)/)?.[1]||'').slice(0,70),
    h: Math.round(img.getBoundingClientRect().height),
    w: Math.round(img.getBoundingClientRect().width)
  }));
  const main = document.querySelector('main');
  const mw = main ? Math.round(main.getBoundingClientRect().width) : 0;
  return { viewport: { w: window.innerWidth, h: window.innerHeight }, mainW: mw, imgs, hs: [...document.querySelectorAll('main h2')].map(h=>h.textContent.trim().slice(0,40)) };
}

() => {
  const imgs = [...document.querySelectorAll('main img')].filter(i => i.getBoundingClientRect().height > 40).map(img => ({
    file: decodeURIComponent((img.currentSrc||img.src||'').match(/url=%2F([^&]+)/)?.[1]||'').slice(0,60),
    h: Math.round(img.getBoundingClientRect().height),
    w: Math.round(img.getBoundingClientRect().width),
    alt: (img.alt||'').slice(0,30)
  }));
  return { viewport: { w: window.innerWidth }, imgs };
}

