const EARLY_VISUAL_TYPES = new Set([
  "infographicSpotlight",
  "browserProof",
  "proofGallery",
  "metricChart",
  "catalogHealthBoard",
  "brandPathwayBoard",
  "brandUnlockGrid",
]);

const LATE_OPS_TYPES = new Set([
  "processSteps",
  "checklistMatrix",
  "comparisonTable",
]);

function ServiceCustomTail({
  service,
  site,
  relatedSubheading,
}: {
  service: ServicePageConfig;
  site: SiteConfig;
  relatedSubheading: string;
}) {
