                  <p className="text-h4 font-black tracking-tight text-primary">
                    {item.metric}
                  </p>
                  <div className="min-w-0">
                    <h3 className="text-body font-semibold text-primary">
                      {item.brand}
                    </h3>
                    <p className="mt-1 text-small text-text-secondary">
                      {item.description}
                    </p>
                  </div>
