async (page) => {
  await page.goto('https://ecom-gliders.vercel.app/amazon-catalog-management/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(600);
  const catalog = await page.evaluate(() => {
    const h1 = document.querySelector('h1')?.textContent?.trim();
    const heroForm = !!document.querySelector('#service-hero #service-lead-form');
    const deferredForm = !!document.querySelector('#service-lead-form');
    const consoleInHero = !!document.querySelector('#service-hero')?.innerText.match(/ASIN|Suppressed|sellercentral/i);
    const requestIntake = !!document.body.innerText.match(/Request intake/i);
    return { h1, heroForm, deferredForm, consoleInHero, requestIntake };
  });
  await page.screenshot({ path: '.playwright-mcp/pass13-catalog-hero.png', fullPage: false });
  await page.goto('https://ecom-gliders.vercel.app/amazon-ppc-management-agency/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(600);
  const ppc = await page.evaluate(() => {
    const heroForm = !!document.querySelector('#service-hero #service-lead-form');
    const hasCapture = !!document.querySelector('#service-hero img');
    return { heroForm, hasCapture };
  });
  await page.screenshot({ path: '.playwright-mcp/pass13-ppc-hero.png', fullPage: false });
  return { catalog, ppc };
}
